    /// B-2026-07-30-11 (discarded-temp leg, place-shape pins) — discard
    /// shapes that move an EXISTING binding must fire its body exactly
    /// once: a moved binding in a tuple (`let _ = (r, 1)` — the tuple gate
    /// declines, the source's own slot fires), a binding moved into an
    /// Option ctor (`Option.Some(s)` — the ctor move retracts the source,
    /// the discard walk is the single fire), an identifier-field literal
    /// (`W { r: r0 }`), a bare moved identifier (`let _ = t`), and a
    /// scalar-place field (`Res { id: k }` — `k` is a copy, so the temp
    /// registers and fires). Twin of `tests/interpreter.rs`'s
    /// `test_wildcard_let_discard_place_shapes_single_fire`.
    #[test]
    fn e2e_wildcard_let_discard_place_shapes_single_fire() {
        let Some(out) = run_program(
            "struct Res { id: i64 }\n\
             struct W { r: Res }\n\
             impl Drop for Res {\n\
             \x20   fn drop(mut ref self) {\n\
             \x20       println(f\"drop {self.id}\")\n\
             \x20   }\n\
             }\n\
             fn main() {\n\
             \x20   let r = Res { id: 31 };\n\
             \x20   println(\"a\");\n\
             \x20   let _ = (r, 1);\n\
             \x20   println(\"b\");\n\
             \x20   let s = Res { id: 32 };\n\
             \x20   let _ = Option.Some(s);\n\
             \x20   println(\"c\");\n\
             \x20   let r0 = Res { id: 33 };\n\
             \x20   let _ = W { r: r0 };\n\
             \x20   println(\"d\");\n\
             \x20   let t = Res { id: 34 };\n\
             \x20   let _ = t;\n\
             \x20   println(\"e\");\n\
             \x20   let k = 5;\n\
             \x20   let _ = Res { id: k };\n\
             \x20   println(\"end\");\n\
             }\n",
        ) else {
            return;
        };
        assert_eq!(
            out,
            "a\ndrop 31\nb\ndrop 32\nc\ndrop 33\nd\ndrop 34\ne\ndrop 5\nend\n"
        );
    }

    /// B-2026-07-30-11 (param-tuple leg, the A shape) — a tuple LITERAL arg
    /// runs its Drop-carrying elements' bodies after the call returns, for
    /// fresh literal and fresh-call elements; a moved-binding element
    /// (`take_tuple((h, 20))`) keeps its own binding's single NLL fire. The
    /// struct-arg baselines (`take_res(Res { .. })`, `take_res(g)`) pin the
    /// pre-existing behavior around the new shapes. Twin of
    /// `tests/interpreter.rs`'s `test_param_tuple_elements_run_drop_bodies`.
    #[test]
    fn e2e_param_tuple_elements_run_drop_bodies() {
        let Some(out) = run_program(
            "struct Res { id: i64 }\n\
             impl Drop for Res {\n\
             \x20   fn drop(mut ref self) {\n\
             \x20       println(f\"drop {self.id}\")\n\
             \x20   }\n\
             }\n\
             fn mk(n: i64) -> Res {\n\
             \x20   Res { id: n }\n\
             }\n\
             fn take_tuple(t: (Res, i64)) {\n\
             \x20   println(f\"callee sees {t.1}\")\n\
             }\n\
             fn take_res(r: Res) {\n\
             \x20   println(f\"callee sees res {r.id}\")\n\
             }\n\
             fn main() {\n\
             \x20   println(\"a\");\n\
             \x20   take_tuple((Res { id: 41 }, 10));\n\
             \x20   println(\"b\");\n\
             \x20   take_res(Res { id: 42 });\n\
             \x20   println(\"c\");\n\
             \x20   let g = Res { id: 43 };\n\
             \x20   take_res(g);\n\
             \x20   println(\"d\");\n\
             \x20   let h = Res { id: 44 };\n\
             \x20   take_tuple((h, 20));\n\
             \x20   println(\"e\");\n\
             \x20   take_tuple((mk(45), 30));\n\
             \x20   println(\"end\");\n\
             }\n",
        ) else {
            return;
        };
        assert_eq!(
            out,
            "a\ncallee sees 10\ndrop 41\nb\ncallee sees res 42\ndrop 42\nc\n\
             callee sees res 43\ndrop 43\nd\ncallee sees 20\ndrop 44\ne\n\
             callee sees 30\ndrop 45\nend\n"
        );
    }

    /// B-2026-07-30-11 (if-let leg) — an `if let` arm binding that receives
    /// a MOVED Drop-bearing enum payload runs the payload's Drop body at
    /// arm end, exactly like the equivalent `match` arm: owned-binding and
    /// fresh-temp scrutinees, a miss edge that fires nothing, and a body
    /// that moves the binding out still fires exactly once. Twin of
    /// `tests/interpreter.rs`'s `test_if_let_moved_payload_runs_drop_body`.
    #[test]
    fn e2e_if_let_moved_payload_runs_drop_body() {
        let Some(out) = run_program(
            "struct Res { id: i64 }\n\
             impl Drop for Res {\n\
             \x20   fn drop(mut ref self) {\n\
             \x20       println(f\"drop {self.id}\")\n\
             \x20   }\n\
             }\n\
             enum Box2 { Full(Res), Empty }\n\
             fn mkbox(n: i64) -> Box2 {\n\
             \x20   Box2.Full(Res { id: n })\n\
             }\n\
             fn take_res(r: Res) {\n\
             \x20   println(f\"consumed {r.id}\")\n\
             }\n\
             fn main() {\n\
             \x20   let b = Box2.Full(Res { id: 33 });\n\
             \x20   println(\"a\");\n\
             \x20   if let Box2.Full(r) = b {\n\
             \x20       println(f\"arm sees {r.id}\");\n\
             \x20   }\n\
             \x20   println(\"b\");\n\
             \x20   if let Box2.Full(r) = mkbox(34) {\n\
             \x20       println(f\"arm sees {r.id}\");\n\
             \x20   }\n\
             \x20   println(\"c\");\n\
             \x20   let e = Box2.Empty;\n\
             \x20   if let Box2.Full(r) = e {\n\
             \x20       println(f\"arm sees {r.id}\");\n\
             \x20   } else {\n\
             \x20       println(\"empty\");\n\
             \x20   }\n\
             \x20   println(\"d\");\n\
             \x20   let c = Box2.Full(Res { id: 35 });\n\
             \x20   if let Box2.Full(r) = c {\n\
             \x20       take_res(r);\n\
             \x20       println(\"after move\");\n\
             \x20   }\n\
             \x20   println(\"end\");\n\
             }\n",
        ) else {
            return;
        };
        assert_eq!(
            out,
            "a\narm sees 33\ndrop 33\nb\narm sees 34\ndrop 34\nc\nempty\nd\n\
             consumed 35\nafter move\ndrop 35\nend\n"
        );
    }

    /// B-2026-07-31-45 — `let…else` with a moved Drop-bearing enum payload
    /// runs the payload's body exactly ONCE, at the escaped binding's NLL
    /// end (after its last use). Pre-fix the interpreter ran it twice (the
    /// source's un-disarmed walk before the binding use + the binding's
    /// slot) and AOT ran it once via the source's walk while the binding
    /// was still live. The miss edge diverges without a spurious fire.
