    /// B-2026-08-01-13 — owned enum ARG body ownership, the coherent
    /// caller-retains rule: a fresh enum-ctor arg's payload body fires
    /// exactly once, CALLER-side, at the arg's statement end — whether the
    /// callee drops the enum whole (was: silent on both backends), matches
    /// it (was: single by accident of two bugs cancelling — output
    /// unchanged, channel flipped to the caller), or if-lets an identifier
    /// arg (was: DOUBLE on both backends — the callee's arm channel fired
    /// on top of the caller's NLL fire). An own-Drop enum fires its own
    /// body then the payload walk. Twin of `tests/interpreter.rs`'s
    /// `test_owned_enum_arg_payload_body_single_caller_fire`.
    #[test]
    fn e2e_owned_enum_arg_payload_body_single_caller_fire() {
        let Some(out) = run_program(
            "struct Res { id: i64, name: String }\n\
             impl Drop for Res {\n\
             \x20   fn drop(mut ref self) {\n\
             \x20       println(f\"drop {self.id} {self.name}\")\n\
             \x20   }\n\
             }\n\
             enum Loud { Hold(Res), Quiet }\n\
             impl Drop for Loud {\n\
             \x20   fn drop(mut ref self) {\n\
             \x20       println(\"loud drop\")\n\
             \x20   }\n\
             }\n\
             enum E2 { B(Res), Empty }\n\
             fn check(w: E2) { println(\"checked\"); }\n\
             fn check_match(w: E2) {\n\
             \x20   match w {\n\
             \x20       E2.B(r2) => { println(f\"got {r2.id}\"); }\n\
             \x20       E2.Empty => { println(\"none\"); }\n\
             \x20   }\n\
             \x20   println(\"match done\");\n\
             }\n\
             fn check_iflet(w: E2) {\n\
             \x20   if let E2.B(r2) = w {\n\
             \x20       println(f\"if {r2.id}\");\n\
             \x20   }\n\
             \x20   println(\"iflet done\");\n\
             }\n\
             fn check_loud(w: Loud) { println(\"loudcheck\"); }\n\
             fn mk(n: i64) -> E2 { return E2.B(Res { id: n, name: f\"x{n}\" }); }\n\
             fn main() {\n\
             \x20   println(\"a\");\n\
             \x20   check(E2.B(Res { id: 55, name: f\"x{55}\" }));\n\
             \x20   println(\"b\");\n\
             \x20   check_loud(Loud.Hold(Res { id: 9, name: f\"l{9}\" }));\n\
             \x20   println(\"c\");\n\
             \x20   let e = mk(53);\n\
             \x20   check_match(e);\n\
             \x20   println(\"d\");\n\
             \x20   check_iflet(E2.B(Res { id: 6, name: f\"x{6}\" }));\n\
             \x20   println(\"end\");\n\
             }\n",
        ) else {
            return;
        };
        assert_eq!(
            out,
            "a\nchecked\ndrop 55 x55\nb\nloudcheck\nloud drop\ndrop 9 l9\nc\ngot 53\n\
             match done\ndrop 53 x53\nd\nif 6\niflet done\ndrop 6 x6\nend\n"
        );
    }

    /// B-2026-08-01-5 — fresh method-RECEIVER Drop temps: a `ref self`
    /// method's fresh receiver fires its body at STATEMENT END on both
    /// backends (pre-fix: never under `karac run`, at scope exit under
    /// `karac build`); an owned-`self` method CONSUMED the receiver, so its
    /// temp stays body-silent on both (pre-fix codegen fired it late over a
    /// possibly-stale slot); a passthrough result (`mk(4).me()`) is owned by
    /// its binding alone — exactly one fire, at the binding's death. Twin of
    /// `tests/interpreter.rs`'s `test_fresh_recv_temp_drop_semantics`.
    #[test]
    fn e2e_fresh_recv_temp_drop_semantics() {
        let Some(out) = run_program(
            "struct Res { id: i64, name: String }\n\
             impl Drop for Res {\n\
             \x20   fn drop(mut ref self) {\n\
             \x20       println(f\"drop {self.id} {self.name}\")\n\
             \x20   }\n\
             }\n\
             impl Res {\n\
             \x20   fn ident(ref self) -> i64 {\n\
             \x20       return self.id;\n\
             \x20   }\n\
             \x20   fn eat(self) -> i64 {\n\
             \x20       return self.id + 100;\n\
             \x20   }\n\
             \x20   fn me(self) -> Res {\n\
             \x20       return self;\n\
             \x20   }\n\
             }\n\
             fn mk(n: i64) -> Res {\n\
             \x20   return Res { id: n, name: f\"r{n}\" };\n\
             }\n\
             fn main() {\n\
             \x20   println(\"a: ref-method fresh struct receiver\");\n\
             \x20   let x = mk(1).ident();\n\
             \x20   println(f\"x={x}\");\n\
             \x20   println(\"b: owned-self consumed receiver (silent)\");\n\
             \x20   let y = mk(2).eat();\n\
             \x20   println(f\"y={y}\");\n\
             \x20   println(\"c: bare ref-method statement\");\n\
             \x20   mk(3).ident();\n\
             \x20   println(\"d: passthrough result owned by binding\");\n\
             \x20   let m = mk(4).me();\n\
             \x20   println(f\"m={m.id}\");\n\
             \x20   println(\"end\");\n\
             }\n",
        ) else {
            return;
        };
        assert_eq!(
            out,
            "a: ref-method fresh struct receiver\ndrop 1 r1\nx=1\n\
             b: owned-self consumed receiver (silent)\ny=102\n\
             c: bare ref-method statement\ndrop 3 r3\n\
             d: passthrough result owned by binding\nm=4\ndrop 4 r4\nend\n"
        );
    }

    /// B-2026-08-01-5 (chain leg) — owned-self passthrough chains no longer
    /// double- or stale-fire: pre-fix `karac build` printed the receiver
    /// body TWICE at scope exit for `mk(3).me().ident()`, re-fired r2 after
    /// y's own death, and fired `mk(1).plus(10)`'s body over a STALE slot
    /// (id 1 after the value had become 11). Each value now fires exactly
    /// once, at its owner's death; chain-link receivers stay body-silent on
    /// both backends (recorded residual). Twin of `tests/interpreter.rs`'s
    /// `test_owned_self_chain_no_double_drop`.
    #[test]
    fn e2e_owned_self_chain_no_double_drop() {
        let Some(out) = run_program(
            "struct Res { id: i64, name: String }\n\
             impl Drop for Res {\n\
             \x20   fn drop(mut ref self) {\n\
             \x20       println(f\"drop {self.id} {self.name}\")\n\
             \x20   }\n\
             }\n\
             impl Res {\n\
             \x20   fn plus(self, n: i64) -> Res {\n\
             \x20       return Res { id: self.id + n, name: self.name.clone() };\n\
             \x20   }\n\
             \x20   fn me(self) -> Res {\n\
             \x20       return self;\n\
             \x20   }\n\
             \x20   fn ident(ref self) -> i64 {\n\
             \x20       return self.id;\n\
             \x20   }\n\
             }\n\
             fn mk(n: i64) -> Res {\n\
             \x20   return Res { id: n, name: f\"r{n}\" };\n\
             }\n\
             fn main() {\n\
             \x20   println(\"a: rebuild-chain\");\n\
             \x20   let x = mk(1).plus(10);\n\
             \x20   println(f\"x={x.id}\");\n\
             \x20   println(\"b: passthrough self\");\n\
             \x20   let y = mk(2).me();\n\
             \x20   println(f\"y={y.id}\");\n\
             \x20   println(\"c: chain then ref-method\");\n\
             \x20   let z = mk(3).me().ident();\n\
             \x20   println(f\"z={z}\");\n\
             \x20   println(\"end\");\n\
             }\n",
        ) else {
            return;
        };
        assert_eq!(
            out,
            "a: rebuild-chain\nx=11\ndrop 11 r1\nb: passthrough self\ny=2\ndrop 2 r2\n\
             c: chain then ref-method\nz=3\nend\n"
        );
    }

    /// B-2026-08-01-6 — codegen parity pin for `tests/interpreter.rs`'s
    /// `test_ref_self_match_borrowed_payload_silent` (same source and
    /// expected string): a `ref self` method matching on `self` binds
    /// borrowed views, so no payload body fires inside the method — the
    /// fresh-receiver shape stays silent and the named-binding shape fires
    /// exactly once via the binding's own walk. This side was already
    /// correct; the interpreter's stash was the diverging half.
    #[test]
    fn e2e_ref_self_match_borrowed_payload_silent() {
        let Some(out) = run_program(
            "struct Res { id: i64, name: String }\n\
             impl Drop for Res {\n\
             \x20   fn drop(mut ref self) {\n\
             \x20       println(f\"drop {self.id} {self.name}\")\n\
             \x20   }\n\
             }\n\
             enum Box2 { Full(Res), Empty }\n\
             impl Box2 {\n\
             \x20   fn tag(ref self) -> i64 {\n\
             \x20       match self {\n\
             \x20           Box2.Full(r) => { return 1; }\n\
             \x20           Box2.Empty => { return 0; }\n\
             \x20       }\n\
             \x20   }\n\
             }\n\
             fn mk_e(n: i64) -> Box2 {\n\
             \x20   return Box2.Full(Res { id: n, name: f\"e{n}\" });\n\
             }\n\
             fn main() {\n\
             \x20   println(\"a: ref-self match on fresh receiver\");\n\
             \x20   let t = mk_e(5).tag();\n\
             \x20   println(f\"t={t}\");\n\
             \x20   println(\"b: ref-self match on named binding\");\n\
             \x20   let bx = mk_e(8);\n\
             \x20   let u = bx.tag();\n\
             \x20   println(f\"u={u}\");\n\
             \x20   println(\"end\");\n\
             }\n",
        ) else {
            return;
        };
        assert_eq!(
            out,
            "a: ref-self match on fresh receiver\nt=1\n\
             b: ref-self match on named binding\ndrop 8 e8\nu=1\nend\n"
        );
    }

    /// B-2026-08-01-7 — an OWNED-`self` method consumes its named value-enum
    /// receiver: the binding's payload-bodies walk disarms at the call
    /// (exactly like `let c = b;`), leaving the method-internal arm channel
    /// as the payload's sole owner. Pre-fix `b.into_id()` printed the body
    /// TWICE on both backends (arm + still-armed walk); the non-consuming
    /// owned-self shape is silent (the consumed value's drop is the
    /// documented owned-self residual). Twin of `tests/interpreter.rs`'s
    /// `test_owned_self_enum_receiver_single_fire`.
    /// B-2026-08-28-69 — the compiled twin of
    /// `test_discarded_match_arm_value_runs_its_drop_body_once`.
    ///
    /// A DISCARDED `match` whose arm value is an owned Drop-bearing temp runs
    /// that body exactly once. The two halves landed together because either
    /// alone MOVES the divergence: the interpreter under-fired when an arm
    /// handed on a bound payload, and BOTH backends were silent when an arm
    /// minted a fresh value. The fresh-value cells are the ones this file
    /// gained — `try_track_discarded_user_drop_temp` resolved a type name only
    /// from a call, so a `Match` tail registered nothing even though
    /// `discarded_match_value_tail` already admitted the shape.
    ///
    /// Memory is balanced in every cell either way, so no ASAN/LSan corpus can
    /// reach this class — only an A/B output comparison can, which is why the
    /// interpreter twin is the other half of the pin.
    #[test]
    fn e2e_discarded_match_arm_value_runs_its_drop_body_once() {
        let hdr = "struct R { id: i64 }\n\
                   impl Drop for R { fn drop(mut ref self) { println(f\"dR{self.id}\") } }\n\
                   fn mk(i: i64) -> R { return R { id: i }; }\n";
        let rows: [(&str, &str, &str); 6] = [
            (
                "let o: Option[R] = Some(R { id: 1 });\n\
                 match o { Some(r) => { r } None => { R { id: 0 } } };\n\
                 println(\"dropped\");",
                "dR1\ndropped\n",
                "braced arm yields the bound payload",
            ),
            (
                "let o: Option[R] = Some(R { id: 1 });\n\
                 match o { Some(r) => r, None => R { id: 0 } };\n\
                 println(\"dropped\");",
                "dR1\ndropped\n",
                "bare arm yields the bound payload",
            ),
            (
                "let n = 1;\n\
                 match n { 1 => { R { id: 7 } } _ => { R { id: 0 } } };\n\
                 println(\"dropped\");",
                "dR7\ndropped\n",
                "braced arm yields a fresh literal",
            ),
            (
                "let n = 1;\n\
                 match n { 1 => R { id: 7 }, _ => R { id: 0 } };\n\
                 println(\"dropped\");",
                "dR7\ndropped\n",
                "bare arm yields a fresh literal",
            ),
            (
                "let n = 1;\n\
                 match n { 1 => mk(7), _ => mk(0) };\n\
                 println(\"dropped\");",
                "dR7\ndropped\n",
                "arm yields a call result",
            ),
            (
                "let r = R { id: 41 };\n\
                 let n = 0;\n\
                 match n { 0 => r, _ => R { id: 9 } };\n\
                 println(\"end\");",
                "dR41\nend\n",
                "BOUNDARY: arm hands out a LIVE enclosing local",
            ),
        ];
        for (body, expected, label) in rows {
            let src = format!("{hdr}fn main() {{\n{body}\n}}\n");
            assert_eq!(run_program(&src).as_deref(), Some(expected), "[{label}]");
        }
        // The two controls: both already ran exactly one body and must keep to
        // it — they are what prove the change did not widen into discarded
        // temporaries generally or into arm bindings generally.
        let call = format!("{hdr}fn main() {{ mk(1); println(\"dropped\"); }}\n");
        assert_eq!(
            run_program(&call).as_deref(),
            Some("dR1\ndropped\n"),
            "[discarded call result]"
        );
        let read = format!(
            "{hdr}fn main() {{\n\
             let o: Option[R] = Some(R {{ id: 1 }});\n\
             match o {{ Some(r) => {{ println(f\"saw{{r.id}}\") }} None => {{ println(\"none\") }} }};\n\
             println(\"dropped\");\n}}\n"
        );
        assert_eq!(
            run_program(&read).as_deref(),
            Some("saw1\ndR1\ndropped\n"),
            "[read-only arm]"
        );
    }

    /// B-2026-08-29-20 — the `let _ = <match>` SIBLING of
    /// `e2e_discarded_match_arm_value_runs_its_drop_body_once`, row for row.
    ///
    /// The bare-statement arm of `compile_stmt` has chained
    /// `discarded_match_value_tail` since B-2026-08-28-69, and its comment says
    /// the two discard spellings "cannot drift apart" because they share the
    /// same `&self` siblings. They had: the WILDCARD-LET arm chained only
    /// `discarded_owned_temp_tail` and `discarded_unit_variant_tail`, neither of
    /// which admits a `Match`, so `let _ = match n { 1 => { R { .. } } .. };`
    /// ran NO `Drop` body on any backend while `match n { .. };` ran one. The
    /// fix is the missing `.or_else` leg plus its guard disjunct.
    ///
    /// ROWS 3-5 ARE THE ONES THIS MOVED (0 bodies -> 1, on all three backends).
    /// Rows 1, 2 and 6 are pinned AS MEASURED, not as preferred, and every one
    /// of them is still wrong:
    ///
    ///  * 1 and 6 are agreed-silent, and 2 is a live run-vs-build DIVERGENCE —
    ///    compiled fires through the general match lowering (an arm-scope drop
    ///    of the binding), the interpreter does not. All three are arms that
    ///    HAND OUT A BINDING rather than mint a value. B-2026-08-29-5 fixed
    ///    the LEAK for that population ("a discarded branch construct strands
    ///    whatever its taken arm hands out"); the missing BODY, which is what
    ///    these rows measure, is B-2026-08-29-31.
    ///
    /// Row 2 is why the interpreter twin EXCLUDES `Identifier` at an arm tail
    /// rather than recursing whole: its predicate admits a bare identifier
    /// unconditionally, so inheriting that would fire this backend on row 1 as
    /// well — where compiled is silent — moving the divergence one row over
    /// instead of removing it. Making rows 1 and 2 agree needs the arm-binding
    /// ownership question answered for both backends at once, which is the
    /// separate design decision B-2026-08-29-31 carries.
    ///
    /// Also still silent and NOT in this table, measured while bounding the
    /// fix: the `if` spelling of the same discard (`let _ = if c { R { .. } }
    /// else { .. };` AND the bare-statement `if c { R { .. } } else { .. };`,
    /// so that gap predates this row and sits at the parent's site too), and a
    /// block-WRAPPED match (`let _ = { match .. };`, which neither gate
    /// recurses into). Both are B-2026-08-29-25.
    ///
    /// Memory is balanced in every cell, so no ASAN/LSan corpus reaches this
    /// class — only an absolute output expectation can see it.
    #[test]
    fn e2e_discarded_let_wildcard_match_runs_its_drop_body_once() {
        let hdr = "struct R { id: i64 }\n\
                   impl Drop for R { fn drop(mut ref self) { println(f\"dR{self.id}\") } }\n\
                   fn mk(i: i64) -> R { return R { id: i }; }\n";
        let rows: [(&str, &str, &str); 6] = [
            (
                "let o: Option[R] = Some(R { id: 1 });\n\
                 let _ = match o { Some(r) => { r } None => { R { id: 0 } } };\n\
                 println(\"dropped\");",
                "dR1\ndropped\n",
                "FIXED (B-2026-08-29-31): braced arm hands out the bound payload",
            ),
            (
                "let o: Option[R] = Some(R { id: 1 });\n\
                 let _ = match o { Some(r) => r, None => R { id: 0 } };\n\
                 println(\"dropped\");",
                "dR1\ndropped\n",
                "FIXED (B-2026-08-29-31): bare arm hands out the bound payload — was \
                 a live divergence, compiled firing here while the interpreter did not",
            ),
            (
                "let n = 1;\n\
                 let _ = match n { 1 => { R { id: 7 } } _ => { R { id: 0 } } };\n\
                 println(\"dropped\");",
                "dR7\ndropped\n",
                "FIXED: braced arm yields a fresh literal",
            ),
            (
                "let n = 1;\n\
                 let _ = match n { 1 => R { id: 7 }, _ => R { id: 0 } };\n\
                 println(\"dropped\");",
                "dR7\ndropped\n",
                "FIXED: bare arm yields a fresh literal",
            ),
            (
                "let n = 1;\n\
                 let _ = match n { 1 => mk(7), _ => mk(0) };\n\
                 println(\"dropped\");",
                "dR7\ndropped\n",
                "FIXED: arm yields a call result",
            ),
            (
                "let r = R { id: 41 };\n\
                 let n = 0;\n\
                 let _ = match n { 0 => r, _ => R { id: 9 } };\n\
                 println(\"end\");",
                "dR41\nend\n",
                "FIXED (B-2026-08-29-31): arm hands out an enclosing local",
            ),
        ];
        for (body, expected, label) in rows {
            let src = format!("{hdr}fn main() {{\n{body}\n}}\n");
            assert_eq!(run_program(&src).as_deref(), Some(expected), "[{label}]");
        }
        // The control that localized the defect: the SAME discard site with a
        // non-match RHS was correct throughout, which is what identifies this
        // as a missing gate leg rather than anything about discards generally.
        let call = format!("{hdr}fn main() {{ let _ = mk(1); println(\"dropped\"); }}\n");
        assert_eq!(
            run_program(&call).as_deref(),
            Some("dR1\ndropped\n"),
            "[control: let _ = call]"
        );
        // A read-only arm yields unit and must stay a no-op — the guard that
        // the widened gate did not start firing on arms that own nothing.
        let read = format!(
            "{hdr}fn main() {{\n\
             let o: Option[R] = Some(R {{ id: 1 }});\n\
             let _ = match o {{ Some(r) => {{ println(f\"saw{{r.id}}\") }} None => {{ println(\"none\") }} }};\n\
             println(\"dropped\");\n}}\n"
        );
        assert_eq!(
            run_program(&read).as_deref(),
            Some("saw1\ndR1\ndropped\n"),
            "[control: read-only arm]"
        );
    }

    /// B-2026-08-29-25 — a discarded `if` runs its arm value's `Drop` body,
    /// in BOTH statement forms, and a discard gate sees through a block
    /// wrapper.
    ///
    /// The `if` half was silent on all three backends: the gate the sibling
    /// `match` spelling goes through (`discarded_match_value_tail`) opened
    /// with a `Match`-only destructure, and the type resolution the battery
    /// needs (`try_track_discarded_user_drop_temp`) had no `If` arm either —
    /// so both halves had to land for the body to fire. The BARE-STATEMENT
    /// row is the one that shows the gap predates B-2026-08-29-20: it sits at
    /// B-2026-08-28-69's site too.
    ///
    /// The wrapper half was an interpreter-vs-compiled DIVERGENCE for the
    /// shapes compiled already admitted (a wrapped call, a wrapped struct
    /// literal) and an agreed silence for the wrapped `match`. Every row here
    /// is one `R`, constructed once and taken by nobody, so one body is due.
    #[test]
    fn e2e_discarded_if_and_block_wrapped_match_run_their_drop_body_once() {
        let hdr = "struct R { id: i64 }\n\
                   impl Drop for R { fn drop(mut ref self) { println(f\"dR{self.id}\") } }\n\
                   fn mk(i: i64) -> R { return R { id: i }; }\n";
        let rows: [(&str, &str, &str); 9] = [
            (
                "let n = 1;\n\
                 let _ = if n == 1 { R { id: 7 } } else { R { id: 0 } };\n\
                 println(\"end\");",
                "dR7\nend\n",
                "FIXED: `let _ = if …`, struct-literal branches",
            ),
            (
                "let n = 1;\n\
                 if n == 1 { R { id: 7 } } else { R { id: 0 } };\n\
                 println(\"end\");",
                "dR7\nend\n",
                "FIXED: bare-statement `if …` — predates B-2026-08-29-20",
            ),
            (
                "let n = 1;\n\
                 let _ = if n == 1 { mk(7) } else { mk(0) };\n\
                 println(\"end\");",
                "dR7\nend\n",
                "FIXED: `let _ = if …`, call branches",
            ),
            (
                "let n = 1;\n\
                 if n == 1 { mk(7) } else { mk(0) };\n\
                 println(\"end\");",
                "dR7\nend\n",
                "FIXED: bare-statement `if …`, call branches",
            ),
            (
                "let n = 1;\n\
                 let _ = if n == 2 { R { id: 1 } } else if n == 1 { R { id: 7 } } else { R { id: 0 } };\n\
                 println(\"end\");",
                "dR7\nend\n",
                "FIXED: `else if` chain — the else branch is another `If`",
            ),
            (
                "let n = 1;\n\
                 let _ = if n == 1 { match n { 1 => { R { id: 7 } } _ => { R { id: 3 } } } } else { R { id: 0 } };\n\
                 println(\"end\");",
                "dR7\nend\n",
                "FIXED: a `match` nested at an `if` branch tail",
            ),
            (
                "let n = 1;\n\
                 let _ = { match n { 1 => { R { id: 7 } } _ => { R { id: 0 } } } };\n\
                 println(\"end\");",
                "dR7\nend\n",
                "FIXED: block-wrapped match, `let _ =` form",
            ),
            (
                "let n = 1;\n\
                 { match n { 1 => { R { id: 7 } } _ => { R { id: 0 } } } };\n\
                 println(\"end\");",
                "dR7\nend\n",
                "FIXED: block-wrapped match, bare-statement form",
            ),
            (
                "let _ = { mk(7) };\n\
                 println(\"end\");",
                "dR7\nend\n",
                "block-wrapped call — compiled fired all along; the interpreter twin \
                 is what this row moved",
            ),
        ];
        for (body, expected, label) in rows {
            let src = format!("{hdr}fn main() {{\n{body}\n}}\n");
            assert_eq!(run_program(&src).as_deref(), Some(expected), "[{label}]");
        }
        // AN `if` BRANCH THAT HANDS OUT AN ENCLOSING LOCAL, both statement
        // forms, measured against the `match` spelling of the same shape —
        // the two agree exactly, which is what says the widening did not give
        // `if` a different answer from its sibling.
        //
        // The bare form is the GUARD RAIL and the reason the gate excludes an
        // `Identifier` branch tail: `r` is still in scope, so its scope-exit
        // body already fires and is correct at ONE. Firing the discard walker
        // on top prints `dR41` twice — the failure the sibling `match` arm's
        // liveness gate was measured into existence by, and this row fails at
        // 2 if the `If` arm's gate is removed.
        //
        // The `let _ =` form is PINNED AT THE DEFECT: `r` is handed out and
        // nothing runs its body on any backend. B-2026-08-29-5 fixed the
        // LEAK for that population; the missing BODY is B-2026-08-29-31, and
        // its `match` twin is pinned identically in
        // `e2e_discarded_let_wildcard_match_runs_its_drop_body_once`.
        for (stmt, expected, label) in [
            (
                "if n == 0 { r } else { R { id: 9 } };",
                "dR41\nend\n",
                "guard: bare form — scope-exit body must stay at ONE",
            ),
            (
                "let _ = if n == 0 { r } else { R { id: 9 } };",
                "dR41\nend\n",
                "FIXED (B-2026-08-29-31): branch hands out an enclosing local",
            ),
        ] {
            let src = format!(
                "{hdr}fn main() {{\n\
                 let r = R {{ id: 41 }};\n\
                 let n = 0;\n\
                 {stmt}\n\
                 println(\"end\");\n}}\n"
            );
            assert_eq!(
                run_program(&src).as_deref(),
                Some(expected),
                "[{label} — {stmt}]"
            );
        }
        // FIXED (B-2026-08-29-30). These two were pinned at the DEFECT here —
        // `"end\n"`, no body on any backend — because with no `else` there is
        // no phi for the statement site to own, so freeing the arm's value
        // needed a registration INSIDE the arm rather than a wider gate at the
        // statement. It has one now (`discarded_arm_owned_aggregate_tail`), so
        // the pin flips to the body that was always due.
        for stmt in [
            "let _ = if n == 1 { R { id: 7 } };",
            "let _ = if n == 1 { mk(7) };",
        ] {
            let src = format!("{hdr}fn main() {{\nlet n = 1;\n{stmt}\nprintln(\"end\");\n}}\n");
            assert_eq!(
                run_program(&src).as_deref(),
                Some("dR7\nend\n"),
                "[FIXED: `if` with no `else` — {stmt}]"
            );
        }
        // FIXED (B-2026-08-29-31): a moved local reached through a wrapper.
        // This pinned the shared SILENCE — `let _ = r` was correct at one body
        // because the let-rebind hook retracts the local's own slot, and no
        // such hook fires through `{ … }`. The wrapper is now a recorded
        // discarding position in its own right, so the block stops handing the
        // buffer to a consumer that does not exist and the local keeps its own
        // scope-exit body. At `KARAC_OPT_LEVEL=0` this also went from 9 B
        // stranded to clean — the body had been firing over a zeroed `cap`.
        let wrapped_local = format!(
            "{hdr}fn main() {{\n\
             let r = R {{ id: 41 }};\n\
             let _ = {{ r }};\n\
             println(\"end\");\n}}\n"
        );
        assert_eq!(
            run_program(&wrapped_local).as_deref(),
            Some("dR41\nend\n"),
            "[FIXED: `let _ = {{ r }}` — moved local through a wrapper]"
        );
    }

    /// B-2026-08-29-30 — the two halves of the row fd4e80f filed against itself,
    /// left, found by filling in its matrix in both directions.
    ///
    ///   * the LEAK half: a bare LITERAL statement reached NO gate. That commit chained
    ///     `discarded_match_value_tail` at both discard sites, but the
    ///     bare-statement arm still chained no `discarded_owned_literal_tail`
    ///     leg — the mirror of what B-2026-08-29-20 fixed one site over, and
    ///     refuted by the same argument its comment makes. The only cell of
    ///     this family that is also a LEAK: `H { s: payload() };` stranded
    ///     36 B where `let _ = H { s: payload() };` was clean
    ///     (`asan_bare_literal_statement_discard_owns_its_heap`).
    ///
    ///   * the no-`else` half: a no-`else` `if` was a live run-vs-build DIVERGENCE — the
    ///     interpreter's statement-site arm gated on liveness alone, which such
    ///     an `if` passes, so it fired a body both compiled backends cannot.
    ///     `compile_if`'s merge yields a placeholder with no `else`, so the
    ///     value never reaches this site. Row 3 pinned the agreed silence that
    ///     restored; it now pins the BODY, because B-2026-08-29-30's remaining
    ///     half landed the arm-level owner that lets all three fire together.
    #[test]
    fn e2e_discarded_literal_statement_and_no_else_if() {
        let hdr = "struct R { id: i64 }\n\
                   impl Drop for R { fn drop(mut ref self) { println(f\"dR{self.id}\") } }\n";
        let rows: [(&str, &str, &str); 3] = [
            (
                "R { id: 7 };\nprintln(\"end\");",
                "dR7\nend\n",
                "FIXED: bare struct-literal statement",
            ),
            (
                "{ R { id: 7 } };\nprintln(\"end\");",
                "dR7\nend\n",
                "FIXED: block-wrapped struct literal, bare statement",
            ),
            (
                "let n = 1;\nif n == 1 { R { id: 7 } };\nprintln(\"end\");",
                "dR7\nend\n",
                "FIXED: a no-`else` `if`, owned from inside the arm",
            ),
        ];
        for (body, expected, label) in rows {
            let src = format!("{hdr}fn main() {{\n{body}\n}}\n");
            assert_eq!(run_program(&src).as_deref(), Some(expected), "[{label}]");
        }
        // A place-moving tuple is the hazard the literal leg brings with it:
        // the source's own cleanup is retracted so this walk is the single
        // owner, which is a DOUBLED body if the retraction is missed. Both
        // spellings must sit at exactly one.
        for (body, label) in [
            (
                "let r = R { id: 1 };\n(r, 20);\nprintln(\"end\");",
                "control: bare tuple statement moving a place element",
            ),
            (
                "let r = R { id: 1 };\nlet _ = (r, 20);\nprintln(\"end\");",
                "control: wildcard-let tuple moving a place element",
            ),
        ] {
            let src = format!("{hdr}fn main() {{\n{body}\n}}\n");
            assert_eq!(
                run_program(&src).as_deref(),
                Some("dR1\nend\n"),
                "[{label}]"
            );
        }
    }

    /// B-2026-08-29-30 (remaining half) — a no-`else` `if` whose taken arm
    /// MINTS an owned value now owns it, on both compiled backends.
    ///
    /// The value was reachable from neither discard site. `compile_if`'s merge
    /// yields a const-0 placeholder when there is no `else`, so the STATEMENT
    /// site never sees the arm's value at all — which is why no widening of
    /// `discarded_match_value_tail` could have reached it, and why the fix is a
    /// registration inside the arm's own frame instead. B-2026-08-29-5 put one
    /// there and gated it on `expr_yields_fresh_owned_temp` (Call / MethodCall);
    /// that leg owns a Vec/String buffer, a Map/Set handle and an RC box, and a
    /// plain user struct is none of the three, so even the CALL spelling
    /// registered nothing.
    ///
    /// All four spellings were silent on all three backends and leaked one
    /// allocation per evaluation — agreed, so invisible to every A/B parity
    /// gate. Twin: `test_no_else_if_arm_owns_the_value_it_mints`, whose table
    /// is these shapes in this order. Leak leg:
    /// `asan_no_else_if_arm_owns_the_value_it_mints`.
    ///
    /// The CONTROLS are the fix's safety argument, each a shape where an
    /// over-eager owner is a DOUBLE free rather than a missing body: a tail
    /// naming a live local, an `if` WITH an `else` (owned by the statement
    /// site), a struct literal whose field names a live local, and the branch
    /// not taken.
    #[test]
    fn e2e_no_else_if_arm_owns_the_value_it_mints() {
        let hdr = "struct R { id: i64, name: String }\n\
                   impl Drop for R { fn drop(mut ref self) { println(f\"dR{self.id}\") } }\n\
                   struct H { s: String }\n\
                   enum E { A(R), B }\n\
                   impl Drop for E { fn drop(mut ref self) { println(\"dE\") } }\n\
                   fn mk(i: i64) -> R { return R { id: i, name: f\"heap-{i}\" }; }\n";
        for (label, body, want) in [
            // ── the row's four spellings ──────────────────────────────
            (
                "wildcard-let-struct-literal",
                "let _ = if n == 1 { R { id: 7, name: f\"h\" } };",
                "dR7\nend\n",
            ),
            (
                "wildcard-let-call",
                "let _ = if n == 1 { mk(7) };",
                "dR7\nend\n",
            ),
            (
                "bare-statement-struct-literal",
                "if n == 1 { R { id: 7, name: f\"h\" } };",
                "dR7\nend\n",
            ),
            ("bare-statement-call", "if n == 1 { mk(7) };", "dR7\nend\n"),
            // ── shapes the widened admission gate brings with it ──────
            (
                "block-wrapped-rhs",
                "let _ = { if n == 1 { mk(19) } };",
                "dR19\nend\n",
            ),
            (
                "nested-branch-tail",
                "let d = 1;\nlet _ = if n == 1 { if d == 1 { mk(6) } else { mk(7) } };",
                "dR6\nend\n",
            ),
            (
                "nested-match-tail",
                "let d = 1;\nlet _ = if n == 1 { match d { 1 => mk(6), _ => mk(7) } };",
                "dR6\nend\n",
            ),
            (
                "tuple-literal-tail",
                "let _ = if n == 1 { (mk(12), 20) };",
                "dR12\nend\n",
            ),
            (
                "inline-enum-ctor-tail",
                "let _ = if n == 1 { E.A(mk(8)) };",
                "dE\ndR8\nend\n",
            ),
            (
                "unit-variant-tail",
                "let _ = if n == 1 { E.B };",
                "dE\nend\n",
            ),
            (
                "loop-body-fires-per-iteration",
                "for i in 0..3 { if n == 1 { mk(i) }; }",
                "dR0\ndR1\ndR2\nend\n",
            ),
            // ── controls: an over-eager owner here is a DOUBLE free ───
            (
                "control: place-tail-bare",
                "let r = mk(1);\nif n == 1 { r };",
                "dR1\nend\n",
            ),
            (
                // FIXED by B-2026-08-29-31, which stopped a wildcard `let`
                // marking its RHS as an escaping position. This pinned `end`
                // when it was written: the local was marked moved-out and
                // nothing ran its body. It now keeps its own scope-exit body,
                // at ONE — still a control, for the opposite direction.
                "control: place-tail-wildcard-let",
                "let r = mk(1);\nlet _ = if n == 1 { r };",
                "dR1\nend\n",
            ),
            (
                "control: else-struct-literal",
                "let _ = if n == 1 { R { id: 2, name: f\"a\" } } else { R { id: 3, name: f\"b\" } };",
                "dR2\nend\n",
            ),
            (
                "control: else-call",
                "let _ = if n == 1 { mk(4) } else { mk(5) };",
                "dR4\nend\n",
            ),
            (
                "control: else-if-chain",
                "let _ = if n == 0 { mk(20) } else if n == 1 { mk(21) } else { mk(22) };",
                "dR21\nend\n",
            ),
            (
                "control: field-is-a-place",
                "let s = f\"live\";\nlet _ = if n == 1 { H { s: s } };\nprintln(\"kept\");",
                "kept\nend\n",
            ),
            (
                "control: branch-not-taken",
                "let _ = if n == 2 { mk(9) };",
                "end\n",
            ),
            (
                "control: branch-not-taken-place-tail",
                "let r = mk(18);\nlet _ = if n == 2 { r };\nprintln(\"still\");",
                "dR18\nstill\nend\n",
            ),
        ] {
            let src =
                format!("{hdr}fn main() {{\nlet n = 1;\n{body}\nprintln(\"end\");\n}}\n");
            assert_eq!(run_program(&src).as_deref(), Some(want), "[{label}]");
        }
    }

    /// B-2026-08-29-31 — the `let _ =` spelling of a discarded branch now owns
    /// whatever its arm hands out, on all three backends.
    ///
    /// B-2026-08-29-5 fixed the BARE-STATEMENT form. The wildcard-`let` form of
    /// the same `if` / `match` / block ran NO `Drop` body anywhere and leaked
    /// one allocation per evaluation, because nothing told the arm its value
    /// had no consumer: a wildcard `let` was not a recorded discarding
    /// position, and — separately — `note_escaping_stmt_sites` marked its RHS
    /// as ESCAPING, which cleared the conditional-move drop flag of whatever
    /// local the taken arm named. Both halves had to go.
    ///
    /// TWO POPULATIONS, and they are fixed by opposite means, which is why the
    /// row could not be closed with one change:
    ///
    ///   * the tail names an ENCLOSING LOCAL — leave the source armed and its
    ///     own scope-exit body is the single fire (`*-local` rows);
    ///   * the tail names the arm's own PATTERN BINDING, which has already left
    ///     scope — nothing is left to arm, so the discard site must own it
    ///     (`payload-*` rows).
    ///
    /// Twin: `test_wildcard_let_discard_owns_what_its_arm_hands_out`, same
    /// shapes in the same order. Leak leg:
    /// `asan_wildcard_let_discard_owns_what_its_arm_hands_out`.
    ///
    /// The DOUBLE-OWN rows are the ones that cost the most to get right. A
    /// bare value-block has no `discard_stmt_owns_value` to stand down
    /// against, so making it a discarding position made it register a second
    /// owner beside the statement frame's and the body ran TWICE — first for
    /// `{ match … }`, and then, after a too-narrow first guard, for
    /// `{ mk(7) }`. Both are pinned here at ONE.
    /// B-2026-08-29-32 — the BODY-COUNT side of teaching the discard battery
    /// to register memory for a body-less aggregate.
    ///
    /// The row itself is invisible here: `P` has no `Drop`, so its leak
    /// changes no transcript and `memory_sanitizer` is the fixture that sees
    /// it. What THIS file is for is the double-own risk the fix runs. The
    /// registration added below `try_track_discarded_user_drop_temp`'s early
    /// return is reached by falling THROUGH a decision that used to return, so
    /// the way it goes wrong is a type that already had an owner acquiring a
    /// second one — which shows up as a doubled `Drop` body long before it
    /// shows up as a double free. Each row here must print its body exactly
    /// once.
    /// B-2026-08-29-36 — a projection scrutinee DEEPER than one hop
    /// (`match w.s.e { .. }`) whose arm materializes the payload.
    ///
    /// B-2026-08-29-33 taught the one-hop form to stop the owner re-running a
    /// payload body the arm already ran, and keyed its mask on a single field
    /// index. A deeper chain resolved to nothing, so the owner's walk stayed
    /// unmasked and fired a SECOND time — on the interpreter against the live
    /// object (`dR8`), on both compiled backends against the slot the move-out
    /// cap-zeroed (`dR0`). One defect, two symptoms: an extra body everywhere
    /// and a run-vs-build divergence in what that body printed.
    ///
    /// The mask is now a PATH. `FieldSkipTree::nested` has been consumed by
    /// the emitter since B-2026-08-28-23; what was missing was anything that
    /// built a non-empty one.
    ///
    /// Every row here must read exactly as its one-hop analogue does.
    /// B-2026-08-29-38 — a METHOD's FRESH-TEMP argument whose value the callee
    /// hands back out.
    ///
    /// The passthrough guard that exists for exactly this computes the right
    /// answer and then acts only `if let ExprKind::Identifier(var_name)`, which
    /// a temp never is — so the caller-side temp drop fired AND the returned
    /// value's own binding fired, two bodies for one object, against one in the
    /// interpreter. The fix feeds the same predicate into `escapes_frame`,
    /// which the registrar reads off the VALUE rather than off a name.
    ///
    /// MEMORY: the row left open whether the extra body came with a second
    /// free. It does not — measured under valgrind with a `String`-carrying
    /// payload, 0 errors and no leak before or after. Bodies only.
    #[test]
    fn e2e_method_fresh_temp_arg_handed_back_runs_one_body() {
        let hdr = "struct R { id: i64, name: String }\n\
                   impl Drop for R { fn drop(mut ref self) { println(f\"drop {self.id} {self.name}\") } }\n\
                   fn mk(i: i64) -> R { return R { id: i, name: f\"h{i}\" }; }\n\
                   enum Box2 { Full(R), Empty }\n\
                   struct T { n: i64 }\n\
                   impl T {\n\
                   \x20   fn take(ref self, b: Box2) -> R {\n\
                   \x20       match b { Box2.Full(r) => { return r; } Box2.Empty => { return mk(0); } }\n\
                   \x20   }\n\
                   \x20   fn keep(ref self, b: Box2) -> i64 {\n\
                   \x20       match b { Box2.Full(r) => { return r.id; } Box2.Empty => { return 0; } }\n\
                   \x20   }\n\
                   }\n\
                   struct K { n: i64 }\n\
                   impl K { fn g(ref self, r: R) -> i64 { return r.id; } }\n";
        for (label, body, want) in [
            (
                "the row: enum temp whose payload is handed back",
                "let t = T { n: 1 };\n\
                 let r = t.take(Box2.Full(mk(7)));\n\
                 println(f\"got {r.id}\");",
                "got 7\ndrop 7 h7\n",
            ),
            (
                "same, result read twice so its own body is unmistakably the survivor",
                "let t = T { n: 1 };\n\
                 let r = t.take(Box2.Full(mk(7)));\n\
                 println(f\"got {r.id}\");\n\
                 println(f\"again {r.id}\");",
                "got 7\nagain 7\ndrop 7 h7\n",
            ),
            // The NAMED spelling was always correct — it is what the guard
            // reaches — and is the in-tree proof that this row is about the
            // argument's SYNTACTIC FORM, not about passthrough analysis.
            (
                "control: the same call with a NAMED binding argument",
                "let t = T { n: 1 };\n\
                 let b = Box2.Full(mk(7));\n\
                 let r = t.take(b);\n\
                 println(f\"got {r.id}\");",
                "got 7\ndrop 7 h7\n",
            ),
            // Controls the widened `escapes_frame` must keep DECLINING: the
            // callee consumes the value instead of handing it back, so the
            // caller-side temp drop is the only owner and must still fire.
            (
                "control: method consumes a struct temp and returns a scalar",
                "let k = K { n: 1 };\n\
                 let n = k.g(mk(7));\n\
                 println(f\"n{n}\");",
                "drop 7 h7\nn7\n",
            ),
        ] {
            let src = format!("{hdr}fn main() {{\n{body}\n}}\n");
            assert_eq!(run_program(&src).as_deref(), Some(want), "[{label}]");
        }
        // PINNED AT KNOWN DEFECTS, not asserted as correct.
        //
        // (a) The METHOD leg's OTHER spelling — a struct temp escaping inside a
        // returned `Option.Some(r)` rather than as the bare param — still runs
        // two bodies compiled against one interpreted. It is NOT reachable by
        // widening a predicate: these are documented conservative-true, and the
        // non-escaping calls in this very program (`false`, `false`) correctly
        // print their body today. A conservative-true answer would skip the
        // caller-side drop on ALL THREE calls, trading one doubled body for two
        // LOST ones and a leak. It needs the per-path callee-side ownership
        // flip that `fn_conditionally_returns_param_bare` has for the bare
        // form. Filed separately.
        //
        // (b) `t.keep(..)`, whose arm binds the payload but returns a SCALAR,
        // runs no body at all on the interpreter against one compiled — the
        // opposite direction, and a different defect. Filed separately.
        let hdr2 = "struct R { id: i64, name: String }\n\
                    impl Drop for R { fn drop(mut ref self) { println(f\"drop {self.id} {self.name}\") } }\n\
                    fn mk(i: i64) -> R { return R { id: i, name: f\"h{i}\" }; }\n\
                    enum Box2 { Full(R), Empty }\n\
                    struct T { n: i64 }\n\
                    impl T { fn keep(ref self, b: Box2) -> i64 {\n\
                    \x20   match b { Box2.Full(r) => { return r.id; } Box2.Empty => { return 0; } } } }\n\
                    struct K { n: i64 }\n\
                    impl K { fn f(ref self, r: R, keep: bool) -> Option[R] {\n\
                    \x20   if keep { return Option.Some(r); }\n\
                    \x20   return Option.None; } }\n";
        assert_eq!(
            run_program(&format!(
                "{hdr2}fn main() {{\n\
                 let k = K {{ n: 1 }};\n\
                 let _ = k.f(mk(3), false); println(\"a\");\n\
                 let _ = k.f(mk(4), true);  println(\"b\");\n\
                 let _ = k.f(mk(5), false); println(\"c\");\n}}\n"
            ))
            .as_deref(),
            Some("drop 3 h3\na\ndrop 4 h4\ndrop 4 h4\nb\ndrop 5 h5\nc\n"),
            "[pinned DEFECT (a): temp escaping inside a returned Option ctor]"
        );
        assert_eq!(
            run_program(&format!(
                "{hdr2}fn main() {{\n\
                 let t = T {{ n: 1 }};\n\
                 let n = t.keep(Box2.Full(mk(7)));\n\
                 println(f\"n{{n}}\");\n}}\n"
            ))
            .as_deref(),
            Some("drop 7 h7\nn7\n"),
            "[pinned DEFECT (b): compiled runs the body the interpreter loses]"
        );
    }

    /// B-2026-08-29-43 — a MIXED struct literal over a struct with its OWN
    /// `impl Drop`: some Drop-bearing fields moved in from a param VIEW, some
    /// minted fresh.
    ///
    /// The view's body belongs to the caller under caller-retains, so this
    /// binding must not run it; the fresh field's body belongs to nobody else,
    /// so it must. Before the fix the whole literal kept its walk and the view
    /// doubled — agreed across all three backends, which is why no A/B gate
    /// caught it.
    ///
    /// The danger in fixing it is the OPPOSITE failure: the only wrapper
    /// surgery available for an own-`Drop` struct used to be all-or-nothing,
    /// and applying that here would have silenced the fresh field too. So every
    /// row below pins BOTH halves — the view fires once, the fresh field fires
    /// once — and the boundary rows (all-views, all-fresh, no-own-`Drop`) pin
    /// that the neighbouring paths did not move.
    /// B-2026-08-29-44 — a WHOLE-VALUE REBIND (`let s2 = s;`) after a MIXED
    /// wrap re-armed the walk the wrap's mask had just withheld.
    ///
    /// Every mask in this family is keyed on the BINDING, and a rebind
    /// registers the destination afresh — so the param view's body ran a
    /// second time. The ALL-VIEWS case has no such hole: it marks the binding
    /// a param view and view-ness already propagates (B-2026-08-01-15), which
    /// is why only the MIXED spellings lost their mask.
    ///
    /// Registering full and disarming afterwards does NOT work at a `let` —
    /// the disarm helpers re-register rather than replace, leaving the
    /// destination with two walkers and MORE bodies. The fix inherits the
    /// source's masks first and builds the walker already masked.
    #[test]
    fn e2e_whole_value_rebind_inherits_the_wrap_mask() {
        let hdr = "struct R { id: i64, name: String }\n\
                   impl Drop for R { fn drop(mut ref self) { println(f\"dR{self.id}\") } }\n\
                   fn mk(i: i64) -> R { return R { id: i, name: f\"heap-{i}\" }; }\n\
                   enum W2 { Two(R, R), None2 }\n\
                   struct S3 { a: R, b: R }\n\
                   struct S1 { r: R }\n";
        for (label, fns, main, want) in [
            (
                "struct literal MIXED, then rebind",
                "fn take(r: R) -> i64 { let s = S3 { a: r, b: mk(2) }; let s2 = s; return 7; }",
                "let v = take(mk(1)); println(f\"v={v}\");",
                "dR2\ndR1\nv=7\n",
            ),
            (
                "tuple MIXED, then rebind",
                "fn take(r: R) -> i64 { let t = (r, 5); let t2 = t; return 7; }",
                "let v = take(mk(1)); println(f\"v={v}\");",
                "dR1\nv=7\n",
            ),
            (
                "rebound twice — the mask survives the chain",
                "fn take(r: R) -> i64 { let s = S3 { a: r, b: mk(2) }; let s2 = s; let s3 = s2; return 7; }",
                "let v = take(mk(1)); println(f\"v={v}\");",
                "dR2\ndR1\nv=7\n",
            ),
            // CONTROLS: the same wraps WITHOUT a rebind were always correct,
            // which is what isolates the rebind as the trigger; and the
            // all-views wrap WITH one was correct through view-ness
            // propagation, the mechanism the mixed case lacks.
            (
                "control: struct MIXED, no rebind",
                "fn take(r: R) -> i64 { let s = S3 { a: r, b: mk(2) }; return 7; }",
                "let v = take(mk(1)); println(f\"v={v}\");",
                "dR2\ndR1\nv=7\n",
            ),
            (
                "control: tuple MIXED, no rebind",
                "fn take(r: R) -> i64 { let t = (r, 5); return 7; }",
                "let v = take(mk(1)); println(f\"v={v}\");",
                "dR1\nv=7\n",
            ),
            (
                "control: ALL-VIEWS struct, then rebind",
                "fn take(r: R) -> i64 { let s = S1 { r: r }; let s2 = s; return 7; }",
                "let v = take(mk(1)); println(f\"v={v}\");",
                "dR1\nv=7\n",
            ),
            (
                "control: enum ctor MIXED, no rebind",
                "fn take(r: R) -> i64 { let w = W2.Two(r, mk(2)); return 7; }",
                "let v = take(mk(1)); println(f\"v={v}\");",
                "dR2\ndR1\nv=7\n",
            ),
        ] {
            let src = format!("{hdr}{fns}\nfn main() {{ {main} }}\n");
            assert_eq!(run_program(&src).as_deref(), Some(want), "[{label}]");
        }
        // PINNED AT THE DEFECT, and deliberately so. The ENUM-CTOR spelling
        // still doubles, on BOTH backends, so it stays an agreed gap rather
        // than a divergence. The interpreter CAN fix it alone — transferring
        // `moved_out_enum_payload_slots` on the rebind makes it print the due
        // `dR2 dR1` — but codegen cannot follow: it derives a constructor's
        // view slots from the ctor EXPRESSION at the `let` and stores nothing
        // per variable, so a rebind has no mask to inherit. Landing the
        // interpreter half alone was MEASURED here during this fix and gave
        // `dR2 dR1` against `dR1 dR2 dR1` — an agreed defect turned into a
        // run-vs-build split, the trade this family keeps refusing. Filed
        // separately; it needs a per-var store on the codegen side first.
        let enum_rebind = format!(
            "{hdr}fn take(r: R) -> i64 {{ let w = W2.Two(r, mk(2)); let w2 = w; return 7; }}\n\
             fn main() {{ let v = take(mk(1)); println(f\"v={{v}}\"); }}\n"
        );
        assert_eq!(
            run_program(&enum_rebind).as_deref(),
            Some("dR1\ndR2\ndR1\nv=7\n"),
            "[pinned DEFECT: enum ctor MIXED then rebind — agreed, awaiting a codegen per-var store]"
        );
    }

    #[test]
    fn e2e_param_view_field_moved_back_out_runs_one_body() {
        let hdr = "struct R { id: i64, name: String }\n\
                   impl Drop for R { fn drop(mut ref self) { println(f\"dR{self.id}\") } }\n\
                   fn mk(i: i64) -> R { return R { id: i, name: f\"heap-{i}\" }; }\n\
                   struct S1 { r: R }\n\
                   struct S3 { a: R, b: R }\n\
                   struct D1 { r: R }\n\
                   impl Drop for D1 { fn drop(mut ref self) { println(\"dD\") } }\n\
                   struct W1 { s: S1 }\n\
                   struct O { r: R }\n\
                   struct O3 { o: O }\n\
                   struct H { n: i64 }\n";
        for (label, fns, main, want) in [
            // THE ROW. `let s = S1 { r: r }` wraps a param view; `let x = s.r`
            // reads it straight back out. The caller runs that body, so `x`
            // must not register one — this printed `dR1 dR1` on all four
            // surfaces, agreed, which is why no A/B parity gate could see it.
            (
                "all-views wrap, then move the view back out",
                "fn take(r: R) -> i64 { let s = S1 { r: r }; let x = s.r; return 7; }",
                "let v = take(mk(1)); println(f\"v={v}\");",
                "dR1\nv=7\n",
            ),
            // NO WRAP AT ALL. The same read straight off a by-value param is
            // the same caller-owned move, and doubled the same way — which is
            // what shows the subject is view-ness, not the wrap.
            (
                "raw owned param, direct field read",
                "fn take(o: O) -> i64 { let x = o.r; return 7; }",
                "let v = take(O { r: mk(1) }); println(f\"v={v}\");",
                "dR1\nv=7\n",
            ),
            (
                "raw owned param, two-hop field read",
                "fn take(w: O3) -> i64 { let x = w.o.r; return 7; }",
                "let v = take(O3 { o: O { r: mk(1) } }); println(f\"v={v}\");",
                "dR1\nv=7\n",
            ),
            // DEPTH. One test at the chain ROOT settles any depth, because
            // everything reachable through a view is a view.
            (
                "two-hop chain through two wraps",
                "fn take(r: R) -> i64 { let s = S1 { r: r }; let w = W1 { s: s }; let x = w.s.r; return 7; }",
                "let v = take(mk(1)); println(f\"v={v}\");",
                "dR1\nv=7\n",
            ),
            // The move-out destination inherits view-ness, so a later whole-
            // value rebind of it does not re-arm what this withheld.
            (
                "move out, then rebind the destination",
                "fn take(r: R) -> i64 { let s = S1 { r: r }; let x = s.r; let y = x; return 7; }",
                "let v = take(mk(1)); println(f\"v={v}\");",
                "dR1\nv=7\n",
            ),
            // READING `x` does not change who owns it.
            (
                "move out, then read the destination",
                "fn take(r: R) -> i64 { let s = S1 { r: r }; let x = s.r; return x.id; }",
                "let v = take(mk(1)); println(f\"v={v}\");",
                "dR1\nv=1\n",
            ),
            // BOTH fields views: the binding is a view whole, and moving one
            // out leaves both bodies to the caller.
            (
                "both fields views, move one out",
                "fn take(p: R, q: R) -> i64 { let s = S3 { a: p, b: q }; let x = s.a; return 7; }",
                "let v = take(mk(1), mk(2)); println(f\"v={v}\");",
                "dR2\ndR1\nv=7\n",
            ),
            // OWN-`Drop` WRAPPER. This wrap never becomes a view — `D1`'s body
            // is the binding's own — so the per-field record is the only thing
            // that can answer for `d.r`. `dD` still fires; only the doubled
            // `dR1` goes.
            (
                "own-Drop wrapper, move the view out",
                "fn take(r: R) -> i64 { let d = D1 { r: r }; let x = d.r; return 7; }",
                "let v = take(mk(1)); println(f\"v={v}\");",
                "dD\ndR1\nv=7\n",
            ),
            // METHOD FRAME. Codegen doubled here where the interpreter did not
            // (its caller-side fire is wired into `eval_call` alone), so this
            // shape was a run-vs-build DIVERGENCE before the fix — the one
            // place in the family where the two backends disagreed. Fixing
            // codegen converges it; the interpreter's method-frame bail is what
            // keeps its single body from going to zero.
            (
                "method frame, all-views wrap",
                "impl H { fn take(ref self, r: R) -> i64 { let s = S1 { r: r }; let x = s.r; return 7; } }",
                "let h = H { n: 0 }; let v = h.take(mk(1)); println(f\"v={v}\");",
                "dR1\nv=7\n",
            ),
            // A REBIND on the way in is still a view.
            (
                "param rebound, then wrapped, then moved out",
                "fn take(r: R) -> i64 { let m = r; let s = S1 { r: m }; let x = s.r; return 7; }",
                "let v = take(mk(1)); println(f\"v={v}\");",
                "dR1\nv=7\n",
            ),
            // CONTROLS. Each is the same statement over a LOCAL source, and
            // each was already correct — which is what isolates view-ness as
            // the missing half rather than the move-out machinery, and what
            // this fix must not disturb.
            (
                "control: local source, move out",
                "fn take() -> i64 { let s = S1 { r: mk(1) }; let x = s.r; return 7; }",
                "let v = take(); println(f\"v={v}\");",
                "dR1\nv=7\n",
            ),
            (
                "control: all-views wrap, NO move out",
                "fn take(r: R) -> i64 { let s = S1 { r: r }; return 7; }",
                "let v = take(mk(1)); println(f\"v={v}\");",
                "dR1\nv=7\n",
            ),
            (
                "control: own-Drop wrapper, local source",
                "fn take() -> i64 { let d = D1 { r: mk(1) }; let x = d.r; return 7; }",
                "let v = take(); println(f\"v={v}\");",
                "dR1\ndD\nv=7\n",
            ),
            (
                "control: method frame, local source",
                "impl H { fn take(ref self) -> i64 { let s = S1 { r: mk(1) }; let x = s.r; return 7; } }",
                "let h = H { n: 0 }; let v = h.take(); println(f\"v={v}\");",
                "dR1\nv=7\n",
            ),
            // CONTROL, and the one that keeps the fix from being a blunt
            // instrument: moving the FRESH field out of a mixed wrap must
            // still register a body, because nobody else runs it.
            (
                "control: mixed wrap, move the FRESH field out",
                "fn take(r: R) -> i64 { let s = S3 { a: r, b: mk(2) }; let x = s.b; return 7; }",
                "let v = take(mk(1)); println(f\"v={v}\");",
                "dR2\ndR1\nv=7\n",
            ),
        ] {
            let src = format!("{hdr}{fns}\nfn main() {{ {main} }}\n");
            assert_eq!(run_program(&src).as_deref(), Some(want), "[{label}]");
        }
        // PINNED AT THE DEFECT. The TUPLE spelling of the same move
        // (`let t = (r, 5); let x = t.0;`) still doubles, on BOTH backends, so
        // it stays an agreed gap rather than a divergence. It needs the tuple
        // peer of the per-field record this fix added — `param_view_locals`
        // never covers it, since a tuple literal's view elements are masked per
        // index and the binding is not marked a view. Filed separately.
        let tuple_moveout = format!(
            "{hdr}fn take(r: R) -> i64 {{ let t = (r, 5); let x = t.0; return 7; }}\n\
             fn main() {{ let v = take(mk(1)); println(f\"v={{v}}\"); }}\n"
        );
        assert_eq!(
            run_program(&tuple_moveout).as_deref(),
            Some("dR1\ndR1\nv=7\n"),
            "[pinned DEFECT: tuple wrap then element move-out — agreed, awaiting a tuple record]"
        );
    }

    #[test]
    fn e2e_mixed_owndrop_literal_masks_only_the_view_body() {
        let hdr = "struct R { id: i64, name: String }\n\
                   impl Drop for R { fn drop(mut ref self) { println(f\"dR{self.id}\") } }\n\
                   fn mk(i: i64) -> R { return R { id: i, name: f\"heap-{i}\" }; }\n\
                   struct Sd3 { a: R, b: R }\n\
                   impl Drop for Sd3 { fn drop(mut ref self) { println(\"dSd3\") } }\n\
                   struct Sd { r: R }\n\
                   impl Drop for Sd { fn drop(mut ref self) { println(\"dSd\") } }\n\
                   struct Plain3 { a: R, b: R }\n\
                   struct Sd4 { a: R, b: R, c: R }\n\
                   impl Drop for Sd4 { fn drop(mut ref self) { println(\"dSd4\") } }\n\
                   struct Mix { a: R, n: i64 }\n\
                   impl Drop for Mix { fn drop(mut ref self) { println(\"dMix\") } }\n";
        for (label, fns, main, want) in [
            (
                "the row: view + fresh",
                "fn take(r: R) -> i64 { let s = Sd3 { a: r, b: mk(2) }; return 7; }",
                "let v = take(mk(1)); println(f\"v={v}\");",
                "dSd3\ndR2\ndR1\nv=7\n",
            ),
            (
                "order reversed: fresh + view",
                "fn take(r: R) -> i64 { let s = Sd3 { a: mk(2), b: r }; return 7; }",
                "let v = take(mk(1)); println(f\"v={v}\");",
                "dSd3\ndR2\ndR1\nv=7\n",
            ),
            (
                "boundary: ALL views (the shape already fixed)",
                "fn take(r: R) -> i64 { let s = Sd { r: r }; return 7; }",
                "let v = take(mk(1)); println(f\"v={v}\");",
                "dSd\ndR1\nv=7\n",
            ),
            (
                "boundary: ALL fresh — nothing masked",
                "fn take(r: R) -> i64 { let s = Sd3 { a: mk(1), b: mk(2) }; return 7; }",
                "let v = take(mk(9)); println(f\"v={v}\");",
                "dSd3\ndR2\ndR1\ndR9\nv=7\n",
            ),
            (
                "boundary: MIXED with NO own Drop — the per-field path, untouched",
                "fn take(r: R) -> i64 { let s = Plain3 { a: r, b: mk(2) }; return 7; }",
                "let v = take(mk(1)); println(f\"v={v}\");",
                "dR2\ndR1\nv=7\n",
            ),
            (
                "three fields, ONE view: both fresh bodies survive",
                "fn take(r: R) -> i64 { let s = Sd4 { a: r, b: mk(2), c: mk(3) }; return 7; }",
                "let v = take(mk(1)); println(f\"v={v}\");",
                "dSd4\ndR3\ndR2\ndR1\nv=7\n",
            ),
            (
                "three fields, TWO views: the fresh body survives",
                "fn take(p: R, q: R) -> i64 { let s = Sd4 { a: p, b: q, c: mk(3) }; return 7; }",
                "let v = take(mk(1), mk(2)); println(f\"v={v}\");",
                "dSd4\ndR3\ndR2\ndR1\nv=7\n",
            ),
            (
                "view beside a NON-Drop field",
                "fn take(r: R) -> i64 { let s = Mix { a: r, n: 5 }; return 7; }",
                "let v = take(mk(1)); println(f\"v={v}\");",
                "dMix\ndR1\nv=7\n",
            ),
            (
                "the masked binding is still readable",
                "fn take(r: R) -> i64 { let s = Sd3 { a: r, b: mk(2) }; println(f\"rd{s.b.id}\"); return 7; }",
                "let v = take(mk(1)); println(f\"v={v}\");",
                "rd2\ndSd3\ndR2\ndR1\nv=7\n",
            ),
            (
                "two mixed literals in one frame keep separate masks",
                "fn take(p: R, q: R) -> i64 { let s = Sd3 { a: p, b: mk(2) }; let t = Sd3 { a: q, b: mk(4) }; return 7; }",
                "let v = take(mk(1), mk(3)); println(f\"v={v}\");",
                "dSd3\ndR2\ndSd3\ndR4\ndR3\ndR1\nv=7\n",
            ),
        ] {
            let src = format!("{hdr}{fns}\nfn main() {{ {main} }}\n");
            assert_eq!(run_program(&src).as_deref(), Some(want), "[{label}]");
        }
    }

    #[test]
    fn e2e_deep_projection_scrutinee_runs_one_payload_body() {
        let hdr = "struct R { id: i64 }\n\
                   impl Drop for R { fn drop(mut ref self) { println(f\"dR{self.id}\") } }\n\
                   enum E { A(R), B }\n\
                   impl Drop for E { fn drop(mut ref self) { println(\"dE\") } }\n\
                   struct S { e: E }\n\
                   struct W { s: S }\n\
                   struct X { w: W }\n\
                   struct Sd { e: E }\n\
                   impl Drop for Sd { fn drop(mut ref self) { println(\"dSd\") } }\n\
                   struct Wd { s: Sd }\n\
                   struct S2 { n: i64, e: E }\n\
                   struct W2 { k: R, s: S2 }\n\
                   struct Coll { e: E, s: S }\n\
                   struct Two { a: S, b: S }\n";
        for (label, body, want) in [
            (
                "control: one hop",
                "let s = S { e: E.A(R { id: 8 }) };\n\
                 match s.e { E.A(r) => { let m = r; println(f\"m{m.id}\") } E.B => {} }",
                "m8\ndR8\ndE\n",
            ),
            (
                "two hops — the row",
                "let w = W { s: S { e: E.A(R { id: 8 }) } };\n\
                 match w.s.e { E.A(r) => { let m = r; println(f\"m{m.id}\") } E.B => {} }",
                "m8\ndR8\ndE\n",
            ),
            (
                "three hops",
                "let x = X { w: W { s: S { e: E.A(R { id: 8 }) } } };\n\
                 match x.w.s.e { E.A(r) => { let m = r; println(f\"m{m.id}\") } E.B => {} }",
                "m8\ndR8\ndE\n",
            ),
            (
                "two hops, intermediate struct has its OWN Drop",
                "let w = Wd { s: Sd { e: E.A(R { id: 8 }) } };\n\
                 match w.s.e { E.A(r) => { let m = r; println(f\"m{m.id}\") } E.B => {} }",
                "m8\ndR8\ndSd\ndE\n",
            ),
            (
                "two hops, sibling fields still walked",
                "let w = W2 { k: R { id: 3 }, s: S2 { n: 1, e: E.A(R { id: 8 }) } };\n\
                 match w.s.e { E.A(r) => { let m = r; println(f\"m{m.id}\") } E.B => {} }",
                "m8\ndR8\ndE\ndR3\n",
            ),
            (
                "two hops, `if let` spelling",
                "let w = W { s: S { e: E.A(R { id: 8 }) } };\n\
                 if let E.A(r) = w.s.e { let m = r; println(f\"m{m.id}\") }",
                "m8\ndR8\ndE\n",
            ),
            (
                "two hops, a statement follows",
                "let w = W { s: S { e: E.A(R { id: 8 }) } };\n\
                 match w.s.e { E.A(r) => { let m = r; println(f\"m{m.id}\") } E.B => {} }\n\
                 println(\"after\");",
                "m8\ndR8\ndE\nafter\n",
            ),
            // CONTROLS the mask must keep DECLINING. A non-consuming arm did
            // not take the payload, so the owner still owes that body; the
            // `B` arm holds no payload at all.
            (
                "control: two hops, arm does NOT consume",
                "let w = W { s: S { e: E.A(R { id: 8 }) } };\n\
                 match w.s.e { E.A(r) => { println(f\"n{r.id}\") } E.B => {} }",
                "n8\ndE\ndR8\n",
            ),
            (
                "control: two hops, payload-less arm taken",
                "let w = W { s: S { e: E.B } };\n\
                 match w.s.e { E.A(r) => { let m = r; println(f\"m{m.id}\") } E.B => { println(\"bee\") } }",
                "bee\ndE\n",
            ),
            // COMPOSITION. A path mask must land on the level that owns the
            // enum and nowhere else — these are the rows that fail if the
            // nesting is built or consumed at the wrong depth.
            (
                "name collision: masking the INNER `e` leaves the outer's payload",
                "let c = Coll { e: E.A(R { id: 1 }), s: S { e: E.A(R { id: 8 }) } };\n\
                 match c.s.e { E.A(r) => { let m = r; println(f\"m{m.id}\") } E.B => {} }",
                "m8\ndR8\ndE\ndE\ndR1\n",
            ),
            (
                "name collision: masking the OUTER `e` leaves the inner's payload",
                "let c = Coll { e: E.A(R { id: 1 }), s: S { e: E.A(R { id: 8 }) } };\n\
                 match c.e { E.A(r) => { let m = r; println(f\"m{m.id}\") } E.B => {} }",
                "m1\ndR1\ndE\ndR8\ndE\n",
            ),
            (
                "compose: a one-hop and a two-hop mask on the same variable",
                "let c = Coll { e: E.A(R { id: 1 }), s: S { e: E.A(R { id: 8 }) } };\n\
                 match c.e { E.A(r) => { let m = r; println(f\"o{m.id}\") } E.B => {} }\n\
                 match c.s.e { E.A(r) => { let m = r; println(f\"i{m.id}\") } E.B => {} }",
                "o1\ndR1\ni8\ndR8\ndE\ndE\n",
            ),
            (
                "compose: both sibling subtrees masked",
                "let t = Two { a: S { e: E.A(R { id: 1 }) }, b: S { e: E.A(R { id: 2 }) } };\n\
                 match t.a.e { E.A(r) => { let m = r; println(f\"a{m.id}\") } E.B => {} }\n\
                 match t.b.e { E.A(r) => { let m = r; println(f\"b{m.id}\") } E.B => {} }",
                "a1\ndR1\nb2\ndR2\ndE\ndE\n",
            ),
            (
                "compose: only ONE sibling subtree masked",
                "let t = Two { a: S { e: E.A(R { id: 1 }) }, b: S { e: E.A(R { id: 2 }) } };\n\
                 match t.a.e { E.A(r) => { let m = r; println(f\"a{m.id}\") } E.B => {} }",
                "a1\ndR1\ndE\ndR2\ndE\n",
            ),
        ] {
            let src = format!("{hdr}fn main() {{\n{body}\n}}\n");
            assert_eq!(run_program(&src).as_deref(), Some(want), "[{label}]");
        }
        // PINNED AT A KNOWN GAP, not asserted as correct. A `self`-ROOTED
        // projection scrutinee is not masked at ANY depth — the resolver needs
        // an identifier root and `self` is its own expression kind — so the
        // payload body runs twice. Both backends agree, so it is an agreed gap
        // rather than a divergence, and it is a different axis from this row:
        // the ONE-hop `self.e` doubles identically, which is what shows this is
        // about the root kind and not the depth this row fixed. Filed
        // separately.
        let selfrooted = "struct R { id: i64 }\n\
             impl Drop for R { fn drop(mut ref self) { println(f\"dR{self.id}\") } }\n\
             enum E { A(R), B }\n\
             impl Drop for E { fn drop(mut ref self) { println(\"dE\") } }\n\
             struct S { e: E }\n\
             struct H1 { e: E }\n\
             impl H1 { fn take(mut ref self) -> i64 { match self.e { E.A(r) => { let m = r; return m.id; } E.B => { return 0; } } } }\n\
             struct H2 { s: S }\n\
             impl H2 { fn take(mut ref self) -> i64 { match self.s.e { E.A(r) => { let m = r; return m.id; } E.B => { return 0; } } } }\n\
             fn main() {\n\
             \x20   let mut a = H1 { e: E.A(R { id: 1 }) };\n\
             \x20   println(a.take());\n\
             \x20   let mut b = H2 { s: S { e: E.A(R { id: 2 }) } };\n\
             \x20   println(b.take());\n\
             }\n";
        assert_eq!(
            run_program(selfrooted).as_deref(),
            Some("dR1\n1\ndE\ndR1\ndR2\n2\ndE\ndR2\n"),
            "[pinned GAP: `self`-rooted projection, one hop and two]"
        );
    }

    #[test]
    fn e2e_discarded_branch_of_body_less_heap_literals_keeps_one_owner() {
        let hdr = "struct P { a: String, b: i64 }\n\
                   struct D { a: String, b: i64 }\n\
                   impl Drop for D { fn drop(mut ref self) { println(f\"dD{self.b}\") } }\n\
                   struct W { r: D, b: i64 }\n\
                   fn pay() -> String { return \"heap\"; }\n\
                   fn mkd(n: i64) -> D { return D { a: pay(), b: n }; }\n\
                   fn mkw(n: i64) -> W { return W { r: mkd(n), b: n }; }\n";
        for (label, body, want) in [
            // The row's own shapes: no body anywhere in `P`, so nothing prints
            // and the only thing that changed is memory.
            (
                "body-less literal through a bare if",
                "if n == 0 { P { a: pay(), b: 1 } } else { P { a: pay(), b: 2 } };",
                "end\n",
            ),
            (
                "body-less literal through a wildcard let match",
                "let _ = match n { 0 => { P { a: pay(), b: 1 } } _ => { P { a: pay(), b: 2 } } };",
                "end\n",
            ),
            // A type that declares its OWN `Drop` never reaches the new
            // fall-through (its wrapper carries body and memory together).
            // One body, not two.
            (
                "own-Drop literal through a branch stays single",
                "let _ = if n == 0 { D { a: pay(), b: 1 } } else { D { a: pay(), b: 2 } };",
                "dD1\nend\n",
            ),
            (
                "own-Drop call through a branch stays single",
                "let _ = if n == 0 { mkd(1) } else { mkd(2) };",
                "dD1\nend\n",
            ),
            // No own `Drop` but a Drop-BEARING field: this one takes the arm
            // BELOW the new one, which registers the field-bodies walk. It is
            // the nearest neighbour to the changed branch and the one most
            // likely to double if the fall-through were placed wrong.
            (
                "Drop-bearing field through a branch stays single",
                "let _ = if n == 0 { W { r: mkd(1), b: 1 } } else { W { r: mkd(2), b: 2 } };",
                "dD1\nend\n",
            ),
            // The direct-discard spellings, which already carried memory AND
            // bodies through `track_inline_owned_aggregate_arg` and must be
            // untouched by this row.
            (
                "control: direct own-Drop literal discard",
                "let _ = D { a: pay(), b: 1 };",
                "dD1\nend\n",
            ),
            (
                "control: bare-statement own-Drop literal discard",
                "D { a: pay(), b: 1 };",
                "dD1\nend\n",
            ),
            // The GUARD's admitted kinds, carrying a body so a wrong decline
            // or a double is visible as a count rather than only as bytes.
            // The GUARD's two sides, carrying a body so a wrong answer shows
            // up as a count rather than only as bytes. The declined shape
            // (a field initializer projected off a FRESH TEMP) must still be
            // correct — the guard withholds the memory registration, not the
            // body — and the admitted shape must stay single.
            (
                "guard declines the aliasing shape and it is still single",
                "let _ = if n == 0 { W { r: mkw(7).r, b: 1 } } else { W { r: mkd(2), b: 2 } };",
                "dD7\nend\n",
            ),
            (
                "guard admits arms that mint their own field",
                "let _ = if n == 0 { W { r: mkd(7), b: 1 } } else { W { r: mkd(2), b: 2 } };",
                "dD7\nend\n",
            ),
        ] {
            let src = format!("{hdr}fn main() {{\nlet n = 0;\n{body}\nprintln(\"end\");\n}}\n");
            assert_eq!(run_program(&src).as_deref(), Some(want), "[{label}]");
        }
        // B-2026-08-31-35 — the WHOLE-LOCAL move is FIXED and asserted as
        // correct: a discarded branch whose arm literal consumes a local now
        // runs that local's body ONCE, at the discard, on every backend. The
        // discarded statement position is an escaping site exactly when this
        // site owns the merged value, so the taken arm's consumed sources are
        // disarmed on the path that handed them over.
        let src = format!(
            "{hdr}fn main() {{\nlet n = 0;\nlet t = mkd(7);\n\
             let _ = if n == 0 {{ W {{ r: t, b: 1 }} }} else {{ W {{ r: mkd(2), b: 2 }} }};\n\
             println(\"end\");\n}}\n"
        );
        assert_eq!(
            run_program(&src).as_deref(),
            Some("dD7\nend\n"),
            "[discarded arm literal consuming a whole local runs one body]"
        );
        // STILL PINNED AT A KNOWN DEFECT, not asserted as correct. The
        // PROJECTED spelling (`W { r: t.r, .. }`) runs the local's body twice
        // — once at the discard, once at its own scope end — because
        // `collect_aggregate_literal_sources` resolves a bare name and not a
        // field projection, so the disarm above never names `t`. All three
        // backends agree on it, so it is an agreed gap rather than a
        // divergence, and it is PRE-EXISTING: measured byte-identical at
        // `c4af3243`, the commit before B-2026-08-29-31 taught this path to
        // own an arm's value at all. Filed separately.
        //
        // Its MEMORY is balanced, which corrects what B-2026-08-31-35's own
        // prose recorded: measured clean under valgrind at `-O2` and at
        // `-O0`, over a 5-iteration loop, and clean at `ebaacfc` too — the
        // second body runs over the moved-from husk rather than re-freeing.
        let src = format!(
            "{hdr}fn main() {{\nlet n = 0;\nlet t = mkw(7);\n\
             let _ = if n == 0 {{ W {{ r: t.r, b: 1 }} }} else {{ W {{ r: mkd(2), b: 2 }} }};\n\
             println(\"end\");\n}}\n"
        );
        assert_eq!(
            run_program(&src).as_deref(),
            Some("dD7\ndD7\nend\n"),
            "[pinned DEFECT: discarded arm literal consuming a local's field]"
        );
    }

    #[test]
    fn e2e_wildcard_let_discard_owns_what_its_arm_hands_out() {
        let hdr = "struct R { id: i64, name: String }\n\
                   impl Drop for R { fn drop(mut ref self) { println(f\"dR{self.id}\") } }\n\
                   fn mk(i: i64) -> R { return R { id: i, name: f\"heap-{i}\" }; }\n";
        for (label, body, want) in [
            // ── the tail names an ENCLOSING LOCAL ─────────────────────────
            (
                "if-hands-out-a-local",
                "let r = mk(41);\nlet _ = if n == 0 { r } else { mk(9) };",
                "dR41\nend\n",
            ),
            (
                "match-hands-out-a-local",
                "let r = mk(41);\nlet _ = match n { 0 => r, _ => mk(9) };",
                "dR41\nend\n",
            ),
            (
                "block-hands-out-a-local",
                "let r = mk(41);\nlet _ = { r };",
                "dR41\nend\n",
            ),
            // ── the tail names the arm's own PATTERN BINDING ──────────────
            (
                "payload-braced-arm",
                "let o: Option[R] = Some(mk(1));\n\
                 let _ = match o { Some(r) => { r } None => { mk(9) } };",
                "dR1\nend\n",
            ),
            // ── double-own guards: ONE body, not two ──────────────────────
            (
                "guard: block-wrapped match is owned by the statement site",
                "let _ = { match n { 0 => { mk(7) } _ => { mk(3) } } };",
                "dR7\nend\n",
            ),
            (
                "guard: block-wrapped call is owned by the statement site",
                "let _ = { mk(7) };",
                "dR7\nend\n",
            ),
            // ── controls, unchanged by this row ───────────────────────────
            (
                "control: bare-statement form (B-2026-08-29-5)",
                "let r = mk(41);\nif n == 0 { r } else { mk(9) };",
                "dR41\nend\n",
            ),
            (
                "control: all-mint if stays statement-owned",
                "let _ = if n == 0 { mk(2) } else { mk(3) };",
                "dR2\nend\n",
            ),
            (
                "control: all-mint match stays statement-owned",
                "let _ = match n { 0 => mk(2), _ => mk(3) };",
                "dR2\nend\n",
            ),
            (
                "control: else-if chain",
                "let _ = if n == 1 { mk(20) } else if n == 0 { mk(21) } else { mk(22) };",
                "dR21\nend\n",
            ),
            (
                // A MIXED branch: one arm names a live local, the other
                // mints. Both bodies are due and neither may double. Before
                // this row BOTH backends printed only `dR18` — the minted
                // value had no owner at all (B-2026-08-30-11's population).
                // `dR4` lands at the discard, `dR18` at the local's own NLL
                // end, which is that same statement.
                "control: mixed branch — minted arm and live local both fire once",
                "let r = mk(18);\nlet _ = if n == 9 { r } else { mk(4) };\nprintln(\"still\");",
                "dR4\ndR18\nstill\nend\n",
            ),
            // B-2026-09-01-10 — the `match` spellings of the two rows above.
            // `compile_match` never told a BLOCK-bodied arm that the
            // construct's value is discarded, so the braced spellings here
            // stranded whatever the taken arm named while the bare ones were
            // already correct; and the minted arm of a match the statement
            // site DECLINES (one arm yields a place) had no owner in the bare
            // spelling at all — the compiled backends were silent on `dR9`
            // where the interpreter fired it.
            (
                "match braced arm — mixed branch, both bodies fire once",
                "let r = mk(18);\nlet _ = match n { 9 => { r } _ => { mk(4) } };\nprintln(\"still\");",
                "dR4\ndR18\nstill\nend\n",
            ),
            (
                "match braced arm — declined match, minted arm taken",
                "let o: Option[R] = None;\nlet _ = match o { Some(r) => { r } None => { mk(9) } };",
                "dR9\nend\n",
            ),
            (
                "match bare arm — declined match, minted arm taken",
                "let o: Option[R] = None;\nlet _ = match o { Some(r) => r, None => mk(9) };",
                "dR9\nend\n",
            ),
            (
                "match braced arm — bare statement, payload binding handed out",
                "let o: Option[R] = Some(mk(1));\nmatch o { Some(r) => { r } None => { mk(9) } };",
                "dR1\nend\n",
            ),
        ] {
            let src = format!("{hdr}fn main() {{\nlet n = 0;\n{body}\nprintln(\"end\");\n}}\n");
            assert_eq!(run_program(&src).as_deref(), Some(want), "[{label}]");
        }
        // PINNED AT A KNOWN DIVERGENCE, not asserted as correct. A BARE arm
        // (no braces) handing out a HEAP-carrying `Option` payload is silent
        // on both compiled backends and fires on the interpreter. It is the
        // boxed-`Option`-payload channel and it is PRE-EXISTING: the
        // BARE-STATEMENT spelling of the same program diverged the same way
        // before this row. Narrowed by measurement — the same bare arm over a
        // USER enum, or over an `Option` whose payload carries no heap, fires
        // on all three. Filed separately; this row's widening neither caused
        // it nor could reach it.
        let boxed = format!(
            "{hdr}fn main() {{\n\
             let o: Option[R] = Some(mk(1));\n\
             let _ = match o {{ Some(r) => r, None => mk(9) }};\n\
             println(\"end\");\n}}\n"
        );
        assert_eq!(
            run_program(&boxed).as_deref(),
            Some("end\n"),
            "[pinned DIVERGENT: bare arm handing out a heap-carrying Option payload]"
        );
    }

    #[test]
    fn e2e_owned_self_enum_receiver_single_fire() {
        let Some(out) = run_program(
            "struct Res { id: i64, name: String }\n\
             impl Drop for Res {\n\
             \x20   fn drop(mut ref self) {\n\
             \x20       println(f\"drop {self.id} {self.name}\")\n\
             \x20   }\n\
             }\n\
             enum Box2 { Full(Res), Empty }\n\
             impl Box2 {\n\
             \x20   fn into_id(self) -> i64 {\n\
             \x20       match self {\n\
             \x20           Box2.Full(r) => { return r.id; }\n\
             \x20           Box2.Empty => { return 0; }\n\
             \x20       }\n\
             \x20   }\n\
             \x20   fn just_three(self) -> i64 {\n\
             \x20       return 3;\n\
             \x20   }\n\
             }\n\
             fn mk_e(n: i64) -> Box2 {\n\
             \x20   return Box2.Full(Res { id: n, name: f\"e{n}\" });\n\
             }\n\
             fn main() {\n\
             \x20   println(\"a: owned-self match-consume fires once via the arm\");\n\
             \x20   let b = mk_e(7);\n\
             \x20   let v = b.into_id();\n\
             \x20   println(f\"v={v}\");\n\
             \x20   println(\"b: owned-self non-consuming — consumed silently\");\n\
             \x20   let c = mk_e(8);\n\
             \x20   let w = c.just_three();\n\
             \x20   println(f\"w={w}\");\n\
             \x20   println(\"end\");\n\
             }\n",
        ) else {
            return;
        };
        assert_eq!(
            out,
            "a: owned-self match-consume fires once via the arm\ndrop 7 e7\nv=7\n\
             b: owned-self non-consuming — consumed silently\nw=3\nend\n"
        );
    }

    /// B-2026-07-30-11 (optres bare-statement leg) — a BARE discarded
    /// `Option` temp fires its payload's Drop body exactly like the
    /// wildcard-let shape: only the `let _ =` arm called the optres
    /// payload-bodies registrar, so `mkopt(2);` and `Option.Some(x);` were
    /// silent on both backends while `let _ = mkopt(1);` fired. Twin of
    /// `tests/interpreter.rs`'s `test_optres_bare_discard_payload_body`.
