    #[test]
    fn test_ir_ptr_expose_mut_compiles() {
        let ir = ir_for("fn caller(p: *mut i64) -> usize { ptr.expose_mut(p) } fn main() {}");
        assert!(
            ir.contains("@caller"),
            "caller fn should be emitted; got IR:\n{ir}"
        );
    }

    #[test]
    fn test_e2e_ptr_addr_round_trips_through_int_storage() {
        // End-to-end: receive a usize masquerading as `*const i64` (via
        // the i64-pointer ABI), call `ptr.addr` to recover the bits,
        // confirm the round-trip via `ptr.with_addr` and `ptr.addr` is
        // observation-equivalent. Doesn't require a real heap pointer
        // because the ABI carries the value as i64 throughout.
        let src = "fn round_trip(p: *const i64) -> bool { \
                       let a: usize = ptr.addr(p); \
                       let q: *const i64 = ptr.with_addr(p, a); \
                       ptr.addr(q) == a \
                   } \
                   fn main() {}";
        let ir = ir_for(src);
        assert!(
            ir.contains("@round_trip"),
            "round_trip fn should be emitted; got IR:\n{ir}"
        );
    }

    // ── ptr.container_of / ptr.container_of_mut (line 509 follow-up) ─

    #[test]
    fn test_ir_ptr_container_of_compiles() {
        let ir = ir_for(
            "struct Inner { x: i32, y: i32 } \
             struct Outer { a: i32, inner: Inner } \
             fn recover(fp: *const i32) -> *const Outer { \
                 unsafe { ptr.container_of(fp, offset_of[Outer](inner.y)) } \
             } \
             fn main() {}",
        );
        assert!(
            ir.contains("@recover"),
            "recover fn should be emitted; got IR:\n{ir}"
        );
        // The lowering subtracts the offset from the field pointer's
        // address bits — `sub` instruction must appear.
        assert!(
            ir.contains("sub"),
            "`ptr.container_of` should emit an integer subtract; got IR:\n{ir}"
        );
    }

    #[test]
    fn test_ir_ptr_container_of_mut_compiles() {
        let ir = ir_for(
            "struct Inner { x: i32, y: i32 } \
             struct Outer { a: i32, inner: Inner } \
             fn recover(fp: *mut i32) -> *mut Outer { \
                 unsafe { ptr.container_of_mut(fp, offset_of[Outer](inner.y)) } \
             } \
             fn main() {}",
        );
        assert!(
            ir.contains("@recover"),
            "recover fn should be emitted; got IR:\n{ir}"
        );
    }

    // ── ptr.null / ptr.dangling / ptr.is_null (line 573 slice 3) ─────

    #[test]
    fn test_ir_ptr_null_compiles() {
        let ir = ir_for("fn caller() -> *const i32 { ptr.null() } fn main() {}");
        assert!(
            ir.contains("@caller"),
            "caller fn should be emitted; got IR:\n{ir}"
        );
        assert!(
            !ir.contains("method dispatch fell through"),
            "ptr.null dispatch must not fall through; got IR:\n{ir}"
        );
    }

    #[test]
    fn test_ir_ptr_null_mut_compiles() {
        let ir = ir_for("fn caller() -> *mut i64 { ptr.null_mut() } fn main() {}");
        assert!(
            ir.contains("@caller"),
            "caller fn should be emitted; got IR:\n{ir}"
        );
    }

    #[test]
    fn test_ir_ptr_dangling_compiles() {
        let ir = ir_for("fn caller() -> *const u8 { ptr.dangling() } fn main() {}");
        assert!(
            ir.contains("@caller"),
            "caller fn should be emitted; got IR:\n{ir}"
        );
    }

    #[test]
    fn test_ir_ptr_is_null_compiles() {
        let ir = ir_for("fn caller(p: *const i32) -> bool { ptr.is_null(p) } fn main() {}");
        assert!(
            ir.contains("@caller"),
            "caller fn should be emitted; got IR:\n{ir}"
        );
    }

    #[test]
    fn test_e2e_ptr_null_is_null_round_trips_to_true() {
        // ptr.is_null(ptr.null()) must observe true. Pins the
        // null-pointer constant + the EQ-against-zero compare.
        let src = "fn main() { \
                       let p: *const i32 = ptr.null(); \
                       if ptr.is_null(p) { println(1); } else { println(0); } \
                   }";
        let out = run_program(src);
        if let Some(out) = out {
            assert_eq!(out, "1\n");
        }
    }

    // ── CStr borrowed surface (Phase 8 — the first pointer-producer) ──
    //
    // `c"..."` lowers to a NUL-terminated internal rodata global carried
    // as a `{ptr, i64}` slice-struct value; `as_ptr` / `len` / `is_empty`
    // / `as_bytes` are extract/compare ops on that aggregate
    // (`compile_cstr_method`). design.md § C-String Literals.

    #[test]
    fn test_ir_cstr_literal_emits_nul_terminated_internal_global() {
        let ir = ir_for("fn main() { let s = c\"hi\"; println(s.len()); }");
        // [3 x i8] = 2 source bytes + the compiler-appended NUL.
        assert!(
            ir.contains("internal constant [3 x i8] c\"hi\\00\""),
            "expected NUL-terminated internal rodata global; got IR:\n{ir}"
        );
    }

    #[test]
    fn test_ir_cstr_as_ptr_passes_rodata_pointer_directly() {
        // The design pins `as_ptr` as a direct rodata pointer — no copy,
        // no runtime call. The lowering is an extractvalue on the
        // literal's `{ptr, i64}` aggregate, which LLVM constant-folds on
        // a literal receiver: the call site receives the `@cstr` global
        // itself. Also pins the pointer-typed extern param lowering
        // (`declare void @sink(ptr ...)` — the `TypeKind::Pointer` arm,
        // not the historical i64 fall-through).
        let ir = ir_for(
            "effect resource R;\n\
             host fn sink(p: *const u8) with writes(R);\n\
             pub fn main() with writes(R) { sink(c\"x\".as_ptr()); }",
        );
        assert!(
            ir.contains("declare void @sink(ptr"),
            "pointer param must lower to `ptr`, not i64; got IR:\n{ir}"
        );
        assert!(
            ir.contains("@sink(ptr @cstr"),
            "as_ptr on a literal should fold to the rodata global at the \
             call site; got IR:\n{ir}"
        );
    }

