    // ── Closure compilation ───────────────────────────────────────────

    #[test]
    fn test_ir_closure_simple() {
        let ir = ir_for(
            r#"
fn main() {
    let f = |x: i64| x + 1;
    println(f(5));
}
"#,
        );
        // A closure function should be generated.
        assert!(
            ir.contains("__closure_0"),
            "should define a closure function"
        );
        // The closure function pointer is extracted from the fat-pointer struct.
        assert!(
            ir.contains("extractvalue"),
            "should extract fn_ptr/env_ptr from fat pointer"
        );
    }

    /// B-2026-06-20-1: a bare named `fn` passed as a first-class `Fn(...)`
    /// value. `apply(doubler, 21)` must lower the `Fn(i64)->i64` parameter to
    /// the closure fat-pointer ABI and reify the bare fn name into a
    /// `{trampoline, null-env}` fat pointer, so the higher-order call runs.
    /// Previously the `Fn`-typed param lowered to `i64` while the bare fn name
    /// lowered to a raw `ptr`, failing LLVM module verification.
    /// B-2026-06-21-2: a `fn` body that *returns* a first-class `Fn(...)` value
    /// (`fn pick() -> Fn(i64)->i64 { doubler }`). The bare fn name in return-tail
    /// position now lowers to a closure fat pointer (the free-fn-as-value source
    /// arm), matching the `{ptr,ptr}` return slot; `let f = pick()` registers
    /// `f` in `closure_fn_types` from `pick`'s declared `Fn(...)` return type, so
    /// the direct call through it works. Before: `ret ptr @doubler` vs `{ptr,ptr}`
    /// verifier error.
    #[test]
    fn fn_value_returned_then_called() {
        let out = run_program(
            "fn doubler(n: i64) -> i64 { n * 2i64 }\n\
             fn pick() -> Fn(i64) -> i64 { doubler }\n\
             fn main() { let f = pick(); println(f\"{f(21i64)}\"); }\n",
        );
        assert_eq!(out.as_deref(), Some("42\n"));
    }

    /// A returned fn value passed straight into a `Fn(...)` parameter — the call
    /// result is already a fat pointer, so it flows through with no reify.
    #[test]
    fn fn_value_returned_passed_directly() {
        let out = run_program(
            "fn doubler(n: i64) -> i64 { n * 2i64 }\n\
             fn pick() -> Fn(i64) -> i64 { doubler }\n\
             fn apply(f: Fn(i64) -> i64, x: i64) -> i64 { f(x) }\n\
             fn main() { println(f\"{apply(pick(), 21i64)}\"); }\n",
        );
        assert_eq!(out.as_deref(), Some("42\n"));
    }

    /// B-2026-06-21-3: an **un-annotated** fn value read out of a struct field
    /// (`let g = h.f;`, no `: Fn(..)`) and called. The lowering pass records the
    /// field-read expression's inferred `Fn(..)` type in `fn_value_typed_exprs`,
    /// so `let_binding_fn_value_type` registers `g` in `closure_fn_types` and
    /// `g(x)` lowers to an indirect call. Before this it fell through to the
    /// unknown-callee path and silently returned 0.
    #[test]
    fn fn_value_struct_field_unannotated_extraction() {
        let out = run_program(
            "fn doubler(n: i64) -> i64 { n * 2i64 }\n\
             struct H { f: Fn(i64) -> i64 }\n\
             fn main() { let h = H { f: doubler }; let g = h.f; println(f\"{g(21i64)}\"); }\n",
        );
        assert_eq!(out.as_deref(), Some("42\n"));
    }

    /// B-2026-06-21-3: the same, un-annotated, from a `Vec[Fn(..)]` element.
    #[test]
    fn fn_value_vec_element_unannotated_extraction() {
        let out = run_program(
            "fn doubler(n: i64) -> i64 { n * 2i64 }\n\
             fn main() {\n\
                 let mut v: Vec[Fn(i64) -> i64] = Vec.new();\n\
                 v.push(doubler);\n\
                 let g = v[0];\n\
                 println(f\"{g(21i64)}\");\n\
             }\n",
        );
        assert_eq!(out.as_deref(), Some("42\n"));
    }

    /// B-2026-06-21-2: a fn value stored in a struct field (`H { f: doubler }`)
    /// — the field initializer lowers to a fat pointer matching the
    /// `f: Fn(...)` field slot. The explicit-annotation extraction path
    /// (`let g: Fn(..) = h.f`); the un-annotated form is covered above
    /// (B-2026-06-21-3).
    #[test]
    fn fn_value_struct_field_annotated_extraction() {
        let out = run_program(
            "fn doubler(n: i64) -> i64 { n * 2i64 }\n\
             struct H { f: Fn(i64) -> i64 }\n\
             fn main() { let h = H { f: doubler }; let g: Fn(i64) -> i64 = h.f; println(f\"{g(21i64)}\"); }\n",
        );
        assert_eq!(out.as_deref(), Some("42\n"));
    }

    /// B-2026-06-21-2: a fn value stored in a `Vec[Fn(...)]` element, extracted
    /// with an explicit annotation and called.
    #[test]
    fn fn_value_vec_element_annotated_extraction() {
        let out = run_program(
            "fn doubler(n: i64) -> i64 { n * 2i64 }\n\
             fn main() {\n\
                 let mut v: Vec[Fn(i64) -> i64] = Vec.new();\n\
                 v.push(doubler);\n\
                 let g: Fn(i64) -> i64 = v[0];\n\
                 println(f\"{g(21i64)}\");\n\
             }\n",
        );
        assert_eq!(out.as_deref(), Some("42\n"));
    }

    /// B-2026-06-21-1 (sibling of B-2026-06-20-1): a bare named `fn` bound to a
    /// local first — `let g = doubler;` — then (a) passed to a `Fn(...)`-typed
    /// parameter and (b) called directly through the local. Both forms, and the
    /// `Fn(...)`-annotated binding, must reify the fn name into the closure
    /// fat-pointer ABI + register the local in `closure_fn_types`. Before this
    /// the local held a raw `ptr`: the pass-to-param form failed LLVM
    /// verification and the direct call silently returned 0.
    #[test]
    fn fn_value_let_bound_named_fn_passed_and_called() {
        let out = run_program(
            "fn doubler(n: i64) -> i64 { n * 2i64 }\n\
             fn apply(f: Fn(i64) -> i64, x: i64) -> i64 { f(x) }\n\
             fn main() {\n\
                 let g = doubler;\n\
                 let h: Fn(i64) -> i64 = doubler;\n\
                 println(f\"{apply(g, 10i64)}\");\n\
                 println(f\"{h(11i64)}\");\n\
             }\n",
        );
        assert_eq!(out.as_deref(), Some("20\n22\n"));
    }

    /// A let-bound fn value and a direct-argument reify of the same fn share one
    /// memoized `__karac_fnval_<name>` trampoline (a single `define`).
    #[test]
    fn fn_value_let_and_arg_reify_share_one_trampoline() {
        let ir = ir_for(
            "fn doubler(n: i64) -> i64 { n * 2i64 }\n\
             fn apply(f: Fn(i64) -> i64, x: i64) -> i64 { f(x) }\n\
             fn main() {\n\
                 let g = doubler;\n\
                 let a = apply(g, 1i64);\n\
                 let b = apply(doubler, 2i64);\n\
                 println(f\"{a + b}\");\n\
             }\n",
        );
        let tramp_defs = ir
            .lines()
            .filter(|l| l.starts_with("define") && l.contains("@__karac_fnval_doubler"))
            .count();
        assert_eq!(tramp_defs, 1, "expected one memoized trampoline:\n{ir}");
    }

    #[test]
    fn fn_value_named_fn_as_fn_typed_param_runs() {
        let out = run_program(
            "fn doubler(n: i64) -> i64 { n * 2i64 }\n\
             fn apply(f: Fn(i64) -> i64, x: i64) -> i64 { f(x) }\n\
             fn main() { println(f\"{apply(doubler, 21i64)}\"); }\n",
        );
        assert_eq!(out.as_deref(), Some("42\n"));
    }

    /// Multi-arg + float `Fn(...)` parameters: the env-first trampoline ABI
    /// forwards every user arg, regardless of arity or scalar width.
    #[test]
    fn fn_value_fn_typed_param_multiarg_and_float_run() {
        let multiarg = run_program(
            "fn combine(a: i64, b: i64) -> i64 { a * 10i64 + b }\n\
             fn apply2(f: Fn(i64, i64) -> i64, x: i64, y: i64) -> i64 { f(x, y) }\n\
             fn main() { println(f\"{apply2(combine, 4i64, 2i64)}\"); }\n",
        );
        assert_eq!(multiarg.as_deref(), Some("42\n"));

        let float = run_program(
            "fn half(x: f64) -> f64 { x / 2.0 }\n\
             fn applyf(f: Fn(f64) -> f64, x: f64) -> f64 { f(x) }\n\
             fn main() { println(f\"{applyf(half, 84.0)}\"); }\n",
        );
        assert_eq!(float.as_deref(), Some("42\n"));
    }

    #[test]
    fn e2e_string_xform_on_a_nonident_receiver_inside_a_chain() {
        // B-2026-08-05-28. `(<non-ident>).to_uppercase()` alone always
        // compiled; putting its result in RECEIVER position did not, because
        // the parser gives a MethodCall its receiver's span, so the outer
        // call's `i64` evicted the inner `String` from the span tables the
        // non-identifier String dispatch keys on. The xform's dispatcher arm
        // was there the whole time — the receiver just stopped looking like a
        // String. Covers the Binary, MethodCall and f-string receiver roots
        // together, since one span-free signal fixes all three.
        let concat = run_program(
            "fn main() {\n\
                 let mut v: Vec[String] = Vec.new();\n\
                 v.push(\"Hi\".to_string());\n\
                 match v.first() {\n\
                     Some(s) => { println((\"p:\".to_string() + s).to_uppercase().len()); }\n\
                     None => { }\n\
                 }\n\
             }",
        );
        assert_eq!(concat, Some("4\n".to_string()));

        let fstring = run_program(
            "fn main() {\n\
                 let mut v: Vec[String] = Vec.new();\n\
                 v.push(\"Hi\".to_string());\n\
                 match v.first() {\n\
                     Some(s) => { println(f\"p:{s}\".trim().len()); }\n\
                     None => { }\n\
                 }\n\
             }",
        );
        assert_eq!(fstring, Some("4\n".to_string()));

        // Identifier ROOT but a MethodCall receiver for the second xform —
        // the shape the row's "non-identifier receiver" framing missed.
        let chained = run_program(
            "fn main() {\n\
                 let mut v: Vec[String] = Vec.new();\n\
                 v.push(\"Hi\".to_string());\n\
                 match v.first() {\n\
                     Some(s) => { println(s.to_uppercase().to_lowercase()); }\n\
                     None => { }\n\
                 }\n\
             }",
        );
        assert_eq!(chained, Some("hi\n".to_string()));

        // `split` is in the same family and was failing the same way; its
        // result is a Vec, so it also exercises the non-String result path.
        let split = run_program(
            "fn main() {\n\
                 let mut v: Vec[String] = Vec.new();\n\
                 v.push(\"a:b\".to_string());\n\
                 match v.first() {\n\
                     Some(s) => { println((\"p:\".to_string() + s).split(\":\").len()); }\n\
                     None => { }\n\
                 }\n\
             }",
        );
        assert_eq!(split, Some("3\n".to_string()));
    }

    #[test]
    fn e2e_fn_value_with_a_ref_vec_param_builds_and_reads() {
        // B-2026-08-05-15: `let f = g` where `g` takes `ref Vec[u8]`. The
        // indirect call used to push the `{ptr, i64, i64}` Vec triple into the
        // signature's `ptr` slot, which LLVM's verifier rejects — so this would
        // not BUILD, while `karac check` passed and the interpreter ran it.
        let out = run_program(
            "fn head(v: ref Vec[u8], i: i64) -> i64 {\n\
                 return v[i] as i64;\n\
             }\n\
             fn main() {\n\
                 let mut v: Vec[u8] = Vec.new();\n\
                 let mut k = 0i64;\n\
                 while k < 6i64 { v.push((k * 3i64) as u8); k = k + 1i64; }\n\
                 let f = head;\n\
                 let mut acc = 0i64;\n\
                 let mut i = 0i64;\n\
                 while i < 6i64 { acc = acc + f(v, i); i = i + 1i64; }\n\
                 println(acc);\n\
             }",
        );
        assert_eq!(out, Some("45\n".to_string()));
    }

    #[test]
    fn e2e_fn_value_with_a_ref_string_param() {
        let out = run_program(
            "fn n(s: ref String) -> i64 { return s.len(); }\n\
             fn main() {\n\
                 let s: String = \"hello\";\n\
                 let f = n;\n\
                 println(f(s));\n\
             }",
        );
        assert_eq!(out, Some("5\n".to_string()));
    }

    #[test]
    fn e2e_fn_value_with_a_mut_ref_vec_param_mutates_the_callers_vec() {
        // The `mut ref` leg: the callee must receive the caller's buffer, not a
        // copy of its header, or the pushes land nowhere observable.
        let out = run_program(
            "fn bump(v: mut ref Vec[i64], x: i64) { v.push(x); }\n\
             fn main() {\n\
                 let mut v: Vec[i64] = Vec.new();\n\
                 let f = bump;\n\
                 let mut i = 0i64;\n\
                 while i < 5i64 { f(mut v, i * 2i64); i = i + 1i64; }\n\
                 let mut s = 0i64;\n\
                 let mut j = 0i64;\n\
                 while j < v.len() { s = s + v[j]; j = j + 1i64; }\n\
                 println(s);\n\
             }",
        );
        assert_eq!(out, Some("20\n".to_string()));
    }

    #[test]
    fn e2e_closure_literal_with_a_ref_vec_param_indexes_it() {
        // B-2026-08-05-15 leg 2, the CALLEE-side mirror: a closure param's side
        // tables were registered from the BORROW type, and
        // `register_var_from_type_expr` has no `Ref` arm — so `w` never reached
        // `vec_elem_types` and `w[i]` failed to build with "Index operator
        // applied to non-array type".
        let out = run_program(
            "fn main() {\n\
                 let mut v: Vec[u8] = Vec.new();\n\
                 let mut k = 0i64;\n\
                 while k < 4i64 { v.push((k + 1i64) as u8); k = k + 1i64; }\n\
                 let f = |w: ref Vec[u8], i: i64| { return w[i] as i64; };\n\
                 println(f(v, 2i64));\n\
             }",
        );
        assert_eq!(out, Some("3\n".to_string()));
    }

    #[test]
    fn e2e_fn_value_shared_param_still_receives_the_handle_not_its_slot() {
        // The discrimination the by-pointer branch must NOT get wrong: a
        // `shared` param also lowers to `ptr`, but its argument is ALREADY a
        // pointer. Taking the address of the binding's slot would hand the
        // callee a pointer-to-pointer, and `n.v` would read the stack.
        let out = run_program(
            "shared struct Node { v: i64 }\n\
             fn get(n: Node) -> i64 { return n.v; }\n\
             fn main() {\n\
                 let n: Node = Node { v: 41i64 };\n\
                 let f = get;\n\
                 println(f(n) + 1i64);\n\
             }",
        );
        assert_eq!(out, Some("42\n".to_string()));
    }

    #[test]
    fn e2e_fn_value_ref_param_takes_a_fresh_rvalue_argument() {
        // The rvalue leg of the by-pointer branch: no named binding whose
        // address to take, so the argument is materialized into a temp. This is
        // the ownership-sensitive path a wrong marshalling would leak or
        // double-free. The payload's BYTES are read (`contains`) and the seed is
        // opaque (`env.args().len()`), so the allocations are not dead and the
        // loop really runs — B-2026-08-04-17's authoring rule.
        let out = run_program(
            "fn score(s: ref String, needle: ref String) -> i64 {\n\
                 if s.contains(needle) { return s.len(); }\n\
                 return 1i64;\n\
             }\n\
             fn mk(k: i64) -> String {\n\
                 let mut s: String = String.new();\n\
                 s.push_str(f\"payload-row-{k}-tail\");\n\
                 return s;\n\
             }\n\
             fn main() {\n\
                 let a: i64 = env.args().len();\n\
                 let f = score;\n\
                 let mut acc = 0i64;\n\
                 let mut i = 0i64;\n\
                 while i < 20i64 {\n\
                     let nd: String = mk(i + a);\n\
                     acc = acc + f(mk(i + a), nd);\n\
                     i = i + 1i64;\n\
                 }\n\
                 println(acc);\n\
             }",
        );
        // Oracle: the interpreter's answer for the same source.
        assert_eq!(out, Some("371\n".to_string()));
    }

    /// The same bare fn passed in `Fn(...)` position at two call sites reuses a
    /// single memoized trampoline (one `define` of `__karac_fnval_doubler`),
    /// and both higher-order calls run.
    #[test]
    fn fn_value_named_fn_reused_across_call_sites() {
        let src = "fn doubler(n: i64) -> i64 { n * 2i64 }\n\
                   fn apply(f: Fn(i64) -> i64, x: i64) -> i64 { f(x) }\n\
                   fn main() {\n\
                       let a = apply(doubler, 10i64);\n\
                       let b = apply(doubler, 11i64);\n\
                       println(f\"{a + b}\");\n\
                   }\n";
        assert_eq!(run_program(src).as_deref(), Some("42\n"));
        let ir = ir_for(src);
        let tramp_defs = ir
            .lines()
            .filter(|l| l.starts_with("define") && l.contains("@__karac_fnval_doubler"))
            .count();
        assert_eq!(
            tramp_defs, 1,
            "trampoline must be synthesized exactly once (memoized):\n{ir}"
        );
    }

    /// Bonus path the same fix enables: a closure *literal* flowing into a
    /// `Fn(...)` parameter slot. The param now lowers to the fat-pointer ABI
    /// and the body call routes through the indirect-call path, so the closure
    /// value passes through and runs (no reify needed — it is already a fat
    /// pointer).
    #[test]
    fn fn_value_closure_literal_into_fn_typed_param_run() {
        let out = run_program(
            "fn apply(f: Fn(i64) -> i64, x: i64) -> i64 { f(x) }\n\
             fn main() { println(f\"{apply(|n| n * 2i64, 21i64)}\"); }\n",
        );
        assert_eq!(out.as_deref(), Some("42\n"));
    }

    /// The reify path synthesizes a per-fn env-ignoring trampoline so the bare
    /// fn name conforms to the env-first closure-call ABI.
    #[test]
    fn test_ir_fn_value_named_fn_reified_trampoline() {
        let ir = ir_for(
            "fn doubler(n: i64) -> i64 { n * 2i64 }\n\
             fn apply(f: Fn(i64) -> i64, x: i64) -> i64 { f(x) }\n\
             fn main() { let r = apply(doubler, 21i64); println(f\"{r}\"); }\n",
        );
        assert!(
            ir.contains("__karac_fnval_doubler"),
            "should synthesize an env-ignoring trampoline for the bare fn value:\n{ir}"
        );
    }

