    // ── Async `sleep_ms` — park-on-timer lowering (phase-5 auto-par ──
    //    divergence A2a-2.2) ──
    //
    // `sleep_ms(ms)` (the leaf `suspends` primitive, `std.time`) lowers to
    // the `karac_park_on_timer` state machine: the call site converts ms →
    // ns, allocs the state struct, drives the poll-fn once (state_0 arms a
    // reactor deadline via `karac_runtime_event_loop_register_timer` and
    // returns Pending), then blocks on a completion slot the dispatcher
    // signals on expiry. Unlike a `blocks` libc `usleep`, two `sleep_ms`
    // calls under `par {}` overlap on the timer wheel rather than pin two
    // OS threads for their full naps.

    #[test]
    fn sleep_ms_lowers_to_park_on_timer() {
        // Runtime-valued duration so the ms→ns multiply is NOT
        // constant-folded away (a literal `sleep_ms(500)` folds
        // `500 * 1_000_000` to a constant and the named `mul` vanishes).
        let ir = ir_for(
            "fn nap(ms: i64) {\n\
                 sleep_ms(ms);\n\
             }\n\
             fn main() {\n\
                 nap(500);\n\
             }",
        );
        // The deadline is armed through the timer-register FFI (NOT
        // register_fd — there is no fd).
        assert!(
            ir.contains("karac_runtime_event_loop_register_timer"),
            "expected sleep_ms to arm a reactor deadline via \
             karac_runtime_event_loop_register_timer; IR:\n{ir}"
        );
        // The park-on-timer poll-fn + constructor are emitted.
        assert!(
            ir.contains("__kara_poll_karac_park_on_timer")
                && ir.contains("__kara_state_new_karac_park_on_timer"),
            "expected the karac_park_on_timer poll-fn + constructor in IR:\n{ir}"
        );
        // The call site composes with the primitive: ms→ns convert (survives
        // because `ms` is runtime-valued), alloc the state, drive the poll,
        // and block on the completion slot (dispatcher-yield model).
        let nap_body = function_body(&ir, "nap").unwrap_or_else(|| {
            panic!("nap body not found in IR:\n{ir}");
        });
        assert!(
            nap_body.contains("kara.timer.ms_to_nanos"),
            "expected the call site to convert ms→ns; nap body:\n{nap_body}"
        );
        assert!(
            nap_body.contains("kara.timer.dur.field") && nap_body.contains("kara.timer.poll_wait"),
            "expected the call site to store the duration + block on the \
             completion slot; nap body:\n{nap_body}"
        );
        // Unlike the fd park, sleep_ms performs NO fd deregister (timers
        // have no fd / no epoll registration; the dispatcher claims its own).
        assert!(
            !nap_body.contains("karac_runtime_event_loop_deregister_fd"),
            "sleep_ms must NOT deregister an fd (timers have none); nap body:\n{nap_body}"
        );
    }

    #[test]
    fn e2e_sleep_ms_resumes_in_order() {
        // A short async sleep runs to completion and resumes the caller in
        // program order — proving the full arm→park→dispatcher-signal→resume
        // path works end-to-end (not just that the IR shape is right).
        if let Some(out) = run_program(
            "fn main() {\n\
                 println(\"a\");\n\
                 sleep_ms(20);\n\
                 println(\"b\");\n\
                 sleep_ms(20);\n\
                 println(\"c\");\n\
             }",
        ) {
            assert_eq!(out, "a\nb\nc\n");
        }
    }

    #[test]
    fn e2e_par_sleeps_both_branches_complete() {
        // Two `sleep_ms` calls inside `par {}` each run to completion (the
        // overlap *timing* win is measured by the bench harness
        // `bench/auto_par_io`; here we pin that the par+suspend composition
        // resumes BOTH branches rather than wedging one). Each branch prints
        // after its nap; both lines must appear.
        if let Some(out) = run_program(
            "fn main() {\n\
                 par {\n\
                     { sleep_ms(20); println(\"left\"); }\n\
                     { sleep_ms(20); println(\"right\"); }\n\
                 }\n\
             }",
        ) {
            assert!(
                out.contains("left") && out.contains("right"),
                "expected both par branches to complete after their naps; got:\n{out}"
            );
        }
    }

    #[test]
    fn e2e_auto_par_sleeps_run_correctly() {
        // A2b: two independent `sleep_ms` timer waits AUTO-parallelize (no
        // explicit `par {}` — the conflict model exempts a standalone `sleep_ms`
        // from the `suspends` boundary gate and lifts `(Suspends,Suspends)`).
        // They overlap on the par thread-block path; here we pin output
        // correctness and termination (the timing win is the bench's job).
        if let Some(out) = run_program(
            "fn main() {\n\
                 sleep_ms(20);\n\
                 sleep_ms(20);\n\
                 println(\"done\");\n\
             }",
        ) {
            assert_eq!(out, "done\n", "auto-par sleeps complete; got:\n{out}");
        }
    }

    #[test]
    fn e2e_auto_par_allocating_calls_run_correctly() {
        // A3: two independent statements that each only `allocates(Heap)` (each
        // builds a fresh Vec) AUTO-parallelize — the conflict model no longer
        // treats allocates+allocates as a conflict (heap is thread-safe;
        // `allocates` is informational per design.md). They run on the par
        // fan-out path; pin that each branch's heap allocation is independent
        // and the combined result is correct (no cross-branch corruption).
        if let Some(out) = run_program(
            "fn make(n: i64) -> Vec[i64] {\n\
                 let mut v: Vec[i64] = Vec.new();\n\
                 v.push(n);\n\
                 v.push(n + 1);\n\
                 return v;\n\
             }\n\
             fn main() {\n\
                 let a = make(10);\n\
                 let b = make(20);\n\
                 println(a[0] + a[1] + b[0] + b[1]);\n\
             }",
        ) {
            assert_eq!(
                out, "62\n",
                "auto-par allocating calls must each build their Vec correctly; got:\n{out}"
            );
        }
    }

    #[test]
    fn e2e_auto_par_panicking_calls_run_correctly() {
        // A3b: two independent statements that each only `panics` (each calls a
        // dividing helper — `/` infers `panics`) AUTO-parallelize now that the
        // conflict model treats panics+panics as non-conflicting. Neither
        // actually divides by zero, so this is the common, beneficial case:
        // ordinary arithmetic runs concurrently. Pin output correctness.
        if let Some(out) = run_program(
            "fn divmod(n: i64, d: i64) -> i64 { return n / d; }\n\
             fn main() {\n\
                 let a = divmod(100, 5);\n\
                 let b = divmod(200, 4);\n\
                 println(a + b);\n\
             }",
        ) {
            assert_eq!(
                out, "70\n",
                "auto-par panicking-effect calls must compute correctly; got:\n{out}"
            );
        }
    }

    #[test]
    fn e2e_auto_par_branch_panic_fails_fast() {
        // A3b soundness gate: when one of two grouped panic-capable statements
        // ACTUALLY panics inside a `__par_branch` worker (here a real divide by
        // zero), the program must FAIL FAST — a Kāra panic lowers to `exit(1)`
        // (a direct process exit, not a Rust unwind), so the worker terminates
        // the whole process. We assert a non-zero exit and the panic message,
        // and the `output_with_hang_watchdog` wrapper makes this double as a
        // deadlock guard: a regression that hung on the worker exit (e.g. exit
        // while another thread holds the output lock) would trip the watchdog
        // rather than pass.
        if let Some(c) = run_program_capturing(
            "fn divmod(n: i64, d: i64) -> i64 { return n / d; }\n\
             fn main() {\n\
                 let zero = 0;\n\
                 let a = divmod(100, 5);\n\
                 let b = divmod(200, zero);\n\
                 println(a + b);\n\
             }",
        ) {
            assert_eq!(
                c.status.code(),
                Some(101),
                "a branch panic must fail fast with exit 1; stdout={:?} stderr={:?}",
                c.stdout,
                c.stderr
            );
            assert!(
                c.stderr.contains("division by zero"),
                "expected the div-by-zero panic message; stdout={:?} stderr={:?}",
                c.stdout,
                c.stderr
            );
        }
    }

    #[test]
    fn e2e_auto_par_channel_consumer_terminates() {
        // Regression (A2b): the producer/consumer channel program must TERMINATE
        // under default auto-par. `consume(rx)` carries a `suspends` effect (from
        // `rx.recv()`) that is indistinguishable at the effect level from a
        // `sleep_ms` timer wait, but a channel recv has a happens-before with its
        // producer — lifting `consume(rx)` into a `__par_branch` worker alongside
        // the `spawn` deadlocks (the recv loop never observes the channel close).
        // The conservative boundary gate keeps it serial (only direct `sleep_ms`
        // is exempt). A regression here would HANG, not just misprint, so the
        // test doubles as the deadlock guard.
        if let Some(out) = run_program(
            "fn producer(tx: Sender[i64]) -> i64 {\n\
                 tx.send(10);\n\
                 tx.send(20);\n\
                 0\n\
             }\n\
             fn consume(rx: Receiver[i64]) -> i64 {\n\
                 let mut sum = 0;\n\
                 let mut go = true;\n\
                 while go {\n\
                     let v = rx.recv();\n\
                     if v == 0 { go = false; } else { sum = sum + v; }\n\
                 }\n\
                 sum\n\
             }\n\
             fn main() {\n\
                 let (tx, rx): (Sender[i64], Receiver[i64]) = Channel.new();\n\
                 let h: TaskHandle[i64] = spawn(|| producer(tx));\n\
                 println(consume(rx));\n\
                 h.join();\n\
             }",
        ) {
            assert_eq!(
                out, "30\n",
                "channel consumer must terminate with 30; got:\n{out}"
            );
        }
    }

    // ── Move-suppression for user-Drop bindings (let-rebind) ──
    //
    // `let g = f;` where `f` has a user `impl Drop` moves the value
    // out of `f` into `g`. Without suppression both bindings would
    // fire their UserDrop at scope exit, double-closing fds /
    // double-calling user Drop bodies. The codegen `stmts.rs`
    // let-binding tracking calls `suppress_user_drop_for_var` on the
    // source name before tracking the destination, removing the
    // source's CleanupAction::UserDrop. These tests pin the
    // observable IR shape: exactly one `call @karac_drop_<Type>`
    // remains in main.

    #[test]
    fn test_ir_let_rebind_suppresses_source_user_drop() {
        let ir = ir_for(
            r#"
struct Foo { x: i64 }
impl Drop for Foo {
    fn drop(mut ref self) {}
}
fn main() {
    let f = Foo { x: 1 };
    let g = f;
    println(g.x);
}
"#,
        );
        let main_body = function_body(&ir, "main").unwrap_or_else(|| {
            panic!("main body not found in IR:\n{}", ir);
        });
        let count = main_body.matches("call void @karac_drop_Foo(").count();
        assert_eq!(
            count, 1,
            "expected exactly ONE `@karac_drop_Foo` call in main \
             (source `f` should be move-suppressed; only destination \
             `g` drops at scope exit); got {} calls; body was:\n{}",
            count, main_body
        );
    }

    #[test]
    fn test_ir_let_rebind_tcp_listener_suppresses_double_close() {
        // Production motivation: `let l2 = l1` for TcpListener should
        // close the fd exactly once at scope exit, not twice. The IR
        // pins the same shape: one `@karac_drop_TcpListener` call.
        let ir = ir_for(
            r#"
fn main() {
    let l1 = TcpListener.bind("127.0.0.1:0").unwrap();
    let l2 = l1;
    println(l2.fd);
}
"#,
        );
        let main_body = function_body(&ir, "main").unwrap_or_else(|| {
            panic!("main body not found in IR:\n{}", ir);
        });
        let count = main_body
            .matches("call void @karac_drop_TcpListener(")
            .count();
        assert_eq!(
            count, 1,
            "expected exactly ONE `@karac_drop_TcpListener` call in main \
             after `let l2 = l1` (source `l1` move-suppressed); got {} \
             calls; body was:\n{}",
            count, main_body
        );
    }

    // ── Move-suppression for return-by-value of user-Drop bindings ──
    //
    // `fn make() -> T { let l = T::new(); l }` — `l`'s value moves
    // out as the function's return value. Without suppression, the
    // function-scope cleanup would fire `l`'s UserDrop (close the
    // fd) before the return happens, leaving the caller with a stale
    // fd. The fix in `suppress_cleanup_for_tail_return` removes `l`'s
    // UserDrop from the scope-cleanup stack right before
    // `emit_scope_cleanup` runs; the caller then closes the fd
    // exactly once when its own binding goes out of scope.

    #[test]
    fn test_ir_return_by_value_suppresses_source_user_drop() {
        let ir = ir_for(
            r#"
struct Foo { x: i64 }
impl Drop for Foo {
    fn drop(mut ref self) {}
}
fn make() -> Foo {
    let f = Foo { x: 7 };
    f
}
fn main() {
    let r = make();
    println(r.x);
}
"#,
        );
        let make_body = function_body(&ir, "make").unwrap_or_else(|| {
            panic!("make body not found in IR:\n{}", ir);
        });
        assert!(
            !make_body.contains("call void @karac_drop_Foo("),
            "expected `make` to NOT contain `@karac_drop_Foo` — `f` is \
             moved out as the return value and its UserDrop should be \
             suppressed before scope-exit cleanup. body was:\n{}",
            make_body
        );
        // The caller still drops the value at its own scope exit.
        let main_body = function_body(&ir, "main").unwrap_or_else(|| {
            panic!("main body not found in IR:\n{}", ir);
        });
        assert!(
            main_body.contains("call void @karac_drop_Foo("),
            "expected `main` to drop `r` at scope exit (caller owns \
             the returned value); body was:\n{}",
            main_body
        );
    }

    #[test]
    fn test_ir_explicit_return_suppresses_source_user_drop() {
        // `return f;` is an explicit return that takes the
        // Return-statement path in `compile_expr`. The companion
        // suppression in `src/codegen/exprs.rs`'s `ExprKind::Return`
        // arm pins this case.
        let ir = ir_for(
            r#"
struct Foo { x: i64 }
impl Drop for Foo {
    fn drop(mut ref self) {}
}
fn make() -> Foo {
    let f = Foo { x: 7 };
    return f;
}
fn main() {
    let r = make();
    println(r.x);
}
"#,
        );
        let make_body = function_body(&ir, "make").unwrap_or_else(|| {
            panic!("make body not found in IR:\n{}", ir);
        });
        assert!(
            !make_body.contains("call void @karac_drop_Foo("),
            "expected `make` to NOT contain `@karac_drop_Foo` — \
             explicit `return f` move-suppresses `f`. body was:\n{}",
            make_body
        );
    }

    // Note: production-shaped `fn make_listener() -> TcpListener {
    // let l = TcpListener.bind(...); l }` is the natural Slice 9d
    // motivating example, but is NOT currently testable end-to-end:
    // TcpListener-as-a-function-return-type fails LLVM module
    // verification with "Function return type does not match
    // operand type of return inst!" because the codegen's stdlib
    // struct-return ABI lowering doesn't yet wire the
    // single-i32-field shape through a function's return slot.
    // The user-struct case above (`fn make() -> Foo`) exercises the
    // same move-suppression mechanism; once the stdlib return-ABI
    // gap closes, the TcpListener case will compile and the move-
    // suppression machinery already wired here will make it
    // correct. Filed as a follow-on in phase-7-codegen.md's
    // move-suppression entry.

    #[test]
    fn test_ir_no_wrapper_without_impl_drop() {
        // No `impl Drop` → no entry in `program.drop_method_keys` →
        // `emit_user_drop_wrappers` synthesizes nothing.
        let ir = ir_for(
            r#"
struct Foo { x: i64 }
fn main() {
    let f = Foo { x: 1 };
}
"#,
        );
        assert!(
            !ir.contains("@karac_drop_Foo"),
            "wrapper `karac_drop_Foo` must NOT be emitted when `Foo` has \
             no `impl Drop`; found in:\n{}",
            ir
        );
    }

    #[test]
    fn test_e2e_struct_owning_map_shared_drops_cleanly() {
        // E2E: an `Owner` struct owns a `Map[i64, Node]` where
        // `Node` is a shared struct. Constructing the field with
        // `Map.new()` inline (no source local to double-track)
        // and letting scope-exit run the synthesized struct drop
        // is the contained surface for item 4 — the local-then-
        // place pattern would trip a pre-existing Map-handle
        // move-suppression gap (struct-field construction
        // suppresses Vec/String/struct source cleanups but not
        // Map handles; double-free on the local's FreeMapHandle
        // + the struct's drop). The IR test above pins the
        // structural assertion (walk emitted in the drop fn);
        // this test exercises it at runtime on the empty-Map
        // path so a future regression that breaks the drop fn's
        // IR shape surfaces as a crash here.
        let out = run_program(
            r#"
shared struct Node { val: i64 }
struct Owner { m: Map[i64, Node] }
fn main() {
    let _o = Owner { m: Map.new() };
    println(42);
}
"#,
        );
        if let Some(out) = out {
            assert_eq!(out.trim(), "42");
        }
    }

    // ── Unit enum variant matching ──────────────────────────────

    #[test]
    fn test_e2e_unit_enum_match() {
        let out = run_program(
            r#"
enum Color { Red, Green, Blue }
fn describe(c: Color) -> i64 {
    match c {
        Color.Red => 1,
        Color.Green => 2,
        Color.Blue => 3,
    }
}
fn main() {
    println(describe(Green));
    println(describe(Red));
    println(describe(Blue));
}
"#,
        );
        if let Some(out) = out {
            let lines: Vec<&str> = out.trim().lines().collect();
            assert_eq!(lines, vec!["2", "1", "3"]);
        }
    }

    #[test]
    fn test_e2e_shared_enum_unit_variant_match() {
        let out = run_program(
            r#"
shared enum Dir { North, South, East, West }
fn to_num(d: Dir) -> i64 {
    match d {
        Dir.North => 0,
        Dir.South => 1,
        Dir.East => 2,
        Dir.West => 3,
    }
}
fn main() {
    println(to_num(East));
    println(to_num(North));
}
"#,
        );
        if let Some(out) = out {
            let lines: Vec<&str> = out.trim().lines().collect();
            assert_eq!(lines, vec!["2", "0"]);
        }
    }

    // ── Array[T, N] fixed-size arrays ────────────────────────────

    #[test]
    fn test_ir_array_param_type() {
        // Array[T, N] parameter lowers to LLVM `[N x T]`.
        let ir = ir_for("fn take(a: Array[i64, 4]) { }");
        assert!(
            ir.contains("[4 x i64]"),
            "expected [4 x i64] in IR, got:\n{}",
            ir
        );
    }

    #[test]
    fn test_ir_array_different_sizes() {
        let ir = ir_for(
            "fn small(a: Array[i64, 3]) { }
             fn big(a: Array[i64, 16]) { }",
        );
        assert!(ir.contains("[3 x i64]"));
        assert!(ir.contains("[16 x i64]"));
    }

    #[test]
    fn test_ir_array_of_bool() {
        let ir = ir_for("fn flags(a: Array[bool, 8]) { }");
        assert!(
            ir.contains("[8 x i1]"),
            "expected [8 x i1] in IR, got:\n{}",
            ir
        );
    }

    #[test]
    fn test_ir_array_literal_construction() {
        // A bare `[…]` literal is `Vec[T]` by the typechecker's synthesis-mode
        // rule, so it now lowers (via the lowering `ArrayLiteral`→`Vec[…]`
        // canonicalization) to the `{ptr, i64, i64}` Vec struct — NOT a fixed
        // `[3 x i64]` array. (Pre-fix it emitted `[3 x i64]`, which segfaulted
        // on a subsequent `.push` and failed verification on a Vec return.)
        // The fixed-array lowering is exercised by `test_ir_array_literal_let_binding`
        // (`let a: Array[i64, 2] = …`) instead.
        let ir = ir_for("fn main() { let a = [10, 20, 30]; }");
        assert!(
            ir.contains("{ ptr, i64, i64 }"),
            "expected Vec struct for bare array literal, got:\n{}",
            ir
        );
    }

    #[test]
    fn test_ir_array_literal_let_binding() {
        let ir = ir_for("fn main() { let a: Array[i64, 2] = [1, 2]; }");
        // Array should be alloca'd and stored.
        assert!(
            ir.contains("alloca [2 x i64]"),
            "expected alloca [2 x i64], got:\n{}",
            ir
        );
    }

    #[test]
    fn test_ir_array_index_read() {
        let ir = ir_for(
            r#"
fn second() -> i64 {
    let a = [10, 20, 30];
    a[1]
}
"#,
        );
        // Should contain GEP into the array and a bounds check.
        assert!(
            ir.contains("getelementptr"),
            "expected getelementptr for array index, got:\n{}",
            ir
        );
        assert!(
            ir.contains("idx.oob"),
            "expected bounds-check OOB block, got:\n{}",
            ir
        );
        assert!(
            ir.contains("idx.ok"),
            "expected bounds-check OK block, got:\n{}",
            ir
        );
    }

    /// The canonical row-major converging two-pointer, shared by the two IR
    /// wiring tests below. Its ONLY Vec index sites are `v[base + lo]` and
    /// `v[base + hi]`, so any surviving `vidx.` bounds-check block in the IR
    /// belongs to them.
    const CONV_TWO_POINTER_SRC: &str = r#"
fn row_scan() -> i64 {
    let n = 20i64;
    let len = 32i64;
    let v: Vec[u8] = Vec.filled(n * len, 48u8);
    let mut acc = 0i64;
    let mut i = 0i64;
    while i < n {
        let base = i * len;
        let mut lo = 0i64;
        let mut hi = len - 1i64;
        while lo <= hi {
            acc = acc + (v[base + lo] as i64) - (v[base + hi] as i64);
            lo = lo + 1i64;
            hi = hi - 1i64;
        }
        i = i + 1i64;
    }
    acc
}
"#;

    #[test]
    fn test_ir_converging_two_pointer_bce_skip_wiring() {
        // B-2026-08-04-8: the converging skip proves `base + lo` and
        // `base + hi` are both in range for the row-major shape — upper from
        // the length pin + enclosing counter bound, lower from a non-negative
        // row origin — so BOTH halves are elided and no check block is emitted
        // at all.
        let ir = ir_for(CONV_TWO_POINTER_SRC);
        assert!(
            !ir.contains("vidx."),
            "expected the converging two-pointer loads to carry NO bounds \
             check, but found a `vidx.` block:\n{ir}"
        );
    }

    /// The same program with `lo`'s step moved BEFORE the index, which defeats
    /// the bounds proof. Used as the differential baseline: it has exactly the
    /// same arithmetic, so any difference in `sadd.with.overflow` count is the
    /// index adds and nothing else.
    fn conv_two_pointer_unproven_src() -> String {
        let src = CONV_TWO_POINTER_SRC.replace(
            "acc = acc + (v[base + lo] as i64) - (v[base + hi] as i64);\n            lo = lo + 1i64;",
            "lo = lo + 1i64;\n            acc = acc + (v[base + lo] as i64) - (v[base + hi] as i64);",
        );
        assert_ne!(src, CONV_TWO_POINTER_SRC, "reorder anchor did not match");
        src
    }

    fn count_add_overflow_intrinsics(ir: &str) -> usize {
        ir.matches("@llvm.sadd.with.overflow").count()
    }

    /// B-2026-08-05-16 — an unqualified variant pattern must resolve against
    /// the match scrutinee's OWN enum, deterministically.
    ///
    /// `Tok.Str(String, Sp)` and `shared enum Expr { .. Str(SLit) }` share the
    /// bare name `Str`. Resolution pinned on `llvm_type` equality for a VALUE
    /// scrutinee, which is not a unique key — two enums with structurally
    /// identical layouts share one LLVM struct type — so the enum came from
    /// whichever the unordered `enum_layouts` map yielded first. The wrong
    /// enum's `field_word_offsets` then drove the binding: `Sp.length` (3) was
    /// loaded and dereferenced as a buffer pointer, SEGV on address 0x3.
    ///
    /// ASSERTED BY REPETITION, deliberately. The trigger is the compiler's own
    /// per-HashMap seed, so ONE green compile proves nothing — the pre-fix
    /// compiler emitted correct IR on roughly a third of runs. Compiling the
    /// same source repeatedly and demanding byte-identical IR tests the
    /// determinism directly, and fails as soon as any run picks the other enum.
    ///
    /// The failure message deliberately does NOT name a cause. It used to
    /// assert one — "an unqualified variant name ... is resolving against
    /// whichever the unordered enum_layouts map yields first" — and when this
    /// test started failing ~6 of 8 full-suite runs, that sentence was read as
    /// the diagnosis and filed as the miscompile returning (B-2026-08-20-26).
    /// It had not: a sibling test was flipping the runtime-debug-metadata gate
    /// on the PROCESS env while this one compiled, so the single differing
    /// line was `@KARAC_SPAWN_SITES_ENABLED`. A repetition test can observe
    /// that two compiles differ; it cannot observe why, so it should not say.
    #[test]
    fn test_ir_shared_variant_name_resolves_to_scrutinee_enum_deterministically() {
        const SRC: &str = r#"
struct Sp { line: i64, column: i64, offset: i64, length: i64 }
struct SLit { value: String, span: Sp }
enum Tok { Str(String, Sp), Int(i64) }
shared enum Expr { Int(i64), Boolish(i64), Str(SLit) }
fn text_of(e: Expr) -> String {
    match e {
        Int(v) => v.to_string(),
        Boolish(v) => v.to_string(),
        Str(n) => n.value,
    }
}
fn tok_kind(t: Tok) -> i64 {
    match t { Str(s, sp) => 1, Int(v) => 2 }
}
fn main() {
    let t = Tok.Str("tok".to_string(), Sp { line: 1, column: 1, offset: 0, length: 3 });
    let n = SLit { value: "hello world".to_string(), span: Sp { line: 1, column: 1, offset: 7, length: 11 } };
    println(tok_kind(t) + text_of(Expr.Str(n)).len());
}
"#;
        let first = ir_for(SRC);
        for i in 1..24 {
            let again = ir_for(SRC);
            let differing: Vec<String> = first
                .lines()
                .zip(again.lines())
                .filter(|(a, b)| a != b)
                .take(8)
                .map(|(a, b)| format!("\n  first: {a}\n  again: {b}"))
                .collect();
            assert_eq!(
                first,
                again,
                "IR for the same source differed on compile {i}. Two causes \
                 produce this, and the differing lines below tell them apart: \
                 an unqualified variant name shared across two enums resolving \
                 against whichever enum the unordered `enum_layouts` map yields \
                 first (B-2026-08-05-16 — expect tag constants / payload word \
                 offsets to move), or another test in this binary mutating a \
                 codegen env gate on the PROCESS env mid-compile \
                 (B-2026-08-20-26 — expect a single global's initializer to \
                 flip). Differing lines:{}",
                differing.join("")
            );
        }
    }

    #[test]
    fn test_ir_proven_index_add_skips_its_overflow_check() {
        // B-2026-08-05-21: when BCE has proven `0 <= base + i < v.len()`, the
        // add that computed the index provably cannot overflow, so its trap is
        // dead and must not be emitted.
        //
        // Asserted as a DIFFERENTIAL against the reordered variant rather than
        // an absolute count: both programs contain the same five adds
        // (`acc + ..`, `base + lo`, `base + hi`, `lo + 1`, `i + 1`), and only
        // the two index adds are provable. So the proven form must carry
        // exactly two fewer intrinsics — an absolute count would silently pass
        // if an unrelated add were added to or removed from the fixture.
        let proven = count_add_overflow_intrinsics(&ir_for(CONV_TWO_POINTER_SRC));
        let unproven = count_add_overflow_intrinsics(&ir_for(&conv_two_pointer_unproven_src()));
        assert_eq!(
            unproven,
            proven + 2,
            "expected the two proven index adds to drop their overflow checks \
             (proven={proven}, unproven={unproven})"
        );
        assert!(
            proven > 0,
            "the unprovable adds (`lo + 1`, `i + 1`, `acc + ..`) must KEEP \
             their checks — a zero count would mean the elision is firing far \
             too widely, got {proven}"
        );
    }

    #[test]
    fn test_ir_unproven_index_add_keeps_its_overflow_check() {
        // The gate, stated positively: with the bounds proof defeated by the
        // reordering, BOTH the bounds check and the overflow check must
        // survive. Pins that the elision rides on the proof rather than on the
        // syntactic `v[a + b]` shape.
        let ir = ir_for(&conv_two_pointer_unproven_src());
        assert!(
            ir.contains("vidx.ok"),
            "expected the unproven loop to keep its bounds check, got:\n{ir}"
        );
        assert!(
            count_add_overflow_intrinsics(&ir) >= 5,
            "expected every add to keep its overflow check when nothing is \
             proven, got {} in:\n{ir}",
            count_add_overflow_intrinsics(&ir)
        );
    }

    #[test]
    fn test_ir_converging_skip_refused_when_index_steps_before_use() {
        // The soundness gate, at the IR level: stepping `lo` BEFORE the index
        // means `lo` can exceed the bound the `lo <= hi` guard established, so
        // the skip must NOT fire and the full combined check must survive.
        // Same program as above with only the statement order changed.
        let src = CONV_TWO_POINTER_SRC.replace(
            "acc = acc + (v[base + lo] as i64) - (v[base + hi] as i64);\n            lo = lo + 1i64;",
            "lo = lo + 1i64;\n            acc = acc + (v[base + lo] as i64) - (v[base + hi] as i64);",
        );
        assert_ne!(src, CONV_TWO_POINTER_SRC, "reorder anchor did not match");
        let ir = ir_for(&src);
        assert!(
            ir.contains("vidx.ok"),
            "expected the reordered loop to KEEP its combined bounds check \
             (the skip is unsound there), got:\n{ir}"
        );
    }

    /// The row-helper shape: the length pin, the enclosing counter and the
    /// linear base all sit in the CALLER, so nothing inside `row_scan` can
    /// prove its own index in range. Shared by the interprocedural wiring
    /// tests below. `{CALLER_LOOP}` is substituted per test.
    const INTERPROC_ROW_HELPER_SRC: &str = r#"
fn row_scan(v: ref Vec[u8], base: i64, len: i64) -> i64 {
    let mut lo = 0i64;
    let mut hi = len - 1i64;
    let mut acc = 0i64;
    while lo <= hi {
        acc = acc + (v[base + lo] as i64) - (v[base + hi] as i64);
        lo = lo + 1i64;
        hi = hi - 1i64;
    }
    acc
}

fn driver() -> i64 {
    let n = 20i64;
    let len = 32i64;
    let v: Vec[u8] = Vec.filled(n * len, 48u8);
    let mut acc = 0i64;
    let mut i = 0i64;
    {CALLER_LOOP}
    acc
}
"#;

    fn interproc_row_helper_src(caller_loop: &str) -> String {
        let out = INTERPROC_ROW_HELPER_SRC.replace("{CALLER_LOOP}", caller_loop);
        assert_ne!(out, INTERPROC_ROW_HELPER_SRC, "caller-loop anchor missing");
        out
    }

    #[test]
    fn test_ir_interproc_row_helper_bce_skip_wiring() {
        // B-2026-08-05-6: `row_scan` walks a caller-owned buffer at a
        // caller-chosen offset. Every fact the intra-function converging skip
        // needs is a parameter value here, so `bce_length_pin` alone leaves
        // both checks standing. `bce_interproc` infers the precondition
        // `base + (len - 1) < v.len()`, discharges it at the one call site
        // (`base = i * len`, `i < n`, `v.len() >= n * len`), and installs the
        // same `ConvergingSkip` record — so the loads carry no check at all.
        let ir = ir_for(&interproc_row_helper_src(
            "while i < n { acc = acc + row_scan(v, i * len, len); i = i + 1i64; }",
        ));
        assert!(
            !ir.contains("vidx."),
            "expected the row-helper loads to carry NO bounds check once the \
             interprocedural precondition is discharged, but found a `vidx.` \
             block:\n{ir}"
        );
    }

    #[test]
    fn test_ir_interproc_skip_refused_when_one_call_site_is_undischarged() {
        // ONE body is emitted, so ONE fact must cover every call. A second
        // call site passing an out-of-range `base` cannot discharge, and that
        // disqualifies the callee outright — the good site does NOT get a
        // specialised copy. Without this the program would read out of bounds
        // through the very call that is in range everywhere else.
        let ir = ir_for(&interproc_row_helper_src(
            "while i < n { acc = acc + row_scan(v, i * len, len); i = i + 1i64; }\n    \
             acc = acc + row_scan(v, n * len - 2i64, len);",
        ));
        assert!(
            ir.contains("vidx."),
            "expected the row-helper loads to KEEP their bounds check when a \
             second call site cannot discharge the precondition, got:\n{ir}"
        );
    }

    #[test]
    fn test_ir_interproc_skip_refused_for_off_by_one_caller_bound() {
        // The caller's guard is `i <= n`, not `i < n`, so the last row starts
        // at `n * len` and runs one whole row past the buffer. The linear
        // cancellation must fail: `n * len - (n * len + len - 1)` is not a
        // positive constant.
        let ir = ir_for(&interproc_row_helper_src(
            "while i <= n { acc = acc + row_scan(v, i * len, len); i = i + 1i64; }",
        ));
        assert!(
            ir.contains("vidx."),
            "expected the row-helper loads to KEEP their bounds check under an \
             off-by-one caller bound, got:\n{ir}"
        );
    }

    #[test]
    fn e2e_interproc_row_helper_reads_the_right_elements() {
        // The IR tests above assert the check is GONE; this one asserts the
        // loads still land on the right elements once it is. Every position
        // holds a distinct value (`k * k + 1`), so an off-by-one in either
        // index — or a row walked at the wrong base — changes the sum. Oracle
        // is the interpreter's answer for the same source.
        let out = run_program(
            "fn row_scan(v: ref Vec[i64], base: i64, len: i64) -> i64 {\n\
                 let mut lo = 0i64;\n\
                 let mut hi = len - 1i64;\n\
                 let mut acc = 0i64;\n\
                 while lo <= hi {\n\
                     acc = acc + v[base + lo] * 3i64 - v[base + hi];\n\
                     lo = lo + 1i64;\n\
                     hi = hi - 1i64;\n\
                 }\n\
                 return acc;\n\
             }\n\
             fn main() {\n\
                 let n = 7i64;\n\
                 let len = 5i64;\n\
                 let mut v: Vec[i64] = Vec.new();\n\
                 let mut k = 0i64;\n\
                 while k < n * len {\n\
                     v.push(k * k + 1i64);\n\
                     k = k + 1i64;\n\
                 }\n\
                 let mut acc = 0i64;\n\
                 let mut i = 0i64;\n\
                 while i < n {\n\
                     acc = acc + row_scan(v, i * len, len);\n\
                     i = i + 1i64;\n\
                 }\n\
                 println(acc);\n\
             }",
        );
        assert_eq!(out, Some("13594\n".to_string()));
    }

    #[test]
    fn e2e_interproc_row_helper_still_panics_on_an_undischarged_call() {
        // The mirror image: a call site that cannot discharge keeps the check,
        // so an out-of-range row still TRAPS instead of reading past the
        // buffer. Note what the trapping run proves: the good rows printed
        // their correct sum first, so the surviving check is not a blanket
        // "analysis gave up" — the same body served both sites and caught only
        // the bad one.
        const BODY: &str = "fn row_scan(v: ref Vec[i64], base: i64, len: i64) -> i64 {\n\
                 let mut lo = 0i64;\n\
                 let mut hi = len - 1i64;\n\
                 let mut acc = 0i64;\n\
                 while lo <= hi {\n\
                     acc = acc + v[base + lo] - v[base + hi];\n\
                     lo = lo + 1i64;\n\
                     hi = hi - 1i64;\n\
                 }\n\
                 return acc;\n\
             }\n\
             fn main() {\n\
                 let n = 7i64;\n\
                 let len = 5i64;\n\
                 let mut v: Vec[i64] = Vec.new();\n\
                 let mut k = 0i64;\n\
                 while k < n * len {\n\
                     v.push(k * k + 1i64);\n\
                     k = k + 1i64;\n\
                 }\n\
                 let mut acc = 0i64;\n\
                 let mut i = 0i64;\n\
                 while i < n {\n\
                     acc = acc + row_scan(v, i * len, len);\n\
                     i = i + 1i64;\n\
                 }\n\
                 println(acc);\n";
        assert_eq!(
            run_program(&format!("{BODY}}}")),
            Some("-1428\n".to_string()),
            "control: the in-range program must run clean"
        );
        // The pre-trap row still prints on stdout; the trap itself is on
        // stderr (B-2026-08-23-17), so this needs the capturing harness.
        let trapped = run_program_capturing(&format!(
            "{BODY}    println(row_scan(v, n * len - 2i64, len));\n}}"
        ))
        .expect("program should build and run");
        assert!(
            trapped.stdout.starts_with("-1428\n")
                && trapped.stderr.contains("vec index out of bounds"),
            "the out-of-range row must still trap — the second call site cannot \
             discharge the precondition, so the bounds check must survive; got \
             stdout={:?} stderr={:?}",
            trapped.stdout,
            trapped.stderr
        );
    }

    /// B-2026-08-24-15 — `Vec.insert` / `Vec.remove` / `Vec.swap_remove` emit
    /// no bounds check in codegen, so an out-of-range index was memory-unsafe
    /// instead of fatal.
    ///
    /// `insert`'s shift count is `len - idx`, so `idx > len` went negative and
    /// reached `memmove` as a huge unsigned byte count (glibc `free(): invalid
    /// pointer`, exit 134). `remove` did the same. `swap_remove` did not crash
    /// at all — it read past the end, returned the garbage (a live heap
    /// pointer, under the JIT) and decremented `len`, dropping a live element
    /// with a clean exit 0.
    ///
    /// Plain indexing `v[i]` was always checked, which is what made this an
    /// inconsistency inside one type rather than a no-checks policy. All three
    /// must now panic exactly as `--interp` and design.md say they do.
    ///
    /// B-2026-08-26-21 follow-up adds `Vec.swap` to the family, and it was the
    /// worst of the four: codegen had NO `swap` arm at all (`karac build`
    /// hard-errored "not yet supported"), while the interpreter accepted an
    /// out-of-range swap and SILENTLY DID NOTHING — `v.swap(0, 99)` on a
    /// two-element Vec left the vector untouched and exited 0. Negative indices
    /// were swallowed the same way, by an `as usize` cast that wrapped them out
    /// of range. Both halves are fixed; the negative cases below are what pin
    /// the wrap.
    #[test]
    fn vec_mutation_methods_bounds_check_out_of_range_index() {
        const PRELUDE: &str = "fn main() {\n\
             let mut v: Vec[i64] = Vec.new();\n\
             v.push(11i64);\n\
             v.push(22i64);\n";

        // (call, panic-message fragment) — each must trap, not corrupt.
        let cases = [
            ("v.insert(7i64, 9i64);", "Vec.insert index out of bounds"),
            ("v.insert(-1i64, 9i64);", "Vec.insert index out of bounds"),
            (
                "let x = v.remove(7i64); println(x);",
                "Vec.remove index out of bounds",
            ),
            (
                "let x = v.remove(-1i64); println(x);",
                "Vec.remove index out of bounds",
            ),
            (
                "let x = v.swap_remove(7i64); println(x);",
                "Vec.swap_remove index out of bounds",
            ),
            (
                "let x = v.swap_remove(-1i64); println(x);",
                "Vec.swap_remove index out of bounds",
            ),
            ("v.swap(7i64, 0i64);", "Vec.swap index out of bounds"),
            ("v.swap(0i64, 7i64);", "Vec.swap index out of bounds"),
            ("v.swap(-1i64, 0i64);", "Vec.swap index out of bounds"),
            ("v.swap(0i64, -1i64);", "Vec.swap index out of bounds"),
        ];

        for (call, want) in cases {
            let src = format!("{PRELUDE}    {call}\n    println(\"survived\");\n}}");
            let run = match run_program_capturing(&src) {
                Some(r) => r,
                None => return, // no runtime archive / linker — harness skip
            };
            assert!(
                run.stderr.contains(want),
                "{call} must panic with {want:?}; got stdout={:?} stderr={:?}",
                run.stdout,
                run.stderr
            );
            assert!(
                !run.stdout.contains("survived"),
                "{call} must not fall through to the next statement; got stdout={:?}",
                run.stdout
            );
            // Exit 101 is the panic path. The bug produced 134 (abort from
            // glibc's heap check) for insert/remove and 0 for swap_remove, so
            // pinning the code is what separates "panics" from "dies somehow".
            assert_eq!(
                run.status.code(),
                Some(101),
                "{call} must exit via panic (101), not abort or success; stderr={:?}",
                run.stderr
            );
        }
    }

    /// B-2026-08-25-3 — THE STRUCTURAL GUARD for
    /// `vec_mutation_methods_bounds_check_out_of_range_index`.
    ///
    /// That test proves the check FIRED on one execution. It cannot distinguish
    /// "the check is present" from "the check is absent but this run happened
    /// not to expose it" — which is exactly why an intermittent green on it was
    /// alarming enough to open B-2026-08-25-3 at high priority: a guard that
    /// sometimes passes lets CI go green while a heap-corruption bug is live.
    /// Sampling cannot fix that property (30,000 clean compile+runs on arm64
    /// bounded the rate and settled nothing). Asserting on the EMITTED CODE can.
    ///
    /// This asserts the panic path for each of the three methods survives into
    /// the object file, i.e. past BOTH codegen and the LLVM pipeline — an
    /// IR-only assertion would miss a backend that deleted the branch later.
    ///
    /// THE INDEX MUST BE OPAQUE, and this is the whole subtlety. LLVM removing
    /// the check when it can PROVE the index in range is CORRECT optimization,
    /// not a bug, so a literal index would assert against legitimate behaviour.
    /// `env.args().len()` is the codebase's opacity idiom (a stable 1 at run
    /// time, unknowable at compile time). Measured while writing this: with a
    /// literal `0` all three messages correctly VANISH from the binary.
    ///
    /// ONE PROGRAM PER METHOD, also load-bearing. Chaining them lets the
    /// compiler carry a range fact across calls — a combined program had
    /// `remove`'s check correctly folded away, because a preceding successful
    /// `insert(i, _)` proves `i <= len` and so `i < len+1`.
    ///
    /// Runs on the OBJECT, so it needs no linker and no runtime archive: unlike
    /// the E2E guard it has no soft-skip path and cannot report a vacuous green.
    #[test]
    fn vec_mutation_bounds_checks_survive_into_emitted_object() {
        use karac::codegen::compile_to_object_with_options;

        // (method, call form, panic message)
        let cases = [
            (
                "insert",
                "v.insert(i, 9); println(v.len());",
                "Vec.insert index out of bounds",
            ),
            (
                "remove",
                "let x = v.remove(i); println(x);",
                "Vec.remove index out of bounds",
            ),
            (
                "swap_remove",
                "let x = v.swap_remove(i); println(x);",
                "Vec.swap_remove index out of bounds",
            ),
        ];

        let emit = |body: &str, tag: &str| -> Vec<u8> {
            let src = format!(
                "fn main() {{\n\
                 \x20   let mut v: Vec[i64] = Vec.new();\n\
                 \x20   v.push(11);\n\
                 \x20   v.push(22);\n\
                 \x20   let i: i64 = env.args().len() as i64;\n\
                 \x20   {body}\n\
                 }}"
            );
            let mut parsed = karac::parse(&src);
            assert!(
                parsed.errors.is_empty(),
                "parse errors: {:?}",
                parsed.errors
            );
            karac::prepare_for_resolve(&mut parsed.program);
            let resolved = karac::resolve(&parsed.program);
            let typed = karac::typecheck(&parsed.program, &resolved);
            super::common::assert_check_clean(&resolved, &typed, &src);
            karac::lower(&mut parsed.program, &typed);
            let ownership = karac::ownershipcheck(&parsed.program, &typed);
            let obj = format!("/tmp/karac_boundsguard_{}_{}.o", std::process::id(), tag);
            let _ = std::fs::remove_file(&obj);
            compile_to_object_with_options(
                &parsed.program,
                &obj,
                Some(&ownership),
                None,
                None,
                None,
            )
            .unwrap_or_else(|e| panic!("codegen failed for {tag}: {e}"));
            let bytes = std::fs::read(&obj)
                .unwrap_or_else(|e| panic!("emitted object for {tag} unreadable: {e}"));
            let _ = std::fs::remove_file(&obj);
            assert!(!bytes.is_empty(), "emitted object for {tag} was empty");
            bytes
        };

        let contains = |hay: &[u8], needle: &str| -> bool {
            hay.windows(needle.len()).any(|w| w == needle.as_bytes())
        };

        // ANTI-VACUITY: a program that never calls these methods must carry
        // none of the three messages. Without this, a match on some unrelated
        // always-present string would make every assertion below trivially true.
        let baseline = emit("println(v.len());", "baseline");
        for (method, _, msg) in cases {
            assert!(
                !contains(&baseline, msg),
                "anti-vacuity failed: {msg:?} appears in an object whose program \
                 never calls Vec.{method} — the search is matching something \
                 unrelated, so the assertions below prove nothing"
            );
        }

        for (method, call, msg) in cases {
            let bytes = emit(call, method);
            assert!(
                contains(&bytes, msg),
                "Vec.{method}'s bounds check did NOT survive into the emitted \
                 object: {msg:?} is absent. The index is `env.args().len()`, \
                 which is opaque at compile time, so the check cannot be \
                 legitimately optimised away — its absence means an \
                 out-of-range {method} would corrupt the heap (B-2026-08-24-15)."
            );
        }
    }

    /// B-2026-08-25-3 — the RUNTIME half of the bounds check, which neither
    /// sibling guard actually reaches.
    ///
    /// `vec_mutation_methods_bounds_check_out_of_range_index` uses LITERAL
    /// indices on a `Vec` whose length is provable, so LLVM settles the
    /// comparison at COMPILE time. Measured: `v.insert(7i64, …)` emits an
    /// unconditional panic and DELETES the `println("survived")` fall-through —
    /// the string is absent from the binary — while `v.insert(1i64, …)` drops
    /// the panic message entirely. Its `!stdout.contains("survived")` assertion
    /// is therefore discharged by dead-code elimination rather than by a check
    /// firing. This surfaced as two different out-of-range literals compiling to
    /// BYTE-IDENTICAL binaries (`insert(7)` and `insert(3)`, same SHA-256).
    ///
    /// `vec_mutation_bounds_checks_survive_into_emitted_object` keeps the index
    /// opaque, but asserts only that the message is PRESENT in the object, and
    /// its index (`env.args().len()`, a stable 1) is IN RANGE — so it never
    /// fires either.
    ///
    /// So nothing covered the case real code actually hits: an index computed at
    /// run time that turns out to be out of range. `env.args().len() + 6` is
    /// opaque to the optimiser and equals 7 against a length of 2, so the check
    /// must survive to the binary AND fire when it runs.
    #[test]
    fn vec_mutation_bounds_check_fires_for_a_runtime_opaque_index() {
        let cases = [
            ("v.insert(i, 9i64);", "Vec.insert index out of bounds"),
            (
                "let x = v.remove(i); println(x);",
                "Vec.remove index out of bounds",
            ),
            (
                "let x = v.swap_remove(i); println(x);",
                "Vec.swap_remove index out of bounds",
            ),
        ];

        for (call, want) in cases {
            let src = format!(
                "fn main() {{\n\
                 \x20   let mut v: Vec[i64] = Vec.new();\n\
                 \x20   v.push(11i64);\n\
                 \x20   v.push(22i64);\n\
                 \x20   let i: i64 = (env.args().len() as i64) + 6i64;\n\
                 \x20   {call}\n\
                 \x20   println(\"survived\");\n\
                 }}"
            );
            let run = match run_program_capturing(&src) {
                Some(r) => r,
                None => return, // no runtime archive / linker — harness skip
            };
            assert!(
                run.stderr.contains(want),
                "a RUN-TIME out-of-range index must panic with {want:?}; got \
                 stdout={:?} stderr={:?}",
                run.stdout,
                run.stderr
            );
            assert!(
                !run.stdout.contains("survived"),
                "{call} fell through to the next statement; got stdout={:?}",
                run.stdout
            );
            assert_eq!(
                run.status.code(),
                Some(101),
                "{call} must exit via panic (101), not abort or success; \
                 stderr={:?}",
                run.stderr
            );
        }
    }

    /// The other half of B-2026-08-24-15: the new bounds checks must not
    /// reject anything legal. `insert(len, v)` is an APPEND and is valid —
    /// `insert` alone accepts `idx == len`, which is why it needs `UGT` where
    /// `remove` / `swap_remove` need `UGE`. Getting that predicate wrong turns
    /// a memory-safety fix into a broken `push`.
    #[test]
    fn vec_mutation_methods_accept_every_in_range_index() {
        let src = "fn main() {\n\
             let mut v: Vec[i64] = Vec.new();\n\
             v.push(11i64);\n\
             v.push(22i64);\n\
             v.insert(2i64, 33i64);\n\
             v.insert(0i64, 0i64);\n\
             println(v.len());\n\
             let a = v.remove(0i64);\n\
             let b = v.remove(v.len() - 1i64);\n\
             let c = v.swap_remove(0i64);\n\
             println(a);\n\
             println(b);\n\
             println(c);\n\
             println(v.len());\n\
             let mut e: Vec[i64] = Vec.new();\n\
             e.insert(0i64, 7i64);\n\
             println(e[0]);\n\
         }";
        // insert(2)=append -> 11 22 33; insert(0) -> 0 11 22 33
        // remove(0)=0; remove(last)=33; swap_remove(0)=11, leaving [22]
        assert_eq!(
            run_program(src),
            Some("4\n0\n33\n11\n1\n7\n".to_string()),
            "in-range insert/remove/swap_remove must be unaffected, including \
             insert-at-len (append) and insert(0) into an EMPTY vec"
        );
    }

    /// B-2026-08-25-20 — the `Vec` capacity family, twinned against the
    /// interpreter rather than pinned to a string.
    ///
    /// TWINNING IS THE POINT HERE, and it is also why every capacity assertion
    /// inside the program is a `>=`. `capacity()` is a lower-bound query, not
    /// an allocator promise: the interpreter grows a host `Vec<Value>` on
    /// Rust's policy and codegen grows on `max(4, cap * 2)`, so the two
    /// legitimately report different numbers. What both owe is the CONTRACT —
    /// `capacity() >= len()`, and `>= len() + n` after `reserve(n)` — plus
    /// identical observable element content, which is what this compares.
    #[test]
    fn e2e_vec_capacity_family_agrees_with_the_interpreter() {
        let cases: &[(&str, &str)] = &[
            (
                "reserve keeps len and grows cap",
                "let mut v: Vec[i64] = Vec.new();\n\
                 v.reserve(100);\n\
                 println(f\"{v.len()} {v.capacity() >= 100}\");\n\
                 let mut i = 0;\n\
                 while i < 100 { v.push(i); i = i + 1; }\n\
                 println(f\"{v.len()} {v[0]} {v[99]}\");",
            ),
            (
                "reserve_exact and non-positive no-ops",
                "let mut v: Vec[i64] = Vec.new();\n\
                 v.push(1);\n\
                 v.reserve_exact(7);\n\
                 println(f\"{v.capacity() >= 8} {v.len()}\");\n\
                 v.reserve(-5);\n\
                 v.reserve(0);\n\
                 println(f\"{v.len()} {v[0]}\");",
            ),
            (
                "resize grows with copies and shrinks like truncate",
                "let mut v: Vec[i64] = Vec.new();\n\
                 v.push(1); v.push(2); v.push(3);\n\
                 v.resize(5, 9);\n\
                 println(f\"{v.len()} {v[3]} {v[4]}\");\n\
                 v.resize(2, 0);\n\
                 println(f\"{v.len()} {v[0]} {v[1]}\");\n\
                 v.resize(-3, 0);\n\
                 println(v.len());",
            ),
            (
                "resize deep-copies a heap fill value",
                "let mut v: Vec[String] = Vec.new();\n\
                 v.push(\"a\"); v.push(\"b\");\n\
                 v.resize(5, \"z\");\n\
                 println(f\"{v.len()} {v[2]} {v[3]} {v[4]}\");\n\
                 v.resize(1, \"q\");\n\
                 println(f\"{v.len()} {v[0]}\");",
            ),
            (
                "append moves an owned source",
                "let mut a: Vec[i64] = Vec.new();\n\
                 a.push(10); a.push(20);\n\
                 let mut b: Vec[i64] = Vec.new();\n\
                 b.push(30); b.push(40);\n\
                 a.append(b);\n\
                 println(f\"{a.len()} {a[0]} {a[3]}\");",
            ),
            (
                "append of heap elements, including into an empty vec",
                "let mut p: Vec[String] = Vec.new();\n\
                 p.push(\"one\"); p.push(\"two\");\n\
                 let mut q: Vec[String] = Vec.new();\n\
                 q.push(\"three\");\n\
                 p.append(q);\n\
                 println(f\"{p.len()} {p[0]} {p[2]}\");\n\
                 let mut e: Vec[String] = Vec.new();\n\
                 let mut f2: Vec[String] = Vec.new();\n\
                 f2.push(\"solo\");\n\
                 e.append(f2);\n\
                 println(f\"{e.len()} {e[0]}\");",
            ),
        ];
        for (label, body) in cases {
            let src = format!("fn main() {{\n{body}\n}}\n");
            let (interp_out, interp_errs, _, _) = karac::run_program_full(&src);
            assert!(
                interp_errs.is_empty(),
                "{label}: interpreter errored: {interp_errs:?}"
            );
            let expected = interp_out.join("");
            if let Some(aot) = run_program(&src) {
                assert_eq!(
                    aot, expected,
                    "{label}: AOT and the interpreter disagree on the Vec \
                     capacity family"
                );
            }
        }
    }

    /// B-2026-08-26-27 — `Vec.try_from_iter`, twinned against the interpreter.
    ///
    /// The two backends do NOT do the same work here, and that is the point of
    /// twinning them: the interpreter always answers `Ok` (its host allocator
    /// does not OOM), while codegen genuinely grows the accumulator through
    /// `karac_alloc_fallible` and can return
    /// `Err(AllocError.OutOfMemory { requested_bytes })`. On the success path —
    /// the only one reachable without an allocator that fails on demand — they
    /// must agree exactly, which is what this asserts.
    ///
    /// The shapes are the same three `e2e_vec_from_iter_and_collect_are_the_same_program`
    /// uses, deliberately: `try_from_iter` routes through the SAME collect
    /// engine as its panicking base, so any shape one accepts the other must.
    #[test]
    fn e2e_vec_try_from_iter_agrees_with_the_interpreter() {
        let src = "fn build() -> Result[i64, AllocError] {\n\
                       let a: Vec[i64] = Vec.try_from_iter(0..4)?;\n\
                       println(f\"{a.len()} {a[0]} {a[3]}\");\n\
                       let b: Vec[i64] = Vec.try_from_iter((0..6).map(|x| x * 2))?;\n\
                       println(f\"{b.len()} {b[5]}\");\n\
                       let s: Vec[i64] = [5, 6, 7];\n\
                       let c: Vec[i64] = Vec.try_from_iter(s.iter().map(|x| x + 1))?;\n\
                       println(f\"{c.len()} {c[2]}\");\n\
                       let h: Vec[String] = [\"a\", \"bb\"];\n\
                       let hu: Vec[String] = Vec.try_from_iter(h.iter().map(|t| t.to_uppercase()))?;\n\
                       println(f\"{hu.len()} {hu[0]} {hu[1]}\");\n\
                       return Ok(a.len() + b.len() + c.len() + hu.len());\n\
                   }\n\
                   fn main() {\n\
                       match build() {\n\
                           Ok(n) => { println(f\"ok {n}\"); }\n\
                           Err(e) => { println(\"oom\"); }\n\
                       }\n\
                   }";
        let (interp_out, interp_errs, _, _) = karac::run_program_full(src);
        assert!(
            interp_errs.is_empty(),
            "interpreter errored: {interp_errs:?}"
        );
        let expected = interp_out.join("");
        assert_eq!(expected, "4 0 3\n6 10\n3 8\n2 A BB\nok 15\n");
        if let Some(aot) = run_program(src) {
            assert_eq!(
                aot, expected,
                "the fallible collect must produce the same Vec as the interpreter's"
            );
        }
    }

    /// ANTI-DRIFT: `try_from_iter` and `from_iter` must accept the same shapes
    /// and produce the same contents. They share one engine — the fallible
    /// switch changes the leaf append and the block's tail, nothing else — and
    /// this is what would catch someone giving the companion its own lowering.
    #[test]
    fn e2e_vec_try_from_iter_matches_its_panicking_base() {
        let fallible = "fn build() -> Result[i64, AllocError] {\n\
                            let a: Vec[i64] = Vec.try_from_iter((0..9).map(|x| x * 3))?;\n\
                            println(f\"{a.len()} {a[0]} {a[8]}\");\n\
                            return Ok(a.len());\n\
                        }\n\
                        fn main() { match build() { Ok(n) => { println(f\"n {n}\"); } Err(e) => { println(\"oom\"); } } }";
        let panicking = "fn main() {\n\
                             let a: Vec[i64] = Vec.from_iter((0..9).map(|x| x * 3));\n\
                             println(f\"{a.len()} {a[0]} {a[8]}\");\n\
                             println(f\"n {a.len()}\");\n\
                         }";
        let (f_out, f_errs, _, _) = karac::run_program_full(fallible);
        let (p_out, p_errs, _, _) = karac::run_program_full(panicking);
        assert!(
            f_errs.is_empty() && p_errs.is_empty(),
            "{f_errs:?} {p_errs:?}"
        );
        assert_eq!(
            f_out.join(""),
            p_out.join(""),
            "try_from_iter and from_iter must collect identically"
        );
        if let (Some(fa), Some(pa)) = (run_program(fallible), run_program(panicking)) {
            assert_eq!(fa, pa, "and identically when compiled");
            assert_eq!(fa, f_out.join(""), "and with the interpreter");
        }
    }

    /// B-2026-08-26-22 — the fallible-allocation remainder, twinned against the
    /// interpreter.
    ///
    /// `String.reserve` carries no `capacity()` companion (see its typechecker
    /// arm), so what the two backends are compared on is the CONTENT, which is
    /// the whole of what a hint owes.
    #[test]
    fn e2e_fallible_alloc_remainder_agrees_with_the_interpreter() {
        let cases: &[(&str, &str)] = &[
            (
                "String.reserve leaves content alone",
                "let mut s: String = String.new();\n\
                 s.push_str(\"hello\");\n\
                 s.reserve(1000);\n\
                 println(f\"[{s}] {s.len()}\");\n\
                 s.push_str(\" world\");\n\
                 s.reserve(-5);\n\
                 s.reserve(0);\n\
                 println(f\"[{s}] {s.len()}\");",
            ),
            (
                "Vec and String reserve share one name",
                "let mut v: Vec[i64] = Vec.new();\n\
                 v.reserve(32);\n\
                 v.push(1);\n\
                 let mut s: String = String.new();\n\
                 s.reserve(32);\n\
                 s.push_str(\"x\");\n\
                 println(f\"{v.len()} {v.capacity() >= 32} [{s}]\");",
            ),
        ];
        for (label, body) in cases {
            let src = format!("fn main() {{\n{body}\n}}\n");
            let (interp_out, interp_errs, _, _) = karac::run_program_full(&src);
            assert!(
                interp_errs.is_empty(),
                "{label}: interpreter errored: {interp_errs:?}"
            );
            let expected = interp_out.join("");
            if let Some(aot) = run_program(&src) {
                assert_eq!(aot, expected, "{label}: AOT and the interpreter disagree");
            }
        }
    }

    /// B-2026-08-26-22 — `Map.reserve` / `Set.reserve` and their `try_` twins,
    /// twinned against the interpreter.
    ///
    /// The two backends do genuinely different work: the interpreter reserves
    /// on a host `HashMap`, codegen calls `karac_map_reserve`, which widens its
    /// own open-addressed table. Neither exposes a `capacity()` accessor, so
    /// they are not obliged to agree on a bucket count — CONTENTS and `len()`
    /// are the contract, and that is what this compares.
    ///
    /// The negative-reserve leg is not padding. The Map path crosses an FFI
    /// boundary, and typing that parameter `u64` rather than `i64` turns
    /// `reserve(-5)` into a reservation of 18 quintillion entries; measured, it
    /// aborted the process with `panic: out of memory`.
    #[test]
    fn e2e_map_and_set_reserve_agree_with_the_interpreter() {
        let cases: &[(&str, &str)] = &[
            (
                "Map.reserve keeps contents",
                "let mut m: Map[i64, i64] = Map.new();\n\
                 m.reserve(1000);\n\
                 let mut i = 0;\n\
                 while i < 200 { m.insert(i, i * 2); i = i + 1; }\n\
                 m.reserve(-5);\n\
                 m.reserve(0);\n\
                 println(f\"{m.len()} {m.get(7).unwrap()} {m.get(199).unwrap()}\");",
            ),
            (
                "Set.reserve keeps contents",
                "let mut s: Set[i64] = Set.new();\n\
                 s.reserve(500);\n\
                 let mut i = 0;\n\
                 while i < 100 { s.insert(i); i = i + 1; }\n\
                 s.reserve(-3);\n\
                 println(f\"{s.len()} {s.contains(7)} {s.contains(999)}\");",
            ),
            (
                "negative reserve is a no-op everywhere",
                "let mut v: Vec[i64] = Vec.new();\n\
                 v.push(1);\n\
                 v.reserve(-100);\n\
                 let mut s: String = String.new();\n\
                 s.push_str(\"k\");\n\
                 s.reserve(-100);\n\
                 let mut m: Map[i64, i64] = Map.new();\n\
                 m.insert(1, 1);\n\
                 m.reserve(-100);\n\
                 let mut t: Set[i64] = Set.new();\n\
                 t.insert(1);\n\
                 t.reserve(-100);\n\
                 println(f\"{v.len()} [{s}] {m.len()} {t.len()}\");",
            ),
            (
                "Vec.from_iter is collect",
                "let a: Vec[i64] = Vec.from_iter(0..4);\n\
                 let b: Vec[i64] = Vec.from_iter((0..6).map(|x| x * 2));\n\
                 let src: Vec[i64] = [5, 6, 7];\n\
                 let c: Vec[i64] = Vec.from_iter(src.iter().map(|x| x + 1));\n\
                 let d = Vec.from_iter(0..3);\n\
                 println(f\"{a[3]} {b[5]} {c[2]} {d.len()}\");",
            ),
        ];
        for (label, body) in cases {
            let src = format!("fn main() {{\n{body}\n}}\n");
            let (interp_out, interp_errs, _, _) = karac::run_program_full(&src);
            assert!(
                interp_errs.is_empty(),
                "{label}: interpreter errored: {interp_errs:?}"
            );
            let expected = interp_out.join("");
            if let Some(aot) = run_program(&src) {
                assert_eq!(aot, expected, "{label}: AOT and the interpreter disagree");
            }
        }
    }

    /// `Vec.from_iter(it)` and `it.collect()` must produce the SAME program,
    /// not merely similar answers: the typechecker types the former by
    /// inferring the latter, and lowering rewrites to it. Comparing the two
    /// spellings directly is what keeps a future "optimisation" from giving
    /// `from_iter` its own divergent path.
    #[test]
    fn e2e_vec_from_iter_and_collect_are_the_same_program() {
        let via_from_iter = "fn main() {\n\
             let a: Vec[i64] = Vec.from_iter((0..8).map(|x| x * 3));\n\
             println(f\"{a.len()} {a[0]} {a[7]}\");\n\
         }\n";
        let via_collect = "fn main() {\n\
             let a: Vec[i64] = (0..8).map(|x| x * 3).collect();\n\
             println(f\"{a.len()} {a[0]} {a[7]}\");\n\
         }\n";
        let (interp_a, errs_a, _, _) = karac::run_program_full(via_from_iter);
        let (interp_b, errs_b, _, _) = karac::run_program_full(via_collect);
        assert!(
            errs_a.is_empty() && errs_b.is_empty(),
            "{errs_a:?} {errs_b:?}"
        );
        assert_eq!(
            interp_a.join(""),
            interp_b.join(""),
            "from_iter and collect must agree in the interpreter"
        );
        if let (Some(aot_a), Some(aot_b)) = (run_program(via_from_iter), run_program(via_collect)) {
            assert_eq!(
                aot_a, aot_b,
                "from_iter and collect must agree when compiled"
            );
            assert_eq!(aot_a, interp_a.join(""), "and with the interpreter");
        }
    }

    /// `try_resize` / `try_append` end to end. Both are all-or-nothing: the
    /// fallible allocation happens before anything is mutated, so an `Err`
    /// leaves the receiver's buffer, length and contents untouched — and for
    /// `try_append`, leaves the SOURCE still owning its elements, which is why
    /// its cleanup is disarmed only on the success path.
    #[test]
    fn e2e_vec_try_resize_and_try_append_agree_with_the_interpreter() {
        let src = "fn build() -> Result[i64, AllocError] {\n\
                       let mut v: Vec[i64] = Vec.new();\n\
                       v.push(1); v.push(2); v.push(3);\n\
                       v.try_resize(6, 7)?;\n\
                       println(f\"grow {v.len()} {v[5]}\");\n\
                       v.try_resize(2, 0)?;\n\
                       println(f\"shrink {v.len()}\");\n\
                       let mut a: Vec[i64] = Vec.new();\n\
                       a.push(10);\n\
                       let mut c: Vec[i64] = Vec.new();\n\
                       c.push(30);\n\
                       a.try_append(c)?;\n\
                       println(f\"append {a.len()} {a[1]}\");\n\
                       let mut p: Vec[String] = Vec.new();\n\
                       p.push(\"one\");\n\
                       p.try_resize(3, \"pad\")?;\n\
                       let mut q: Vec[String] = Vec.new();\n\
                       q.push(\"tail\");\n\
                       p.try_append(q)?;\n\
                       println(f\"heap {p.len()} {p[2]} {p[3]}\");\n\
                       return Ok(p.len());\n\
                   }\n\
                   fn main() {\n\
                       match build() {\n\
                           Ok(n) => { println(f\"ok {n}\"); }\n\
                           Err(e) => { println(\"alloc failed\"); }\n\
                       }\n\
                   }";
        let (interp_out, interp_errs, _, _) = karac::run_program_full(src);
        assert!(
            interp_errs.is_empty(),
            "interpreter errored: {interp_errs:?}"
        );
        let expected = interp_out.join("");
        assert_eq!(
            expected,
            "grow 6 7\nshrink 2\nappend 2 30\nheap 4 pad tail\nok 4\n"
        );
        if let Some(aot) = run_program(src) {
            assert_eq!(aot, expected, "AOT and the interpreter disagree");
        }
    }

    /// The `try_*` half. The row's headline was three missing `try_*` methods;
    /// the actual missing half was the PANICKING base each one derives from
    /// (`fallible_alloc.rs` recurses into the base for argument validation and
    /// return-type synthesis), so this is what proves the derivation closed.
    #[test]
    fn e2e_vec_try_reserve_companions_agree_with_the_interpreter() {
        let src = "fn build() -> Result[bool, AllocError] {\n\
                       let mut v: Vec[i64] = Vec.new();\n\
                       v.try_reserve(64)?;\n\
                       let mut w: Vec[i64] = Vec.new();\n\
                       w.try_reserve_exact(9)?;\n\
                       v.try_reserve(0)?;\n\
                       return Ok(v.capacity() >= 64 and w.capacity() >= 9);\n\
                   }\n\
                   fn main() {\n\
                       match build() {\n\
                           Ok(n) => { println(f\"ok {n}\"); }\n\
                           Err(e) => { println(\"alloc failed\"); }\n\
                       }\n\
                   }";
        let (interp_out, interp_errs, _, _) = karac::run_program_full(src);
        assert!(
            interp_errs.is_empty(),
            "interpreter errored: {interp_errs:?}"
        );
        assert_eq!(interp_out.join(""), "ok true\n");
        if let Some(aot) = run_program(src) {
            assert_eq!(
                aot, "ok true\n",
                "the fallible reserve companions must lower to real \
                 `karac_alloc_fallible` + `Result`, not diverge from the \
                 interpreter"
            );
        }
    }

    /// B-2026-08-26-12 — an `if`-EXPRESSION whose arms yield an
    /// `Option[shared]` binding, passed BY VALUE to a function, inside a loop
    /// that rebinds it, corrupts the heap on both compiled backends.
    ///
    /// The control below is the same program with the `if` removed
    /// (`show(a)` instead of `show(if s == 0 { a } else { a })`) and is green,
    /// so the whole delta is the if-expression. `--interp` prints `v 0` /
    /// `v 1` correctly; `karac run` (JIT) and `karac build` both died with
    /// glibc's `malloc(): unaligned tcache chunk detected` (SIGABRT).
    ///
    /// FIXED: a branch leaf handing out an `Option[shared]` binding now takes
    /// the same per-arm retain the plain-`shared` leaf already took. The
    /// if-expression turned out to be one member of a family — see
    /// `option_shared_through_every_branch_leaf_form_survives_a_rebinding_loop`
    /// below, which covers the `match` arm, the bare block, the nested and
    /// else-if chains, and the mixed-arm shape that pins the fix per-arm.
    ///
    /// Deliberately an E2E test and NOT an ASAN fixture: the
    /// `-fsanitize=address` link does not reproduce it at all — under ASAN's
    /// allocator this program runs clean AND prints the right answer, which is
    /// why the ~1200-fixture `tests/memory_sanitizer.rs` corpus never caught
    /// the class. Measured, not assumed — and structural, not luck: the
    /// sanitizer is linked in, never compiled in (`link_executable_with_sanitizer`
    /// passes `-fsanitize=address` to `cc` at LINK time only), so ASAN sees
    /// allocator-level faults — double free, invalid free, leaks — and cannot
    /// see a use-after-free ACCESS from the uninstrumented Kāra object. This
    /// bug's fault is a stray refcount decrement THROUGH a freed box, which
    /// writes `-1` where glibc keeps the tcache `fd` word and never calls
    /// `free` twice, so there is nothing at the allocator boundary to catch.
    /// B-2026-08-27-34 — the THIRD consumption of an `Option[shared]` selected
    /// by a value-position branch read through a freed box.
    ///
    /// The mechanism is one step earlier than "the retain is emitted once per
    /// binding rather than once per use", which is how the symptom reads from
    /// the outside. MEASURED by instrumenting `share_option_shared_ref_for_arg`:
    /// the consuming binding `t` was never registered in
    /// `var_option_shared_heap` AT ALL, because `control_flow_owned_option_shared`
    /// — case (g) of the `let`-RHS cascade — only counted a leaf as owning a
    /// `+1` if it was a `Some(..)`/call/`None` PRODUCER, and a bare binding
    /// handed out of an arm is none of those. So `t` got neither a scope-exit
    /// `RcDecOption` nor the per-USE call-site retains that a registered
    /// binding gets, and the single leaf retain B-2026-08-26-12 added was
    /// standing in for the whole of `t`'s ownership. One `+1` covers exactly
    /// TWO consumptions, which is why the boundary is exact and why two reads
    /// look green.
    ///
    /// The fix teaches case (g) that a bare `Option[shared]` binding IS an
    /// owning leaf now — which is precisely what B-2026-08-26-12 made true when
    /// it taught the leaf to retain. Registering `t` restores the invariant the
    /// other cases already rely on: each use incs and the callee decs, so the
    /// count stops depending on how many times the binding is consumed.
    ///
    /// This has no loop and no rebinding at all — it is straight-line code:
    ///
    /// ```kara
    /// let t = if true { a } else { b };
    /// println(f"{show(t)} {show(t)} {show(t)}");
    /// ```
    ///
    /// `--interp` printed `1 1 1`. `karac build` printed `1 1 <garbage>` and
    /// exited **0** — a silent wrong answer, not a crash, and the garbage word
    /// differed run to run. `karac run` (JIT) printed the same garbage and then
    /// aborted inside the allocator. The control below is the identical program
    /// with the if-expression removed and was green throughout, so the delta is
    /// exactly the branch leaf.
    #[test]
    fn option_shared_from_a_branch_leaf_survives_a_third_consumption() {
        let src = "shared struct Node { val: i64 }\n\
                   fn make(n: i64) -> Option[Node] { return Some(Node { val: n }); }\n\
                   fn show(t: Option[Node]) -> i64 {\n\
                       match t { None => { return 0; } Some(n) => { return n.val; } }\n\
                   }\n\
                   fn main() {\n\
                       let a = make(1);\n\
                       let b = make(2);\n\
                       let t = if true { a } else { b };\n\
                       println(f\"{show(t)} {show(t)} {show(t)}\");\n\
                   }";
        if let Some(c) = run_program_capturing(src) {
            assert_eq!(
                c.stdout, "1 1 1\n",
                "every read of a branch-leaf `Option[shared]` must see the same value"
            );
            assert!(
                c.status.success(),
                "process died ({:?}) — stderr: {}",
                c.status,
                c.stderr
            );
        }
    }

    /// B-2026-08-27-34, the whole branch-leaf family at THREE-PLUS consumptions
    /// — the axis every fixture that landed with B-2026-08-26-12 missed, since
    /// each of those consumes the selected value exactly once (twice over a
    /// two-iteration loop, which is a different axis: per-iteration accounting
    /// is correct, per-use accounting is not).
    ///
    /// Twelve legs, each binding the branch's value and then consuming that
    /// ONE binding three times (five on leg 11), so the count can no longer be
    /// balanced by the single leaf retain standing in for the binding's
    /// ownership. Two legs are load-bearing beyond the reported `if` shape:
    ///
    ///   * Leg 3, the `if let` THEN arm. B-2026-08-26-12's message says its
    ///     `compile_block_with_frame` hook covers "if/if let arms". It covers
    ///     `if`, and an `if let`'s ELSE branch (leg 4) which routes through
    ///     that same helper — but NOT an `if let`'s then arm, which hand-rolls
    ///     its frame drain against a plain `compile_block`. That gap was
    ///     invisible while the consuming binding went unregistered (no retain
    ///     and no dec is balanced by accident for one use) and became a live
    ///     use-after-free the moment registration made the missing `+1`
    ///     load-bearing, so the two halves of this fix are not separable.
    ///   * Legs 9 and 10, the MIXED arms, which pin the retain per-arm rather
    ///     than at the phi: `{ a }` hands out a borrowed binding and needs the
    ///     retain, `{ make(19) }` carries its producer's own `+1` and must not
    ///     take a second. Omit the retain and the borrowed arm double-frees;
    ///     add it at the phi and the fresh arm leaks. Both directions are
    ///     exercised, and `asan_option_shared_branch_leaf_repeated_consumption_is_clean`
    ///     in `tests/memory_sanitizer.rs` is the LSan half that catches the
    ///     over-retaining wrong fix.
    ///
    /// Twinned against the interpreter, which was correct throughout.
    #[test]
    fn option_shared_from_every_branch_leaf_form_survives_repeated_consumption() {
        let src = "shared struct Node { val: i64 }\n\
                   fn make(n: i64) -> Option[Node] { return Some(Node { val: n }); }\n\
                   fn show(t: Option[Node]) -> i64 {\n\
                       match t { None => { return 0; } Some(n) => { return n.val; } }\n\
                   }\n\
                   fn main() {\n\
                       let a1 = make(1); let b1 = make(2);\n\
                       let t1 = if true { a1 } else { b1 };\n\
                       println(f\"{show(t1)} {show(t1)} {show(t1)}\");\n\
                       let a2 = make(3); let b2 = make(4);\n\
                       let t2 = if false { a2 } else { b2 };\n\
                       println(f\"{show(t2)} {show(t2)} {show(t2)}\");\n\
                       let a3 = make(5); let b3 = make(6); let o3 = Some(1);\n\
                       let t3 = if let Some(x) = o3 { a3 } else { b3 };\n\
                       println(f\"{show(t3)} {show(t3)} {show(t3)}\");\n\
                       let a4 = make(7); let b4 = make(8); let o4: Option[i64] = None;\n\
                       let t4 = if let Some(y) = o4 { a4 } else { b4 };\n\
                       println(f\"{show(t4)} {show(t4)} {show(t4)}\");\n\
                       let a5 = make(9); let b5 = make(10); let k5 = 0;\n\
                       let t5 = match k5 { 0 => a5, _ => b5 };\n\
                       println(f\"{show(t5)} {show(t5)} {show(t5)}\");\n\
                       let a6 = make(11);\n\
                       let t6 = { a6 };\n\
                       println(f\"{show(t6)} {show(t6)} {show(t6)}\");\n\
                       let a7 = make(12); let b7 = make(13); let c7 = make(14); let k7 = 1;\n\
                       let t7 = if k7 == 0 { a7 } else if k7 == 1 { b7 } else { c7 };\n\
                       println(f\"{show(t7)} {show(t7)} {show(t7)}\");\n\
                       let a8 = make(15); let b8 = make(16);\n\
                       let t8 = if true { if true { a8 } else { b8 } } else { make(99) };\n\
                       println(f\"{show(t8)} {show(t8)} {show(t8)}\");\n\
                       let a9 = make(17);\n\
                       let t9 = if true { a9 } else { make(99) };\n\
                       println(f\"{show(t9)} {show(t9)} {show(t9)}\");\n\
                       let a10 = make(18);\n\
                       let t10 = if false { a10 } else { make(19) };\n\
                       println(f\"{show(t10)} {show(t10)} {show(t10)}\");\n\
                       let a11 = make(20); let b11 = make(21);\n\
                       let t11 = if true { a11 } else { b11 };\n\
                       println(f\"{show(t11)} {show(t11)} {show(t11)} {show(t11)} {show(t11)}\");\n\
                       let a12 = make(22);\n\
                       let t12 = if false { a12 } else { None };\n\
                       println(f\"{show(t12)} {show(t12)} {show(t12)}\");\n\
                   }";
        let expected = "1 1 1\n4 4 4\n5 5 5\n8 8 8\n9 9 9\n11 11 11\n13 13 13\n15 15 15\n17 17 17\n19 19 19\n20 20 20 20 20\n0 0 0\n";
        if let Some(c) = run_program_capturing(src) {
            assert_eq!(
                c.stdout, expected,
                "every branch-leaf form must survive repeated consumption of \
                 the binding it was selected into"
            );
            assert!(
                c.status.success(),
                "process died ({:?}) — stderr: {}",
                c.status,
                c.stderr
            );
        }
        let (interp_out, interp_errs, _, _) = karac::run_program_full(src);
        assert!(
            interp_errs.is_empty(),
            "interpreter errored on the twin: {interp_errs:?}"
        );
        assert_eq!(
            interp_out.join(""),
            expected,
            "interpreter twin must agree with the compiled backend"
        );
    }

    /// B-2026-08-27-43 — the ARM-LOCAL half of the branch-leaf family, split
    /// out of B-2026-08-27-34 and unchanged in either direction by its fix.
    ///
    /// The delta from the sibling test above is one line per leg: the arm binds
    /// a LOCAL and hands the local out (`if c { let u = make(1); u }`) instead
    /// of handing out a binding from the enclosing scope. That moves the
    /// failure boundary from the THIRD consumption to the FIRST: there the leaf
    /// retain survived and the box reached the uses at rc 2, paying for two of
    /// them; here the arm-local's own scope-exit dec drains with the arm's frame
    /// and cancels the retain, so the box arrives at rc 1 with nobody owning it
    /// and the first callee's param dec already frees it.
    ///
    /// Both halves were individually right, which is why the sibling fix moved
    /// nothing: the leaf hook fires, and case (g)'s `Identifier` arm correctly
    /// DECLINES to register a binding whose retain was cancelled — it reads
    /// `var_option_shared_heap`, and `compile_block_with_frame` reverted the
    /// arm's name env before the `let` classified its RHS, so the name is
    /// simply gone. The fix gives case (g) a second source of truth that
    /// survives the revert: the emission RECORD each leaf retain writes,
    /// keyed by the leaf expression's span.
    ///
    /// Eleven arm-local legs plus the enclosing-binding control. Every leg
    /// consumes its ONE binding three times (four on leg 4, five on leg 5), so
    /// no count can be balanced by accident. Measured against the unfixed
    /// compiler: legs 1-11 all RED and all exiting 0 — silent wrong answers,
    /// `/ 0 0` and garbage words — and leg 12 GREEN, which is what attributes
    /// the failure to the arm-LOCAL shape rather than to branch leaves at large.
    ///
    /// Leg 4 is load-bearing beyond the reported shape: the arm-local is itself
    /// an ALIAS of an enclosing binding (`let u = d; u`), so `d` must still read
    /// correctly AFTER the branch's value has been consumed three times. It
    /// pins that the escaping `+1` the new binding adopts is the arm-local's
    /// own, not the source's.
    ///
    /// Twinned against the interpreter, which was correct throughout.
    #[test]
    fn option_shared_from_an_arm_local_leaf_survives_repeated_consumption() {
        let src = "shared struct Node { val: i64 }\n\
                   fn make(n: i64) -> Option[Node] { return Some(Node { val: n }); }\n\
                   fn show(t: Option[Node]) -> i64 {\n\
                       match t { None => { return 0; } Some(n) => { return n.val; } }\n\
                   }\n\
                   fn main() {\n\
                       let b = make(2);\n\
                       let t1 = if true { let u = make(1); u } else { b };\n\
                       println(f\"{show(t1)} {show(t1)} {show(t1)}\");\n\
                       let c = make(3);\n\
                       let t2 = if false { c } else { let u = make(4); u };\n\
                       println(f\"{show(t2)} {show(t2)} {show(t2)}\");\n\
                       let t3 = if true { let u = make(5); u } else { let v = make(6); v };\n\
                       println(f\"{show(t3)} {show(t3)} {show(t3)}\");\n\
                       let d = make(7);\n\
                       let t4 = if true { let u = d; u } else { b };\n\
                       println(f\"{show(t4)} {show(t4)} {show(t4)} {show(d)}\");\n\
                       let t5 = if true { let u = make(8); u } else { b };\n\
                       println(f\"{show(t5)} {show(t5)} {show(t5)} {show(t5)} {show(t5)}\");\n\
                       let k = 1;\n\
                       let t6 = match k { 1 => { let u = make(9); u } _ => { b } };\n\
                       println(f\"{show(t6)} {show(t6)} {show(t6)}\");\n\
                       let t7 = if true { { let u = make(10); u } } else { b };\n\
                       println(f\"{show(t7)} {show(t7)} {show(t7)}\");\n\
                       let t8 = if false { b } else if true { let u = make(11); u } else { b };\n\
                       println(f\"{show(t8)} {show(t8)} {show(t8)}\");\n\
                       let t9 = if true { let u = make(12); u } else { None };\n\
                       println(f\"{show(t9)} {show(t9)} {show(t9)}\");\n\
                       let src2 = make(13);\n\
                       let t10 = if let Some(n) = src2 { let u = make(n.val); u } else { b };\n\
                       println(f\"{show(t10)} {show(t10)} {show(t10)}\");\n\
                       let mut i = 0;\n\
                       while i < 3 {\n\
                           let t11 = if true { let u = make(20 + i); u } else { b };\n\
                           println(f\"{show(t11)} {show(t11)} {show(t11)}\");\n\
                           i = i + 1;\n\
                       }\n\
                       let t12 = if true { b } else { b };\n\
                       println(f\"{show(t12)} {show(t12)} {show(t12)}\");\n\
                   }";
        let expected = "1 1 1\n4 4 4\n5 5 5\n7 7 7 7\n8 8 8 8 8\n9 9 9\n\
                        10 10 10\n11 11 11\n12 12 12\n13 13 13\n20 20 20\n\
                        21 21 21\n22 22 22\n2 2 2\n";
        if let Some(c) = run_program_capturing(src) {
            assert_eq!(
                c.stdout, expected,
                "an ARM-LOCAL branch leaf must hand its `Option[shared]` to the \
                 binding with an owner, on the first consumption as on the third"
            );
            assert!(
                c.status.success(),
                "process died ({:?}) — stderr: {}",
                c.status,
                c.stderr
            );
        }
        let (interp_out, interp_errs, _, _) = karac::run_program_full(src);
        assert!(
            interp_errs.is_empty(),
            "interpreter errored on the twin: {interp_errs:?}"
        );
        assert_eq!(
            interp_out.join(""),
            expected,
            "interpreter twin must agree with the compiled backend"
        );
    }

    /// The control for `option_shared_from_a_branch_leaf_survives_a_third_consumption`:
    /// the same three reads with no branch leaf between the binding and the
    /// uses. Green today, and it is what keeps that test's failure attributable
    /// to the branch leaf rather than to reading an `Option[shared]` three times.
    #[test]
    fn option_shared_read_three_times_without_a_branch_leaf() {
        let src = "shared struct Node { val: i64 }\n\
                   fn make(n: i64) -> Option[Node] { return Some(Node { val: n }); }\n\
                   fn show(t: Option[Node]) -> i64 {\n\
                       match t { None => { return 0; } Some(n) => { return n.val; } }\n\
                   }\n\
                   fn main() {\n\
                       let a = make(1);\n\
                       println(f\"{show(a)} {show(a)} {show(a)}\");\n\
                   }";
        if let Some(c) = run_program_capturing(src) {
            assert_eq!(c.stdout, "1 1 1\n");
            assert!(c.status.success(), "stderr: {}", c.stderr);
        }
    }

    #[test]
    fn option_shared_through_if_expression_survives_a_rebinding_loop() {
        let src = "shared struct Node { val: i64 }\n\
                   fn make(n: i64) -> Option[Node] { return Some(Node { val: n }); }\n\
                   fn show(t: Option[Node]) {\n\
                       match t { None => { } Some(n) => { println(f\"v {n.val}\"); } }\n\
                   }\n\
                   fn main() {\n\
                       let mut s = 0;\n\
                       while s < 2 {\n\
                           let a = make(s);\n\
                           show(if s == 0 { a } else { a });\n\
                           s = s + 1;\n\
                       }\n\
                   }";
        if let Some(c) = run_program_capturing(src) {
            assert_eq!(
                c.stdout, "v 0\nv 1\n",
                "if-expression over an Option[shared] must not change the value"
            );
            assert!(
                c.status.success(),
                "process died ({:?}) — stderr: {}",
                c.status,
                c.stderr
            );
        }
    }

    /// The control for `option_shared_through_if_expression_survives_a_rebinding_loop`:
    /// identical except the if-expression is gone. Green today, and it is what
    /// makes that test's failure attributable to the if-expression rather than
    /// to `Option[shared]` in a loop generally.
    #[test]
    fn option_shared_without_an_if_expression_survives_a_rebinding_loop() {
        let src = "shared struct Node { val: i64 }\n\
                   fn make(n: i64) -> Option[Node] { return Some(Node { val: n }); }\n\
                   fn show(t: Option[Node]) {\n\
                       match t { None => { } Some(n) => { println(f\"v {n.val}\"); } }\n\
                   }\n\
                   fn main() {\n\
                       let mut s = 0;\n\
                       while s < 2 {\n\
                           let a = make(s);\n\
                           show(a);\n\
                           s = s + 1;\n\
                       }\n\
                   }";
        if let Some(c) = run_program_capturing(src) {
            assert_eq!(c.stdout, "v 0\nv 1\n");
            assert!(c.status.success(), "stderr: {}", c.stderr);
        }
    }

    /// B-2026-08-26-12, the FAMILY. The reported shape was an if-expression,
    /// but the defect was never about `if`: any value-position branch leaf that
    /// hands an `Option[shared]` binding to an owned parameter handed out an
    /// UNCOUNTED alias, so the callee's exit dec took the box to rc 0 and freed
    /// it while the source's still-armed `RcDecOption` decremented through the
    /// freed memory. Every leg below aborted before the fix; only the direct
    /// `show(a)` control did not.
    ///
    /// The `mixed` leg is the one with teeth. Its arms are not alike —
    /// `{ d }` hands out a borrowed binding and needs the retain, `{ make(9) }`
    /// carries `make`'s own `+1` and must not take a second — so it fails in
    /// BOTH directions: a compiler that retains neither double frees, and one
    /// that retains at the merge instead of per-arm leaks the fresh arm. That
    /// is what forces the retain into each arm's own basic block.
    ///
    /// Twinned against `--interp` rather than a hardcoded string, so the two
    /// backends are asserted equal as well as correct.
    #[test]
    fn option_shared_through_every_branch_leaf_form_survives_a_rebinding_loop() {
        let src = "shared struct Node { val: i64 }\n\
                   fn make(n: i64) -> Option[Node] { return Some(Node { val: n }); }\n\
                   fn take(t: Option[Node]) -> i64 {\n\
                       match t { None => { return 0; } Some(n) => { return n.val; } }\n\
                   }\n\
                   fn main() {\n\
                       let mut s = 0;\n\
                       let mut total = 0;\n\
                       while s < 4 {\n\
                           let a = make(s);\n\
                           total = total + take(if s == 0 { a } else { a });\n\
                           let b = make(s);\n\
                           total = total + take(match s { 0 => b, _ => b });\n\
                           let c = make(s);\n\
                           total = total + take({ c });\n\
                           let d = make(s);\n\
                           total = total + take(if s < 2 { d } else { make(9) });\n\
                           let e = make(s);\n\
                           total = total + take(if s == 0 { if s == 0 { e } else { e } } else { e });\n\
                           let g = make(s);\n\
                           total = total + take(if s == 0 { g } else if s == 1 { g } else { g });\n\
                           let h = make(s);\n\
                           let bound = if s == 0 { h } else { h };\n\
                           total = total + take(bound);\n\
                           s = s + 1;\n\
                       }\n\
                       println(total);\n\
                   }";
        // 6 legs yield s (0+1+2+3 = 6 each = 36); the mixed leg yields s for
        // s<2 (0+1 = 1) and 9 twice (18) = 19. 36 + 19 = 55.
        let expected = "55\n";
        if let Some(c) = run_program_capturing(src) {
            assert_eq!(
                c.stdout, expected,
                "every branch-leaf form handing out an Option[shared] must \
                 keep the value intact"
            );
            assert!(
                c.status.success(),
                "process died ({:?}) — stderr: {}",
                c.status,
                c.stderr
            );
        }
        let (interp_out, interp_errs, _, _) = karac::run_program_full(src);
        assert!(
            interp_errs.is_empty(),
            "interpreter errored on the twin: {interp_errs:?}"
        );
        assert_eq!(
            interp_out.join(""),
            expected,
            "interpreter twin must agree with the compiled backend"
        );
    }

    #[test]
    fn test_ir_descending_loop_bce_skip_wiring() {
        // B-2026-07-17-1: the descending-loop skip proves `k < row.len()` for
        // the in-place `row[k] = row[k] + row[k-1]` update, so codegen emits a
        // LOWER-only bounds check (the signed `< 0` half, which LLVM folds from
        // the `k >= 1` guard) — NOT the combined unsigned check. The combined
        // path produces a `v.st.ok` block; the lower-only path produces
        // `v.st.oob.neg` / `v.st.lower.ok`. Assert the wiring pushed the
        // UpperBound (skip fired): the store keeps only its lower half.
        let ir = ir_for(
            r#"
fn get_row(row_index: i64) -> Vec[i64] {
    let mut row: Vec[i64] = Vec.new();
    let mut j = 0i64;
    while j <= row_index { row.push(1i64); j = j + 1i64; }
    let mut i = 2i64;
    while i <= row_index {
        let mut k = i - 1i64;
        while k >= 1i64 { row[k] = row[k] + row[k - 1i64]; k = k - 1i64; }
        i = i + 1i64;
    }
    row
}
"#,
        );
        assert!(
            ir.contains("v.st.oob.neg"),
            "expected the descending store to keep its lower-half check, got:\n{ir}"
        );
        assert!(
            !ir.contains("v.st.ok"),
            "expected NO combined store bounds check (skip should elide the \
             upper half), but found a `v.st.ok` block:\n{ir}"
        );
    }

    #[test]
    fn test_e2e_descending_skip_keeps_the_check_when_a_nested_block_moves_the_goalposts() {
        // B-2026-08-04-13. The descending-loop BCE skip freezes four facts by
        // scanning a region: the fill counter starts at 0, the enclosing
        // counter still satisfies its guard at the inner loop, and the index's
        // init is the value written before it. `stmt_writes_ident` answered all
        // of them looking only at TOP-LEVEL assignment targets, so a write one
        // block deep left every fact reading "unchanged" while the program
        // changed it — and the skip then dropped a check that was carrying
        // real weight.
        //
        // This is an E2E and not an IR assertion on purpose: the failure is a
        // *store* past the end of the buffer, and what that looks like is
        // allocator-dependent (the three cases below produced a silent exit 0,
        // `munmap_chunk(): invalid pointer`, and a glibc malloc assertion).
        // Asserting the clean panic is the only stable oracle; any of those
        // corruption modes fails it.
        //
        // `k` starts at `i + 9` and walks down, on a Vec filled to 10 — in
        // range for the control, and pushed out of it by each lever: the first
        // two raise `k` itself, the third shrinks the buffer under it.
        let case_src = |pre_fill: &str, enc_head: &str, post_init: &str| {
            format!(
                r#"
fn main() {{
    let mut v: Vec[i64] = Vec.new();
    let mut j = 0i64;
    let flag = 1i64;
    {pre_fill}
    while j < 10i64 {{ v.push(0i64); j = j + 1i64; }}
    let mut i = 0i64;
    while i <= 0i64 {{
        {enc_head}
        let mut k = i + 9i64;
        {post_init}
        while k >= 0i64 {{ v[k] = 7i64; k = k - 1i64; }}
        i = i + 1i64;
    }}
    println(f"len={{v.len()}}");
}}
"#
            )
        };

        // Control first: with no nested write every index is in range, so the
        // program completes. This is what makes the three assertions below
        // about the nested write and not about a program that was always OOB.
        if let Some(c) = run_program_capturing(&case_src("", "", "")) {
            assert!(
                c.stdout.contains("len=10"),
                "control must run clean, got stdout={:?} stderr={:?}",
                c.stdout,
                c.stderr
            );
        }

        let cases = [
            (
                "enclosing counter rewritten in a nested block",
                "",
                "if flag == 1i64 { i = 50i64; }",
                "",
            ),
            (
                "index init rewritten in a nested block",
                "",
                "",
                "if flag == 1i64 { k = 50i64; }",
            ),
            // Here the index arithmetic is sound and the PREMISE is not: the
            // fill runs 5 iterations instead of 10, so the length pin claims a
            // buffer twice the size of the real one.
            (
                "fill counter preset in a nested block",
                "if flag == 1i64 { j = 5i64; }",
                "",
                "",
            ),
        ];
        for (label, pre_fill, enc_head, post_init) in cases {
            if let Some(c) = run_program_capturing(&case_src(pre_fill, enc_head, post_init)) {
                assert!(
                    c.stderr.contains("vec index out of bounds"),
                    "[{label}] an out-of-range store must panic, not be elided; \
                     got stdout={:?} stderr={:?}",
                    c.stdout,
                    c.stderr
                );
            }
        }
    }

