    #[test]
    fn test_e2e_option_narrow_int_payload_narrows_to_surface_width() {
        // Regression: `Vec[u8].pop()` returns `Option[u8]`, whose payload
        // word is i64 in the variant word stream. The `Some(top)` binding
        // must narrow that word back to i8 (u8's LLVM width) — otherwise
        // `top == b` (b: u8 → i8) emits `icmp i64, i8` and module
        // verification fails with "Both operands to ICmp instruction are
        // not of the same type!". Exercises the valid-parentheses stack
        // shape (LeetCode #20) that surfaced the bug: push the matching
        // closer, pop + compare on a closer. Also covers `char` (i32) and
        // `u32` to confirm the narrowing keys off the recorded surface
        // width, not just u8.
        let out = run_program(
            r#"
fn is_valid(s: ref String) -> bool {
    let bytes = s.bytes();
    let n = bytes.len();
    let mut stack: Vec[u8] = Vec.new();
    let mut i = 0i64;
    while i < n {
        let b = bytes[i];
        if b == b'(' or b == b'[' or b == b'{' {
            if b == b'(' { stack.push(b')'); }
            else if b == b'[' { stack.push(b']'); }
            else { stack.push(b'}'); }
        } else {
            match stack.pop() {
                Some(top) => { if top != b { return false; } }
                None => { return false; }
            }
        }
        i = i + 1i64;
    }
    stack.is_empty()
}

fn main() {
    if is_valid("([{}])") { println(1); } else { println(0); }
    if is_valid("(]") { println(1); } else { println(0); }

    // char payload (i32) narrowed from the i64 word.
    let mut cs: Vec[char] = Vec.new();
    cs.push('x');
    match cs.pop() {
        Some(c) => { if c == 'x' { println(2); } else { println(0); } }
        None => { println(0); }
    }

    // u32 payload narrowed from the i64 word.
    let mut ns: Vec[u32] = Vec.new();
    ns.push(7u32);
    if let Some(v) = ns.pop() {
        let w: u32 = 7u32;
        if v == w { println(3); }
    }
}
"#,
        );
        if let Some(out) = out {
            let lines: Vec<&str> = out.trim().lines().collect();
            assert_eq!(lines, vec!["1", "0", "2", "3"]);
        }
    }

    #[test]
    fn test_e2e_vec_deque_pop_front_returns_option_with_tuple_payload() {
        // The LeetCode 3629 kata's blocking shape: VecDeque[(i64, i64)]
        // BFS frontier with `pop_front()` returning `Option[(i64,i64)]`.
        // Multi-word Option payload via the bumped layout +
        // `coerce_to_payload_words(val, 3)` construction; destructure
        // uses the direct-pattern form `Some((i, d))` which routes
        // through the existing tuple-payload reconstruction machinery.
        let out = run_program(
            r#"
fn main() {
    let mut q: VecDeque[(i64, i64)] = VecDeque.new();
    q.push_back((0, 0));
    let mut sum = 0i64;
    loop {
        match q.pop_front() {
            None => { break; },
            Some((i, d)) => {
                sum = sum + i + d;
                if i < 3 {
                    q.push_back((i + 1, d + 1));
                }
            },
        }
    }
    println(sum);
}
"#,
        );
        if let Some(out) = out {
            // BFS: pop (0,0) sum+=0; push (1,1) → pop sum+=2 (2);
            // push (2,2) → pop sum+=4 (6); push (3,3) → pop sum+=6 (12);
            // i==3 no push; empty → break. Total 12.
            assert_eq!(out.trim(), "12");
        }
    }

    #[test]
    fn test_e2e_par_group_serializes_for_iter_with_outer_mutable_write() {
        // The concurrency analyzer's per-stmt info now collects
        // nested-block writes (Assign / CompoundAssign) into
        // `info.defines`. Without this, a `for v in nums.iter()`
        // expression-stmt that writes to outer `cap` was treated as
        // "no dependencies" against a subsequent `let f =
        // dummy(cap)` — the analyzer grouped them and the par-branch
        // fn's local copy of `cap` never propagated back, so the
        // function call read the initial value of `cap`.
        //
        // Repro:
        let out = run_program(
            r#"
fn dummy(n: i64) -> Vec[i64] {
    let mut v: Vec[i64] = Vec.new();
    let mut i = 0i64;
    while i < n { v.push(i); i = i + 1; }
    v
}
fn helper(nums: Slice[i64]) -> i64 {
    let mut cap = 1i64;
    for v in nums.iter() {
        if v > cap { cap = v; }
    }
    let f: Vec[i64] = dummy(cap);
    println(cap);
    println(f.len());
    cap
}
fn main() {
    let a: Array[i64, 4] = [1, 2, 4, 6];
    println(helper(a));
}
"#,
        );
        if let Some(out) = out {
            // cap finds max = 6 from [1,2,4,6]; dummy(6) yields a
            // 6-element Vec; helper returns 6.
            assert_eq!(out.trim(), "6\n6\n6");
        }
    }

    #[test]
    fn test_e2e_for_in_indexed_iter() {
        // `for p in coll[i].iter()` — the iter peel-off in
        // `compile_for` recurses on the receiver, but for an
        // indexed receiver the recursion would land on an Index
        // expression which falls through to the silent `_ =>` arm.
        // Fix: synthesize a temp identifier for the indexed
        // element and recurse with it, mirroring
        // `compile_nested_index_read`. Pins the kata's
        // `for p in factors[v].iter() { bucket.entry(p)... }` shape.
        let out = run_program(
            r#"
fn main() {
    let mut factors: Vec[Vec[i64]] = Vec.filled(7, Vec.new());
    factors[6].push(2);
    factors[6].push(3);
    let mut sum = 0i64;
    for p in factors[6].iter() {
        sum = sum + p;
    }
    println(sum);
}
"#,
        );
        if let Some(out) = out {
            assert_eq!(out.trim(), "5");
        }
    }

    #[test]
    fn test_e2e_function_returning_vec_of_vec_no_double_free() {
        // Move-aware scope-exit cleanup: when a function returns a
        // tracked Vec / String binding via the tail expression, the
        // let-site's `track_vec_var` cleanup is suppressed (by
        // zeroing the source's `cap` field) so the caller's
        // `f.data` isn't pointing at a freed buffer. Without this,
        // `Vec[Vec[i64]]` returns SIGSEGV at the first inner indexed
        // access (the inner Vec's data pointer GEPs through a freed
        // outer slot).
        let out = run_program(
            r#"
fn make_grid(n: i64) -> Vec[Vec[i64]] {
    let mut g: Vec[Vec[i64]] = Vec.filled(n, Vec.new());
    g[0].push(99);
    g[0].push(11);
    g[2].push(42);
    g
}
fn main() {
    let f: Vec[Vec[i64]] = make_grid(3);
    println(f.len());
    println(f[0].len());
    println(f[0][0]);
    println(f[0][1]);
    println(f[2][0]);
}
"#,
        );
        if let Some(out) = out {
            assert_eq!(out.trim(), "3\n2\n99\n11\n42");
        }
    }

    #[test]
    fn test_e2e_function_returning_vec_i64_no_double_free() {
        // Sibling: `Vec[i64]` return — same fix applies. The
        // primitive case happened to work pre-fix due to
        // use-after-free reading stable data, but is now correct
        // by construction (cleanup skipped at the move site, caller
        // owns the buffer cleanly).
        let out = run_program(
            r#"
fn make_vec(n: i64) -> Vec[i64] {
    let mut v: Vec[i64] = Vec.new();
    let mut i = 0i64;
    while i < n {
        v.push(i * 10);
        i = i + 1;
    }
    v
}
fn main() {
    let f: Vec[i64] = make_vec(4);
    println(f.len());
    println(f[3]);
}
"#,
        );
        if let Some(out) = out {
            assert_eq!(out.trim(), "4\n30");
        }
    }

    #[test]
    fn test_e2e_struct_field_move_no_double_free() {
        // Move-aware suppression at struct-construction sites. When
        // a struct field's initializer is an Identifier naming a
        // tracked Vec / String, the field captures the binding's
        // data pointer — but the source's let-site `track_vec_var`
        // unconditionally schedules a scope-exit free that would
        // free the buffer the caller now reads through the struct.
        // This is the shape Parallax/HTTP hits via
        // `Response { body: my_string }` — without suppression,
        // the caller reads NUL bytes (or SIGSEGVs) downstream of
        // FFI consumption.
        let out = run_program(
            r#"
struct Holder {
    tag: i64,
    body: String,
}
fn build() -> Holder {
    let mut s: String = String.new();
    s.push_str("hello, world");
    Holder { tag: 7, body: s }
}
fn main() {
    let h: Holder = build();
    println(h.tag);
    println(h.body);
}
"#,
        );
        if let Some(out) = out {
            assert_eq!(out.trim(), "7\nhello, world");
        }
    }

    #[test]
    fn test_e2e_struct_param_field_move_out() {
        // B-2026-06-10-2: moving a Vec field OUT of a by-value struct PARAM
        // (`let inner = h.v`) deep-copies the field buffer so the moved-out
        // local is independent of the caller's (the caller's struct-drop frees
        // the original). Pre-fix this double-freed (the buffer was shallow-
        // shared; ASAN coverage in `tests/memory_sanitizer.rs`). Output
        // correctness on the codegen lane is the non-ASAN guard: reuse + the
        // original both stay valid.
        let out = run_program(
            "struct Holder { v: Vec[i64] }\n\
             fn build() -> Holder {\n\
             \x20   let mut inner: Vec[i64] = Vec.new();\n\
             \x20   inner.push(10i64); inner.push(20i64);\n\
             \x20   Holder { v: inner }\n\
             }\n\
             fn first_elem(h: Holder) -> i64 { let inner = h.v; inner[0] }\n\
             fn main() {\n\
             \x20   let h = build();\n\
             \x20   let a = first_elem(h);\n\
             \x20   let b = first_elem(h);\n\
             \x20   println(a + b);\n\
             }\n",
        );
        if let Some(out) = out {
            assert_eq!(out.trim(), "20");
        }
    }

    #[test]
    fn test_e2e_struct_pattern_destructure_heap_field() {
        // #16 (phase-12 self-hosting): a plain struct-pattern match destructure of
        // an OWNED local struct (`match v { S { a, b: _ } => … }`) moves each
        // consumed field's heap payload into the new binding. Without
        // `suppress_destructured_struct_pattern_cleanup` the source struct's drop
        // re-frees the moved buffer (double-free; exit 134 under guardmalloc / ASAN
        // — see `tests/memory_sanitizer.rs::asan_struct_pattern_destructure_no_
        // double_free`). Output correctness is the codegen-lane guard: the
        // partial-bind field (`b: _`) is left to the source drop, the bound fields
        // (including a nested-struct field and an enum field moved whole) read back
        // intact.
        let out = run_program(
            r#"
struct Inner { s: String }
enum Tok { Id(String), Eof }
struct S { a: String, b: String, inner: Inner, tok: Tok, n: i64 }
fn main() {
    let v = S {
        a: "aa".to_string(),
        b: "bb".to_string(),
        inner: Inner { s: "deep".to_string() },
        tok: Tok.Id("tok".to_string()),
        n: 7,
    };
    match v {
        S { a, b: _, inner, tok, n } => {
            let Inner { s } = inner;
            println(a);
            println(s);
            match tok { Id(t) => println(t), Eof => println("eof") }
            println(n.to_string());
        }
    }
}
"#,
        );
        if let Some(out) = out {
            assert_eq!(out.trim(), "aa\ndeep\ntok\n7");
        }
    }

    #[test]
    fn test_e2e_let_rebind_move_no_double_free() {
        // `let outer = inner;` where `inner` is a tracked Vec /
        // String is a move — both slots end up holding the same
        // {ptr, len, cap}. Without source-cap suppression at the
        // let-rebind site, both `track_vec_var`-queued cleanups
        // fire and double-free the heap buffer. The LHS's track
        // becomes the unique cleanup owner.
        let out = run_program(
            r#"
fn build() -> String {
    let mut inner: String = String.new();
    inner.push_str("relayed");
    let outer: String = inner;
    outer
}
fn main() {
    let s: String = build();
    println(s);
}
"#,
        );
        if let Some(out) = out {
            assert_eq!(out.trim(), "relayed");
        }
    }

    #[test]
    fn test_e2e_assign_rebind_move_no_double_free() {
        // `acc = extra;` where both `acc` and `extra` are tracked
        // Vec / String bindings is an assign-rebind. The old
        // `acc` buffer leaks (no RAII drop in v1), but without
        // source-cap suppression on `extra`, both queued cleanups
        // fire against the same post-assign buffer → double-free.
        let out = run_program(
            r#"
fn build() -> String {
    let mut acc: String = String.new();
    acc.push_str("first");
    let mut extra: String = String.new();
    extra.push_str("second");
    acc = extra;
    acc
}
fn main() {
    let s: String = build();
    println(s);
}
"#,
        );
        if let Some(out) = out {
            assert_eq!(out.trim(), "second");
        }
    }

    #[test]
    fn test_e2e_for_range_step_by_codegen() {
        // `for j in (start..=end).step_by(n)` — the iterator-adaptor
        // chain previously fell through `compile_for`'s match to the
        // silent `_ =>` arm, skipping the body entirely. Now lowers
        // to a Range loop with the step expr evaluated once before
        // the loop and used as the increment. Pins the sieve / strided
        // iteration pattern that the LeetCode 3629 kata uses.
        let out = run_program(
            r#"
fn main() {
    let mut sum = 0i64;
    for j in (2..=10).step_by(2) {
        sum = sum + j;
    }
    println(sum);
    let mut count = 0i64;
    for _ in (0..20).step_by(5) {
        count = count + 1;
    }
    println(count);
}
"#,
        );
        if let Some(out) = out {
            assert_eq!(out.trim(), "30\n4");
        }
    }

    #[test]
    fn test_e2e_for_range_step_by_with_runtime_step() {
        // The kata's actual usage: the step expression refers to an
        // outer variable. The step is evaluated once per loop entry
        // and captured into the increment block.
        let out = run_program(
            r#"
fn main() {
    let cap = 12i64;
    for i in 2..=cap {
        let mut count = 0i64;
        for _j in (i..=cap).step_by(i) {
            count = count + 1;
        }
        println(count);
    }
}
"#,
        );
        // For each i in 2..=12, count multiples of i up to cap=12:
        //   i=2 → 2,4,6,8,10,12 → 6
        //   i=3 → 3,6,9,12 → 4
        //   i=4 → 4,8,12 → 3
        //   i=5 → 5,10 → 2
        //   i=6 → 6,12 → 2
        //   i=7 → 7 → 1
        //   i=8 → 8 → 1
        //   i=9 → 9 → 1
        //   i=10 → 10 → 1
        //   i=11 → 11 → 1
        //   i=12 → 12 → 1
        if let Some(out) = out {
            assert_eq!(out.trim(), "6\n4\n3\n2\n2\n1\n1\n1\n1\n1\n1");
        }
    }

    /// B-2026-08-09-21 — a nested index whose base is a struct FIELD
    /// (`h.data[i][j]`), read and write.
    ///
    /// RUN-VS-BUILD: `--interp` ran these; `karac run` (JIT) and `karac build`
    /// both refused them. The boundary was oddly narrow and is what identifies
    /// the cause — `d[i][j]` on a named local BUILT, `h.data[i]` (single index
    /// on a field) BUILT, `let row = h.data[i]; row[j]` BUILT; only the DOUBLE
    /// index rooted at a field failed. `compile_nested_index_read` recovered the
    /// element `TypeExpr` from `var_elem_type_exprs[outer_name]`, which is
    /// keyed by variable name and so has no entry for a field.
    ///
    /// Cases 3 and 4 are the ones that matter most in practice, and they are why
    /// the read arm resolves the base through `lower_field_access_ptr` rather
    /// than `field_chain_place_ptr`: the latter deliberately declines a
    /// `ref`-param root (its slot holds a pointer, not the aggregate), which
    /// would have left every `ref self` method and `ref H` parameter failing —
    /// the shape a 2D-cursor struct actually writes, and the motivating kata's
    /// canonical spelling (`v.data[v.row][v.col]`).
    ///
    /// Case 5 pins what stays deferred: a TRIPLE index is still refused by the
    /// separate MR5 guard, loudly. Widening the field base was not an excuse to
    /// generalise that too.
    #[test]
    fn test_e2e_nested_index_rooted_at_struct_field() {
        // 1. The filed reproduction — read.
        assert_eq!(
            run_program(
                "struct H { data: Vec[Vec[i64]] }\n\
                 fn main() {\n\
                     let mut i: Vec[i64] = Vec.new();\n\
                     i.push(1i64);\n\
                     let mut d: Vec[Vec[i64]] = Vec.new();\n\
                     d.push(i);\n\
                     let h = H { data: d };\n\
                     println(f\"{h.data[0][0]}\");\n\
                 }"
            )
            .as_deref(),
            Some("1\n")
        );
        // 2. The WRITE half, which failed on a different gate ("Index
        // assignment target must be a variable") and needed its own arm.
        assert_eq!(
            run_program(
                "struct H { data: Vec[Vec[i64]] }\n\
                 fn main() {\n\
                     let mut i: Vec[i64] = Vec.new();\n\
                     i.push(1i64);\n\
                     let mut d: Vec[Vec[i64]] = Vec.new();\n\
                     d.push(i);\n\
                     let mut h = H { data: d };\n\
                     h.data[0][0] = 42i64;\n\
                     println(f\"{h.data[0][0]}\");\n\
                 }"
            )
            .as_deref(),
            Some("42\n")
        );
        // 3. `ref self` / `mut ref self` methods — the canonical 2D-cursor shape.
        assert_eq!(
            run_program(
                "struct G { grid: Vec[Vec[i64]] }\n\
                 impl G {\n\
                 \x20   fn get(ref self, i: i64, j: i64) -> i64 { return self.grid[i][j]; }\n\
                 \x20   fn set(mut ref self, i: i64, j: i64, v: i64) { self.grid[i][j] = v; }\n\
                 }\n\
                 fn main() {\n\
                     let mut r0: Vec[i64] = Vec.new();\n\
                     r0.push(1i64); r0.push(2i64);\n\
                     let mut g0: Vec[Vec[i64]] = Vec.new();\n\
                     g0.push(r0);\n\
                     let mut g = G { grid: g0 };\n\
                     println(f\"{g.get(0i64, 1i64)}\");\n\
                     g.set(0i64, 1i64, 99i64);\n\
                     println(f\"{g.get(0i64, 1i64)}\");\n\
                 }"
            )
            .as_deref(),
            Some("2\n99\n")
        );
        // 4. A `ref` / `mut ref` PARAM root, the free-function form of case 3.
        assert_eq!(
            run_program(
                "struct H { data: Vec[Vec[i64]] }\n\
                 fn read(h: ref H, i: i64, j: i64) -> i64 { return h.data[i][j]; }\n\
                 fn bump(h: mut ref H) { h.data[0][0] = h.data[0][0] + 1i64; }\n\
                 fn main() {\n\
                     let mut r: Vec[i64] = Vec.new();\n\
                     r.push(5i64);\n\
                     let mut d: Vec[Vec[i64]] = Vec.new();\n\
                     d.push(r);\n\
                     let mut h = H { data: d };\n\
                     println(f\"{read(h, 0i64, 0i64)}\");\n\
                     bump(mut h);\n\
                     println(f\"{read(h, 0i64, 0i64)}\");\n\
                 }"
            )
            .as_deref(),
            Some("5\n6\n")
        );
        // 5. The triple index. This case was added to pin the MR5 guard as a
        // LOUD deferral, on the principle that widening the field base was not
        // an excuse to generalise that guard too. B-2026-08-20-33 then
        // generalised it deliberately, through a shared place resolver rather
        // than a fourth hand-written base shape — so the case is INVERTED here
        // rather than deleted: it is the one that pins where the boundary sits,
        // and it now sits one level deeper.
        let triple = ir_result(
            "fn main() {\n\
                 let mut a: Vec[i64] = Vec.new();\n\
                 a.push(1i64);\n\
                 let mut b: Vec[Vec[i64]] = Vec.new();\n\
                 b.push(a);\n\
                 let mut c: Vec[Vec[Vec[i64]]] = Vec.new();\n\
                 c.push(b);\n\
                 println(f\"{c[0][0][0]}\");\n\
             }",
        );
        assert!(
            triple.is_ok(),
            "triple index must lower since B-2026-08-20-33, got {triple:?}"
        );
        // 6. Bounds checking survives the new path — the inner index goes
        // through the same checked helper the named-base path uses, so an OOB
        // outer index panics rather than reading out of the buffer.
        if let Some(c) = run_program_capturing(
            "struct H { data: Vec[Vec[i64]] }\n\
             fn main() {\n\
                 let mut r: Vec[i64] = Vec.new();\n\
                 r.push(1i64);\n\
                 let mut d: Vec[Vec[i64]] = Vec.new();\n\
                 d.push(r);\n\
                 let h = H { data: d };\n\
                 println(f\"{h.data[0][5]}\");\n\
             }",
        ) {
            assert!(
                c.stderr.contains("vec index out of bounds"),
                "expected OOB panic, got stdout={:?} stderr={:?}",
                c.stdout,
                c.stderr
            );
        }
        // 7. A shared-struct receiver, and a loop driving computed indices
        // through both the read and the write.
        assert_eq!(
            run_program(
                "struct H { data: Vec[Vec[i64]] }\n\
                 fn main() {\n\
                     let mut r0: Vec[i64] = Vec.new();\n\
                     r0.push(10i64); r0.push(20i64);\n\
                     let mut r1: Vec[i64] = Vec.new();\n\
                     r1.push(30i64); r1.push(40i64);\n\
                     let mut d: Vec[Vec[i64]] = Vec.new();\n\
                     d.push(r0); d.push(r1);\n\
                     let mut h = H { data: d };\n\
                     let mut i: i64 = 0;\n\
                     let mut total: i64 = 0;\n\
                     while i < 2 {\n\
                         let mut j: i64 = 0;\n\
                         while j < 2 {\n\
                             total = total + h.data[i][j];\n\
                             h.data[i][j] = h.data[i][j] + 1i64;\n\
                             j = j + 1;\n\
                         }\n\
                         i = i + 1;\n\
                     }\n\
                     println(f\"{total}\");\n\
                     println(f\"{h.data[1][1]}\");\n\
                 }"
            )
            .as_deref(),
            Some("100\n41\n")
        );
    }

    /// B-2026-08-21-4 — `as_slice()` on a `ref`-mode receiver, and a call
    /// declared to return `Slice[T]`.
    ///
    /// THE SILENT HALF was `as_slice` reading the slice header straight out of
    /// the receiver's SLOT. For an owned binding the alloca IS the aggregate,
    /// so that was right by accident; for a `ref` / `mut ref` PARAMETER the
    /// alloca holds a POINTER to the caller's aggregate, and the lowering read
    /// that pointer as the Vec's `data` and whatever sat beside it on the stack
    /// as `len`. `v.as_slice().len()` returned a pointer-sized number, exit 0,
    /// no diagnostic. Case 1 needs no `Slice` return at all, which is what
    /// identifies the cause: the row was filed against the return boundary, but
    /// the header is built wrong before it ever reaches a `return`.
    ///
    /// THE LOUD HALF was the element type: a call result had no entry in
    /// either slice-element resolver, so `pick(v)[2]` and `for x in s` refused.
    /// The filing row measured that arm ALONE and reverted it — with the header
    /// still wrong it turned the loud failures into silent ones (`pick(v)[2]`
    /// gave 3, the length, instead of 30). Both land together here, and case 5
    /// is the one that proves the order mattered.
    #[test]
    fn e2e_as_slice_on_a_ref_receiver_and_a_slice_returning_call() {
        // 1. No `Slice` return anywhere — the minimal shape of the miscompile.
        //    The owned twin was always correct and is the control.
        assert_eq!(
            run_program(
                "fn probe(v: ref Vec[i64]) -> i64 {\n\
                 \x20   let s = v.as_slice();\n\
                 \x20   return s.len();\n\
                 }\n\
                 fn owned(v: Vec[i64]) -> i64 {\n\
                 \x20   let s = v.as_slice();\n\
                 \x20   return s.len();\n\
                 }\n\
                 fn main() {\n\
                 \x20   let v: Vec[i64] = [10, 20, 30];\n\
                 \x20   println(f\"{probe(v)}\");\n\
                 \x20   let w: Vec[i64] = [1, 2];\n\
                 \x20   println(f\"{owned(w)}\");\n\
                 }\n"
            )
            .as_deref(),
            Some("3\n2\n")
        );
        // 2. The row's own repro: an inline call through a `Slice[T]` return.
        assert_eq!(
            run_program(
                "fn pick(v: ref Vec[i64]) -> Slice[i64] {\n\
                 \x20   return v.as_slice();\n\
                 }\n\
                 fn main() {\n\
                 \x20   let v: Vec[i64] = [10, 20, 30];\n\
                 \x20   println(f\"{pick(v).len()}\");\n\
                 }\n"
            )
            .as_deref(),
            Some("3\n")
        );
        // 3. Bound to a local, then a method on it.
        assert_eq!(
            run_program(
                "fn pick(v: ref Vec[i64]) -> Slice[i64] {\n\
                 \x20   return v.as_slice();\n\
                 }\n\
                 fn main() {\n\
                 \x20   let v: Vec[i64] = [10, 20, 30];\n\
                 \x20   let s = pick(v);\n\
                 \x20   println(f\"{s.len()}\");\n\
                 }\n"
            )
            .as_deref(),
            Some("3\n")
        );
        // 4. Iterated — the shape that flooded garbage words rather than
        //    printing three elements.
        assert_eq!(
            run_program(
                "fn pick(v: ref Vec[i64]) -> Slice[i64] {\n\
                 \x20   return v.as_slice();\n\
                 }\n\
                 fn main() {\n\
                 \x20   let v: Vec[i64] = [10, 20, 30];\n\
                 \x20   let s = pick(v);\n\
                 \x20   for x in s {\n\
                 \x20       println(f\"{x}\");\n\
                 \x20   }\n\
                 }\n"
            )
            .as_deref(),
            Some("10\n20\n30\n")
        );
        // 5. INDEXED, inline and bound. This is the case the filing row saw
        //    return 3 (the length) when the element type was registered while
        //    the header was still wrong — so `30` here is what proves the
        //    header fix has to come first, not merely alongside.
        assert_eq!(
            run_program(
                "fn pick(v: ref Vec[i64]) -> Slice[i64] {\n\
                 \x20   return v.as_slice();\n\
                 }\n\
                 fn main() {\n\
                 \x20   let v: Vec[i64] = [10, 20, 30];\n\
                 \x20   println(f\"{pick(v)[2]}\");\n\
                 \x20   let s = pick(v);\n\
                 \x20   println(f\"{s[0]}\");\n\
                 }\n"
            )
            .as_deref(),
            Some("30\n10\n")
        );
        // 6. A METHOD declared `-> Slice[T]`. The impl pass emits it as a
        //    `Type.method` function and records its return in the same table,
        //    so resolving the receiver's type name is the whole of the extra
        //    work. The filing row measured this sibling as a hard refusal and
        //    asked for it to be re-measured once the header was fixed.
        assert_eq!(
            run_program(
                "struct Buf { v: Vec[i64] }\n\
                 impl Buf {\n\
                 \x20   fn view(ref self) -> Slice[i64] {\n\
                 \x20       return self.v.as_slice();\n\
                 \x20   }\n\
                 }\n\
                 fn main() {\n\
                 \x20   let b = Buf { v: [7, 8, 9] };\n\
                 \x20   println(f\"{b.view()[2]}\");\n\
                 \x20   let s = b.view();\n\
                 \x20   println(f\"{s.len()}\");\n\
                 \x20   println(f\"{b.view().len()}\");\n\
                 }\n"
            )
            .as_deref(),
            Some("9\n3\n3\n")
        );
        // 7. A `mut ref` receiver, and a slice taken through it after a
        //    mutation — the length must track the caller's Vec, not a stale
        //    copy of the header.
        assert_eq!(
            run_program(
                "fn grow(v: mut ref Vec[i64]) -> i64 {\n\
                 \x20   v.push(40i64);\n\
                 \x20   let s = v.as_slice();\n\
                 \x20   return s.len();\n\
                 }\n\
                 fn main() {\n\
                 \x20   let mut v: Vec[i64] = [10, 20, 30];\n\
                 \x20   println(f\"{grow(mut v)}\");\n\
                 }\n"
            )
            .as_deref(),
            Some("4\n")
        );
    }

    /// B-2026-08-20-35 — a nested index whose outer container is a MAP.
    ///
    /// The READ (`m[k][i]`) was refused `outer is not a Vec/Slice/Array`. The
    /// WRITE was worse than refused: `m[k][i] = v` BUILT and then SEGFAULTED.
    /// `var_elem_type_exprs` holds a map's VALUE TypeExpr, so for
    /// `Map[K, Vec[V]]` that is `Vec[V]` and the nested store's "is the outer a
    /// Vec of Vecs?" test happily said yes — handing a MAP HANDLE to
    /// `compile_nested_vec_vec_index_store`, which indexed it as a Vec of Vecs.
    /// The row that filed this described a clean refusal on both halves; the
    /// store half was a silent miscompile.
    ///
    /// Case 4 is the one that shows the fix generalised rather than special-
    /// cased: a `Vec[Map[K, V]]` matches NEITHER test — the outer is a Vec and
    /// its element is not — and is served by the shared place resolver.
    #[test]
    fn e2e_nested_index_through_a_map() {
        // 1. The read half.
        assert_eq!(
            run_program(
                "fn main() {\n\
                 \x20   let mut m: Map[i64, Vec[i64]] = Map.new();\n\
                 \x20   m.insert(1i64, [7i64, 8i64]);\n\
                 \x20   println(f\"{m[1i64][0]}\");\n\
                 }\n"
            )
            .as_deref(),
            Some("7\n")
        );
        // 2. The write half — the one that used to build and segfault. The
        // read-back also proves the store reached the MAP's storage rather
        // than a temporary.
        assert_eq!(
            run_program(
                "fn main() {\n\
                 \x20   let mut m: Map[i64, Vec[i64]] = Map.new();\n\
                 \x20   m.insert(1i64, [7i64, 8i64]);\n\
                 \x20   m.insert(2i64, [9i64]);\n\
                 \x20   m[1i64][1] = 55i64;\n\
                 \x20   println(f\"{m[1i64][0]} {m[1i64][1]} {m[2i64][0]}\");\n\
                 }\n"
            )
            .as_deref(),
            Some("7 55 9\n")
        );
        // 3. A Map whose values are Maps.
        assert_eq!(
            run_program(
                "fn main() {\n\
                 \x20   let mut mm: Map[i64, Map[i64, i64]] = Map.new();\n\
                 \x20   let mut inner: Map[i64, i64] = Map.new();\n\
                 \x20   inner.insert(5i64, 6i64);\n\
                 \x20   mm.insert(1i64, inner);\n\
                 \x20   mm[1i64][5i64] = 66i64;\n\
                 \x20   println(f\"{mm[1i64][5i64]}\");\n\
                 }\n"
            )
            .as_deref(),
            Some("66\n")
        );
        // 4. A VEC whose elements are Maps — neither the vec-of-vec test nor
        // the map test matches, so this only works through the shared
        // resolver. It was still refused after the first two were fixed.
        assert_eq!(
            run_program(
                "fn main() {\n\
                 \x20   let mut vm: Vec[Map[i64, i64]] = Vec.new();\n\
                 \x20   let mut e: Map[i64, i64] = Map.new();\n\
                 \x20   e.insert(3i64, 4i64);\n\
                 \x20   vm.push(e);\n\
                 \x20   vm[0][3i64] = 44i64;\n\
                 \x20   println(f\"{vm[0][3i64]}\");\n\
                 }\n"
            )
            .as_deref(),
            Some("44\n")
        );
        // 5. A Map reached through a struct FIELD.
        assert_eq!(
            run_program(
                "struct Holder { buckets: Map[i64, Vec[i64]] }\n\
                 fn main() {\n\
                 \x20   let mut h = Holder { buckets: Map.new() };\n\
                 \x20   h.buckets.insert(1i64, [1i64, 2i64]);\n\
                 \x20   h.buckets[1i64][0] = 21i64;\n\
                 \x20   println(f\"{h.buckets[1i64][0]} {h.buckets[1i64][1]}\");\n\
                 }\n"
            )
            .as_deref(),
            Some("21 2\n")
        );
    }

    /// B-2026-08-20-34 — stack exhaustion SAYS SO instead of dying silently.
    ///
    /// A Kāra binary has its own `main`, so Rust's `lang_start` never runs and
    /// std's guard-page handler was never installed: exhausting the stack
    /// killed the process with a bare SIGSEGV, exit 139, and ZERO bytes on
    /// stderr — nothing naming recursion as the cause. Measured against the
    /// mirrors on the same machine, Kāra matched `cc -O0` and lost to both
    /// comparators it otherwise benchmarks against; unoptimized `rustc` prints
    /// `thread 'main' has overflowed its stack` and exits 134.
    ///
    /// The fixture recurses without allocating, so it faults in single-digit
    /// milliseconds rather than churning the heap on the way down.
    #[test]
    fn e2e_stack_overflow_reports_itself() {
        let Some(run) = run_program_capturing(
            "fn down(n: i64) -> i64 {\n\
             \x20   if n <= 0 {\n\
             \x20       return 0;\n\
             \x20   }\n\
             \x20   let sub = down(n - 1);\n\
             \x20   return sub + n;\n\
             }\n\
             fn main() {\n\
             \x20   println(f\"{down(50000000i64)}\");\n\
             }\n",
        ) else {
            return;
        };
        assert!(
            !run.status.success(),
            "the fixture must actually overflow; got a clean exit with stdout {:?}",
            run.stdout
        );
        assert!(
            run.stderr.contains("stack overflow"),
            "stack exhaustion must name itself, got stderr {:?} status {:?}",
            run.stderr,
            run.status
        );
        // The hint is the half that makes it actionable — a bare "stack
        // overflow" would still leave a reader guessing what to change.
        assert!(
            run.stderr.contains("recursive") && run.stderr.contains("ulimit"),
            "expected the cause + remedy notes, got stderr {:?}",
            run.stderr
        );
    }

    /// B-2026-08-20-33 — a THREE-level index, read and write.
    ///
    /// `a[i][j][k] = v` was refused `Index assignment target must be a
    /// variable` — a message that named the wrong thing, since the target IS a
    /// variable, just reached through two indices. The read half was refused
    /// separately as an explicit MR5 deferral. Two levels worked on both sides,
    /// so the boundary was exactly one index deep.
    ///
    /// The fix is a shared recursive place resolver rather than a fourth
    /// hand-written base shape. That is what the earlier siblings had each
    /// added one of — B-2026-08-09-21 for a struct-FIELD base, B-2026-08-10-5
    /// for a TUPLE-field base — and each still required whatever sat under it
    /// to be a bare identifier, which is why a chained base fell through all of
    /// them. Cases 4-6 below are the ones that prove it GENERALISED rather than
    /// moved the boundary by one: depth four, a struct-field root at depth
    /// three, and computed (non-literal) indices at every level.
    #[test]
    fn e2e_three_level_index_read_and_write() {
        // 1. The row's own repro — the write half.
        assert_eq!(
            run_program(
                "fn main() {\n\
                 \x20   let mut d: Vec[Vec[Vec[i64]]] = [[[5]]];\n\
                 \x20   d[0][0][0] = 42i64;\n\
                 \x20   println(f\"{d[0][0][0]}\");\n\
                 }\n"
            )
            .as_deref(),
            Some("42\n")
        );
        // 2. The read half, which failed on the separate MR5 guard.
        assert_eq!(
            run_program(
                "fn main() {\n\
                 \x20   let deep: Vec[Vec[Vec[i64]]] = [[[5, 6]]];\n\
                 \x20   println(f\"{deep[0][0][1]}\");\n\
                 }\n"
            )
            .as_deref(),
            Some("6\n")
        );
        // 3. Through a `mut ref` parameter — the store has to reach the
        // caller's buffer, not a copy.
        assert_eq!(
            run_program(
                "fn bump(d: mut ref Vec[Vec[Vec[i64]]]) {\n\
                 \x20   d[0][0][0] = d[0][0][0] + 1i64;\n\
                 }\n\
                 fn main() {\n\
                 \x20   let mut d: Vec[Vec[Vec[i64]]] = [[[5]]];\n\
                 \x20   bump(mut d);\n\
                 \x20   println(f\"{d[0][0][0]}\");\n\
                 }\n"
            )
            .as_deref(),
            Some("6\n")
        );
        // 4. DEPTH FOUR — the resolver recurses, so one more level costs
        // nothing. A per-depth special case would fail here.
        assert_eq!(
            run_program(
                "fn main() {\n\
                 \x20   let mut d: Vec[Vec[Vec[Vec[i64]]]] = [[[[1]]]];\n\
                 \x20   d[0][0][0][0] = 4i64;\n\
                 \x20   println(f\"{d[0][0][0][0]}\");\n\
                 }\n"
            )
            .as_deref(),
            Some("4\n")
        );
        // 5. A struct-FIELD root at depth three — the B-2026-08-09-21 base
        // shape one level deeper than that row could reach.
        assert_eq!(
            run_program(
                "struct Grid { cells: Vec[Vec[Vec[i64]]] }\n\
                 fn main() {\n\
                 \x20   let mut g = Grid { cells: [[[9]]] };\n\
                 \x20   g.cells[0][0][0] = 11i64;\n\
                 \x20   println(f\"{g.cells[0][0][0]}\");\n\
                 }\n"
            )
            .as_deref(),
            Some("11\n")
        );
        // 6. COMPUTED indices at every level, and a neighbour left alone —
        // constant-folding a literal index would pass cases 1-5 while getting
        // this wrong.
        assert_eq!(
            run_program(
                "fn main() {\n\
                 \x20   let mut d: Vec[Vec[Vec[i64]]] = [[[0, 0]], [[0, 0]]];\n\
                 \x20   let i: i64 = 1;\n\
                 \x20   let j: i64 = 0;\n\
                 \x20   let k: i64 = 1;\n\
                 \x20   d[i][j][k] = 77i64;\n\
                 \x20   println(f\"{d[1][0][1]} {d[0][0][0]}\");\n\
                 }\n"
            )
            .as_deref(),
            Some("77 0\n")
        );
    }

    /// B-2026-08-10-1 — a NESTED indexed store releases the element it
    /// overwrites, as the single-index store already did.
    ///
    /// `compile_nested_vec_vec_index_store` ended in a bare `build_store`, so
    /// `d[0][0] = f"zz"` orphaned the old String's buffer while the
    /// single-index `r[0] = f"zz"` freed it. Both paths now go through one
    /// helper, which is the point — the leak existed because the nested path
    /// never grew a copy of a discipline the other has carried since
    /// B-2026-06-19-7, and a second copy would have drifted the same way.
    ///
    /// This test asserts VALUES, not memory: the leak itself is invisible in
    /// output and is gated by the ASAN fixture (whose memory half needs the
    /// `-O0` leg, since at the default level the orphaned allocation is dead
    /// and LLVM deletes it). What these cases catch is the release going
    /// WRONG rather than missing — freeing a buffer that is still live shows
    /// up here as a wrong or empty string.
    ///
    /// Case 2 is the struct-FIELD base, which only reaches this path because
    /// B-2026-08-09-21 routed it here. Case 3 is the self-alias `d[0][0] =
    /// d[0][0]`, the shape where a release-before-store would free the very
    /// buffer being read. Case 4 is a scalar leaf, which must take the
    /// no-release path untouched.
    /// B-2026-08-10-4 — `split_at_mut` (design.md "`split_at_mut` — disjoint
    /// mutable partition"), which was specified in full and implemented
    /// nowhere. Both halves are `mut Slice[T]` views over the receiver's own
    /// buffer, so a write through either lands in the caller's collection.
    ///
    /// Both receivers the spec names are pinned — `Vec[T]` and `mut Slice[T]`
    /// — because they take different paths to the base pointer, and the Slice
    /// one is where the interpreter twin got it wrong: an aliasing bug there
    /// is INVISIBLE except by writing through a half and reading back through
    /// the original, since the returned lengths are correct either way.
    ///
    /// The halves are passed to a function rather than written as
    /// `parts.0[0] = x`. That spelling is a separate PRE-EXISTING codegen gap
    /// — index-assign through a tuple field whose type is a Slice — which
    /// reproduces without `split_at_mut` via `(v.as_slice_mut(), 0)` and is
    /// filed on its own row.
    /// B-2026-08-10-5 — indexing a SLICE-typed tuple field, read and write.
    ///
    /// `t.0[i]` was refused by codegen whenever the field's type was a Slice
    /// ("Index operator applied to non-array type" on a read, "Index
    /// assignment target must be a variable" on a store), while the identical
    /// spelling built fine with a Vec-typed field and `--interp` handled both.
    ///
    /// The cause was one gate: the typechecker recorded the element type into
    /// `temp_recv_elem_types` only for `Type::Named{Vec|VecDeque}`, and a
    /// `Slice[T]` is `Type::Slice`, so codegen's tuple-index arms never fired
    /// and the expression fell to the generic tail.
    ///
    /// Case 2 is why this mattered enough to fix rather than document:
    /// `split_at_mut` returns a tuple of slices, so writing through a half by
    /// index — the obvious use of a mutable partition — hit this on every
    /// program. Case 3 is the Vec-typed field, which must keep working: the
    /// arms now choose the container shape from the tuple's LLVM field type,
    /// and getting that backwards would read a `cap` word off a 16-byte slice
    /// slot or miss one on a 24-byte Vec slot.
    /// B-2026-08-10-13 — a `sort_by` / `sort_by_key` closure parameter keeps
    /// its element type, so the body can call methods and index it.
    ///
    /// `v.sort_by(|x, y| x.len().cmp(y.len()))` over a `Vec[Vec[i64]]` or
    /// `Vec[String]` failed codegen with a self-identified dispatch
    /// fall-through ("no handler for method 'len' on variable 'x'"), while the
    /// interpreter ran it. The comparator params were registered with
    /// `record_var_type_name` only — enough for `compile_field_access`, which
    /// needs a struct name, and not for method dispatch or index lowering,
    /// which resolve through `vec_elem_types` / `var_elem_type_exprs`.
    ///
    /// That is why the corpus never hit it: every earlier `sort_by` compared
    /// TUPLE FIELDS (`|a, b| a.0.cmp(b.0)`), and tuple-field access needs no
    /// type lookup at all. Case 4 keeps that shape as the control — it also
    /// takes a different code path entirely (the mono sort, gated to
    /// all-int-field elements), so it proves the fix did not disturb the path
    /// that already worked.
    ///
    /// Case 3 is index-in-comparator and cases 5/6 are `sort_by_key`, the
    /// sibling method: it had the identical gap and is fixed with it rather
    /// than left for the next kata to rediscover.
    /// B-2026-08-10-16 — an explicit `return` inside a sort comparator body
    /// produces the comparator's result instead of a real function return.
    ///
    /// The body is INLINED into the thunk (or, on the mono path, straight into
    /// the sort function), so the fn-level return machinery was wrong twice:
    /// it emitted `ret <Ordering>` where the enclosing LLVM function returns
    /// `i64` or `void`, and it drained the WHOLE cleanup stack including the
    /// CALLER's frames, referencing the caller's allocas from inside the sort
    /// function. Module verification reported both — "Found return instr that
    /// returns non-void in Function of void return type" and "Instruction does
    /// not dominate all uses".
    ///
    /// Case 1 is the mono path (all-int element) and case 2 the thunk path
    /// (container element); they are separate emitters and the verifier
    /// failure differs between them, so one does not cover the other.
    ///
    /// Cases 3 and 4 are the shapes that already built — implicit block tail
    /// and if-expression tail. They matter because the fix routes ALL bodies
    /// through the retarget now: if the join mishandled a body that never
    /// returns early, these would break while the `return` cases passed.
    /// B-2026-08-10-17 — kata #254's own comparator, end to end.
    ///
    /// A lexicographic comparator is the shape that needs an EARLY return from
    /// inside a loop: compare element-by-element, exit at the first
    /// difference. It could not be written before — the `return`s were checked
    /// against the enclosing fn's return type — and could not be BUILT before
    /// B-2026-08-10-16, which retargeted the explicit return in a comparator.
    ///
    /// It is pinned here rather than only in the typechecker because the two
    /// fixes are only jointly sufficient: -17 makes it typecheck, -16 makes it
    /// codegen. This is the case that stayed broken while three successive
    /// minimised repros were each fixed, so it is worth an end-to-end test of
    /// its own.
    /// B-2026-08-10-18 — an explicit `return` inside a fused-iterator closure
    /// produces THAT ELEMENT's value and lets the loop continue.
    ///
    /// The emitters splice the closure body into a synthesized loop compiled in
    /// the ENCLOSING function, so a `return` there returned from that function.
    /// `fold` did not fail at all: it exited `main` on the first element with
    /// status 0, silently truncating the program; the other five left a `ret`
    /// mid-block and failed LLVM verification.
    ///
    /// Case 1 is the semantic crux and the reason the obvious fix is wrong.
    /// Retargeting the `return` to a merge AFTER the loop would compile and
    /// look plausible, but it would EXIT the iteration — only one element would
    /// be produced. Returning early on exactly one element and asserting the
    /// other three are still mapped is what distinguishes "this element's
    /// value" from "stop here".
    ///
    /// Case 2 does the same for `fold`, where the distinction is visible in the
    /// accumulator: skipping the `3` must still sum 1 + 2 + 4.
    #[test]
    fn test_e2e_explicit_return_in_a_fused_iter_closure() {
        assert_eq!(
            run_program(
                "fn main() {\n\
                     let v: Vec[i64] = [1i64, 2i64, 3i64, 4i64];\n\
                     let d: Vec[i64] = v.iter()\n\
                         .map(|n| { if n == 2i64 { return 99i64; } n })\n\
                         .collect();\n\
                     let s: i64 = v.iter()\n\
                         .fold(0i64, |acc, n| { if n == 3i64 { return acc; } acc + n });\n\
                     let e: Vec[i64] = v.iter()\n\
                         .filter(|n| { if n == 1i64 { return true; } return n > 3i64; })\n\
                         .collect();\n\
                     println(f\"{d[0]} {d[1]} {d[2]} {d[3]} | {s} | {e[0]} {e[1]}\");\n\
                 }"
            )
            .as_deref(),
            Some("1 99 3 4 | 7 | 1 4\n")
        );
        // The remaining terminals, each with a plain explicit return.
        assert_eq!(
            run_program(
                "fn main() {\n\
                     let v: Vec[i64] = [1i64, 2i64, 3i64];\n\
                     let a: bool = v.iter().any(|n| { return n > 2i64; });\n\
                     let b: bool = v.iter().all(|n| { return n > 0i64; });\n\
                     let mut w: Vec[i64] = v;\n\
                     w.retain(|n| { return n > 1i64; });\n\
                     println(f\"{a} {b} {w.len()}\");\n\
                 }"
            )
            .as_deref(),
            Some("true true 2\n")
        );
        // `fold` again, standalone: this is the arm that used to exit `main`,
        // so the assertion is as much that the LATER println runs at all.
        assert_eq!(
            run_program(
                "fn main() {\n\
                     println(f\"before\");\n\
                     let v: Vec[i64] = [1i64, 2i64, 3i64];\n\
                     let s: i64 = v.iter().fold(0i64, |acc, n| { return acc + n; });\n\
                     println(f\"after {s}\");\n\
                 }"
            )
            .as_deref(),
            Some("before\nafter 6\n")
        );
    }

    /// The two directions the fix above could get wrong, which matter more
    /// than the returning cases themselves.
    ///
    /// Case 1: every fused pipeline WITHOUT a `return` must still compile and
    /// run — these are the hot paths the fusion exists for, and a guard that
    /// tripped on them would be far worse than the bug.
    ///
    /// Case 2: a `return` inside a NESTED closure belongs to THAT closure,
    /// which is lowered as a real closure body where `return` already worked.
    /// An earlier iteration of this work walked into nested closures and
    /// mishandled it, breaking a program that built correctly — measured, not
    /// hypothetical, and the reason the body walker stops at a nested closure.
    #[test]
    fn test_e2e_fused_iter_pipelines_without_return_are_untouched() {
        assert_eq!(
            run_program(
                "fn main() {\n\
                     let v: Vec[i64] = [1i64, 2i64, 3i64, 4i64];\n\
                     let d: Vec[i64] = v.iter().map(|n| n * 2i64).collect();\n\
                     let e: Vec[i64] = v.iter().filter(|n| n > 2i64).collect();\n\
                     let s: i64 = v.iter().fold(0i64, |acc, n| acc + n);\n\
                     let a: bool = v.iter().any(|n| n > 3i64);\n\
                     let b: bool = v.iter().all(|n| n > 0i64);\n\
                     let mut w: Vec[i64] = v;\n\
                     w.retain(|n| n > 2i64);\n\
                     println(f\"{d[3]} {e.len()} {s} {a} {b} {w.len()}\");\n\
                 }"
            )
            .as_deref(),
            Some("8 2 10 true true 2\n")
        );
        assert_eq!(
            run_program(
                "fn apply(f: Fn(i64) -> i64, x: i64) -> i64 { f(x) }\n\
                 fn main() {\n\
                     let v: Vec[i64] = [1i64, 2i64];\n\
                     let d: Vec[i64] = v.iter()\n\
                         .map(|n| apply(|m| { if m > 1i64 { return m * 10i64; } return m; }, n))\n\
                         .collect();\n\
                     println(f\"{d[0]} {d[1]}\");\n\
                 }"
            )
            .as_deref(),
            Some("1 20\n")
        );
    }

    #[test]
    fn test_e2e_lexicographic_comparator_with_early_returns() {
        assert_eq!(
            run_program(
                "fn main() {\n\
                     let mut v: Vec[Vec[i64]] = Vec.new();\n\
                     let mut a: Vec[i64] = Vec.new(); a.push(2i64); a.push(6i64);\n\
                     let mut b: Vec[i64] = Vec.new(); b.push(2i64); b.push(2i64);\n\
                     let mut c: Vec[i64] = Vec.new(); c.push(1i64);\n\
                     v.push(a); v.push(b); v.push(c);\n\
                     v.sort_by(|x, y| {\n\
                         let mut i: i64 = 0i64;\n\
                         while i < x.len() and i < y.len() {\n\
                             if x[i] < y[i] { return Ordering.Less; }\n\
                             if x[i] > y[i] { return Ordering.Greater; }\n\
                             i = i + 1i64;\n\
                         }\n\
                         return x.len().cmp(y.len());\n\
                     });\n\
                     println(f\"{v[0][0]} {v[1][0]}{v[1][1]} {v[2][0]}{v[2][1]}\");\n\
                 }"
            )
            .as_deref(),
            Some("1 22 26\n")
        );
    }

    #[test]
    fn test_e2e_explicit_return_in_a_sort_comparator() {
        // 1. Mono path — all-int element, explicit return.
        assert_eq!(
            run_program(
                "fn main() {\n\
                     let mut v: Vec[(i64, i64)] = Vec.new();\n\
                     v.push((3i64, 1i64)); v.push((1i64, 2i64));\n\
                     v.sort_by(|x, y| { return x.0.cmp(y.0) });\n\
                     println(f\"{v[0].0} {v[1].0}\");\n\
                 }"
            )
            .as_deref(),
            Some("1 3\n")
        );
        // 2. Thunk path — container element, explicit return.
        assert_eq!(
            run_program(
                "fn main() {\n\
                     let mut v: Vec[String] = Vec.new();\n\
                     v.push(f\"ccc\"); v.push(f\"a\"); v.push(f\"bb\");\n\
                     v.sort_by(|x, y| { return x.len().cmp(y.len()) });\n\
                     println(f\"{v[0]} {v[1]} {v[2]}\");\n\
                 }"
            )
            .as_deref(),
            Some("a bb ccc\n")
        );
        // 3. CONTROL — implicit block tail, which always built.
        assert_eq!(
            run_program(
                "fn main() {\n\
                     let mut v: Vec[(i64, i64)] = Vec.new();\n\
                     v.push((3i64, 1i64)); v.push((1i64, 2i64));\n\
                     v.sort_by(|x, y| { let d = x.0; d.cmp(y.0) });\n\
                     println(f\"{v[0].0} {v[1].0}\");\n\
                 }"
            )
            .as_deref(),
            Some("1 3\n")
        );
        // 4. CONTROL — if-expression tail.
        assert_eq!(
            run_program(
                "fn main() {\n\
                     let mut v: Vec[(i64, i64)] = Vec.new();\n\
                     v.push((3i64, 1i64)); v.push((1i64, 2i64));\n\
                     v.sort_by(|x, y| if x.0 < y.0 { Ordering.Less } else { Ordering.Greater });\n\
                     println(f\"{v[0].0} {v[1].0}\");\n\
                 }"
            )
            .as_deref(),
            Some("1 3\n")
        );
    }

    #[test]
    fn test_e2e_sort_by_closure_param_keeps_its_element_type() {
        // 1. The row's repro — Vec[Vec[i64]] by length.
        assert_eq!(
            run_program(
                "fn main() {\n\
                     let mut v: Vec[Vec[i64]] = Vec.new();\n\
                     let mut a: Vec[i64] = Vec.new(); a.push(1i64); a.push(2i64); a.push(3i64);\n\
                     let mut b: Vec[i64] = Vec.new(); b.push(9i64);\n\
                     let mut c: Vec[i64] = Vec.new(); c.push(4i64); c.push(5i64);\n\
                     v.push(a); v.push(b); v.push(c);\n\
                     v.sort_by(|x, y| x.len().cmp(y.len()));\n\
                     println(f\"{v[0].len()} {v[1].len()} {v[2].len()}\");\n\
                 }"
            )
            .as_deref(),
            Some("1 2 3\n")
        );
        // 2. Vec[String] by length — a different container element.
        assert_eq!(
            run_program(
                "fn main() {\n\
                     let mut v: Vec[String] = Vec.new();\n\
                     v.push(f\"ccc\"); v.push(f\"a\"); v.push(f\"bb\");\n\
                     v.sort_by(|x, y| x.len().cmp(y.len()));\n\
                     println(f\"{v[0]} {v[1]} {v[2]}\");\n\
                 }"
            )
            .as_deref(),
            Some("a bb ccc\n")
        );
        // 3. INDEX inside the comparator, the other lowering that needs the type.
        assert_eq!(
            run_program(
                "fn main() {\n\
                     let mut v: Vec[Vec[i64]] = Vec.new();\n\
                     let mut a: Vec[i64] = Vec.new(); a.push(5i64);\n\
                     let mut b: Vec[i64] = Vec.new(); b.push(2i64);\n\
                     v.push(a); v.push(b);\n\
                     v.sort_by(|x, y| x[0].cmp(y[0]));\n\
                     println(f\"{v[0][0]} {v[1][0]}\");\n\
                 }"
            )
            .as_deref(),
            Some("2 5\n")
        );
        // 4. CONTROL — tuple fields, which already built and route through the
        //    all-int mono sort rather than the thunk this fix touches.
        assert_eq!(
            run_program(
                "fn main() {\n\
                     let mut v: Vec[(i64, i64)] = Vec.new();\n\
                     v.push((3i64, 1i64)); v.push((1i64, 2i64));\n\
                     v.sort_by(|a, b| a.0.cmp(b.0));\n\
                     println(f\"{v[0].0} {v[1].0}\");\n\
                 }"
            )
            .as_deref(),
            Some("1 3\n")
        );
        // 5/6. `sort_by_key`, the sibling with the same gap.
        assert_eq!(
            run_program(
                "fn main() {\n\
                     let mut v: Vec[String] = Vec.new();\n\
                     v.push(f\"ccc\"); v.push(f\"a\"); v.push(f\"bb\");\n\
                     v.sort_by_key(|x| x.len());\n\
                     println(f\"{v[0]} {v[1]} {v[2]}\");\n\
                 }"
            )
            .as_deref(),
            Some("a bb ccc\n")
        );
        assert_eq!(
            run_program(
                "fn main() {\n\
                     let mut v: Vec[Vec[i64]] = Vec.new();\n\
                     let mut a: Vec[i64] = Vec.new(); a.push(1i64); a.push(2i64);\n\
                     let mut b: Vec[i64] = Vec.new(); b.push(9i64);\n\
                     v.push(a); v.push(b);\n\
                     v.sort_by_key(|x| x.len());\n\
                     println(f\"{v[0].len()} {v[1].len()}\");\n\
                 }"
            )
            .as_deref(),
            Some("1 2\n")
        );
    }

    #[test]
    fn test_e2e_index_through_a_slice_typed_tuple_field() {
        // 1. Read and write through a slice-typed tuple field.
        assert_eq!(
            run_program(
                "fn main() {\n\
                     let mut v: Vec[i64] = [1i64, 2i64, 3i64];\n\
                     let mut t: (mut Slice[i64], i64) = (v.as_slice_mut(), 5i64);\n\
                     let r: i64 = t.0[1];\n\
                     t.0[0] = 9i64;\n\
                     println(f\"{r} {v[0]} {v[1]}\");\n\
                 }"
            )
            .as_deref(),
            Some("2 9 2\n")
        );
        // 2. The motivating shape — writing through `split_at_mut` halves.
        assert_eq!(
            run_program(
                "fn main() {\n\
                     let mut buf: Vec[u8] = [0u8, 0u8, 0u8, 0u8];\n\
                     let mut p: (mut Slice[u8], mut Slice[u8]) = buf.split_at_mut(2i64);\n\
                     p.0[0] = 7u8;\n\
                     p.1[1] = 9u8;\n\
                     println(f\"{buf[0]} {buf[1]} {buf[2]} {buf[3]}\");\n\
                 }"
            )
            .as_deref(),
            Some("7 0 0 9\n")
        );
        // 3. CONTROL — a Vec-typed tuple field, which already worked.
        assert_eq!(
            run_program(
                "fn main() {\n\
                     let mut t: (Vec[i64], i64) = ([1i64, 2i64], 5i64);\n\
                     t.0[0] = 9i64;\n\
                     println(f\"{t.0[0]} {t.0[1]} {t.1}\");\n\
                 }"
            )
            .as_deref(),
            Some("9 2 5\n")
        );
    }

    #[test]
    fn test_e2e_split_at_mut_halves_write_through_to_the_source() {
        // Vec receiver.
        assert_eq!(
            run_program(
                "fn fill(s: mut Slice[u8], v: u8) {\n\
                     let mut i: i64 = 0i64;\n\
                     while i < s.len() { s[i] = v; i = i + 1i64; }\n\
                 }\n\
                 fn main() {\n\
                     let mut buf: Vec[u8] = [0u8, 0u8, 0u8, 0u8, 0u8, 0u8];\n\
                     let mut parts: (mut Slice[u8], mut Slice[u8]) = buf.split_at_mut(2i64);\n\
                     fill(parts.0, 7u8);\n\
                     fill(parts.1, 9u8);\n\
                     println(f\"{buf[0]} {buf[1]} {buf[2]} {buf[5]}\");\n\
                 }"
            )
            .as_deref(),
            Some("7 7 9 9\n")
        );
        // `mut Slice` receiver, over an Array — the second spec'd receiver.
        assert_eq!(
            run_program(
                "fn fill(s: mut Slice[i64], v: i64) {\n\
                     let mut i: i64 = 0i64;\n\
                     while i < s.len() { s[i] = v; i = i + 1i64; }\n\
                 }\n\
                 fn main() {\n\
                     let mut a: Array[i64, 4] = [1i64, 2i64, 3i64, 4i64];\n\
                     let mut s: mut Slice[i64] = a.as_slice_mut();\n\
                     let mut p: (mut Slice[i64], mut Slice[i64]) = s.split_at_mut(1i64);\n\
                     fill(p.0, 100i64);\n\
                     fill(p.1, 200i64);\n\
                     println(f\"{a[0]} {a[1]} {a[2]} {a[3]}\");\n\
                 }"
            )
            .as_deref(),
            Some("100 200 200 200\n")
        );
        // Boundary: mid == 0 and mid == len are legal; only `mid > len` panics.
        assert_eq!(
            run_program(
                "fn main() {\n\
                     let mut v: Vec[i64] = [1i64, 2i64, 3i64];\n\
                     let mut a: (mut Slice[i64], mut Slice[i64]) = v.split_at_mut(0i64);\n\
                     let mut b: (mut Slice[i64], mut Slice[i64]) = v.split_at_mut(3i64);\n\
                     println(f\"{a.0.len()} {a.1.len()} {b.0.len()} {b.1.len()}\");\n\
                 }"
            )
            .as_deref(),
            Some("0 3 3 0\n")
        );
    }

    #[test]
    fn test_e2e_nested_index_store_releases_the_displaced_element() {
        // 1. The row's own repro.
        assert_eq!(
            run_program(
                "fn main() {\n\
                     let mut r: Vec[String] = Vec.new();\n\
                     r.push(f\"aa\"); r.push(f\"bb\");\n\
                     let mut d: Vec[Vec[String]] = Vec.new();\n\
                     d.push(r);\n\
                     d[0][0] = f\"zz\";\n\
                     println(f\"{d[0][0]} {d[0][1]}\");\n\
                 }"
            )
            .as_deref(),
            Some("zz bb\n")
        );
        // 2. Struct-FIELD base — the B-2026-08-09-21 route into this path.
        assert_eq!(
            run_program(
                "struct H { data: Vec[Vec[String]] }\n\
                 fn main() {\n\
                     let mut r: Vec[String] = Vec.new();\n\
                     r.push(f\"aa\"); r.push(f\"bb\");\n\
                     let mut h: H = H { data: Vec.new() };\n\
                     h.data.push(r);\n\
                     h.data[0][0] = f\"zz\";\n\
                     println(f\"{h.data[0][0]} {h.data[0][1]}\");\n\
                 }"
            )
            .as_deref(),
            Some("zz bb\n")
        );
        // 3. SELF-ALIAS — releasing before storing must not free the source.
        //
        // Spelled without an element-to-element store, which reads a non-`Copy`
        // element out of a container and is rejected now (B-2026-08-26-21). The
        // property under test is unchanged and both halves survive: `swap(0, 0)`
        // is the degenerate same-slot case that must not free anything, and the
        // clone-then-store still makes slot 1 hold slot 0's value while slot 0
        // stays alive — which is what "releasing before storing must not free
        // the source" means. The row goes through a temporary because
        // `d[0][0].clone()` is a chained indexed receiver, deferred in codegen.
        assert_eq!(
            run_program(
                "fn main() {\n\
                     let mut r: Vec[String] = Vec.new();\n\
                     r.push(f\"aa\"); r.push(f\"bb\");\n\
                     let mut d: Vec[Vec[String]] = Vec.new();\n\
                     d.push(r);\n\
                     d[0].swap(0, 0);\n\
                     let row: Vec[String] = d[0].clone();\n\
                     d[0][1] = row[0].clone();\n\
                     println(f\"{d[0][0]} {d[0][1]}\");\n\
                 }"
            )
            .as_deref(),
            Some("aa aa\n")
        );
        // 4. SCALAR leaf — no release applies; must be untouched.
        assert_eq!(
            run_program(
                "fn main() {\n\
                     let mut r: Vec[i64] = Vec.new();\n\
                     r.push(1i64); r.push(2i64);\n\
                     let mut d: Vec[Vec[i64]] = Vec.new();\n\
                     d.push(r);\n\
                     d[0][0] = 9i64;\n\
                     println(f\"{d[0][0]} {d[0][1]}\");\n\
                 }"
            )
            .as_deref(),
            Some("9 2\n")
        );
    }

    #[test]
    fn test_e2e_nested_indexed_read_vec_of_vec() {
        // `grid[0][0]` — nested indexed read on `Vec[Vec[i64]]`.
        // Codegen synthesizes a fresh identifier for the inner
        // `grid[0]` (pointing into grid's storage) and re-dispatches
        // the outer index through the existing identifier-keyed path.
        let out = run_program(
            r#"
fn main() {
    let mut grid: Vec[Vec[i64]] = Vec.filled(3, Vec.new());
    grid[0].push(99);
    grid[0].push(11);
    grid[2].push(42);
    let v = grid[0][0];
    let w = grid[0][1];
    let x = grid[2][0];
    println(v);
    println(w);
    println(x);
}
"#,
        );
        if let Some(out) = out {
            assert_eq!(out.trim(), "99\n11\n42");
        }
    }

    #[test]
    fn test_e2e_par_group_return_slot_preserves_vec_bool_elem_type() {
        // Regression: when auto-par groups `let v: Vec[bool] = ...`
        // with another stmt, the return-slot rebind in
        // `compile_function_body` was unconditionally overwriting
        // `vec_elem_types[v]` to i64 (the placeholder). Later
        // `not v[i]` then loaded an i64 instead of bool, lowered
        // through `xor i64 …, -1`, and the short-circuit phi
        // rejected the i64 operand against an i1 result. Fix uses
        // `entry().or_insert_with(...)` to preserve the let's
        // annotated element type.
        let out = run_program(
            r#"
fn helper(nums: Slice[i64]) -> i64 {
    let n = nums.len();
    let mut visited: Vec[bool] = Vec.filled(n, false);
    let mut bucket: Map[i64, i64] = Map.new();
    let i = 1i64;
    if i > 0 and not visited[i - 1] {
        return 1;
    }
    0
}
fn main() {
    let a: Array[i64, 3] = [1, 2, 3];
    println(helper(a));
}
"#,
        );
        if let Some(out) = out {
            assert_eq!(out.trim(), "1");
        }
    }

    #[test]
    fn test_e2e_match_bound_payload_vec_field_copy_over_ref_vec() {
        // B-2026-07-17-20: `for it in items { match it { Fu(f) => { let ps =
        // f.params; … } } }` over `items: ref Vec[It]` — copying a Vec field out
        // of a match-bound struct payload that aliases a borrowed ref-Vec enum
        // element. Pre-fix this AOT-crashed with `free(): double free` (the copy
        // shallow-aliased the container's buffer); now the field deep-copies.
        // Locks run == build parity on the exact repro.
        let out = run_program(
            r#"
struct P { n: i64 }
struct F { name: String, params: Vec[P] }
enum It { Fu(F), Other }
fn collect(items: ref Vec[It]) -> i64 {
    let mut total = 0;
    for it in items {
        match it {
            It.Fu(f) => {
                let ps = f.params;
                for p in ps { total = total + p.n; }
            }
            It.Other => {}
        }
    }
    total
}
fn main() {
    let mut items: Vec[It] = Vec.new();
    let mut ps1: Vec[P] = Vec.new();
    ps1.push(P { n: 1 });
    ps1.push(P { n: 2 });
    items.push(It.Fu(F { name: "a", params: ps1 }));
    items.push(It.Other);
    println(collect(items).to_string());
}
"#,
        );
        if let Some(out) = out {
            assert_eq!(out.trim(), "3");
        }
    }

    #[test]
    fn test_e2e_match_bound_struct_variant_vec_field_reborrow_over_ref_vec() {
        // B-2026-07-18-4: a STRUCT-VARIANT enum payload's Vec field bound
        // DIRECTLY (`match it { Fu { params } => … }`, not through a struct
        // payload `f`), then whole-moved into a local (`let ps = params`), over
        // `items: ref Vec[It]`. `params` is typed `ref Vec[P]` (a borrow of the
        // container-owned buffer), so `ps` is a re-borrow. Pre-fix the binding
        // recorded none of the Vec dispatch tables — `ps.len()` build-failed and
        // `for p in ps` compiled to an EMPTY Vec (AOT sum 0 vs interp 9). The
        // typechecker now peels the borrow to register `ps`'s element type, and
        // codegen binds `ps` as an alias (no scope-exit free) so the container
        // stays the sole owner. Locks run == build parity and no double-free.
        let out = run_program(
            r#"
struct P { n: i64 }
enum It { Fu { params: Vec[P] }, Other }
fn collect(items: ref Vec[It]) -> i64 {
    let mut total = 0;
    for it in items {
        match it {
            It.Fu { params } => {
                let ps = params;
                for p in ps { total = total + p.n; }
            }
            It.Other => {}
        }
    }
    total
}
fn main() {
    let mut items: Vec[It] = Vec.new();
    let mut ps: Vec[P] = Vec.new();
    ps.push(P { n: 4 });
    ps.push(P { n: 5 });
    items.push(It.Fu { params: ps });
    items.push(It.Other);
    println(collect(items).to_string());
}
"#,
        );
        if let Some(out) = out {
            assert_eq!(out.trim(), "9");
        }
    }

    #[test]
    fn test_e2e_match_some_node_let_destructure_tuple_payload() {
        // The kata's canonical BFS shape: `Some(node) => let (i, d) = node`
        // where `node: (i64, i64)` is reconstituted as a tuple struct
        // value from the multi-word Option payload. The typechecker
        // records the tuple `TypeExpr` in `pattern_binding_inner_types`
        // (tagged "Tuple" in `pattern_binding_types`); codegen's
        // `reconstruct_payload_value` Binding arm walks the recorded
        // element types and builds a tuple struct from `field_words`.
        let out = run_program(
            r#"
fn main() {
    let mut q: VecDeque[(i64, i64)] = VecDeque.new();
    q.push_back((3, 30));
    q.push_back((7, 70));
    loop {
        match q.pop_front() {
            None => { break; },
            Some(node) => {
                let (a, b) = node;
                println(a);
                println(b);
            },
        }
    }
}
"#,
        );
        if let Some(out) = out {
            assert_eq!(out.trim(), "3\n30\n7\n70");
        }
    }

