    #[test]
    fn test_e2e_into_drives_user_from_impl() {
        // User `impl From[Inches] for Cm` compiles as `Cm.from`; `.into()`
        // at a `let: Cm` position lowers to `Cm.from(...)` and routes to it.
        let out = run_program(
            r#"
struct Inches { n: i64 }
struct Cm { n: i64 }
impl From for Cm {
    fn from(i: Inches) -> Cm { Cm { n: i.n * 254 / 100 } }
}
fn main() {
    let i: Inches = Inches { n: 10 };
    let c: Cm = i.into();
    println(c.n);
}
"#,
        );
        if let Some(out) = out {
            assert_eq!(out.trim(), "25");
        }
    }

    #[test]
    fn test_e2e_into_wraps_value_in_some_and_ok() {
        // `From[T] for Option[T]` / `From[T] for Result[T, E]` blanket wraps
        // (design.md § Conversion Traits): `.into()` lowers to `Some(x)` /
        // `Ok(x)`, indistinguishable from hand-written variant construction, so
        // codegen reuses its existing enum-build path. Covers the let,
        // if/else-tail return, and struct-field positions plus a heap `String`
        // payload; the `Err`/`None` arms stay hand-writable. Build==run parity
        // with the interpreter sibling `test_into_wraps_value_in_some_and_ok`.
        // (Leak-clean under valgrind — the `String` payloads are freed on the
        // match/discard paths; verified by hand.)
        let out = run_program(
            r#"
fn get_opt(present: bool) -> Option[i64] {
    if present { 42.into() } else { None }
}
fn get_res(ok: bool) -> Result[i64, String] {
    if ok { 7.into() } else { Err("nope") }
}
struct Holder { slot: Option[String] }
fn main() {
    let o: Option[i64] = 5.into();
    match o { Some(v) => println(v), None => println(-1) };
    match get_opt(true) { Some(v) => println(v), None => println(-1) };
    match get_opt(false) { Some(v) => println(v), None => println(-1) };
    match get_res(true) { Ok(v) => println(v), Err(e) => println(e) };
    match get_res(false) { Ok(v) => println(v), Err(e) => println(e) };
    let h: Holder = Holder { slot: "hi".into() };
    match h.slot { Some(s) => println(s), None => println("none") };
}
"#,
        );
        if let Some(out) = out {
            assert_eq!(out.trim(), "5\n42\n-1\n7\nnope\nhi");
        }
    }

    #[test]
    fn test_e2e_into_at_struct_field_if_and_match_tails() {
        // `.into()` threads the expected type through a struct-literal field
        // value, an if/else tail, and a match-arm tail — the three positions
        // the let/return/call-arg codegen tests above don't reach. Each flows
        // through `check_expr` with the contextual type, so the user
        // `impl From[Celsius] for Kelvin` lowers to `Kelvin.from(...)` at
        // every one. Build==run parity with the interpreter sibling
        // (`test_into_at_struct_field_if_and_match_tails`).
        let out = run_program(
            r#"
struct Celsius { deg: i64 }
struct Kelvin { k: i64 }
impl From for Kelvin {
    fn from(c: Celsius) -> Kelvin { Kelvin { k: c.deg + 273 } }
}
struct Reading { temp: Kelvin }
fn pick(hot: bool) -> Kelvin {
    if hot { (Celsius { deg: 100 }).into() }
    else { (Celsius { deg: 0 }).into() }
}
fn classify(n: i64) -> Kelvin {
    match n {
        0 => (Celsius { deg: 0 }).into(),
        _ => (Celsius { deg: n }).into(),
    }
}
fn main() {
    let r: Reading = Reading { temp: (Celsius { deg: 27 }).into() };
    println(r.temp.k);
    println(pick(true).k);
    println(pick(false).k);
    println(classify(0).k);
    println(classify(50).k);
}
"#,
        );
        if let Some(out) = out {
            assert_eq!(out.trim(), "300\n373\n273\n273\n323");
        }
    }

    #[test]
    fn test_e2e_tryinto_drives_user_tryfrom_impl() {
        // A user `impl TryFrom[Celsius] for Kelvin` compiles as `Kelvin.try_from`;
        // `.try_into()` at a `let: Result[Kelvin, _]` position lowers to
        // `Kelvin.try_from(...)` and routes to it. Exercises the Ok arm and the
        // Err arm (a heap `String` error payload). The fallible sibling of
        // `test_e2e_into_drives_user_from_impl`; the whole `.try_into()` desugar
        // chain had no codegen coverage before. (Leak-clean under valgrind — the
        // `Result[Kelvin, String]` Err String is freed on the discard/`e.len()`
        // paths; verified by hand.)
        let out = run_program(
            r#"
struct Celsius { deg: i64 }
struct Kelvin { deg: i64 }
impl TryFrom for Kelvin {
    type Error = String;
    fn try_from(c: Celsius) -> Result[Kelvin, String] {
        if c.deg < -273 { Err("below absolute zero") }
        else { Ok(Kelvin { deg: c.deg + 273 }) }
    }
}
fn main() {
    match Kelvin.try_from(Celsius { deg: 27 }) {
        Ok(k) => println(k.deg),
        Err(e) => println(e),
    }
    let r: Result[Kelvin, String] = (Celsius { deg: -300 }).try_into();
    match r {
        Ok(k) => println(k.deg),
        Err(e) => println(e),
    }
}
"#,
        );
        if let Some(out) = out {
            assert_eq!(out.trim(), "300\nbelow absolute zero");
        }
    }

    #[test]
    fn test_e2e_user_impl_eq_drives_equality() {
        // End-to-end: `a == b` on user type lowers to `Point.eq(a, b)`,
        // which routes through the codegen-compiled impl method.
        // CR-202 slice 5b: companion `impl PartialEq for Point` satisfies
        // the new `Eq: PartialEq` supertrait edge.
        let out = run_program(
            r#"
struct Point { x: i64, y: i64 }
impl PartialEq for Point {
    fn eq(ref self, other: ref Point) -> bool {
        self.x == other.x and self.y == other.y
    }
}
impl Eq for Point {
    fn eq(self, other: Point) -> bool {
        self.x == other.x and self.y == other.y
    }
}
fn main() {
    let a = Point { x: 1, y: 2 };
    let b = Point { x: 1, y: 2 };
    let c = Point { x: 9, y: 9 };
    println(a == b);
    println(a != c);
}
"#,
        );
        if let Some(out) = out {
            assert_eq!(out.trim(), "true\ntrue");
        }
    }

    // ── Generic associated types (GATs) codegen ───────────────────
    //
    // The GAT typechecker/resolver slices (design.md § Generic
    // associated types) are pinned by 46 tests in `tests/typechecker.rs`,
    // but the runtime lowering of a projected GAT return had NO codegen
    // coverage. These two E2E tests exercise it: a call whose signature
    // return is `Self.Mapped[..]` must lower to the impl binding's
    // concrete right-hand side and run correctly. The first is a concrete
    // impl (`Mapped[U] = Vec[U]`); the second is the harder generic impl
    // where the RHS mixes the impl's own param `T` with the GAT param `U`
    // (`Mapped[U] = Pair[T, U]`), so codegen must apply the two-sided
    // substitution the resolver computes, not just a single map.

    #[test]
    fn test_e2e_gat_concrete_impl_projection_returns_vec() {
        // `Doubler` binds `Mapped[U] = Vec[U]`; `map_to_i64(ref self) ->
        // Self.Mapped[i64]` resolves to `Vec[i64]`. The returned vector is
        // indexed at the call site, proving the projected type lowered to a
        // real `Vec[i64]` (not an opaque/aborted shape).
        let out = run_program(
            r#"
trait Functor {
    type Mapped[U];
    fn map_to_i64(ref self) -> Self.Mapped[i64];
}
struct Doubler {}
impl Functor for Doubler {
    type Mapped[U] = Vec[U];
    fn map_to_i64(ref self) -> Vec[i64] {
        let mut v: Vec[i64] = Vec.new();
        v.push(21i64);
        v.push(42i64);
        v
    }
}
fn caller(d: ref Doubler) -> Vec[i64] {
    d.map_to_i64()
}
fn main() {
    let dbl = Doubler {};
    let result = caller(dbl);
    println(f"{result[0]}");
    println(f"{result[1]}");
}
"#,
        );
        if let Some(out) = out {
            assert_eq!(out.trim(), "21\n42");
        }
    }

    #[test]
    fn test_e2e_gat_generic_impl_two_sided_substitution() {
        // `impl[T] Functor for Wrapper[T]` with `Mapped[U] = Pair[T, U]`:
        // resolving `Self.Mapped[i64]` for `Wrapper[bool]` must substitute
        // BOTH the impl param `T = bool` and the GAT param `U = i64`,
        // yielding `Pair[bool, i64]`. Reads back both fields to prove each
        // side of the substitution reached codegen intact.
        let out = run_program(
            r#"
trait Functor {
    type Mapped[U];
    fn rewrap(ref self) -> Self.Mapped[i64];
}
struct Pair[A, B] { a: A, b: B }
struct Wrapper[T] { x: T }
impl[T] Functor for Wrapper[T] {
    type Mapped[U] = Pair[T, U];
    fn rewrap(ref self) -> Pair[T, i64] {
        Pair { a: self.x, b: 99i64 }
    }
}
fn main() {
    let w = Wrapper { x: true };
    let p = w.rewrap();
    let msg = if p.a { "yes" } else { "no" };
    println(msg);
    println(f"{p.b}");
}
"#,
        );
        if let Some(out) = out {
            assert_eq!(out.trim(), "yes\n99");
        }
    }

    // ── F-string codegen (Phase 7.2 minimum formatter) ────────────

    #[test]
    fn test_e2e_fstring_text_literal_only() {
        let out = run_program(
            r#"
fn main() {
    let s = f"hello, world";
    println(s);
}
"#,
        );
        if let Some(out) = out {
            assert_eq!(out.trim(), "hello, world");
        }
    }

    #[test]
    fn test_e2e_fstring_string_interpolation() {
        let out = run_program(
            r#"
fn main() {
    let mut name: String = String.new();
    name.push_str("Alice");
    let msg = f"Hello, {name}!";
    println(msg);
}
"#,
        );
        if let Some(out) = out {
            assert_eq!(out.trim(), "Hello, Alice!");
        }
    }

    #[test]
    fn test_e2e_fstring_match_arm_value() {
        // phase-12 self-hosting blocker #3: an f-string that is a match
        // arm's TAIL (value) expression, interpolating the arm's payload
        // binding, compiled to empty under AOT. The f-string accumulator is
        // an entry-block alloca registered for scope cleanup; the per-arm
        // `drain_top_frame_with_emit` freed its buffer between the value load
        // and the merge, so the match result (and any caller binding) saw an
        // empty/dangling String. Fix: when the arm tail is an f-string, zero
        // the acc's `cap` so its cleanup no-ops and the value escapes via the
        // match phi (mirrors the function-tail f-string-return handling).
        // Covers fn-return, let-bound, i64 payload, nested-into-outer, and a
        // discarded result (must not double-free). The brace-WRAPPED arm body
        // (`=> { f"…" }` / `=> { let p = f"…"; p }`) is the separate
        // block-expr-value heap-return shape, fixed and covered by
        // `test_e2e_block_expr_value_heap_return` (B-2026-06-11-2).
        let out = run_program(
            r#"
enum E { A(String), B(i64) }
fn describe(e: E) -> String {
    match e {
        E.A(name) => f"A[{name}]",
        E.B(k) => f"B[{k}]",
    }
}
fn main() {
    println(describe(E.A("x" + "y")));
    println(describe(E.B(99)));
    let e = E.A("hi");
    let s = match e {
        E.A(name) => f"<{name}>",
        E.B(_) => "none",
    };
    println(s);
    let r = describe(E.A("a" + "b"));
    println(f"outer:{r}");
    let d = E.A("z");
    match d {
        E.A(n) => f"[{n}]",
        E.B(_) => "x",
    };
    println("done");
}
"#,
        );
        if let Some(out) = out {
            assert_eq!(out, "A[xy]\nB[99]\n<hi>\nouter:A[ab]\ndone\n");
        }
    }

    #[test]
    fn test_e2e_block_expr_value_heap_return() {
        // B-2026-06-11-2: a block expression USED AS A VALUE whose tail is a
        // scope-registered heap value (an f-string accumulator or a block-local
        // `let`-bound String) lost the value under AOT — it printed empty. The
        // block's `compile_block_with_frame` loaded the tail, then drained its
        // own frame, freeing the tail's buffer between the load and the value
        // escaping (a use-after-free). Fix: suppress the tail value's cleanup
        // before the block-frame drain (mirrors `compile_function`'s tail
        // handling) so the consumer's own binding is the sole owner. Covers
        // every consumer the bug surfaced across: plain let-RHS (f-string and
        // identifier tail), `if`-arm value, a block-`let` inside a loop, a
        // brace-WRAPPED match arm (f-string and identifier tail), a nested
        // block, a function-return block, and a struct-field initializer block.
        let out = run_program(
            r#"
enum E { A(String), B }
fn mk() -> String { { f"ret{1}" } }
struct S { name: String }
fn main() {
    let a = { f"a{1}" };
    println(a);
    let b = { let p = "x" + "y"; p };
    println(b);
    let c = if true { f"yes{2}" } else { f"no{0}" };
    println(c);
    let mut i = 0i64;
    while i < 2i64 { let v = { f"v{i}" }; println(v); i = i + 1i64; }
    let e1 = E.A("m");
    let d = match e1 { E.A(n) => { f"<{n}>" }, E.B => "z" };
    println(d);
    let e2 = E.A("k");
    let g = match e2 { E.A(n) => { let p = f"[{n}]"; p }, E.B => "z" };
    println(g);
    let h = { { f"nest{3}" } };
    println(h);
    println(mk());
    let s = S { name: { f"fld{4}" } };
    println(s.name);
}
"#,
        );
        if let Some(out) = out {
            assert_eq!(out, "a1\nxy\nyes2\nv0\nv1\n<m>\n[k]\nnest3\nret1\nfld4\n");
        }
    }

    #[test]
    fn test_e2e_by_value_aggregate_drops() {
        // B-2026-06-11-4: by-value aggregates leaked their heap fields across
        // several shapes the named-struct drop path didn't cover. This asserts
        // the VALUE is correct (the heap field survives to its use) across all
        // of them; the no-leak / single-free side is `tests/memory_sanitizer.rs
        // ::asan_by_value_aggregate_drops_single_free`. Shapes: a let-bound
        // tuple passed by value, a tuple-to-tuple move, a tuple returned from a
        // fn, a tuple forwarded through two params, a tuple literal arg, a
        // struct literal arg, and a nested-struct field.
        let out = run_program(
            r#"
struct S { k: i64, name: String }
struct Inner { name: String }
struct Outer { id: i64, inner: Inner }
fn show_tup(p: (i64, String)) { println(p.1); }
fn fwd(p: (i64, String)) { show_tup(p); }
fn show_s(s: S) { println(s.name); }
fn show_o(o: Outer) { println(o.inner.name); }
fn mk(n: i64) -> (i64, String) { (n, f"r-{n}") }
fn main() {
    let t = (1i64, f"let-{1}");
    show_tup(t);
    let u = (2i64, f"mv-{2}");
    let w = u;
    println(w.1);
    let r = mk(3i64);
    println(r.1);
    fwd((4i64, f"fwd-{4}"));
    show_tup((5i64, f"lit-{5}"));
    show_s(S { k: 6i64, name: f"slit-{6}" });
    let o = Outer { id: 7i64, inner: Inner { name: f"nest-{7}" } };
    show_o(o);
}
"#,
        );
        if let Some(out) = out {
            assert_eq!(out, "let-1\nmv-2\nr-3\nfwd-4\nlit-5\nslit-6\nnest-7\n");
        }
    }

    #[test]
    fn test_e2e_tuple_projection() {
        // B-2026-06-11-7: a chained tuple index `t.1.1` failed to PARSE (the
        // lexer ate `1.1` as a float). B-2026-06-11-6: a struct field read
        // THROUGH a tuple element `t.1.name` compiled to the `i64 0` placeholder
        // under AOT (interp was correct) because `type_name_of_expr` couldn't
        // resolve the tuple element's struct type. Both fixed: the lexer treats
        // a `.`-preceded number as a tuple index, and a tuple binding's element
        // type names are recorded so the field access resolves. Covers nested
        // tuple index, struct-through-tuple (multi-field), and an annotated tuple.
        let out = run_program(
            r#"
struct Inner { name: String, age: i64 }
fn main() {
    let nt = (1i64, (2i64, 3i64));
    println(nt.1.0);
    println(nt.1.1);
    let t = (9i64, Inner { name: f"in-{2}", age: 7i64 });
    println(t.1.name);
    println(t.1.age);
    let a: (i64, Inner) = (5i64, Inner { name: f"ann-{4}", age: 8i64 });
    println(a.1.name);
}
"#,
        );
        if let Some(out) = out {
            assert_eq!(out, "2\n3\nin-2\n7\nann-4\n");
        }
    }

