    fn test_e2e_enum_match_simple_singleton() {
        let out = run_program(
            r#"
#[derive(Hash, Eq)]
enum Color { Red, Green, Blue }

fn main() {
    let g: Color = Color.Green;
    match g {
        Color.Green => println(11_i64),
        _ => println(99_i64),
    }
}
"#,
        );
        let out = out.expect("simple enum match should not bail");
        assert_eq!(out.trim(), "11");
    }

    #[test]
    fn test_e2e_method_on_enum_unit_variant_literal() {
        // B-2026-07-13-4: a method called directly on an enum UNIT-VARIANT
        // LITERAL — `Dir.North.code()` — parses as `Call(Path([Dir, North,
        // code]))`. The typechecker left it untyped and neither backend
        // dispatched a method on a bare enum-literal receiver (codegen keys on
        // an identifier receiver). The typechecker now types it via
        // `infer_method_call` and lowering materializes the receiver into a
        // fresh local (`{ let __recv: Dir = Dir.North; __recv.code() }`).
        // Covers: a chained `.to_string()` (the block-value receiver), a method
        // with an argument, a heap (String) return, and use of the result in
        // arithmetic — each previously failed codegen or the interpreter.
        let out = run_program(
            r#"
enum Color { Red, Green, Blue }
impl Color {
    fn code(self) -> i64 { match self { Color.Red => 0, Color.Green => 1, Color.Blue => 2 } }
    fn name(self) -> String { match self { Color.Red => f"red", Color.Green => f"green", Color.Blue => f"blue" } }
    fn plus(self, n: i64) -> i64 { self.code() + n }
}
fn main() {
    println(Color.Green.code().to_string());
    println(Color.Blue.name());
    println(Color.Red.plus(10).to_string());
    let z = Color.Blue.code() + 5;
    println(z.to_string());
}
"#,
        );
        let out = out.expect("method on enum unit-variant literal should compile");
        assert_eq!(out.trim(), "1\nblue\n10\n7");
    }

    #[test]
    fn test_e2e_enum_explicit_discriminants_payload() {
        // Explicit discriminants are declarations, not layout commitments
        // (design.md § Explicit Discriminants on Payload Variants): codegen
        // lowers the payload enum exactly as it does without them, so construct
        // + match on a `#[repr(u8)]` enum carrying explicit values runs the same
        // as the interpreter (the `run_program` harness pins build == run).
        let out = run_program(
            r#"
#[repr(u8)] enum Op { Reset = 1, Ping(u32) = 5, Stop = 255 }

fn code(o: Op) -> i64 {
    match o {
        Op.Reset => 1_i64,
        Op.Ping(n) => n as i64,
        Op.Stop => 255_i64,
    }
}

fn main() {
    println(code(Op.Reset));
    println(code(Op.Ping(42_u32)));
    println(code(Op.Stop));
}
"#,
        );
        let out = out.expect("payload enum with explicit discriminants should codegen + run");
        assert_eq!(out.trim(), "1\n42\n255");
    }

    #[test]
    fn test_e2e_enum_variant_match_codegen_sanity() {
        // Sanity: distinct unit-enum variants codegen to distinct values
        // (different tags). Pre-requisite for `Map[Color, V]` to work.
        let out = run_program(
            r#"
#[derive(Hash, Eq)]
enum Color { Red, Green, Blue }

fn main() {
    let r: Color = Color.Red;
    let g: Color = Color.Green;
    let b: Color = Color.Blue;
    match r {
        Color.Red => println(0_i64),
        _ => println(99_i64),
    }
    match g {
        Color.Green => println(1_i64),
        _ => println(99_i64),
    }
    match b {
        Color.Blue => println(2_i64),
        _ => println(99_i64),
    }
}
"#,
        );
        let out = out.expect("enum variant match codegen sanity");
        let lines: Vec<&str> = out.trim().lines().collect();
        assert_eq!(lines, vec!["0", "1", "2"]);
    }

    #[test]
    fn test_e2e_map_unit_enum_key() {
        // Unit-variant enum used as a Map key. Layout is `{ i64 tag }` — the
        // existing primitive hash/eq path (byte-by-byte over sizeof(K))
        // already does the right thing once the typechecker permits the
        // `K: Hash + Eq` bound.
        let out = run_program(
            r#"
#[derive(Hash, Eq)]
enum Color { Red, Green, Blue }

fn main() {
    let mut m: Map[Color, i64] = Map.new();
    m.insert(Color.Red,   100_i64);
    m.insert(Color.Green, 200_i64);
    m.insert(Color.Blue,  300_i64);
    println(m.len());
    let v1 = m.get(Color.Red);
    match v1 {
        Some(x) => println(x),
        None => println(0_i64 - 1_i64),
    }
    let v2 = m.get(Color.Green);
    match v2 {
        Some(x) => println(x),
        None => println(0_i64 - 1_i64),
    }
    let v3 = m.get(Color.Blue);
    match v3 {
        Some(x) => println(x),
        None => println(0_i64 - 1_i64),
    }
}
"#,
        );
        let out = out.expect("unit-enum-key codegen should not bail");
        let lines: Vec<&str> = out.trim().lines().collect();
        assert_eq!(lines, vec!["3", "100", "200", "300"]);
    }

    #[test]
    fn test_e2e_map_tuple_string_string_key() {
        // Two heap-bearing fields in the tuple — exercises the per-field
        // recursion path on both sides. A byte-loop FNV over raw struct bytes
        // would hash the two String headers (data ptr / len / cap pairs), which
        // diverge across allocations when the contents are equal — so this
        // test would fail under the pre-recursion hash.
        let out = run_program(
            r#"
fn main() {
    let mut m: Map[(String, String), i64] = Map.new();
    m.insert(("alice", "red"),  1_i64);
    m.insert(("alice", "blue"), 2_i64);
    m.insert(("bob",   "red"),  3_i64);
    println(m.len());
    let v = m.get(("alice", "blue"));
    match v {
        Some(x) => println(x),
        None => println(0_i64 - 1_i64),
    }
    let v2 = m.get(("alice", "green"));
    match v2 {
        Some(x) => println(x),
        None => println(0_i64 - 1_i64),
    }
}
"#,
        );
        let out = out.expect("(String,String)-key codegen should not bail");
        let lines: Vec<&str> = out.trim().lines().collect();
        assert_eq!(lines, vec!["3", "2", "-1"]);
    }

    #[test]
    fn test_e2e_map_compound_key_cache_reuse() {
        // Two distinct Map variables in one program share the same compound
        // key shape `(String, i64)`. Cache reuse means `karac_hash_tuple_*`
        // and `karac_eq_tuple_*` are emitted exactly once and called by both
        // map-new sites — duplicate emission would surface as a `module
        // already has a function named ...` panic during codegen, so this
        // test failing to compile is the cache regression signal.
        let out = run_program(
            r#"
fn main() {
    let mut m1: Map[(String, i64), i64] = Map.new();
    let mut m2: Map[(String, i64), i64] = Map.new();
    m1.insert(("a", 1_i64), 10_i64);
    m2.insert(("a", 1_i64), 99_i64);
    println(m1.len());
    println(m2.len());
    let v1 = m1.get(("a", 1_i64));
    match v1 {
        Some(x) => println(x),
        None => println(0_i64 - 1_i64),
    }
    let v2 = m2.get(("a", 1_i64));
    match v2 {
        Some(x) => println(x),
        None => println(0_i64 - 1_i64),
    }
}
"#,
        );
        let out = out.expect("compound-key cache reuse codegen should not bail");
        let lines: Vec<&str> = out.trim().lines().collect();
        assert_eq!(lines, vec!["1", "1", "10", "99"]);
    }

