    // ── Phase 6 line 26 slice 8o: terminal-arm final-expression value ─────
    //
    // The terminal-arm store into the state-struct terminal field now
    // uses the user's `body.final_expr` value when it's a recognised
    // `BodyArg` shape (slice-8k discipline: integer literal or in-scope
    // identifier). Slice 8i's placeholder `i64 0` survives only as a
    // fallback for unrecognised final-exprs or absent final-exprs.

    #[test]
    fn test_terminal_return_8o_uses_int_literal_final_expr() {
        // `fn driver() -> i64 ... { fetch(); 42 }` — the user's
        // trailing `42` becomes the stored terminal value.
        let ir = ir_for_with_state_struct_layouts(
            "effect resource Network;
             pub fn fetch() with sends(Network) receives(Network) {}
             fn driver() -> i64 with sends(Network) receives(Network) { fetch(); 42 }",
        );
        let body = extract_fn_ir(&ir, "__kara_poll_driver");
        assert!(
            body.contains("store i64 42, ptr %kara.return.field_ptr"),
            "terminal arm must store user's literal 42 into terminal field:\n{body}"
        );
    }

    #[test]
    fn test_terminal_return_8o_uses_captured_local_final_expr() {
        // `fn driver(n: i64) -> i64 ... { fetch(); n }` — `n` is a
        // captured local; the terminal arm loads it from the slot and
        // stores into the terminal field.
        let ir = ir_for_with_state_struct_layouts(
            "effect resource Network;
             pub fn fetch() with sends(Network) receives(Network) {}
             fn driver(n: i64) -> i64 with sends(Network) receives(Network) { fetch(); n }",
        );
        let body = extract_fn_ir(&ir, "__kara_poll_driver");
        assert!(
            body.contains("%n.return = load i64, ptr %n.slot"),
            "terminal arm must load captured local n via .return:\n{body}"
        );
        assert!(
            body.contains("store i64 %n.return, ptr %kara.return.field_ptr"),
            "terminal arm must store slot-loaded n into terminal field:\n{body}"
        );
    }

    #[test]
    fn test_terminal_return_8o_uses_arm_local_let_final_expr() {
        // `fn driver() -> i64 ... { fetch(); let r = 99; r }` — slice
        // 8m emits the let into the terminal arm's slot_map; slice 8o
        // loads from that slot for the final-expression return.
        let ir = ir_for_with_state_struct_layouts(
            "effect resource Network;
             pub fn fetch() with sends(Network) receives(Network) {}
             fn driver() -> i64 with sends(Network) receives(Network) {
                 fetch();
                 let r = 99;
                 r
             }",
        );
        let body = extract_fn_ir(&ir, "__kara_poll_driver");
        assert!(
            body.contains("store i64 99, ptr %r.slot"),
            "let r = 99 must store into r.slot in terminal arm:\n{body}"
        );
        assert!(
            body.contains("%r.return = load i64, ptr %r.slot"),
            "terminal arm must load r.slot via .return:\n{body}"
        );
        assert!(
            body.contains("store i64 %r.return, ptr %kara.return.field_ptr"),
            "terminal arm must store r's loaded value into terminal field:\n{body}"
        );
    }

    // ── Phase 6 line 26 slice 8ah: terminal-arm call-returning-value ──
    //
    // Slice 8o + 8q recognised int literals, captured-local references,
    // arm-local lets, and lowered binary arithmetic in the user
    // function's final-expression position. Slice 8ah widens
    // recognition to bare-identifier `Call` shapes (free-fn calls that
    // return a value), closing the third final-expression class called
    // out in slice 8i's note. Network-yield callees are filtered at
    // recognition time so a yielding call in tail position still falls
    // through to the placeholder rather than emitting a synchronous
    // call that would skip its yield.

    #[test]
    fn test_terminal_return_8ah_uses_call_no_args() {
        // `fn driver() -> i64 ... { fetch(); other_fn() }` where
        // `other_fn` is a pure i64-returning callee — slice 8ah
        // emits `call i64 @other_fn()` in the terminal arm and stores
        // the result into the terminal return field.
        let ir = ir_for_with_state_struct_layouts(
            "effect resource Network;
             pub fn fetch() with sends(Network) receives(Network) {}
             fn other_fn() -> i64 { 99 }
             fn driver() -> i64 with sends(Network) receives(Network) { fetch(); other_fn() }",
        );
        let body = extract_fn_ir(&ir, "__kara_poll_driver");
        assert!(
            body.contains("%other_fn.return = call i64 @other_fn()"),
            "terminal arm must emit named call to @other_fn:\n{body}"
        );
        assert!(
            body.contains("store i64 %other_fn.return, ptr %kara.return.field_ptr"),
            "terminal arm must store call result into terminal field:\n{body}"
        );
    }

    #[test]
    fn test_terminal_return_8ah_uses_call_with_captured_arg() {
        // `fn driver(n: i64) -> i64 ... { fetch(); ident(n) }` — `n`
        // is a captured local; slice 8ah materialises it via the
        // per-arm slot map and threads the loaded value as the
        // synchronous call's arg.
        let ir = ir_for_with_state_struct_layouts(
            "effect resource Network;
             pub fn fetch() with sends(Network) receives(Network) {}
             fn ident(x: i64) -> i64 { x }
             fn driver(n: i64) -> i64 with sends(Network) receives(Network) { fetch(); ident(n) }",
        );
        let body = extract_fn_ir(&ir, "__kara_poll_driver");
        assert!(
            body.contains("%n.return = load i64, ptr %n.slot"),
            "terminal arm must load n.slot via .return:\n{body}"
        );
        assert!(
            body.contains("%ident.return = call i64 @ident(i64 %n.return)"),
            "terminal arm must emit call passing the slot-loaded n:\n{body}"
        );
        assert!(
            body.contains("store i64 %ident.return, ptr %kara.return.field_ptr"),
            "terminal arm must store call result into terminal field:\n{body}"
        );
    }

    #[test]
    fn test_terminal_return_8ah_yielding_callee_keeps_zero_fallback() {
        // `fn driver() -> i64 ... { let _x = 1; remote_fetch() }` —
        // the tail call is itself a network-yield callee returning
        // i64. Slice 8ah's recognition filter rejects yielding
        // callees so the terminal field keeps the slice-8i `i64 0`
        // placeholder rather than emitting a synchronous
        // `call i64 @remote_fetch` that would skip the yield. The
        // leading let ensures the body isn't trivially yield-only.
        let ir = ir_for_with_state_struct_layouts(
            "effect resource Network;
             pub fn remote_fetch() -> i64 with sends(Network) receives(Network) { 7 }
             fn driver() -> i64 with sends(Network) receives(Network) {
                 let _x = 1;
                 remote_fetch()
             }",
        );
        let body = extract_fn_ir(&ir, "__kara_poll_driver");
        assert!(
            !body.contains("call i64 @remote_fetch"),
            "yielding callee must NOT be lowered as a synchronous call \
             in the terminal arm:\n{body}"
        );
        assert!(
            body.contains("store i64 0, ptr %kara.return.field_ptr"),
            "yielding tail callee must fall back to i64 0 placeholder:\n{body}"
        );
    }

    // ── Phase 6 line 26 slice 8n: cross-yield captured-local writeback ────
    //
    // Before each non-terminal arm's tag-store + Pending return, the
    // poll-fn now writes each captured-local's current slot value back
    // into its state-struct field. This makes slice 8m's arm-local lets
    // (which can shadow captured-local slot pointers) actually survive
    // across yields — the next arm's reload prologue reads the post-arm-
    // body value.

    #[test]
    fn test_body_splitting_8n_writes_back_captured_local_before_yield() {
        // `fn driver(n: i64) with sends(Network) { fetch(); }` — `n` is
        // a captured local, no user mutation; the writeback is a value-
        // equivalent no-op but still appears in IR as a load+GEP+store
        // before the tag-store + Pending return.
        let ir = ir_for_with_state_struct_layouts(
            "effect resource Network;
             pub fn fetch() with sends(Network) receives(Network) {}
             fn driver(n: i64) with sends(Network) receives(Network) {
                 fetch();
             }",
        );
        let body = extract_fn_ir(&ir, "__kara_poll_driver");
        assert!(
            body.contains("%n.writeback = load i64, ptr %n.slot"),
            "state_0 must load n.slot for writeback:\n{body}"
        );
        assert!(
            body.contains("%n.writeback_field_ptr = getelementptr inbounds %kara.state.driver, ptr %0, i32 0, i32 1"),
            "writeback must GEP into state-struct field 1 for n:\n{body}"
        );
        // Writeback must precede the tag-store + Pending return.
        let writeback_store_pos = body
            .find("store i64 %n.writeback, ptr %n.writeback_field_ptr")
            .expect("writeback store missing");
        let tag_store_pos = body
            .find("store i32 1, ptr %state_0.next_tag_ptr")
            .expect("tag-store missing");
        assert!(
            writeback_store_pos < tag_store_pos,
            "writeback must precede tag-store:\n{body}"
        );
    }

    #[test]
    fn test_body_splitting_8n_writeback_skipped_in_terminal_arm() {
        // The terminal arm doesn't yield — it returns Ready and the
        // caller's `@free` releases the state struct. No writeback
        // needed (or wanted; the field is about to be freed).
        let ir = ir_for_with_state_struct_layouts(
            "effect resource Network;
             pub fn fetch() with sends(Network) receives(Network) {}
             fn driver(n: i64) with sends(Network) receives(Network) {
                 fetch();
             }",
        );
        let body = extract_fn_ir(&ir, "__kara_poll_driver");
        // Single yield → one non-terminal arm (state_0) + one terminal
        // arm (state_1). Writeback shows up exactly once.
        assert_eq!(
            body.matches("%n.writeback = load i64").count(),
            1,
            "writeback must appear in non-terminal arm only:\n{body}"
        );
    }

    #[test]
    fn test_body_splitting_8n_writeback_includes_let_shadowed_local() {
        // `fn driver(n: i64) with sends(Network) { let n = 99; fetch(); }`
        // — slice 8m's let shadows the captured-local `n` slot in the
        // slot map. The writeback before the yield uses the slice-8m
        // alloca's stored value (99), not the slice-8a reload's value
        // (the original n).
        let ir = ir_for_with_state_struct_layouts(
            "effect resource Network;
             pub fn fetch() with sends(Network) receives(Network) {}
             fn driver(n: i64) with sends(Network) receives(Network) {
                 let n = 99;
                 fetch();
             }",
        );
        let body = extract_fn_ir(&ir, "__kara_poll_driver");
        // The let-store (slice 8m) puts `99` into n.slot.
        assert!(
            body.contains("store i64 99, ptr %n.slot"),
            "let n = 99 must store 99 into n.slot:\n{body}"
        );
        // The writeback then loads n.slot (which now has 99) and
        // stores into the state-struct field.
        assert!(
            body.contains("%n.writeback = load i64, ptr %n.slot"),
            "writeback must load from the (now-shadowed) n.slot:\n{body}"
        );
    }

    #[test]
    fn test_body_splitting_8n_multi_yield_writeback_in_each_arm() {
        // Two yields → two non-terminal arms (state_0, state_1) each
        // emit writeback for the captured local; terminal arm (state_2)
        // does not. Total writeback occurrences: 2 (LLVM auto-suffixes
        // the duplicate SSA names so we match the named-GEP suffix
        // which appears once per writeback).
        let ir = ir_for_with_state_struct_layouts(
            "effect resource Network;
             pub fn fetch() with sends(Network) receives(Network) {}
             fn driver(n: i64) with sends(Network) receives(Network) {
                 fetch();
                 fetch();
             }",
        );
        let body = extract_fn_ir(&ir, "__kara_poll_driver");
        // The GEP-defining line ` = getelementptr` for the
        // `writeback_field_ptr` name appears once per writeback site
        // (the store using the name is a separate match site we don't
        // count). LLVM may auto-suffix the SSA name across sites.
        assert_eq!(
            body.matches("writeback_field_ptr").count() / 2,
            2,
            "two non-terminal arms must each emit one writeback site:\n{body}"
        );
    }

    // ── Phase 6 line 26 slice 8l: args-bearing method-call body-splitting ─
    //
    // Mirrors slice 8k's free-fn arg compilation for `MethodCall` shapes:
    // method args go through the same `BodyArg` recognition (literal int
    // or captured-local identifier) and the same per-arm slot map. The
    // receiver claims call position 0; args follow at 1..=N.

    #[test]
    fn test_body_splitting_8l_emits_method_with_int_literal_arg() {
        // `fn driver() { let h = Hub { count: 0 }; h.take(42); fetch(); }`
        // — `h.take(42)` lowers to `call void @Hub.take(ptr %h.slot, i64 42)`.
        let ir = ir_for_with_state_struct_layouts(
            "effect resource Network;
             pub fn fetch() with sends(Network) receives(Network) {}
             struct Hub { count: i64 }
             impl Hub { fn take(ref self, n: i64) {} }
             fn driver() with sends(Network) receives(Network) {
                 let h = Hub { count: 0 };
                 h.take(42);
                 fetch();
             }",
        );
        let body = extract_fn_ir(&ir, "__kara_poll_driver");
        assert!(
            body.contains("call void @Hub.take(ptr %h.slot, i64 42)"),
            "h.take(42) must pass receiver + literal arg in order:\n{body}"
        );
    }

    #[test]
    fn test_body_splitting_8l_emits_method_with_identifier_arg_from_slot() {
        // `fn driver(n: i64) { let h = Hub { count: 0 }; h.take(n); fetch(); }`
        // — `n` is a captured layout field, loaded from `%n.slot` and
        // passed as the second arg to the method.
        let ir = ir_for_with_state_struct_layouts(
            "effect resource Network;
             pub fn fetch() with sends(Network) receives(Network) {}
             struct Hub { count: i64 }
             impl Hub { fn take(ref self, x: i64) {} }
             fn driver(n: i64) with sends(Network) receives(Network) {
                 let h = Hub { count: 0 };
                 h.take(n);
                 fetch();
             }",
        );
        let body = extract_fn_ir(&ir, "__kara_poll_driver");
        // Load of n from its slot; call passes the loaded value.
        assert!(
            body.contains("load i64, ptr %n.slot"),
            "method-call arg must load i64 from slice-8a slot:\n{body}"
        );
        assert!(
            body.contains("call void @Hub.take(ptr %h.slot, i64 %n.marg)"),
            "h.take(n) must pass receiver + slot-loaded arg:\n{body}"
        );
    }

    #[test]
    fn test_body_splitting_8l_emits_method_with_multi_arg_mix() {
        // `fn driver(n: i64) { let h = Hub { count: 0 }; h.mix(n, 7); fetch(); }`
        // — receiver + slot-loaded + literal in source order.
        let ir = ir_for_with_state_struct_layouts(
            "effect resource Network;
             pub fn fetch() with sends(Network) receives(Network) {}
             struct Hub { count: i64 }
             impl Hub { fn mix(ref self, a: i64, b: i64) {} }
             fn driver(n: i64) with sends(Network) receives(Network) {
                 let h = Hub { count: 0 };
                 h.mix(n, 7);
                 fetch();
             }",
        );
        let body = extract_fn_ir(&ir, "__kara_poll_driver");
        assert!(
            body.contains("call void @Hub.mix(ptr %h.slot, i64 %n.marg, i64 7)"),
            "h.mix(n, 7) must order receiver + slot + literal:\n{body}"
        );
    }

    #[test]
    fn test_body_splitting_8l_skips_method_with_unrecognised_arg() {
        // `fn driver(n: i64) { let h = ...; h.take(if n > 0 { n } else { 0 }); fetch(); }`
        // — the `if`-expression arg shape stays outside the
        // recognised `BodyArg` set (slice 8q widened to lowered
        // integer arithmetic; slice 8ah widened to bare-identifier
        // free-fn calls; if/match/block expressions remain
        // unrecognised). So the whole method call is silently
        // skipped at body-splitting time. No `call void @Hub.take`
        // appears in the poll-fn body.
        let ir = ir_for_with_state_struct_layouts(
            "effect resource Network;
             pub fn fetch() with sends(Network) receives(Network) {}
             struct Hub { count: i64 }
             impl Hub { fn take(ref self, x: i64) {} }
             fn driver(n: i64) with sends(Network) receives(Network) {
                 let h = Hub { count: 0 };
                 h.take(if n > 0 { n } else { 0 });
                 fetch();
             }",
        );
        let body = extract_fn_ir(&ir, "__kara_poll_driver");
        assert!(
            !body.contains("call void @Hub.take"),
            "unrecognised method-call arg must skip the whole call:\n{body}"
        );
    }

    #[test]
    fn test_body_splitting_8k_emits_int_literal_arg_call() {
        // `fn driver() { take(42); fetch(); }` — `take(42)` runs in
        // state_0; the literal `42` is materialised as an `i64` const
        // and passed to `@take` ahead of the tag-store.
        let ir = ir_for_with_state_struct_layouts(
            "effect resource Network;
             pub fn fetch() with sends(Network) receives(Network) {}
             fn take(n: i64) {}
             fn driver() with sends(Network) receives(Network) {
                 take(42);
                 fetch();
             }",
        );
        let body = extract_fn_ir(&ir, "__kara_poll_driver");
        assert!(
            body.contains("call void @take(i64 42)"),
            "take(42) literal arg must lower to `call void @take(i64 42)`:\n{body}"
        );
        let call_pos = body.find("call void @take(i64 42)").unwrap();
        let tag_store_pos = body
            .find("store i32 1, ptr %state_0.next_tag_ptr")
            .expect("state_0 must store next tag = 1");
        assert!(
            call_pos < tag_store_pos,
            "take(42) call must precede the tag-store in state_0:\n{body}"
        );
    }

    #[test]
    fn test_body_splitting_8k_emits_identifier_arg_loaded_from_slot() {
        // `fn driver(n: i64) { take(n); fetch(); }` — `n` is a captured
        // layout field, reloaded into `%n.slot` by slice 8a, and the
        // call's arg loads from the slot before passing to `@take`.
        let ir = ir_for_with_state_struct_layouts(
            "effect resource Network;
             pub fn fetch() with sends(Network) receives(Network) {}
             fn take(x: i64) {}
             fn driver(n: i64) with sends(Network) receives(Network) {
                 take(n);
                 fetch();
             }",
        );
        let body = extract_fn_ir(&ir, "__kara_poll_driver");
        // The load from %n.slot into %n.arg, then the call passing %n.arg.
        assert!(
            body.contains("load i64, ptr %n.slot"),
            "identifier arg must load i64 from slice-8a slot:\n{body}"
        );
        assert!(
            body.contains("call void @take(i64 %n.arg)"),
            "take(n) must pass the loaded slot value as arg:\n{body}"
        );
    }

    #[test]
    fn test_body_splitting_8k_emits_multi_arg_mix_of_literal_and_identifier() {
        // `fn driver(n: i64) { mix(n, 7); fetch(); }` — first arg is a
        // slot-loaded value, second arg is a literal const, both passed
        // to `@mix` in source order.
        let ir = ir_for_with_state_struct_layouts(
            "effect resource Network;
             pub fn fetch() with sends(Network) receives(Network) {}
             fn mix(a: i64, b: i64) {}
             fn driver(n: i64) with sends(Network) receives(Network) {
                 mix(n, 7);
                 fetch();
             }",
        );
        let body = extract_fn_ir(&ir, "__kara_poll_driver");
        assert!(
            body.contains("call void @mix(i64 %n.arg, i64 7)"),
            "mix(n, 7) must pass slot-load + literal in order:\n{body}"
        );
    }

    #[test]
    fn test_body_splitting_8k_skips_unrecognised_arg_shape() {
        // `fn driver(n: i64) { take(if n > 0 { n } else { 0 }); fetch(); }`
        // — the `if`-expression arg shape stays outside the
        // recognised `BodyArg` set (slice 8q widened to lowered
        // integer arithmetic; slice 8ah widened to bare-identifier
        // free-fn calls; if/match/block expressions remain
        // unrecognised). So the whole `take` call is silently
        // skipped — the poll-fn body emits no `call void @take`
        // between the reload prologue and the tag-store.
        let ir = ir_for_with_state_struct_layouts(
            "effect resource Network;
             pub fn fetch() with sends(Network) receives(Network) {}
             fn take(x: i64) {}
             fn driver(n: i64) with sends(Network) receives(Network) {
                 take(if n > 0 { n } else { 0 });
                 fetch();
             }",
        );
        let body = extract_fn_ir(&ir, "__kara_poll_driver");
        assert!(
            !body.contains("call void @take"),
            "unrecognised arg shape must skip the whole call:\n{body}"
        );
    }

    #[test]
    fn test_body_splitting_8j_method_call_passes_reloaded_slot_pointer() {
        // Pins that the receiver argument routes through the slice-8a
        // `%h.slot` alloca — slot pointer passed directly to `ref self`.
        // The regression pin: receiver mechanic actually wires through
        // to the method call, not just emits a call with garbage.
        let ir = ir_for_with_state_struct_layouts(
            "effect resource Network;
             pub fn fetch() with sends(Network) receives(Network) {}
             struct Hub { count: i64 }
             impl Hub { fn helper(ref self) {} }
             fn driver() with sends(Network) receives(Network) {
                 let h = Hub { count: 0 };
                 h.helper();
                 fetch();
             }",
        );
        let body = extract_fn_ir(&ir, "__kara_poll_driver");
        assert!(
            body.contains("call void @Hub.helper(ptr %h.slot)"),
            "h.helper(ref self) must receive the slice-8a h.slot pointer:\n{body}"
        );
    }

    // ── Phase 6 line 26 slice 8u: state-struct destructor helper ──────────
    //
    // For each network-boundary function whose state-struct holds at
    // least one heap-bearing captured-local field, codegen emits an
    // `define internal void @__kara_state_drop_<fn_key>(ptr %state)`
    // helper that walks the captured-local fields and frees any
    // heap-bearing ones (`cap > 0 ? free(data)` for Vec/String/VecDeque,
    // `rc_dec` against the slot's loaded handle for shared struct
    // fields). The destructor is the unified unwind primitive the
    // future `?`-Err-propagation and cooperative-cancel use sites
    // both invoke; slice 8u lands the primitive only.
    //
    // The state struct's own heap allocation is the *caller's*
    // responsibility to `free` after invoking the destructor — matches
    // the constructor's caller-allocates / caller-frees discipline.
    // Skipped entirely when no captured-local field is heap-bearing
    // (an empty destructor would be dead IR).

    #[test]
    fn test_state_destructor_emitted_for_state_struct_with_vec_captured_local() {
        // A `Vec[i64]` captured local triggers destructor emission —
        // the field's `cap > 0 ? free(data)` pattern is the v1
        // heap-bearing arm.
        let ir = ir_for_with_state_struct_layouts(
            "effect resource Network;
             pub fn fetch() with sends(Network) receives(Network) {}
             fn driver(items: Vec[i64]) { fetch(); }",
        );
        let define_line = ir
            .lines()
            .find(|l| l.contains("@__kara_state_drop_driver"))
            .unwrap_or_else(|| panic!("expected @__kara_state_drop_driver in IR:\n{ir}"));
        assert!(
            define_line.contains("define"),
            "destructor should be defined: {define_line}"
        );
        assert!(
            define_line.contains("internal"),
            "destructor should have internal linkage: {define_line}"
        );
        assert!(
            define_line.contains("void @__kara_state_drop_driver(ptr"),
            "destructor signature must be `void @__kara_state_drop_driver(ptr ...)`: {define_line}"
        );
    }

    #[test]
    fn test_state_destructor_emits_cap_gt_zero_free_for_vec_field() {
        // The Vec captured-local field's destructor body emits the
        // `cap > 0 ? free(data)` pattern: GEP into the state-struct
        // field (offset 1, after tag), GEP cap (Vec struct field 2),
        // load i64, icmp ugt 0, conditional branch to a free BB that
        // loads the data ptr and calls free.
        let ir = ir_for_with_state_struct_layouts(
            "effect resource Network;
             pub fn fetch() with sends(Network) receives(Network) {}
             fn driver(items: Vec[i64]) { fetch(); }",
        );
        let body = extract_fn_ir(&ir, "__kara_state_drop_driver");
        // GEP captured-local field at struct-field idx 1 (tag at 0).
        assert!(
            body.contains("%items.drop.field_ptr"),
            "destructor must GEP the captured-local field as %items.drop.field_ptr:\n{body}"
        );
        // Load Vec cap and compare against 0.
        assert!(
            body.contains("%items.drop.cap = load i64"),
            "destructor must load Vec cap as i64:\n{body}"
        );
        assert!(
            body.contains("%items.drop.is_heap = icmp ugt i64 %items.drop.cap, 0"),
            "destructor must compare cap > 0:\n{body}"
        );
        // The free branch loads data and calls free.
        assert!(
            body.contains("%items.drop.data = load ptr"),
            "destructor's free branch must load the data ptr:\n{body}"
        );
        assert!(
            body.contains("call void @free(ptr %items.drop.data)"),
            "destructor's free branch must call free on the data ptr:\n{body}"
        );
    }

    #[test]
    fn test_state_destructor_emits_rc_dec_for_shared_struct_field() {
        // A shared-struct captured local (`h: Hub` where `Hub` is a
        // `shared struct`) lowers to a pointer-sized handle in the
        // state struct. The destructor must load the handle,
        // null-guard, and dispatch through the rc_dec machinery.
        let ir = ir_for_with_state_struct_layouts(
            "effect resource Network;
             pub fn fetch() with sends(Network) receives(Network) {}
             shared struct Hub { count: i64 }
             fn driver(h: Hub) { fetch(); }",
        );
        let body = extract_fn_ir(&ir, "__kara_state_drop_driver");
        // Load handle.
        assert!(
            body.contains("%h.drop.handle = load ptr"),
            "destructor must load shared-struct handle:\n{body}"
        );
        // Null-guard: the slice-8a uninitialized-reload concern means
        // we must compare the handle against null before dec'ing.
        assert!(
            body.contains("%h.drop.is_null = icmp eq ptr %h.drop.handle, null"),
            "destructor must null-guard the shared-struct handle before rc_dec:\n{body}"
        );
        // The rc_dec branch GEPs the refcount field (Hub heap struct
        // field 0) and decrements — the canonical `emit_rc_dec` IR shape.
        assert!(
            body.contains("%rc_ptr"),
            "destructor must reach rc_dec's refcount GEP via %rc_ptr:\n{body}"
        );
        assert!(
            body.contains("%rc_dec = sub i64 %rc, 1"),
            "destructor must emit the rc -= 1 step:\n{body}"
        );
    }

    #[test]
    fn test_state_destructor_not_emitted_when_all_fields_primitive() {
        // A primitive-only captured-local set (`i64`-typed param) has
        // no heap-bearing field. Slice 8u skips destructor emission
        // entirely — the destructor would have an `entry: ret void`
        // body that's effectively dead code, and the absence is the
        // fast "no cleanup to do" signal for the future use sites.
        let ir = ir_for_with_state_struct_layouts(
            "effect resource Network;
             pub fn fetch() with sends(Network) receives(Network) {}
             fn driver(n: i64) { fetch(); }",
        );
        assert!(
            !ir.contains("@__kara_state_drop_driver"),
            "primitive-only captures must not emit a destructor:\n{ir}"
        );
    }

    #[test]
    fn test_state_destructor_not_emitted_for_pure_function() {
        // Pure functions (no network-effect calls) have no state-struct
        // entry and therefore no destructor.
        let ir = ir_for_with_state_struct_layouts(
            "effect resource Network;
             pub fn fetch() with sends(Network) receives(Network) {}
             fn pure_helper(x: i64) -> i64 { x + 1 }",
        );
        assert!(
            !ir.contains("@__kara_state_drop_pure_helper"),
            "pure function must not emit a destructor:\n{ir}"
        );
    }

    #[test]
    fn test_state_destructor_walks_multiple_heap_fields_in_source_order() {
        // Two captured-local heap fields: `items: Vec[i64]` at source
        // pos 0, `name: String` at source pos 1. Both lower to the
        // same `{ptr, i64, i64}` inline layout but the destructor must
        // emit per-field drop IR keyed by the source binding names,
        // and the `items.*` block must precede the `name.*` block
        // (strict source order). This pins both the multi-field
        // walk and the source-order discipline that a future
        // reverse-construction-order Drop hook needs to verify
        // against.
        let ir = ir_for_with_state_struct_layouts(
            "effect resource Network;
             pub fn fetch() with sends(Network) receives(Network) {}
             fn driver(items: Vec[i64], name: String) { fetch(); }",
        );
        let body = extract_fn_ir(&ir, "__kara_state_drop_driver");
        let items_pos = body
            .find("%items.drop.field_ptr")
            .unwrap_or_else(|| panic!("missing %items.drop.field_ptr in destructor:\n{body}"));
        let name_pos = body
            .find("%name.drop.field_ptr")
            .unwrap_or_else(|| panic!("missing %name.drop.field_ptr in destructor:\n{body}"));
        assert!(
            items_pos < name_pos,
            "items drop must precede name drop (source order):\n{body}"
        );
        // Each field gets its own `cap > 0 ? free` pair.
        assert!(
            body.contains("%items.drop.is_heap = icmp ugt i64 %items.drop.cap, 0"),
            "items field needs its cap > 0 compare:\n{body}"
        );
        assert!(
            body.contains("%name.drop.is_heap = icmp ugt i64 %name.drop.cap, 0"),
            "name field needs its cap > 0 compare:\n{body}"
        );
    }

    #[test]
    fn test_state_destructor_returns_void() {
        // Destructor's terminator is `ret void` — caller pairs the call
        // with the state-struct's own `free`, so the destructor itself
        // doesn't free the state pointer (matches the constructor's
        // caller-allocates / caller-frees discipline).
        let ir = ir_for_with_state_struct_layouts(
            "effect resource Network;
             pub fn fetch() with sends(Network) receives(Network) {}
             fn driver(items: Vec[i64]) { fetch(); }",
        );
        let body = extract_fn_ir(&ir, "__kara_state_drop_driver");
        assert!(
            body.contains("ret void"),
            "destructor must end with ret void:\n{body}"
        );
        // Sanity: the destructor must NOT free the state ptr itself —
        // that's the caller's job. A `call void @free(ptr %state)` shape
        // would indicate the destructor doubled-up the free.
        assert!(
            !body.contains("call void @free(ptr %state)"),
            "destructor must not free the state ptr (caller does):\n{body}"
        );
    }

    // ── Phase 6 line 26 slice 8v Phase 1: skip generics from base-name emission ──
    //
    // Polymorphic yielding functions (`fn driver[T](item: T) { fetch(); }`)
    // get an entry in `state_struct_layouts` under their base name with
    // a captured-local field whose `type_name` references the
    // unsubstituted type parameter (`Some("T")`). Slices 5 / 6 / 8c / 8u
    // run before any per-mono `type_subst` is active, so
    // `llvm_type_for_name("T")` would fall through to the i64 default —
    // producing dead-and-broken state-struct LLVM types / poll-fns /
    // constructors / destructors that the caller-side intercept can't
    // reach (the `compile_call` dispatch short-circuits through
    // `compile_generic_call` for generics, bypassing the slice-8d
    // intercept). Slice 8v Phase 1 detects generic entries via
    // `is_generic_fn_key` and skips them entirely from all four
    // base-name passes — removing the dead IR without affecting any
    // non-generic state-machine emission. Per-mono emission + caller-
    // side intercept routing land in slice 8v Phase 2.

    #[test]
    fn test_state_machine_skips_polymorphic_state_struct_type() {
        // Polymorphic yielding fn produces no `%kara.state.<base>`
        // LLVM struct type — slice 5's iteration over
        // `state_struct_layouts` now filters via `is_generic_fn_key`.
        // Per-mono emission DOES land under the mangled key (e.g.
        // `%"kara.state.driver$i64"`) once slice 8v Phase 2's
        // `compile_generic_call` orchestrator runs; the assertion
        // matches the full base-name shape `%kara.state.driver = type`
        // exactly, so per-mono variants (`%"kara.state.driver$..."`)
        // don't trip the filter.
        let ir = ir_for_with_state_struct_layouts(
            "effect resource Network;
             pub fn fetch() with sends(Network) receives(Network) {}
             fn driver[T](item: T) { fetch(); }
             fn caller() { driver(42i64); }",
        );
        assert!(
            !ir.contains("%kara.state.driver = type"),
            "polymorphic driver must not emit a base-name state struct type:\n{ir}"
        );
        // Anchor global mirrors the state-struct type — base-name
        // must not appear. Per-mono anchors (e.g.
        // `@"__kara_state_type_anchor_driver$i64"`) are expected and
        // get a separate test in the Phase 2 section below.
        assert!(
            !ir.contains("@__kara_state_type_anchor_driver = "),
            "polymorphic driver must not emit a base-name state-struct anchor global:\n{ir}"
        );
    }

    #[test]
    fn test_state_machine_skips_polymorphic_poll_fn() {
        // Polymorphic yielding fn produces no `__kara_poll_<base>`
        // poll-fn — slice 6's iteration now filters generics.
        // Per-mono emission lands `@"__kara_poll_driver$i64"` (with
        // `$` triggering LLVM's quoted-symbol convention); the
        // assertion shape `@__kara_poll_driver(` matches the base
        // name's call-site shape exactly and doesn't trip on the
        // mangled variant.
        let ir = ir_for_with_state_struct_layouts(
            "effect resource Network;
             pub fn fetch() with sends(Network) receives(Network) {}
             fn driver[T](item: T) { fetch(); }
             fn caller() { driver(42i64); }",
        );
        assert!(
            !ir.contains("@__kara_poll_driver("),
            "polymorphic driver must not emit a base-name poll-fn:\n{ir}"
        );
    }

    #[test]
    fn test_state_machine_skips_polymorphic_state_constructor() {
        // Polymorphic yielding fn produces no `__kara_state_new_<base>`
        // constructor — slice 8c's iteration now filters generics.
        // Per-mono `@"__kara_state_new_driver$i64"()` is expected and
        // tested separately in Phase 2's section.
        let ir = ir_for_with_state_struct_layouts(
            "effect resource Network;
             pub fn fetch() with sends(Network) receives(Network) {}
             fn driver[T](item: T) { fetch(); }
             fn caller() { driver(42i64); }",
        );
        assert!(
            !ir.contains("@__kara_state_new_driver("),
            "polymorphic driver must not emit a base-name state constructor:\n{ir}"
        );
    }

    #[test]
    fn test_state_machine_skips_polymorphic_state_destructor() {
        // Polymorphic yielding fn whose captured-local would be
        // heap-bearing on every monomorphization (here `items: Vec[T]`,
        // type_name `Some("Vec")` — classifies as `FieldDrop::VecOrString`)
        // still emits no base-name destructor — slice 8v Phase 1 skips
        // the polymorphic key before the classification runs. Per-mono
        // destructor emission lands the right shape at the mangled key
        // in slice 8v Phase 2. Function need only be declared; the
        // Phase 1 skip fires during the base-name iteration over
        // `state_struct_layouts`, independent of any call sites.
        let ir = ir_for_with_state_struct_layouts(
            "effect resource Network;
             pub fn fetch() with sends(Network) receives(Network) {}
             fn driver[T](items: Vec[T]) { fetch(); }",
        );
        assert!(
            !ir.contains("@__kara_state_drop_driver("),
            "polymorphic driver must not emit a base-name state destructor:\n{ir}"
        );
    }

    #[test]
    fn test_state_machine_still_emits_for_non_generic_concrete_function() {
        // Sanity guard: slice 8v Phase 1's filter must NOT affect
        // non-generic yielding fns — `caller()` here has no generic
        // params and is itself transitively network-boundary
        // (through `driver(42)`'s call to `fetch()`), so all four
        // helpers must still emit under its base name.
        let ir = ir_for_with_state_struct_layouts(
            "effect resource Network;
             pub fn fetch() with sends(Network) receives(Network) {}
             fn driver[T](item: T) { fetch(); }
             fn caller() { driver(42i64); }",
        );
        assert!(
            ir.contains("%kara.state.caller = type"),
            "non-generic caller must still emit its state struct type:\n{ir}"
        );
        assert!(
            ir.contains("@__kara_poll_caller"),
            "non-generic caller must still emit its poll-fn:\n{ir}"
        );
        assert!(
            ir.contains("@__kara_state_new_caller"),
            "non-generic caller must still emit its state constructor:\n{ir}"
        );
    }

    #[test]
    fn test_state_machine_skips_polymorphic_impl_method() {
        // Polymorphic methods on a non-generic impl block also skip
        // base-name emission — `is_generic_fn_key` resolves
        // `"Hub.run"` to the impl method's AST and checks
        // `generic_params.is_some()`.
        let ir = ir_for_with_state_struct_layouts(
            "effect resource Network;
             pub fn fetch() with sends(Network) receives(Network) {}
             shared struct Hub { count: i64 }
             impl Hub {
                 fn run[T](self, item: T) { fetch(); }
             }",
        );
        assert!(
            !ir.contains("%kara.state.Hub.run = type"),
            "polymorphic Hub.run must not emit a base-name state struct type:\n{ir}"
        );
        assert!(
            !ir.contains("@__kara_poll_Hub.run("),
            "polymorphic Hub.run must not emit a base-name poll-fn:\n{ir}"
        );
    }

    // ── Phase 6 line 26 slice 8v Phase 2: per-mono state-machine emission + caller intercept ──
    //
    // For each monomorphization of a polymorphic network-yielding fn
    // (e.g. `fn driver[T](item: T) { fetch(); }` called with `T = i64`,
    // `T = Vec[i64]`, ...), codegen emits the four state-machine
    // helpers — state-struct LLVM type, poll-fn, constructor,
    // destructor — under the mangled key (`driver$i64`, etc.),
    // with `type_subst` active so `T`-typed captured locals resolve
    // to the per-mono concrete LLVM type. The caller-side intercept
    // in `compile_generic_call` routes the call through
    // `__kara_state_new_<mangled>` + poll loop + `free` instead of
    // a direct `call @<mangled>(args)`, mirroring the slice 8d
    // caller intercept for non-generic yielding fns.

    #[test]
    fn test_per_mono_state_struct_type_emitted_with_concrete_field_type() {
        // `driver[T](item: T)` instantiated with `T = i64` emits
        // `%"kara.state.driver$i64" = type { i32, i64 }` — the
        // `T`-typed `item` field resolves to `i64` via the active
        // `type_subst` at per-mono emission time, matching the
        // slot type that `compile_mono_function` allocated for the
        // parameter binding.
        let ir = ir_for_with_state_struct_layouts(
            "effect resource Network;
             pub fn fetch() with sends(Network) receives(Network) {}
             fn driver[T](item: T) { fetch(); }
             fn caller() { driver(42i64); }",
        );
        // LLVM quotes named types containing `$`; the IR contains
        // `%"kara.state.driver$i64" = type { i32, i64 }`.
        let line = ir
            .lines()
            .find(|l| l.contains("%\"kara.state.driver$i64\" = type"))
            .unwrap_or_else(|| {
                panic!("expected per-mono state struct %\"kara.state.driver$i64\":\n{ir}")
            });
        assert!(
            line.contains("{ i32, i64 }"),
            "per-mono state struct must have {{ i32, i64 }} layout (tag + i64 item): {line}"
        );
    }

    #[test]
    fn test_per_mono_poll_fn_constructor_destructor_emitted_at_mangled_key() {
        // All three callable helpers (poll-fn + constructor;
        // destructor only when heap-bearing — this mono has only
        // `i64`, no destructor) emit at the mangled key.
        let ir = ir_for_with_state_struct_layouts(
            "effect resource Network;
             pub fn fetch() with sends(Network) receives(Network) {}
             fn driver[T](item: T) { fetch(); }
             fn caller() { driver(42i64); }",
        );
        assert!(
            ir.contains("@\"__kara_poll_driver$i64\""),
            "per-mono poll-fn must emit at mangled key:\n{ir}"
        );
        assert!(
            ir.contains("@\"__kara_state_new_driver$i64\""),
            "per-mono constructor must emit at mangled key:\n{ir}"
        );
        // Destructor for i64-only captures: not emitted (skip-when-empty rule).
        assert!(
            !ir.contains("@\"__kara_state_drop_driver$i64\""),
            "per-mono destructor must skip for primitive-only captures:\n{ir}"
        );
    }

    #[test]
    fn test_per_mono_caller_intercept_routes_through_state_machine() {
        // When the polymorphic source is network-yielding, the
        // caller's body must invoke the per-mono helpers instead
        // of direct-calling the mono fn:
        //   - constructor call to allocate the state struct
        //   - poll-loop with `kara.poll_loop` BB
        //   - cooperative `sched_yield` on Pending
        //   - terminal `free` on done
        //   - NO direct `call void @"driver$i64"(args)` in caller body
        let ir = ir_for_with_state_struct_layouts(
            "effect resource Network;
             pub fn fetch() with sends(Network) receives(Network) {}
             fn driver[T](item: T) { fetch(); }
             fn caller() { driver(42i64); }",
        );
        let caller_body = extract_fn_ir(&ir, "caller");
        assert!(
            caller_body.contains("call ptr @\"__kara_state_new_driver$i64\"()"),
            "caller must invoke per-mono state constructor:\n{caller_body}"
        );
        assert!(
            caller_body.contains("kara.poll_loop:"),
            "caller must emit per-mono poll-loop block:\n{caller_body}"
        );
        assert!(
            caller_body.contains("call i8 @\"__kara_poll_driver$i64\"(ptr %kara.state, ptr null)"),
            "caller must invoke per-mono poll-fn with state ptr + null cancel:\n{caller_body}"
        );
        assert!(
            caller_body.contains("call void @free(ptr %kara.state)"),
            "caller must free the per-mono state struct after done block:\n{caller_body}"
        );
        // CRITICAL: caller must NOT direct-call the mono fn. Slice
        // 8v Phase 2's intercept replaces the direct call with the
        // state-machine invocation. A surviving direct call would
        // mean the intercept fired without replacing the trailing
        // emit, or the mono path's gating predicate missed.
        assert!(
            !caller_body.contains("call void @\"driver$i64\"("),
            "caller must NOT direct-call the mono fn (intercept replaces it):\n{caller_body}"
        );
    }

    #[test]
    fn test_per_mono_caller_intercept_stores_arg_into_state_struct_field() {
        // The caller-side intercept stores the call arg into the
        // state struct's captured-local field at position 1 (after
        // the tag at 0). Mirrors slice 8f's discipline keyed on the
        // mangled state-struct type.
        let ir = ir_for_with_state_struct_layouts(
            "effect resource Network;
             pub fn fetch() with sends(Network) receives(Network) {}
             fn driver[T](item: T) { fetch(); }
             fn caller() { driver(42i64); }",
        );
        let caller_body = extract_fn_ir(&ir, "caller");
        assert!(
            caller_body.contains("%kara.arg0.field_ptr"),
            "intercept must GEP state struct field for arg0:\n{caller_body}"
        );
        // Arg value 42 stored into the field. With opaque pointers,
        // the store shape is `store i64 42, ptr %kara.arg0.field_ptr`.
        assert!(
            caller_body.contains("store i64 42, ptr %kara.arg0.field_ptr"),
            "intercept must store arg value 42 into state struct field:\n{caller_body}"
        );
    }

    #[test]
    fn test_two_distinct_monos_each_get_their_own_state_machine_helpers() {
        // `driver[T]` instantiated twice with two different types
        // produces two distinct per-mono state-machine helper sets.
        // The polymorphic source has no `with` clause mentioning an
        // effect parameter, so all monos share the same concrete
        // effect set (trivially-monomorphic v1 scope — see slice 8v's
        // doc framing). Each mono gets its own state struct, poll-fn,
        // constructor under its mangled name. Uses two int widths
        // (`i64` and `i32`) so both monos produce stable layouts
        // through the unified `llvm_type_to_mangle_str` path without
        // depending on String / collection lowering through
        // `compile_generic_call`'s arg materialisation (which has
        // independent gaps tracked outside slice 8v).
        let ir = ir_for_with_state_struct_layouts(
            "effect resource Network;
             pub fn fetch() with sends(Network) receives(Network) {}
             fn driver[T](item: T) { fetch(); }
             fn caller() {
                 driver(42i64);
                 driver(7i32);
             }",
        );
        assert!(
            ir.contains("%\"kara.state.driver$i64\" = type"),
            "i64 mono state struct must be emitted:\n{ir}"
        );
        assert!(
            ir.contains("%\"kara.state.driver$i32\" = type"),
            "i32 mono state struct must be emitted:\n{ir}"
        );
        // Each layout uses the per-mono concrete field type.
        let i64_line = ir
            .lines()
            .find(|l| l.contains("%\"kara.state.driver$i64\" = type"))
            .unwrap();
        assert!(
            i64_line.contains("{ i32, i64 }"),
            "i64 mono state struct must be {{ i32, i64 }}: {i64_line}"
        );
        let i32_line = ir
            .lines()
            .find(|l| l.contains("%\"kara.state.driver$i32\" = type"))
            .unwrap();
        assert!(
            i32_line.contains("{ i32, i32 }"),
            "i32 mono state struct must be {{ i32, i32 }}: {i32_line}"
        );
        // Both poll-fns + constructors emit at their mangled keys.
        assert!(
            ir.contains("@\"__kara_poll_driver$i64\""),
            "i64 mono poll-fn must emit:\n{ir}"
        );
        assert!(
            ir.contains("@\"__kara_poll_driver$i32\""),
            "i32 mono poll-fn must emit:\n{ir}"
        );
        assert!(
            ir.contains("@\"__kara_state_new_driver$i64\""),
            "i64 mono constructor must emit:\n{ir}"
        );
        assert!(
            ir.contains("@\"__kara_state_new_driver$i32\""),
            "i32 mono constructor must emit:\n{ir}"
        );
    }

    #[test]
    fn test_non_yielding_generic_fn_keeps_direct_call() {
        // A polymorphic fn that's NOT network-yielding (no `fetch()`
        // or similar) gets no state-struct entry under its base
        // name, so the slice 8v Phase 2 orchestrator no-ops for its
        // monos. The caller-side intercept's gating predicate (
        // `state_machine_state_constructors.get(&mangled)`) misses,
        // so the call falls through to the direct-call path. This
        // is the common case for ordinary user generics.
        let ir = ir_for_with_state_struct_layouts(
            "effect resource Network;
             fn identity[T](x: T) -> T { x }
             fn caller() {
                 let v = identity(42i64);
             }",
        );
        // No per-mono state struct.
        assert!(
            !ir.contains("%\"kara.state.identity$i64\""),
            "non-yielding generic mono must not emit a state struct:\n{ir}"
        );
        // No per-mono poll-fn.
        assert!(
            !ir.contains("@\"__kara_poll_identity$i64\""),
            "non-yielding generic mono must not emit a poll-fn:\n{ir}"
        );
        // Caller body direct-calls the mono.
        let caller_body = extract_fn_ir(&ir, "caller");
        assert!(
            caller_body.contains("call i64 @\"identity$i64\""),
            "caller must direct-call the non-yielding mono:\n{caller_body}"
        );
    }

    // ── Phase 6 line 26 slice 8w: destructor classification via `type_subst` ──
    //
    // Slice 8v Phase 2 lands per-mono state-machine emission, but the
    // destructor classifier only inspects `field.type_name` directly.
    // For type-parameter-typed parameters (e.g. `fn driver[T](item: T)`)
    // the typechecker records `type_name: None`, so the destructor
    // fell back to `FieldDrop::Skip` for every mono — leaking heap-
    // bearing monos like `T = String` under runtime cancel/Err
    // unwinding. Slice 8w closes the Vec-shape gap: when
    // `field.type_name == None`, look up the parameter's declared
    // `TypeExpr` via `lookup_param_type_expr` (shared with the
    // state-struct shape path) and resolve through
    // `llvm_type_for_type_expr` against the active `type_subst`. If
    // the resolved LLVM type is the Vec struct shape (`{ ptr, i64,
    // i64 }`, used by `String` / `Vec[U]` / `VecDeque[U]`),
    // classify as `FieldDrop::VecOrString`. Shared-`T` stays as
    // `Skip` in 8w because `infer_type_args` loses the surface name
    // when it binds `T → ptr_type` — recovering the
    // `shared_types[N].heap_type` for `emit_refcount_dec` needs a
    // parallel name-tracking table, deferred as a follow-on slice.

    #[test]
    fn test_slice_8w_per_mono_destructor_emitted_for_string_type_arg() {
        // `fn driver[T](item: T)` instantiated with `T = String` —
        // the polymorphic field's `type_name` is `None`, but
        // `lookup_param_type_expr` recovers `TypeExpr::Path(["T"])`
        // and `llvm_type_for_type_expr` resolves it through
        // `type_subst[T]` (set by `infer_type_args` to the LLVM
        // type of the `String` arg — the vec_struct_type shape).
        // The 8w classification recognises this as
        // `FieldDrop::VecOrString` and emits the per-mono destructor
        // with the `cap > 0 ? free(data)` IR pattern.
        let ir = ir_for_with_state_struct_layouts(
            "effect resource Network;
             pub fn fetch() with sends(Network) receives(Network) {}
             fn driver[T](item: T) { fetch(); }
             fn caller() {
                 let s = String.new();
                 driver(s);
             }",
        );
        // The per-mono destructor's mangled key picks up
        // `llvm_type_to_mangle_str`'s `struct` shorthand for the
        // vec-struct-shaped String arg, PLUS the B-2026-07-11-35
        // element-aware collision-disambiguation suffix (`$T_ct_String`)
        // so String / Vec[i64] / Vec[String] monos are distinct symbols.
        let drop_fn_marker = "@\"__kara_state_drop_driver$struct$T_ct_String\"";
        assert!(
            ir.contains(drop_fn_marker),
            "per-mono destructor must emit for String-typed T captured local:\n{ir}"
        );
        // Verify the `cap > 0 ? free` shape inside the destructor
        // body. LLVM quotes the destructor name (`@"..."`) due to
        // the `$` mangling marker, so we grep the whole IR rather
        // than extract by exact name (extract_fn_ir's needle would
        // miss the quoted form).
        assert!(
            ir.contains("%item.drop.cap = load i64"),
            "destructor must load Vec cap for the T-typed item field:\n{ir}"
        );
        assert!(
            ir.contains("%item.drop.is_heap = icmp ugt i64 %item.drop.cap, 0"),
            "destructor must compare cap > 0:\n{ir}"
        );
        assert!(
            ir.contains("call void @free(ptr %item.drop.data)"),
            "destructor must call free on the captured String's data ptr:\n{ir}"
        );
    }

    #[test]
    fn test_slice_8w_per_mono_destructor_still_skipped_for_primitive_type_arg() {
        // Regression guard: the slice 8w None-fallback must NOT
        // emit a destructor when the resolved LLVM type is a plain
        // integer (or any non-Vec-struct shape). Primitive-only
        // monos (`T = i64`) still skip-when-empty.
        let ir = ir_for_with_state_struct_layouts(
            "effect resource Network;
             pub fn fetch() with sends(Network) receives(Network) {}
             fn driver[T](item: T) { fetch(); }
             fn caller() { driver(42i64); }",
        );
        assert!(
            !ir.contains("@\"__kara_state_drop_driver$i64\""),
            "per-mono destructor must skip for i64 T:\n{ir}"
        );
    }

    #[test]
    fn test_slice_8w_two_monos_only_heap_bearing_one_gets_destructor() {
        // `driver[T]` instantiated with both i64 (primitive — skip)
        // and String (Vec-struct shape — emit). The per-mono
        // destructors emit independently under each mangled key,
        // and the i64 mono's destructor stays absent (skip-when-
        // empty per slice 8u). Pins the asymmetric heap-bearingness
        // across monos at the classification level.
        let ir = ir_for_with_state_struct_layouts(
            "effect resource Network;
             pub fn fetch() with sends(Network) receives(Network) {}
             fn driver[T](item: T) { fetch(); }
             fn caller() {
                 driver(42i64);
                 let s = String.new();
                 driver(s);
             }",
        );
        assert!(
            !ir.contains("@\"__kara_state_drop_driver$i64\""),
            "i64 mono must not emit a destructor:\n{ir}"
        );
        assert!(
            ir.contains("@\"__kara_state_drop_driver$struct$T_ct_String\""),
            "String mono must emit a destructor:\n{ir}"
        );
    }

    #[test]
    fn test_slice_8w_non_generic_with_recorded_typename_unchanged() {
        // Regression guard for the slice 8w None-fallback: a
        // non-generic yielding fn whose captured local has a
        // recorded `type_name` (e.g. `items: Vec[i64]` records
        // `Some("Vec")`) still classifies via the existing direct
        // `Some(name)` arm — the None-fallback path doesn't fire
        // here. The destructor emits as it did pre-8w.
        let ir = ir_for_with_state_struct_layouts(
            "effect resource Network;
             pub fn fetch() with sends(Network) receives(Network) {}
             fn driver(items: Vec[i64]) { fetch(); }",
        );
        let body = extract_fn_ir(&ir, "__kara_state_drop_driver");
        assert!(
            body.contains("%items.drop.is_heap = icmp ugt i64 %items.drop.cap, 0"),
            "non-generic Vec captured local still emits cap > 0 check:\n{body}"
        );
        assert!(
            body.contains("call void @free(ptr %items.drop.data)"),
            "non-generic Vec captured local still emits free:\n{body}"
        );
    }

    // ── Phase 6 line 26 slice 8x: body-walk for generic-typed let-bindings ──
    //
    // Slice 8v Phase 2 / 8w resolved type-parameter-typed *parameters*
    // through `lookup_param_type_expr` against the active `type_subst`,
    // but a `let copy = item;` introduced inside a `T`-typed yielding
    // fn body whose binding is captured across a later yield still
    // fell through to the i64 default — the typechecker's
    // `pattern_binding_types` recorder emits `type_name: None` for
    // type-parameter-typed bindings whose RHS is itself a
    // type-parameter-typed identifier, and the `None`-fallback chain
    // only consulted the parameter list. Slice 8x widens that chain
    // with `lookup_let_type_expr`, which walks `fn_ast.body`
    // recursively for a body-level `let`-binding and returns its
    // explicit type annotation (if any) or — for bare-identifier
    // RHS — recursively resolves through `lookup_param_type_expr`
    // (params take priority) then this helper (chained let-bindings).

    #[test]
    fn test_slice_8x_per_mono_state_struct_lowers_let_binding_for_vec_t() {
        // `fn driver[T](item: T) { fetch(); let copy = item; fetch();
        // }` instantiated with `T = Vec[i64]`. Both `item` (param)
        // and `copy` (body-level let) are in scope at the second
        // yield, so the state-struct layout records both with
        // `type_name: None`. Slice 8w handled `item` via the param
        // lookup; slice 8x handles `copy` via the new let lookup
        // (bare-identifier RHS resolves through `item`'s parameter
        // type, which `type_subst` lowers to the Vec struct shape).
        let ir = ir_for_with_state_struct_layouts(
            "effect resource Network;
             pub fn fetch() with sends(Network) receives(Network) {}
             fn driver[T](item: T) { fetch(); let copy = item; fetch(); }
             fn caller() {
                 let v: Vec[i64] = Vec.new();
                 driver(v);
             }",
        );
        // Per-mono state struct line carries two Vec struct shapes
        // (one for `item`, one for `copy`) alongside the i32 tag.
        let line = ir
            .lines()
            .find(|l| l.starts_with("%\"kara.state.driver$struct$T_ct_Vec_i64\" = type {"))
            .unwrap_or_else(|| panic!("no per-mono state struct type def in IR:\n{ir}"));
        let vec_shape = "{ ptr, i64, i64 }";
        let occurrences = line.matches(vec_shape).count();
        assert!(
            occurrences >= 2,
            "expected two Vec-struct fields (item + copy) in per-mono state struct line, got {occurrences}:\n{line}"
        );
    }

    #[test]
    fn test_slice_8x_per_mono_destructor_emits_free_for_let_binding() {
        // Same source as above. The destructor body must walk both
        // captured-local fields in source-introduction order — `item`
        // (param) first, `copy` (body let) second — and emit
        // `cap > 0 ? free` for each. Without slice 8x, the `copy`
        // field's classification would fall through to `Skip` and
        // its heap buffer would leak on cancel/Err unwinding.
        let ir = ir_for_with_state_struct_layouts(
            "effect resource Network;
             pub fn fetch() with sends(Network) receives(Network) {}
             fn driver[T](item: T) { fetch(); let copy = item; fetch(); }
             fn caller() {
                 let v: Vec[i64] = Vec.new();
                 driver(v);
             }",
        );
        assert!(
            ir.contains("@\"__kara_state_drop_driver$struct$T_ct_Vec_i64\""),
            "per-mono destructor must emit for Vec-typed T captured + let:\n{ir}"
        );
        // Both fields emit the `cap > 0 ? free` shape.
        for field_name in ["item", "copy"] {
            assert!(
                ir.contains(&format!("%{field_name}.drop.cap = load i64")),
                "destructor must load cap for `{field_name}` field:\n{ir}"
            );
            assert!(
                ir.contains(&format!(
                    "%{field_name}.drop.is_heap = icmp ugt i64 %{field_name}.drop.cap, 0"
                )),
                "destructor must compare cap > 0 for `{field_name}` field:\n{ir}"
            );
            assert!(
                ir.contains(&format!("call void @free(ptr %{field_name}.drop.data)")),
                "destructor must call free on `{field_name}.drop.data`:\n{ir}"
            );
        }
        // Source order: `item.drop.cap` precedes `copy.drop.cap` in
        // the IR text — pins the strict source-introduction order
        // discipline the field walk inherited from slice 8u.
        let item_pos = ir
            .find("%item.drop.cap")
            .expect("item.drop.cap must appear");
        let copy_pos = ir
            .find("%copy.drop.cap")
            .expect("copy.drop.cap must appear");
        assert!(
            item_pos < copy_pos,
            "destructor must walk fields in source order (item before copy):\n{ir}"
        );
    }

    #[test]
    fn test_slice_8x_explicit_let_annotation_resolves_through_type_subst() {
        // `let copy: T = item;` with an explicit annotation hits the
        // primary `lookup_let_type_expr` path (returns the annotation
        // directly without recursing through the RHS chain). With
        // `T = String`, the annotation resolves through `type_subst`
        // to the Vec struct shape and the destructor's `cap > 0 ? free`
        // shape emits for `copy` alongside `item`.
        let ir = ir_for_with_state_struct_layouts(
            "effect resource Network;
             pub fn fetch() with sends(Network) receives(Network) {}
             fn driver[T](item: T) { fetch(); let copy: T = item; fetch(); }
             fn caller() {
                 let s = String.new();
                 driver(s);
             }",
        );
        assert!(
            ir.contains("@\"__kara_state_drop_driver$struct$T_ct_String\""),
            "explicit-annotation let must also produce per-mono destructor:\n{ir}"
        );
        assert!(
            ir.contains("%copy.drop.cap = load i64"),
            "explicit annotation `let copy: T = item;` must classify as VecOrString for T=String:\n{ir}"
        );
        assert!(
            ir.contains("call void @free(ptr %copy.drop.data)"),
            "explicit-annotation let must emit free for copy field:\n{ir}"
        );
    }

    #[test]
    fn test_slice_8x_primitive_t_let_binding_still_no_destructor() {
        // Regression guard for skip-when-empty: with `T = i64`, both
        // `item` and `copy` resolve to primitive int — neither field
        // classifies as `VecOrString` (Vec-struct identity check
        // fails) — so the destructor stays absent. Mirrors the
        // slice 8w primitive-only guard for the body-let surface.
        let ir = ir_for_with_state_struct_layouts(
            "effect resource Network;
             pub fn fetch() with sends(Network) receives(Network) {}
             fn driver[T](item: T) { fetch(); let copy = item; fetch(); }
             fn caller() { driver(42i64); }",
        );
        assert!(
            !ir.contains("@\"__kara_state_drop_driver$i64\""),
            "primitive-T let-binding mono must not emit a destructor:\n{ir}"
        );
    }

    // ── Phase 6 line 26 slice 8z: ref / slice-elem params via per-mono intercept ──
    //
    // Slice 8v Phase 2's per-mono caller-side intercept (in
    // `compile_generic_call`, `src/codegen/mono.rs`) stored compiled
    // `arg_vals[i]` values directly into state-struct captured-local
    // fields. For owned-value params that's correct; for `ref T` /
    // `mut ref T` / `mut Slice[T]` params the loaded value (Vec
    // struct, i64, etc.) is the wrong shape — the state-struct
    // field's type is `ptr` (for ref) or `{ ptr, i64 }` (for slice),
    // and the size mismatch produced ill-typed IR that the LLVM
    // verifier accepted under opaque pointers but that wrote past
    // the field's intended footprint into adjacent state-struct
    // bytes. Slice 8z closes the gap by mirroring the slice 8d
    // non-generic intercept's arg-handling discipline:
    //
    // - `declare_mono_function` populates `fn_param_ref` /
    //   `fn_param_slice_elem` under the mangled key (mirrors
    //   `declare_one_function` for non-generic fns).
    // - The per-mono intercept's arg-store loop now consults those
    //   tables: ref-flagged params consume the caller-side data ptr
    //   via `get_data_ptr` (Identifier args) or materialize into a
    //   stack temp (rvalue args, with `track_vec_var` registration
    //   for Vec-struct-shaped rvalues so heap cleanup queues
    //   correctly); slice-elem params route through `coerce_to_slice`
    //   to synthesize the `{ptr, i64}` slice header at the call site.
    //
    // The same change also surfaced a latent gap in
    // `llvm_type_for_name`: the canonical `"Slice"` surface name
    // (recorded by the typechecker in `pattern_binding_types` for
    // `Type::Slice` bindings) fell through to the i64 default
    // because the match arms didn't include "Slice" — so even with
    // the intercept storing the right value, the state-struct
    // field's layout was 8 bytes for a 16-byte slice header. The
    // arm now mirrors `llvm_type_for_type_expr`'s identical Slice
    // recognition.

    #[test]
    fn test_slice_8z_ref_t_identifier_arg_stores_data_ptr() {
        // `fn driver[T](item: ref T)` with `T = Vec[i64]`. The
        // state-struct field for `item` is `ptr` (ref T lowers
        // through `TypeKind::Ref` regardless of T's resolution).
        // The caller-side intercept must store the data ptr
        // (via `get_data_ptr("v")`) into the field, NOT the loaded
        // Vec value. Pre-slice-8z, the loaded `{ ptr, i64, i64 }`
        // got stored into the ptr-sized field — size mismatch.
        let ir = ir_for_with_state_struct_layouts(
            "effect resource Network;
             pub fn fetch() with sends(Network) receives(Network) {}
             fn driver[T](item: ref T) { fetch(); }
             fn caller() {
                 let mut v: Vec[i64] = Vec.new();
                 v.push(1);
                 driver(v);
             }",
        );
        // State-struct field is ptr-shaped. The mono is `driver$struct`
        // (T = Vec[i64] now binds via the call-site type-arg record —
        // B-2026-07-02-41; the `$` forces LLVM to quote the type name),
        // so match by substring rather than an exact `driver` prefix.
        let state_line = ir
            .lines()
            .find(|l| l.contains("kara.state.driver") && l.contains("= type {"))
            .unwrap_or_else(|| panic!("no state struct in IR:\n{ir}"));
        assert!(
            state_line.contains("{ i32, ptr }"),
            "ref T field must lower to ptr:\n{state_line}"
        );
        // Caller stores a ptr — slice 8d's `get_data_ptr` pattern.
        // The exact identifier name (`%v`) survives inkwell's
        // mangling because there's only one local binding, but be
        // defensive and just check the value type is ptr.
        let caller = extract_fn_ir(&ir, "caller");
        assert!(
            caller.contains("store ptr %v, ptr %kara.arg0.field_ptr"),
            "intercept must store data ptr (not loaded Vec value) into ref-T field:\n{caller}"
        );
        // Regression guard: the wrong-shape store (loaded Vec
        // struct into the state-struct ref-T field) must not
        // appear. Narrowly check stores TO `kara.arg0.field_ptr`
        // — broader Vec stores from `v.push` etc. are fine.
        assert!(
            !caller.contains("store { ptr, i64, i64 } %v, ptr %kara.arg0.field_ptr")
                && !caller.contains("store { ptr, i64, i64 } %v1, ptr %kara.arg0.field_ptr"),
            "intercept must NOT store loaded Vec struct into ref-T field:\n{caller}"
        );
    }

    #[test]
    fn test_slice_8z_mut_slice_t_arg_synthesizes_slice_header() {
        // `fn driver[T](items: mut Slice[T])` — the state-struct
        // field's LLVM type is `{ ptr, i64 }` (slice struct). The
        // caller's `driver(v)` where `v: Vec[i64]` must synthesize
        // the slice header at the call site (slice 8d's
        // `coerce_to_slice` pattern) and store the resulting `{ ptr,
        // i64 }` into the field. Pre-slice-8z, the field was sized
        // i64 (the "Slice" surface name fell through
        // `llvm_type_for_name`'s default arm) while the store wrote
        // 16 bytes — a corrupt store overflowing into adjacent
        // state-struct fields.
        let ir = ir_for_with_state_struct_layouts(
            "effect resource Network;
             pub fn fetch() with sends(Network) receives(Network) {}
             fn driver[T](items: mut Slice[T]) { fetch(); }
             fn caller() {
                 let mut v: Vec[i64] = Vec.new();
                 v.push(1);
                 driver(mut v);
             }",
        );
        // State-struct field is the slice struct shape.
        let state_line = ir
            .lines()
            .find(|l| l.starts_with("%kara.state.driver = type {"))
            .unwrap_or_else(|| panic!("no state struct in IR:\n{ir}"));
        assert!(
            state_line.contains("{ ptr, i64 }"),
            "mut Slice[T] field must lower to slice struct {{ ptr, i64 }}:\n{state_line}"
        );
        // Caller stores the slice header (synthesized from Vec).
        let caller = extract_fn_ir(&ir, "caller");
        assert!(
            caller.contains("store { ptr, i64 }") && caller.contains("ptr %kara.arg0.field_ptr"),
            "intercept must store synthesized slice header into mut Slice[T] field:\n{caller}"
        );
        // Regression guard: the wrong-shape store (loaded Vec
        // struct into the state-struct slice field) must not
        // appear. Narrowly check stores TO `kara.arg0.field_ptr`.
        assert!(
            !caller.contains("store { ptr, i64, i64 } %v, ptr %kara.arg0.field_ptr")
                && !caller.contains("store { ptr, i64, i64 } %v1, ptr %kara.arg0.field_ptr"),
            "intercept must NOT store loaded Vec struct into mut Slice[T] field:\n{caller}"
        );
    }

    #[test]
    fn test_slice_8z_owned_t_param_still_stores_loaded_value() {
        // Regression guard: the slice 8z extension is gated on
        // `fn_param_ref` / `fn_param_slice_elem` tables and must
        // NOT change the storage shape for owned-value T params.
        // `fn driver[T](item: T)` with `T = i64` still stores the
        // loaded `i64` value into the field; no ptr or slice-header
        // synthesis fires.
        let ir = ir_for_with_state_struct_layouts(
            "effect resource Network;
             pub fn fetch() with sends(Network) receives(Network) {}
             fn driver[T](item: T) { fetch(); }
             fn caller() { driver(42i64); }",
        );
        let caller = extract_fn_ir(&ir, "caller");
        assert!(
            caller.contains("store i64 42, ptr %kara.arg0.field_ptr"),
            "owned-T param must store the loaded value:\n{caller}"
        );
    }

    // ── Phase 6 line 26 slice 8af: slice 8z verification gaps ────────────
    //
    // Slice 8z covered `ref T` (with `T = Vec[i64]`) and `mut Slice[T]`
    // (with `T = i64`). Slice 8af closes the remaining type-param-typed
    // slice verification gap: composite element type (e.g.
    // `mut Slice[T]` with `T = Vec[i64]`).
    //
    // The other 8af-tracked gap — `mut ref T` per-mono intercept
    // verification — was probed 2026-05-20 and surfaced a real
    // typechecker bug (`driver(mut n)` with `fn driver[T](item: mut
    // ref T)` fails to unify with "expected 'mut ref T', found
    // 'i64'", indicating the typechecker doesn't apply the mut-marker
    // auto-ref-take when the param is a type-parameter-typed
    // `mut ref T`). Per the slice 8af tracker entry's policy ("if
    // either test surfaces a real bug, that fix lands as a new
    // entry"), the bug is carried as a separate tracker entry rather
    // than blocking 8af; the `mut ref T` per-mono intercept dispatch
    // path is still structurally covered by `declare_mono_function`'s
    // `TypeKind::Ref(_) | TypeKind::MutRef(_)` match arm (slice 8z),
    // so the missing test is verification-only — the codegen path is
    // correct as soon as the typechecker accepts the call.
    //
    // Slice 8af ships verification-only; no codegen change.

    #[test]
    fn test_slice_8af_mut_slice_t_composite_element_type() {
        // `fn driver[T](items: mut Slice[T])` with `T = Vec[i64]` —
        // slice of vecs. The element-type-resolution chain is:
        // `extract_slice_elem_type(mut Slice[T])` → calls
        // `llvm_type_for_type_expr(T)` → type_subst[T] = vec_struct.
        // The state-struct field is the slice struct `{ ptr, i64 }`
        // regardless of element type (slice's run-time width is
        // independent of element width — it's always
        // `{ data_ptr, len }`). The caller-side `coerce_to_slice`
        // must produce the slice header from the `Vec[Vec[i64]]`
        // source binding.
        let ir = ir_for_with_state_struct_layouts(
            "effect resource Network;
             pub fn fetch() with sends(Network) receives(Network) {}
             fn driver[T](items: mut Slice[T]) { fetch(); }
             fn caller() {
                 let mut vv: Vec[Vec[i64]] = Vec.new();
                 driver(mut vv);
             }",
        );
        // State-struct field is the slice struct shape — independent
        // of element type.
        let state_line = ir
            .lines()
            .find(|l| l.starts_with("%kara.state.driver = type {"))
            .unwrap_or_else(|| panic!("no state struct in IR:\n{ir}"));
        assert!(
            state_line.contains("{ ptr, i64 }"),
            "mut Slice[T] field must lower to slice struct {{ ptr, i64 }} regardless of element type:\n{state_line}"
        );
        // Caller stores the synthesized slice header.
        let caller = extract_fn_ir(&ir, "caller");
        assert!(
            caller.contains("store { ptr, i64 }") && caller.contains("ptr %kara.arg0.field_ptr"),
            "intercept must store synthesized slice header for Vec[Vec[i64]] arg:\n{caller}"
        );
    }

    // ── Phase 6 line 26 slice 8ag: re-enabled mut ref T per-mono intercept ─
    //
    // Carved out of slice 8af 2026-05-20 by the typechecker probe that
    // surfaced the missing owned-to-mut-ref coercion arm. With slice
    // 8ag's typechecker fix landed (`is_subtype` / `types_compatible`
    // / `unify_types` accept owned source against `mut ref T` at call
    // boundaries, marker enforcement stays at `check_call_site_marker`),
    // the codegen-side dispatch is now reachable end-to-end. The
    // dispatch itself is unchanged — slice 8z's `declare_mono_function`
    // already handles `TypeKind::MutRef(_)` symmetrically with
    // `TypeKind::Ref(_)`; this test exercises the previously-blocked
    // verification gap.

    #[test]
    fn test_slice_8ag_per_mono_mut_ref_typeparam_stores_ptr() {
        // `fn driver[T](item: mut ref T) { fetch(); }` with `T = i64`.
        // The state-struct field for `item` lowers to `ptr` (MutRef
        // mirrors Ref's lowering at the layout level — both are
        // pointer-shaped in the captured-local state struct). The
        // caller's per-mono intercept must store the address-of the
        // owned source binding rather than the loaded i64 value.
        let ir = ir_for_with_state_struct_layouts(
            "effect resource Network;
             pub fn fetch() with sends(Network) receives(Network) {}
             fn driver[T](item: mut ref T) { fetch(); }
             fn caller() {
                 let mut n: i64 = 7;
                 driver(mut n);
             }",
        );
        // State-struct field is ptr-shaped. The mono is `driver$i64`
        // (T = i64 now binds via the call-site type-arg record —
        // B-2026-07-02-41; the `$` forces LLVM to quote the type name),
        // so match by substring rather than an exact `driver` prefix.
        let state_line = ir
            .lines()
            .find(|l| l.contains("kara.state.driver") && l.contains("= type {"))
            .unwrap_or_else(|| panic!("no state struct in IR:\n{ir}"));
        assert!(
            state_line.contains("ptr"),
            "mut ref T field must lower to ptr in state struct:\n{state_line}"
        );
        // Caller stores a ptr into the state-struct field — the
        // address of `n`, not the loaded i64 value. Regression guard
        // against `store i64 %v, ptr %kara.arg0.field_ptr`.
        let caller = extract_fn_ir(&ir, "caller");
        assert!(
            caller.contains("store ptr") && caller.contains("ptr %kara.arg0.field_ptr"),
            "intercept must store ptr (address-of source) into mut ref T field:\n{caller}"
        );
        assert!(
            !caller.contains("store i64 7, ptr %kara.arg0.field_ptr")
                && !caller.contains("store i64 %n, ptr %kara.arg0.field_ptr"),
            "intercept must NOT store loaded i64 value into mut ref T field:\n{caller}"
        );
    }

    // ── Phase 6 line 26 slice 8ad: non-generic state-machine intercept ref/slice ──
    //
    // Slice 8z closed the per-mono intercept (`compile_generic_call`)
    // arg-storing gap for `ref T` / `mut ref T` / `mut Slice[T]`
    // params. Slice 8ad closes the identical gap in the parallel non-
    // generic intercept (`src/codegen/call_dispatch.rs:271-286`).
    // Empirical probe 2026-05-20 verified that `fn driver(item: ref
    // Vec[i64]) { fetch(); }` emitted `store { ptr, i64, i64 } %v,
    // ptr %kara.arg0.field_ptr` — a 24-byte Vec struct stored into an
    // 8-byte ptr-typed state-struct field. The in-code comment at
    // `call_dispatch.rs:262-265` acknowledged ref-passing through the
    // state struct was deferred. The fix mirrors slice 8z exactly:
    // consult `fn_param_ref` / `fn_param_slice_elem` keyed on the
    // bare fn name, dispatch by mode. The
    // `materialize_rvalue_for_ref_arg` helper from slice 8z is now
    // `pub(super)` and shared between both intercepts.

    #[test]
    fn test_slice_8ad_non_generic_ref_vec_param_stores_data_ptr() {
        // `fn driver(item: ref Vec[i64]) { fetch(); }` — the
        // state-struct field for `item` is `ptr` (TypeKind::Ref
        // lowers to ptr). The caller-side non-generic intercept must
        // store the data ptr (via `get_data_ptr("v")`) into the
        // field, NOT the loaded `{ ptr, i64, i64 }` Vec struct.
        let ir = ir_for_with_state_struct_layouts(
            "effect resource Network;
             pub fn fetch() with sends(Network) receives(Network) {}
             fn driver(item: ref Vec[i64]) { fetch(); }
             fn caller() {
                 let mut v: Vec[i64] = Vec.new();
                 v.push(1);
                 driver(v);
             }",
        );
        // State-struct field is ptr-shaped.
        let state_line = ir
            .lines()
            .find(|l| l.starts_with("%kara.state.driver = type {"))
            .unwrap_or_else(|| panic!("no state struct in IR:\n{ir}"));
        assert!(
            state_line.contains("{ i32, ptr }"),
            "ref Vec[i64] field must lower to ptr:\n{state_line}"
        );
        // Caller stores a ptr — slice 8d's `get_data_ptr` pattern
        // now fires inside the non-generic state-machine intercept.
        let caller = extract_fn_ir(&ir, "caller");
        assert!(
            caller.contains("store ptr %v, ptr %kara.arg0.field_ptr"),
            "intercept must store data ptr (not loaded Vec value) into ref field:\n{caller}"
        );
        // Regression guard: no Vec struct stored at the state-struct
        // field (the pre-fix shape).
        assert!(
            !caller.contains("store { ptr, i64, i64 } %v, ptr %kara.arg0.field_ptr")
                && !caller.contains("store { ptr, i64, i64 } %v1, ptr %kara.arg0.field_ptr"),
            "intercept must NOT store loaded Vec struct into ref field:\n{caller}"
        );
    }

