    // ── Slice 10: composite-initializer codegen (design.md §1280-1297) ─
    //
    // Module-level `let X: T = INIT;` where INIT is a struct literal,
    // tuple literal, array literal, repeat literal, or enum
    // unit-variant path. Each shape lowers to an LLVM constant
    // initializer of the matching aggregate type. Field / index /
    // method dispatch inside function bodies sees the binding via the
    // reseeded `var_type_names` / `vec_elem_types` side tables — the
    // reseed runs at the start of every function body so the binding's
    // declared type is visible to the use-site dispatchers without
    // being declared inside the function.

    #[test]
    fn test_e2e_modbind_struct_literal() {
        // Struct literal init → `@DEFAULT_CFG = internal constant`
        // with each field's constant value lowered into its slot.
        // The Path-form access `DEFAULT_CFG.max` routes through the
        // module-binding path-arm to a `load + extractvalue` against
        // the global.
        let output = run_program(
            "struct Config { max: i64, count: i64 }\n\
             let DEFAULT_CFG: Config = Config { max: 64, count: 7 };\n\
             fn main() {\n\
                 println(DEFAULT_CFG.max);\n\
                 println(DEFAULT_CFG.count);\n\
             }",
        )
        .expect("compile + run failed");
        assert_eq!(output, "64\n7\n");
    }

    #[test]
    fn test_e2e_modbind_struct_literal_field_order_in_source() {
        // Source-order != declaration-order — the codegen path must
        // pivot through `struct_field_names` to land each value in
        // the right slot.
        let output = run_program(
            "struct Pair { a: i64, b: i64 }\n\
             let PR: Pair = Pair { b: 22, a: 11 };\n\
             fn main() { println(PR.a); println(PR.b); }",
        )
        .expect("compile + run failed");
        assert_eq!(output, "11\n22\n");
    }

    #[test]
    fn test_e2e_modbind_array_literal() {
        // Fixed-size `[a, b, c]` → `[N x i64]` constant. Indexed read
        // uses the global's pointer as the array-storage pointer
        // (collections.rs fast path).
        let output = run_program(
            "let ARR: Array[i64, 3] = [10, 20, 30];\n\
             fn main() {\n\
                 println(ARR[0]);\n\
                 println(ARR[1]);\n\
                 println(ARR[2]);\n\
             }",
        )
        .expect("compile + run failed");
        assert_eq!(output, "10\n20\n30\n");
    }

    #[test]
    fn test_e2e_modbind_repeat_literal() {
        // `[v; n]` materialises an `[n x T]` constant with each slot
        // initialised to `v`. Verifies the count fold + element-value
        // replication path.
        let output = run_program(
            "let REPS: Array[i64, 4] = [7; 4];\n\
             fn main() {\n\
                 let mut s: i64 = 0;\n\
                 let mut i: i64 = 0;\n\
                 while i < 4 {\n\
                     s = s + REPS[i];\n\
                     i = i + 1;\n\
                 }\n\
                 println(s);\n\
             }",
        )
        .expect("compile + run failed");
        assert_eq!(output, "28\n");
    }

    #[test]
    fn test_e2e_modbind_enum_unit_variant() {
        // `EnumName.UnitVariant` path → enum layout's struct constant
        // with the tag in field 0 and zero-initialised payload words.
        // Match-arm dispatches against the loaded tag.
        let output = run_program(
            "enum Mode { Off, On, Auto }\n\
             let DEFAULT_MODE: Mode = Mode.Off;\n\
             let LIVE_MODE: Mode = Mode.Auto;\n\
             fn main() {\n\
                 let m: Mode = DEFAULT_MODE;\n\
                 let a: Mode = LIVE_MODE;\n\
                 match m {\n\
                     Mode.Off => println(0),\n\
                     Mode.On => println(1),\n\
                     Mode.Auto => println(2),\n\
                 }\n\
                 match a {\n\
                     Mode.Off => println(0),\n\
                     Mode.On => println(1),\n\
                     Mode.Auto => println(2),\n\
                 }\n\
             }",
        )
        .expect("compile + run failed");
        assert_eq!(output, "0\n2\n");
    }

    #[test]
    fn test_e2e_modbind_struct_with_negative_field() {
        // `Unary { Neg, Integer }` inside a struct field flows through
        // the value-driven recursion. Verifies the recursive surface
        // doesn't lose the sign at the nested position.
        let output = run_program(
            "struct Range { lo: i64, hi: i64 }\n\
             let SPAN: Range = Range { lo: -7, hi: 3 };\n\
             fn main() { println(SPAN.lo); println(SPAN.hi); }",
        )
        .expect("compile + run failed");
        assert_eq!(output, "-7\n3\n");
    }

    #[test]
    fn test_ir_modbind_struct_emits_constant_struct() {
        // The IR contains the struct constant with the right field
        // values. `internal constant { i64, i64 } { i64 N, i64 M }`
        // is the canonical shape; LLVM collapses all-zero aggregates
        // to `zeroinitializer`, so we use a non-zero value here to
        // exercise the explicit-field path.
        let ir = ir_for(
            "struct Pt { x: i64, y: i64 }\n\
             let CORNER: Pt = Pt { x: 3, y: 7 };\n\
             fn main() { println(CORNER.x); }",
        );
        assert!(
            ir.contains("@CORNER = internal constant { i64, i64 } { i64 3, i64 7 }"),
            "expected @CORNER const struct in IR, got:\n{}",
            ir
        );
    }

    #[test]
    fn test_ir_modbind_array_emits_constant_array() {
        // `Array[i64, 3]` with literal init lowers to a `[3 x i64]`
        // constant aggregate global.
        let ir = ir_for(
            "let ARR: Array[i64, 3] = [1, 2, 3];\n\
             fn main() { println(ARR[0]); }",
        );
        assert!(
            ir.contains("@ARR = internal constant [3 x i64]"),
            "expected `@ARR = internal constant [3 x i64]` in IR, got:\n{}",
            ir
        );
    }

    #[test]
    fn test_e2e_defer_in_nested_block_fires_at_inner_block_exit() {
        // Bare `{ ... }` (ExprKind::Block) routes through
        // `compile_block_with_frame` in slice 1.5, so a defer
        // inside the nested block scopes to that block — fires
        // at the inner block's end-of-emission, before any
        // outer-block statements that follow. Expected stream:
        // `before` → `in-block` → defer body (`inner-defer`) →
        // `after`.
        let out = run_program(
            r#"
fn main() {
    println("before");
    {
        defer { println("inner-defer"); }
        println("in-block");
    };
    println("after");
}
"#,
        );
        if let Some(out) = out {
            let lines: Vec<&str> = out.trim().lines().collect();
            assert_eq!(lines, vec!["before", "in-block", "inner-defer", "after"]);
        }
    }

    // ── Phase 6 line 17/170: karac_park_on_fd leaf parking primitive ──
    //
    // The leaf primitive recognised by codegen. When effectcheck classifies
    // it as a network-yield callee (via the declared
    // `sends(Network) receives(Network)` effects), the state-machine
    // emission pass overrides its body with a hand-rolled 2-state machine.
    // Async-sched slice 2/3 (dispatcher-yield): state_0 allocates a
    // per-park completion slot + registers the fd and returns Pending;
    // state_1 — re-invoked by the dispatcher only on real readiness, routed
    // by the wakeup's parked pointer — signals that slot and returns Ready.
    // The caller blocks on the slot (rather than re-polling) and deregisters
    // the fd afterwards. The state struct carries the `KaracParkedTask
    // { poll_fn, state }` record (so the dispatcher can re-invoke the
    // poll-fn) plus trailing `token` + `slot` fields.

    fn park_on_fd_source() -> &'static str {
        "effect resource Network;
         pub fn karac_park_on_fd(fd: i32, direction: u8) \
             with sends(Network) receives(Network) {}
         fn driver(socket_fd: i32) { karac_park_on_fd(socket_fd, 0); }"
    }

    #[test]
    fn test_park_on_fd_state_struct_emitted_with_parked_task_trailing_fields() {
        // `%kara.state.karac_park_on_fd` carries the layout
        // `{ i32 tag, i32 fd, i8 direction, ptr poll_fn, ptr state,
        //    i64 token, ptr slot }`. The poll_fn/state ptrs are the
        // `KaracParkedTask` storage the dispatcher reads back; the trailing
        // `token` + `slot` (async-sched slice 2/3) carry the registration
        // handle (for the caller's one-shot deregister) and the per-park
        // completion slot (the caller blocks on it, state_1 signals it).
        let ir = ir_for_with_state_struct_layouts(park_on_fd_source());
        let line = ir
            .lines()
            .find(|l| l.starts_with("%kara.state.karac_park_on_fd = type {"))
            .unwrap_or_else(|| panic!("missing karac_park_on_fd state struct in IR:\n{ir}"));
        assert!(
            line.contains("i32") && line.contains("i64") && line.matches("ptr").count() >= 3,
            "state struct must carry tag (i32) + token (i64) + 3 ptrs \
             (poll_fn, state, slot): {line}"
        );
    }

    #[test]
    fn test_park_on_fd_constructor_initializes_parked_task_pointers() {
        // The constructor `__kara_state_new_karac_park_on_fd` must
        // store the poll-fn pointer into the parked_task.poll_fn slot
        // (field 3) and the state pointer (self-reference) into
        // parked_task.state (field 4).
        let ir = ir_for_with_state_struct_layouts(park_on_fd_source());
        let ctor_body = function_body(&ir, "__kara_state_new_karac_park_on_fd")
            .expect("constructor body must be present in IR");
        assert!(
            ctor_body.contains("parked.poll_fn.ptr"),
            "constructor must GEP parked_task.poll_fn field:\n{ctor_body}"
        );
        assert!(
            ctor_body.contains("parked.state.ptr"),
            "constructor must GEP parked_task.state field:\n{ctor_body}"
        );
        assert!(
            ctor_body.contains("@__kara_poll_karac_park_on_fd"),
            "constructor must store poll-fn address into parked_task:\n{ctor_body}"
        );
    }

    #[test]
    fn test_park_on_fd_poll_fn_emits_register_fd_call_in_state_0() {
        // state_0 allocates the per-park completion slot, calls
        // `karac_runtime_event_loop_register_fd(fd, dir, &parked_task)`,
        // stores the token + `tag = 1`, and returns Pending.
        let ir = ir_for_with_state_struct_layouts(park_on_fd_source());
        let body = function_body(&ir, "__kara_poll_karac_park_on_fd")
            .expect("poll-fn body must be present");
        assert!(
            body.contains("@karac_runtime_event_loop_register_fd"),
            "state_0 must call karac_runtime_event_loop_register_fd:\n{body}"
        );
        assert!(
            body.contains("kara.park.parked_ptr"),
            "state_0 must GEP &parked_task field:\n{body}"
        );
        assert!(
            body.contains("@karac_runtime_park_slot_new"),
            "state_0 must allocate the per-park completion slot:\n{body}"
        );
    }

    #[test]
    fn test_park_on_fd_poll_fn_signals_slot_in_state_1_not_take_wakeups() {
        // Async-sched slice 2/3: state_1 — reached only when the dispatcher
        // re-invokes on real readiness — signals the per-park completion
        // slot and returns Ready. It must NOT block on the global
        // `take_wakeups` (the wakeup-stealing source of the P0 wedge).
        let ir = ir_for_with_state_struct_layouts(park_on_fd_source());
        let body = function_body(&ir, "__kara_poll_karac_park_on_fd")
            .expect("poll-fn body must be present");
        assert!(
            body.contains("@karac_runtime_park_slot_signal"),
            "state_1 must signal the completion slot:\n{body}"
        );
        assert!(
            !body.contains("@karac_runtime_event_loop_take_wakeups"),
            "state_1 must NOT block on the global take_wakeups queue:\n{body}"
        );
    }

    #[test]
    fn test_park_on_fd_poll_fn_starts_dispatcher_in_entry() {
        // Entry block calls `karac_runtime_scheduler_start_dispatcher`
        // before dispatching on the tag — idempotent bootstrap so the
        // dispatcher (which re-invokes this poll-fn at state_1, routed by
        // the wakeup's parked pointer) is running before register_fd.
        let ir = ir_for_with_state_struct_layouts(park_on_fd_source());
        let body = function_body(&ir, "__kara_poll_karac_park_on_fd")
            .expect("poll-fn body must be present");
        assert!(
            body.contains("@karac_runtime_scheduler_start_dispatcher"),
            "poll-fn entry must start the scheduler dispatcher (idempotent bootstrap):\n{body}"
        );
    }

    #[test]
    fn test_park_on_fd_caller_routes_through_dispatcher_yield_intercept() {
        // The driver that calls `karac_park_on_fd(socket_fd, 0)` routes
        // through the dispatcher-yield helper: allocate the state struct
        // via `__kara_state_new_karac_park_on_fd`, invoke the poll-fn once
        // (state_0), then on Pending block on the completion slot
        // (`kara.park.poll_wait`) and deregister the fd afterwards. This is
        // the leaf primitive's yield to the dispatcher — distinct from the
        // synchronous spin-loop the generic intercept still uses.
        let ir = ir_for_with_state_struct_layouts(park_on_fd_source());
        let driver = function_body(&ir, "driver").expect("driver body must be present");
        assert!(
            driver.contains("@__kara_state_new_karac_park_on_fd"),
            "driver must invoke state-struct constructor for karac_park_on_fd:\n{driver}"
        );
        assert!(
            driver.contains("@__kara_poll_karac_park_on_fd"),
            "driver must invoke poll-fn for karac_park_on_fd:\n{driver}"
        );
        assert!(
            driver.contains("kara.park.poll_wait"),
            "driver must block on the per-park completion slot (dispatcher-yield):\n{driver}"
        );
        assert!(
            driver.contains("@karac_runtime_park_slot_wait"),
            "driver must wait on the completion slot:\n{driver}"
        );
        assert!(
            driver.contains("@karac_runtime_event_loop_deregister_fd"),
            "driver must deregister the fd after the park completes:\n{driver}"
        );
    }

    // ── Phase 8 File handle slice F5 — ?-propagation ──────────────────
    //
    // Validates that `?` on a `Result[File, IoError]` (or
    // `Result[T, IoError]` for any T) early-returns the IoError to the
    // caller's Result. The mechanism reuses the existing 4-word Result
    // payload path widened at phase-8 line 435 slice 2 (2026-05-21);
    // Json.parse exercised the Ok-with-4-word-payload case, F5
    // validates the Err-with-multi-word-payload case (IoError variant
    // tag + optional String message for the Other variant). No
    // codegen changes at F5 — the existing `compile_question` path
    // handles this shape correctly.
    //
    // The tests run a compiled binary that calls a helper returning
    // `Result[i64, IoError]` and uses `?` to propagate `File.open`'s
    // Err arm; the caller matches the propagated IoError variant.

    /// B-2026-08-10-3 — `File.seek` through the compiled backends.
    ///
    /// The runtime entry point `karac_runtime_file_seek` has existed since the
    /// File slice shipped, exported early and kept on the
    /// `__preserve_no_mangle_symbols` list precisely so adding the surface
    /// would need no runtime rebuild. This pins that the promise held: the only
    /// codegen work was declaring the extern, truncating the `SeekFrom` tag to
    /// the ABI's `u8`, and unpacking the io-result as a byte count.
    ///
    /// Reads the byte AT the sought position rather than only checking the
    /// returned offset — a position check alone passes even if the cursor never
    /// moved. The file is "ABCD", so seeking to 2 must yield 'C' (67).
    #[test]
    fn test_e2e_file_seek_positions_and_reads() {
        let tmp = std::env::temp_dir().join("karac_e2e_file_seek.bin");
        let path = tmp.to_str().unwrap().replace('\\', "\\\\");
        let _ = std::fs::remove_file(&tmp);
        let out = run_program(&format!(
            r#"
fn main() {{
    match File.create("{path}") {{
        Ok(f) => {{
            let data = [65u8, 66u8, 67u8, 68u8];
            match f.write(data[0..4]) {{ Ok(_) => {{}} Err(_) => println("write err") }}
            match f.flush() {{ Ok(_) => {{}} Err(_) => println("flush err") }}
        }}
        Err(_) => println("create err"),
    }}
    match File.open("{path}") {{
        Ok(g) => {{
            match g.seek(SeekFrom.Start, 2i64) {{
                Ok(p) => println("pos " + p.to_string()),
                Err(_) => println("seek err"),
            }}
            let mut buf = [0u8, 0u8];
            match g.read(mut buf) {{
                Ok(n) => println("read " + n.to_string() + " b0 " + buf[0].to_string()),
                Err(_) => println("read err"),
            }}
            match g.seek(SeekFrom.End, -1i64) {{
                Ok(e) => println("end " + e.to_string()),
                Err(_) => println("seek err"),
            }}
            match g.seek(SeekFrom.Current, 0i64) {{
                Ok(c) => println("cur " + c.to_string()),
                Err(_) => println("seek err"),
            }}
            match g.seek(SeekFrom.Start, -5i64) {{
                Ok(_) => println("unexpected ok"),
                Err(_) => println("neg rejected"),
            }}
        }}
        Err(_) => println("open err"),
    }}
}}
"#
        ));
        let _ = std::fs::remove_file(&tmp);
        assert_eq!(
            out.as_deref(),
            Some("pos 2\nread 2 b0 67\nend 3\ncur 3\nneg rejected\n")
        );
    }

    /// B-2026-08-10-3 — the pin that actually caught the bug in this slice, and
    /// the reason it is a separate test from `seek` itself.
    ///
    /// `SeekFrom` is a PRELUDE enum, and prelude enums reach the typechecker
    /// through `STDLIB_PROGRAMS` but never codegen's `declare_enums`, which
    /// walks only the user's `program.items`. Each one therefore needs an
    /// explicit layout seed (`Ordering`, `VarError`, `IoError` all carry one).
    /// Without it every variant construction falls through to the `i64 0`
    /// placeholder.
    ///
    /// That failure is silent and DIRECTIONAL, which is what makes it worth its
    /// own pin: `Start` is tag 0, so seeking from the start kept working while
    /// `Current` and `End` both silently became `Start` — a wrong seek, not an
    /// error. Measured pre-seed, `f.seek(SeekFrom.End, -1)` returned `Err`
    /// (negative absolute position) and `f.seek(SeekFrom.Current, 0)` reported
    /// position 0. A seek-only test would have caught it here by luck; this one
    /// catches the CAUSE, and would catch it for any future prelude enum whose
    /// seed is forgotten.
    #[test]
    fn test_e2e_seek_from_prelude_enum_discriminates() {
        assert_eq!(
            run_program(
                "fn name(w: SeekFrom) -> String {\n\
                 \x20   match w {\n\
                 \x20       SeekFrom.Start => { return \"start\"; }\n\
                 \x20       SeekFrom.Current => { return \"current\"; }\n\
                 \x20       SeekFrom.End => { return \"end\"; }\n\
                 \x20   }\n\
                 }\n\
                 fn main() {\n\
                     println(name(SeekFrom.Start));\n\
                     println(name(SeekFrom.Current));\n\
                     println(name(SeekFrom.End));\n\
                 }"
            )
            .as_deref(),
            Some("start\ncurrent\nend\n")
        );
    }

