    #[test]
    fn test_e2e_tensor_broadcast() {
        // Row / column / rank-mismatch broadcasting, two-singleton expand, a
        // fresh-temp argument (`a + b`), and float division. Operand reuse
        // afterward confirms borrow-not-move. Output verified vs `karac run`.
        let out = run_program(
            "fn main() {\n\
                 let m: Tensor[i64, [2, 3]] = Tensor.from([[1, 2, 3], [4, 5, 6]]);\n\
                 let row: Tensor[i64, [1, 3]] = Tensor.from([[10, 20, 30]]);\n\
                 let r = m.broadcast_add(row);\n\
                 println(r[0, 0]); println(r[1, 2]);\n\
                 let col: Tensor[i64, [2, 1]] = Tensor.from([[100], [200]]);\n\
                 let c = m.broadcast_mul(col);\n\
                 println(c[0, 1]); println(c[1, 0]);\n\
                 let v: Tensor[i64, [3]] = Tensor.from([1, 2, 3]);\n\
                 let d = m.broadcast_sub(v);\n\
                 println(d[0, 0]); println(d[1, 1]);\n\
                 // two singletons broadcast UP to [2, 3].\n\
                 let g = row.broadcast_add(col);\n\
                 println(g[1, 0]);\n\
                 // fresh-temp argument (the `b + b` intermediate is freed).\n\
                 let b: Tensor[i64, [1, 3]] = Tensor.from([[1, 1, 1]]);\n\
                 let h = m.broadcast_add(b + b);\n\
                 println(h[0, 0]);\n\
                 // float division.\n\
                 let fm: Tensor[f64, [2, 2]] = Tensor.from([[2.0, 4.0], [6.0, 8.0]]);\n\
                 let fc: Tensor[f64, [2, 1]] = Tensor.from([[2.0], [4.0]]);\n\
                 let fq = fm.broadcast_div(fc);\n\
                 println(fq[1, 0]);\n\
                 println(m[1, 2]);\n\
             }\n",
        );
        if let Some(out) = out {
            // r[0,0]=1+10=11, r[1,2]=6+30=36; c[0,1]=2*100=200, c[1,0]=4*200=800;
            // d[0,0]=1-1=0, d[1,1]=5-2=3; g[1,0]=row[0,0]+col[1,0]=10+200=210;
            // h[0,0]=1+(1+1)=3; fq[1,0]=6/4=1.5; m reused=6.
            assert_eq!(
                out, "11\n36\n200\n800\n0\n3\n210\n3\n1.5\n6\n",
                "tensor broadcast AOT output must match the interpreter twin",
            );
        }
    }

    #[test]
    fn test_e2e_tensor_broadcast_runtime_dims_and_trap() {
        // `?`-dim operands: a compatible broadcast (row [1,?] over [?,?]) and
        // an incompatible one that the codegen runtime guard traps. The static
        // checker can't prove either, so both go through the header-driven
        // runtime path.
        let ok = run_program(
            "fn mk_mat(r: i64, c: i64) -> Tensor[i64, [?, ?]] {\n\
                 let t: Tensor[i64, [?, ?]] = Tensor.full([r, c], 2);\n\
                 t\n\
             }\n\
             fn mk_row(n: i64) -> Tensor[i64, [1, ?]] {\n\
                 let t: Tensor[i64, [1, ?]] = Tensor.full([1, n], 5);\n\
                 t\n\
             }\n\
             fn main() {\n\
                 let m: Tensor[i64, [?, ?]] = mk_mat(2, 3);\n\
                 let row: Tensor[i64, [1, ?]] = mk_row(3);\n\
                 let r = m.broadcast_add(row);\n\
                 println(r[0, 0]); println(r[1, 2]);\n\
             }\n",
        );
        if let Some(out) = ok {
            assert_eq!(
                out, "7\n7\n",
                "runtime-dim broadcast must match `karac run`"
            );
        }
        let captured = run_program_capturing(
            "fn mk(r: i64, c: i64) -> Tensor[i64, [?, ?]] {\n\
                 let t: Tensor[i64, [?, ?]] = Tensor.full([r, c], 1);\n\
                 t\n\
             }\n\
             fn main() {\n\
                 let a: Tensor[i64, [?, ?]] = mk(2, 3);\n\
                 let b: Tensor[i64, [?, ?]] = mk(2, 4);\n\
                 let r = a.broadcast_add(b);\n\
                 println(r[0, 0]);\n\
             }\n",
        );
        if let Some(c) = captured {
            assert!(
                c.stderr.contains("not broadcast-compatible"),
                "expected the broadcast-incompatible trap, got stdout={:?} stderr={:?}",
                c.stdout,
                c.stderr
            );
        }
    }

    // ── Owned String/Vec parameter retention (kata-22 family, 2026-06-06) ──
    //
    // The call ABI passes owned String/Vec headers by value while the
    // CALLER retains the buffer's scope-exit free — so a callee that
    // RETAINS the value (push into a container, return it, capture it
    // in a struct/enum payload) must deep-copy the buffer instead of
    // aliasing it (`emit_vecstr_defensive_copy`). Before the fix every
    // shape below either aborted under macOS malloc (exit 133 double
    // free) or read freed memory. The f-string siblings pin the
    // `last_fstr_acc` take-points at the same consume sites (the temp
    // accumulator's queued cleanup must be disarmed when the container
    // takes the buffer).

    #[test]
    fn test_e2e_owned_string_param_push_branch_move() {
        // Recursive backtracking shape: `cur` is moved into the vec in
        // the base-case branch and borrowed by the f-string in the
        // recursive branch. The cap-sentinel machinery gives the
        // per-branch flow sensitivity; the defensive copy keeps the
        // pushed buffer alive past the caller's f-string-temp cleanup.
        let out = run_program(
            r#"
fn add_rec(cur: String, k: i64, out: mut ref Vec[String]) {
    if k == 0 {
        out.push(cur);
        return;
    }
    add_rec(f"{cur}(", k - 1, out);
}

fn generate(n: i64) -> Vec[String] {
    let mut out: Vec[String] = Vec.new();
    add_rec("", n, mut out);
    out
}

fn main() {
    let combos = generate(3);
    println(combos.len());
    println(combos[0]);
}
"#,
        );
        if let Some(out) = out {
            assert_eq!(out.trim(), "1\n(((");
        }
    }

    #[test]
    fn test_e2e_map_insert_owned_string_param_value() {
        // `m.insert(k, v)` where `v: String` is an owned PARAM and the map
        // outlives the callee (passed `mut ref`): the Map must store a
        // private deep copy, not an alias into the caller's buffer, or the
        // caller's scope-exit free and the Map's bucket free double-hit the
        // same buffer (kata-22 owned-param UAF family, Cluster 1). The read
        // back through `m.get` proves the value buffer survives.
        let out = run_program(
            r#"
fn store(m: mut ref Map[i64, String], v: String) {
    m.insert(7i64, v);
}

fn main() {
    let mut m: Map[i64, String] = Map.new();
    let mut s = String.new();
    s.push_str("payload");
    store(mut m, s);
    println(m.len());
    match m.get(7i64) { Some(g) => println(g), None => println("missing") }
}
"#,
        );
        if let Some(out) = out {
            assert_eq!(out.trim(), "1\npayload");
        }
    }

    #[test]
    fn test_e2e_set_insert_owned_string_param() {
        // `s.insert(v)` where `v: String` is an owned PARAM and the set
        // outlives the callee: same defensive-copy requirement as
        // `Map.insert`'s value side (Set lowers to `Map[T, ()]`, the
        // element is the bucket key). The `contains` reads prove the keys
        // survive past the caller's frees.
        let out = run_program(
            r#"
fn add(set: mut ref Set[String], v: String) {
    set.insert(v);
}

fn main() {
    let mut s: Set[String] = Set.new();
    let mut a = String.new();
    a.push_str("apple");
    add(mut s, a);
    let mut b = String.new();
    b.push_str("banana");
    add(mut s, b);
    println(s.len());
    println(s.contains("apple"));
    println(s.contains("banana"));
    println(s.contains("cherry"));
}
"#,
        );
        if let Some(out) = out {
            assert_eq!(out.trim(), "2\ntrue\ntrue\nfalse");
        }
    }

    #[test]
    fn test_e2e_vec_map_param_deep_copy() {
        // `Vec[Map[i64, i64]]` owned param tail-returned: the defensive
        // copy must deep-clone each map handle, not alias it (Cluster 1).
        // Value-correctness companion to the ASAN double-free pin — the
        // cloned maps must carry the original entries.
        let out = run_program(
            r#"
fn id(v: Vec[Map[i64, i64]]) -> Vec[Map[i64, i64]] {
    v
}

fn main() {
    let mut v: Vec[Map[i64, i64]] = Vec.new();
    let mut m: Map[i64, i64] = Map.new();
    m.insert(1i64, 10i64);
    m.insert(2i64, 20i64);
    v.push(m);
    let mut m2: Map[i64, i64] = Map.new();
    m2.insert(3i64, 30i64);
    v.push(m2);
    let r = id(v);
    println(r.len());
    match r[0].get(1i64) { Some(x) => println(x), None => println(-1i64) }
    match r[0].get(2i64) { Some(x) => println(x), None => println(-1i64) }
    match r[1].get(3i64) { Some(x) => println(x), None => println(-1i64) }
}
"#,
        );
        if let Some(out) = out {
            assert_eq!(out.trim(), "2\n10\n20\n30");
        }
    }

    #[test]
    fn test_e2e_vec_map_returned_from_helper() {
        // The headline `Vec[Map]` ownership bug (Cluster 1): a Map pushed
        // into a Vec aliased a handle owned by the origin `m` binding, which
        // freed it at the helper's scope exit — so the returned Vec dangled
        // and the read in `main` saw a freed/reused handle (AOT printed
        // `-1`, interp `777`). The fix transfers ownership to the Vec at the
        // push and frees the handle at the Vec's drop. ASAN twin:
        // `memory_sanitizer.rs::asan_vec_map_returned_from_helper_no_uaf`.
        let out = run_program(
            r#"
fn make() -> Vec[Map[i64, i64]] {
    let mut v: Vec[Map[i64, i64]] = Vec.new();
    let mut m: Map[i64, i64] = Map.new();
    m.insert(1i64, 777i64);
    v.push(m);
    v
}

fn main() {
    let v = make();
    match v[0].get(1i64) { Some(x) => println(x), None => println(-1i64) }
}
"#,
        );
        if let Some(out) = out {
            assert_eq!(out.trim(), "777");
        }
    }

    #[test]
    fn test_e2e_expression_position_container_ctors() {
        // B-2026-08-02-12 — `Map.new()` / `Set.new()` / `SortedMap.new()` in
        // a non-`let` EXPRESSION position (push / push_back / Vec.insert
        // args, `Vec.filled` fill values) used to compile to the silent
        // `i64 0` assoc-call default: a NULL handle in the container slot,
        // segfaulting at the first element use. With the fix the handle is
        // built from the typechecker's resolved span-keyed type (the
        // container-method arms re-record the ctor arg post-unify), so
        // String keys get the right key size + content hash — `get` finds
        // what `insert` stored — and filled slots deep-clone independently
        // (incl. SortedMap, whose clone/drop/vec-elem dispatch heads were
        // widened onto Map's KaracMap paths).
        let out = run_program(
            r#"
fn main() {
    let mut v: Vec[Map[String, i64]] = Vec.new();
    v.push(Map.new());
    v.push(Map.new());
    let _ = v[0].insert(f"k{1}", 5);
    match v[0].get(f"k{1}") { Some(x) => println(f"got {x}"), None => println("miss") }
    println(f"m0 {v[0].len()} m1 {v[1].len()}");
    let mut g: Vec[Map[String, i64]] = Vec.filled(2, Map.new());
    let _ = g[0].insert(f"a{2}", 7);
    println(f"g0 {g[0].len()} g1 {g[1].len()}");
    let mut s: Vec[Set[i64]] = Vec.new();
    s.push(Set.new());
    let _ = s[0].insert(9i64);
    println(f"s0 {s[0].len()}");
    let mut d: Vec[SortedMap[i64, i64]] = Vec.filled(2, SortedMap.new());
    let _ = d[0].insert(7i64, 70i64);
    println(f"d0 {d[0].len()} d1 {d[1].len()}");
    let mut q: VecDeque[Map[String, i64]] = VecDeque.new();
    q.push_back(Map.new());
    let _ = q[0].insert(f"z{3}", 4);
    match q[0].get(f"z{3}") { Some(x) => println(f"qgot {x}"), None => println("qmiss") }
    let mut w: Vec[Set[i64]] = Vec.new();
    w.insert(0, Set.new());
    let _ = w[0].insert(9i64);
    println(f"w0 {w[0].len()}");
    println("end");
}
"#,
        );
        if let Some(out) = out {
            assert_eq!(
                out.trim(),
                "got 5\nm0 1 m1 0\ng0 1 g1 0\ns0 1\nd0 1 d1 0\nqgot 4\nw0 1\nend"
            );
        }
    }

    #[test]
    fn test_e2e_generic_parent_drop_field_bodies() {
        // B-2026-08-02-14 — a Drop-carrying field of a GENERIC-mono parent
        // (`Box2[Res]`): the name-keyed field-bodies walk saw only the
        // declared bare param (`item: T`) and stayed silent at owner death
        // (both backends), and the Vec-element leg additionally leaked the
        // element's String buffer under AOT (base struct synthesis read
        // `T` as a scalar). The subst-aware walk fires both bodies and the
        // mono element drop frees the heap — matching the non-generic
        // control byte-for-byte.
        let out = run_program(
            r#"
struct Res { id: i64, name: String }
impl Drop for Res {
    fn drop(mut ref self) { println(f"drop {self.id} {self.name}") }
}
struct Box2[T] { item: T, tag: i64 }
fn main() {
    println("a");
    {
        let b: Box2[Res] = Box2 { item: Res { id: 3, name: f"ggg{3}" }, tag: 1 };
        println(f"tag {b.tag}");
    }
    println("mid");
    {
        let mut v: Vec[Box2[Res]] = Vec.new();
        v.push(Box2 { item: Res { id: 4, name: f"hhhhh{4}" }, tag: 2 });
        println(f"vlen {v.len()}");
    }
    println("end");
}
"#,
        );
        if let Some(out) = out {
            assert_eq!(
                out.trim(),
                "a\ntag 1\ndrop 3 ggg3\nmid\nvlen 1\ndrop 4 hhhhh4\nend"
            );
        }
    }

    #[test]
    fn test_e2e_generic_parent_vec_field_elem_bodies() {
        // B-2026-08-02-16 — the container-field sibling of B-2026-08-02-14:
        // a GENERIC parent's `Vec[T]`-of-Drop field (`Pack[T] { items:
        // Vec[T] }` at `Pack[Res]`). The dbv element walk was gated off for
        // mono parents, so AOT stayed silent while the interpreter's
        // value-driven Vec-field arm fired — a run-vs-build divergence.
        // The field TE now resolves through the mono subst before the walk,
        // so both backends print the element body at owner death.
        let out = run_program(
            r#"
struct Res { id: i64, name: String }
impl Drop for Res {
    fn drop(mut ref self) { println(f"drop {self.id} {self.name}") }
}
struct Pack[T] { items: Vec[T], tag: i64 }
fn main() {
    println("a");
    {
        let mut p: Pack[Res] = Pack { items: Vec.new(), tag: 1 };
        p.items.push(Res { id: 7, name: f"qq{7}" });
        println(f"n {p.items.len()}");
    }
    println("end");
}
"#,
        );
        if let Some(out) = out {
            assert_eq!(out.trim(), "a\nn 1\ndrop 7 qq7\nend");
        }
    }

    #[test]
    fn test_e2e_struct_field_tuple_and_map_drop_bodies() {
        // B-2026-08-02-18 — TUPLE-held and Map-VALUE-held Drop values in
        // struct fields: the owner-death bodies walk now has a tuple arm
        // (reusing the __karac_dropelems_tuple walker on the field slot) and
        // a Map/Set arm (reusing __karac_dropelems_map), on both backends.
        // The generic block additionally pins B-2026-08-02-19: the mono
        // parent's NestedTuple memory drop resolves `(T, i64)` through the
        // subst, so the tuple-held String is freed (the asan twin proves the
        // memory half; here the body line proves dispatch).
        let out = run_program(
            r#"
struct Res { id: i64, name: String }
impl Drop for Res {
    fn drop(mut ref self) { println(f"drop {self.id} {self.name}") }
}
struct DuoR { pair: (Res, i64), tag: i64 }
struct Duo[T] { pair: (T, i64), tag: i64 }
struct MapHold { m: Map[i64, Res], tag: i64 }
fn main() {
    println("a");
    {
        let d = DuoR { pair: (Res { id: 1, name: f"aa{1}" }, 5), tag: 7 };
        println(d.tag);
    }
    println("b");
    {
        let g: Duo[Res] = Duo { pair: (Res { id: 2, name: f"bb{2}" }, 6), tag: 8 };
        println(g.tag);
    }
    println("c");
    {
        let mut h = MapHold { m: Map.new(), tag: 9 };
        h.m.insert(1i64, Res { id: 3, name: f"cc{3}" });
        println(h.tag);
    }
    println("end");
}
"#,
        );
        if let Some(out) = out {
            assert_eq!(
                out.trim(),
                "a\n7\ndrop 1 aa1\nb\n8\ndrop 2 bb2\nc\n9\ndrop 3 cc3\nend"
            );
        }
    }

    #[test]
    fn test_e2e_tuple_field_parent_displaced_and_vec_elem_bodies() {
        // B-2026-08-02-18 (gate legs) — a parent whose ONLY Drop content is
        // a tuple field now classifies Drop-relevant on both backends'
        // widened gates: the displaced old value fires its tuple-held body
        // at reassignment, and a Vec element of such a parent fires it at
        // the container's death (the interp side pins the
        // field_value_carries_user_drop widening; pre-fix the interp was
        // silent on both while AOT fired — a run-vs-build divergence).
        let out = run_program(
            r#"
struct Res { id: i64, name: String }
impl Drop for Res {
    fn drop(mut ref self) { println(f"drop {self.id} {self.name}") }
}
struct DuoR { pair: (Res, i64), tag: i64 }
fn main() {
    println("a");
    {
        let mut x = DuoR { pair: (Res { id: 1, name: f"a{1}" }, 5), tag: 7 };
        println(x.tag);
        x = DuoR { pair: (Res { id: 2, name: f"b{2}" }, 6), tag: 8 };
        println(x.tag);
    }
    println("mid");
    {
        let mut v: Vec[DuoR] = Vec.new();
        v.push(DuoR { pair: (Res { id: 3, name: f"x{3}" }, 5), tag: 9 });
        println(v.len());
    }
    println("end");
}
"#,
        );
        if let Some(out) = out {
            assert_eq!(
                out.trim(),
                "a\n7\ndrop 1 a1\n8\ndrop 2 b2\nmid\n1\ndrop 3 x3\nend"
            );
        }
    }

    #[test]
    fn test_e2e_truncate_and_reassign_run_displaced_drop_bodies() {
        // B-2026-08-03-2 (class 1, remainder) — the last two positions where a
        // container element is destroyed with no binding to receive it.
        // `truncate(n)` needed a RANGED walk, not the whole-container walker
        // `clear` uses: its SURVIVORS still fire at binding death, so a
        // whole-container walk would double them. `v = w` displaces every old
        // element, so there the whole-container walker is right. Both had the
        // same memory-yes/bodies-no split as clear.
        let out = run_program(
            r#"
struct Res { id: i64, name: String }
impl Drop for Res {
    fn drop(mut ref self) { println(f"drop {self.id} {self.name}") }
}
fn main() {
    println("truncate:");
    {
        let mut v: Vec[Res] = Vec.new();
        v.push(Res { id: 1, name: f"a{1}" });
        v.push(Res { id: 2, name: f"b{2}" });
        v.truncate(1);
        println(v.len());
    }
    println("truncate0:");
    {
        let mut u: Vec[Res] = Vec.new();
        u.push(Res { id: 3, name: f"c{3}" });
        u.truncate(0);
        println(u.len());
    }
    println("reassign:");
    {
        let mut w: Vec[Res] = Vec.new();
        w.push(Res { id: 4, name: f"d{4}" });
        let mut z: Vec[Res] = Vec.new();
        z.push(Res { id: 5, name: f"e{5}" });
        w = z;
        println(w.len());
    }
    println("end");
}
"#,
        );
        if let Some(out) = out {
            assert_eq!(
                out.trim(),
                "truncate:\ndrop 2 b2\n1\ndrop 1 a1\ntruncate0:\ndrop 3 c3\n0\n\
                 reassign:\ndrop 4 d4\n1\ndrop 5 e5\nend"
            );
        }
    }

    #[test]
    fn test_e2e_discarded_vec_removal_fires_and_frees() {
        // B-2026-08-03-2 (class 2) — a DISCARDED `v.remove(i);` /
        // `v.swap_remove(i);` hands the element back BY VALUE with nothing to
        // receive it: the body never ran and the element's heap LEAKED, on both
        // backends and on the shipping path. Builtins have no
        // `fn_return_type_names` entry, so the discard battery could not resolve
        // what it was holding; it now falls back to the receiver's recorded
        // element TypeExpr. `bound` is the control that was always correct, and
        // `survivor` checks only the REMOVED element fires early while the one
        // left behind still fires at scope exit.
        let out = run_program(
            r#"
struct Res { id: i64, name: String }
impl Drop for Res {
    fn drop(mut ref self) { println(f"drop {self.id} {self.name}") }
}
fn main() {
    println("remove:");
    {
        let mut v: Vec[Res] = Vec.new();
        v.push(Res { id: 1, name: f"a{1}" });
        v.remove(0);
        println(v.len());
    }
    println("swapremove:");
    {
        let mut w: Vec[Res] = Vec.new();
        w.push(Res { id: 2, name: f"b{2}" });
        w.swap_remove(0);
        println(w.len());
    }
    println("bound:");
    {
        let mut u: Vec[Res] = Vec.new();
        u.push(Res { id: 3, name: f"c{3}" });
        let r = u.remove(0);
        println(u.len());
    }
    println("survivor:");
    {
        let mut t: Vec[Res] = Vec.new();
        t.push(Res { id: 4, name: f"d{4}" });
        t.push(Res { id: 5, name: f"e{5}" });
        t.remove(0);
        println(t.len());
    }
    println("end");
}
"#,
        );
        if let Some(out) = out {
            assert_eq!(
                out.trim(),
                "remove:\ndrop 1 a1\n0\nswapremove:\ndrop 2 b2\n0\nbound:\ndrop 3 c3\n0\n\
                 survivor:\ndrop 4 d4\n1\ndrop 5 e5\nend"
            );
        }
    }

    #[test]
    fn test_e2e_container_clear_runs_element_drop_bodies() {
        // B-2026-08-03-2 (class 1) — `v.clear()` / `m.clear()` destroy every
        // element but ran no destructor. Both arms did all the MEMORY work and
        // none of the body work, so the shapes were vg-clean and silent —
        // parity-equal, invisible to backend diffing and to any sanitizer, and
        // only a fire-count oracle sees them. The third block is a
        // clear-then-reuse control: the cleared element fires, the buffer is
        // reusable, and the replacement fires at scope exit.
        let out = run_program(
            r#"
struct Res { id: i64, name: String }
impl Drop for Res {
    fn drop(mut ref self) { println(f"drop {self.id} {self.name}") }
}
fn main() {
    println("vecclear:");
    {
        let mut v: Vec[Res] = Vec.new();
        v.push(Res { id: 1, name: f"a{1}" });
        v.push(Res { id: 2, name: f"b{2}" });
        v.clear();
        println(v.len());
    }
    println("mapclear:");
    {
        let mut m: Map[i64, Res] = Map.new();
        m.insert(5, Res { id: 3, name: f"c{3}" });
        m.clear();
        println(m.len());
    }
    println("reuse:");
    {
        let mut w: Vec[Res] = Vec.new();
        w.push(Res { id: 4, name: f"d{4}" });
        w.clear();
        w.push(Res { id: 5, name: f"e{5}" });
        println(w.len());
    }
    println("end");
}
"#,
        );
        if let Some(out) = out {
            assert_eq!(
                out.trim(),
                "vecclear:\ndrop 1 a1\ndrop 2 b2\n0\nmapclear:\ndrop 3 c3\n0\n\
                 reuse:\ndrop 4 d4\n1\ndrop 5 e5\nend"
            );
        }
    }

    #[test]
    fn test_e2e_optres_payload_bodies_in_nested_positions() {
        // B-2026-08-03-1 — an `Option[P]` payload ran its Drop body only when
        // bound DIRECTLY; in every NESTED position it was silent on BOTH
        // backends, so parity diffing saw nothing and (memory being clean) no
        // sanitizer did either. Option/Result were simply missing from the
        // one-container-level widening Vec/Map/Set/tuple already had, in all
        // three layers: the reachability gates, the field-index selector, and
        // the per-position dispatchers. Four positions plus a `None` control
        // that must stay silent.
        let out = run_program(
            r#"
struct Res { id: i64, name: String }
impl Drop for Res {
    fn drop(mut ref self) { println(f"drop {self.id} {self.name}") }
}
struct H { o: Option[Res], t: i64 }
fn main() {
    println("field:");
    {
        let h = H { o: Option.Some(Res { id: 1, name: f"a{1}" }), t: 2 };
        println(h.t);
    }
    println("vecelem:");
    {
        let mut v: Vec[Option[Res]] = Vec.new();
        v.push(Option.Some(Res { id: 2, name: f"b{2}" }));
        println(v.len());
    }
    println("mapval:");
    {
        let mut m: Map[i64, Option[Res]] = Map.new();
        m.insert(5, Option.Some(Res { id: 3, name: f"c{3}" }));
        println(m.len());
    }
    println("tupelem:");
    {
        let t = (Option.Some(Res { id: 4, name: f"d{4}" }), 7);
        println(t.1);
    }
    println("none:");
    {
        let h2 = H { o: Option.None, t: 9 };
        println(h2.t);
    }
    println("end");
}
"#,
        );
        if let Some(out) = out {
            assert_eq!(
                out.trim(),
                "field:\n2\ndrop 1 a1\nvecelem:\n1\ndrop 2 b2\nmapval:\n1\n\
                 drop 3 c3\ntupelem:\n7\ndrop 4 d4\nnone:\n9\nend"
            );
        }
    }

    #[test]
    fn test_e2e_nested_call_temp_owned_arg_drop() {
        // B-2026-08-02-28 — a call RESULT consumed directly as another call's
        // owned argument (`use_it(mk(xs))`). The fn-call arm of the owned-arg
        // registrar registered the field-BODIES walk and returned, omitting the
        // memory drop its struct-LITERAL sibling registers for the identical
        // value — so the body printed while the Holder's Vec buffer and its
        // element leaves leaked once per call (asan pin
        // `nested_call_temp_owned_arg_freed` covers that half). Fire count was
        // already right; this pins the ORDER, which the fix also settled: the
        // memory drop is pushed first so the LIFO drain runs the body before
        // the fields it reads are freed. Three shapes — bound outer result,
        // bare-statement discard, and an inner call taking no argument.
        let out = run_program(
            r#"
struct Res { id: i64, name: String }
impl Drop for Res {
    fn drop(mut ref self) { println(f"drop {self.id} {self.name}") }
}
struct Holder { xs: Vec[Res], tag: i64 }
fn mk(v: Vec[Res]) -> Holder { Holder { xs: v, tag: 9 } }
fn mkh() -> Holder {
    let mut v: Vec[Res] = Vec.new();
    v.push(Res { id: 7, name: f"g{7}" });
    Holder { xs: v, tag: 3 }
}
fn use_it(h: Holder) -> i64 { h.tag }
fn main() {
    println("a");
    {
        let mut xs: Vec[Res] = Vec.new();
        xs.push(Res { id: 1, name: f"a{1}" });
        let n = use_it(mk(xs));
        println(n);
    }
    println("b");
    {
        let mut ys: Vec[Res] = Vec.new();
        ys.push(Res { id: 2, name: f"b{2}" });
        use_it(mk(ys));
    }
    println("c");
    {
        let m = use_it(mkh());
        println(m);
    }
    println("end");
}
"#,
        );
        if let Some(out) = out {
            assert_eq!(
                out.trim(),
                "a\ndrop 1 a1\n9\nb\ndrop 2 b2\nc\ndrop 7 g7\n3\nend"
            );
        }
    }

    #[test]
    fn test_e2e_tuple_binding_container_element_drop() {
        // B-2026-08-03-5 — a TUPLE binding whose element is a CONTAINER of
        // Drop-running values (`let t = (xs, 9)` with `xs: Vec[Res]`). Two
        // independent gaps, both AOT-only, so `karac run` was right and
        // `karac build` was wrong in two ways at once:
        //   * bodies — `emit_tuple_elem_user_drop_bodies_fn` accepted only an
        //     element that was a Path naming a user struct, so `Vec[Res]` read
        //     as the drop-free head "Vec" and the whole walker declined;
        //   * memory — the LLVM-type aggregate drop freed the element Vec's
        //     BUFFER shallowly, leaking every live `Res`'s String.
        // Underneath both sat `infer_arg_elem_te` erasing the generic argument,
        // so the element type was bare `Vec` at every decision point. All three
        // element sources exercised: a named binding, a fresh call, and an
        // annotated binding.
        let out = run_program(
            r#"
struct Res { id: i64, name: String }
impl Drop for Res {
    fn drop(mut ref self) { println(f"drop {self.id} {self.name}") }
}
fn mkv() -> Vec[Res] {
    let mut v: Vec[Res] = Vec.new();
    v.push(Res { id: 2, name: f"b{2}" });
    v
}
fn main() {
    println("a");
    {
        let mut xs: Vec[Res] = Vec.new();
        xs.push(Res { id: 1, name: f"a{1}" });
        let t = (xs, 9);
        println(t.1);
    }
    {
        let u = (mkv(), 8);
        println(u.1);
    }
    {
        let mut ys: Vec[Res] = Vec.new();
        ys.push(Res { id: 3, name: f"c{3}" });
        let w: (Vec[Res], i64) = (ys, 7);
        println(w.1);
    }
    println("end");
}
"#,
        );
        if let Some(out) = out {
            assert_eq!(
                out.trim(),
                "a\n9\ndrop 1 a1\n8\ndrop 2 b2\n7\ndrop 3 c3\nend"
            );
        }
    }

    #[test]
    fn test_e2e_tuple_literal_own_drop_source_disarm() {
        // B-2026-08-02-27 — `let r = Res { .. }; let t = (r, 9);`. The
        // consuming-ARG aggregate arms were promoted to the strong
        // `suppress_user_drop_for_var` in B-2026-08-02-22, but the let-RHS
        // sibling `disarm_container_bodies_move_sources` kept the weak
        // container-only form, so `r`'s OWN body stayed armed and fired at
        // r's NLL end over the moved-from slot — printing an EMPTY name —
        // then again through the tuple's element walk. The inline control
        // below (`(Res { .. }, 4)`, no move at all) already fired exactly
        // once, which is what proves the tuple binding owns the body and the
        // strong disarm is safe.
        let out = run_program(
            r#"
struct Res { id: i64, name: String }
impl Drop for Res {
    fn drop(mut ref self) { println(f"drop {self.id} {self.name}") }
}
fn main() {
    println("a");
    {
        let r = Res { id: 1, name: f"a{1}" };
        let t = (r, 9);
        println(t.1);
    }
    {
        let u = (Res { id: 2, name: f"b{2}" }, 4);
        println(u.1);
    }
    println("end");
}
"#,
        );
        if let Some(out) = out {
            assert_eq!(out.trim(), "a\n9\ndrop 1 a1\n4\ndrop 2 b2\nend");
        }
    }

    #[test]
    fn test_e2e_passthrough_arg_and_returned_literal_single_fire() {
        // B-2026-08-02-23 leg 2 — a param that flows back OUT to the caller.
        // The caller-drops-the-owned-arg convention fires the arg binding's
        // body at the call, which is right when the value dies inside the
        // callee (`consume` below) and a duplicate when the callee hands it
        // back. Two return shapes, both previously double-firing on BOTH
        // backends: a bare-identifier passthrough, and the param moved into a
        // returned struct literal (which `fn_returns_param` did not even
        // recognize as a return site until it learned to look inside
        // aggregate literals).
        let out = run_program(
            r#"
struct Res { id: i64, name: String }
impl Drop for Res {
    fn drop(mut ref self) { println(f"drop {self.id} {self.name}") }
}
struct Holder { xs: Vec[Res], tag: i64 }
fn passthru(v: Vec[Res]) -> Vec[Res] { v }
fn mk(v: Vec[Res]) -> Holder { Holder { xs: v, tag: 9 } }
fn consume(v: Vec[Res]) -> i64 { v.len() }
fn main() {
    println("a");
    {
        let mut xs: Vec[Res] = Vec.new();
        xs.push(Res { id: 1, name: f"a{1}" });
        let ys = passthru(xs);
        println(ys.len());
    }
    {
        let mut zs: Vec[Res] = Vec.new();
        zs.push(Res { id: 2, name: f"b{2}" });
        let h = mk(zs);
        println(h.tag);
    }
    {
        let mut ws: Vec[Res] = Vec.new();
        ws.push(Res { id: 3, name: f"c{3}" });
        println(consume(ws));
    }
    println("end");
}
"#,
        );
        if let Some(out) = out {
            assert_eq!(
                out.trim(),
                "a\n1\ndrop 1 a1\n9\ndrop 2 b2\n1\ndrop 3 c3\nend"
            );
        }
    }

    #[test]
    fn test_e2e_nested_literal_move_source_disarm() {
        // B-2026-08-02-23 leg 1 — the aggregate-literal source disarm was
        // depth-1: `v.push(Outer { inner: Inner { xs: xs } })` inspected only
        // the OUTER literal's immediate fields, and `inner` is a
        // StructLiteral rather than an Identifier, so `xs` was never
        // disarmed and its element body fired twice (once at xs's death,
        // once at the container's) identically on both backends — a
        // parity-equal double that only a fire-COUNT oracle catches.
        // Exactly one fire, at the container's death, is correct.
        let out = run_program(
            r#"
struct Res { id: i64, name: String }
impl Drop for Res {
    fn drop(mut ref self) { println(f"drop {self.id} {self.name}") }
}
struct Inner { xs: Vec[Res] }
struct Outer { inner: Inner, tag: i64 }
fn main() {
    println("a");
    {
        let mut v: Vec[Outer] = Vec.new();
        let mut xs: Vec[Res] = Vec.new();
        xs.push(Res { id: 1, name: f"n{1}" });
        v.push(Outer { inner: Inner { xs: xs }, tag: 5 });
        println(v.len());
    }
    println("end");
}
"#,
        );
        if let Some(out) = out {
            assert_eq!(out.trim(), "a\n1\ndrop 1 n1\nend");
        }
    }

    #[test]
    fn test_e2e_vec_of_tuple_element_drop_bodies() {
        // B-2026-08-02-22 — `Vec[(Res, i64)]`: the container's per-element
        // machinery had no tuple arm on either axis, so the element's Drop
        // body never fired (both backends) and its heap leaked. Two shapes:
        // an INLINE element (the minimal repro — no move involved) and one
        // built from a NAMED source, which additionally left the source's own
        // body armed so AOT fired it early over a moved-from slot, printing
        // an empty name. Both must now produce exactly ONE fire, at the
        // container's death, with the correct field content. The leak half is
        // pinned by asan_vec_of_tuple_element_heap_freed.
        let out = run_program(
            r#"
struct Res { id: i64, name: String }
impl Drop for Res {
    fn drop(mut ref self) { println(f"drop {self.id} {self.name}") }
}
fn main() {
    println("inline:");
    {
        let mut t: Vec[(Res, i64)] = Vec.new();
        t.push((Res { id: 9, name: f"in{9}" }, 8));
        println(t.len());
    }
    println("named:");
    {
        let mut u: Vec[(Res, i64)] = Vec.new();
        let r = Res { id: 4, name: f"tt{4}" };
        u.push((r, 8));
        println(u.len());
    }
    println("end");
}
"#,
        );
        if let Some(out) = out {
            assert_eq!(
                out.trim(),
                "inline:\n1\ndrop 9 in9\nnamed:\n1\ndrop 4 tt4\nend"
            );
        }
    }

